def _check_password(user: str, password: str) -> bool:
    try:
        iters, salt_hex, hash_hex = APP_PASSWORD_HASH.split(":")
        dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), bytes.fromhex(salt_hex), int(iters))
        pw_ok = hmac.compare_digest(dk.hex(), hash_hex)
    except Exception:
        return False
    user_ok = hmac.compare_digest(user.encode("utf-8"), APP_USER.encode("utf-8"))
    return pw_ok and user_ok


def _hash_pw(password: str) -> str:
    salt = os.urandom(16)
    return f"200000:{salt.hex()}:{hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 200000).hex()}"


def _verify_pw(stored: str, password: str) -> bool:
    try:
        iters, salt_hex, hash_hex = stored.split(":")
        dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), bytes.fromhex(salt_hex), int(iters))
        return hmac.compare_digest(dk.hex(), hash_hex)
    except Exception:
        return False


def _norm_phone(s: str) -> str:
    """Телефон → цифры в едином виде (7XXXXXXXXXX). Пусто, если на телефон не похоже."""
    d = re.sub(r"\D", "", s or "")
    if len(d) == 11 and d[0] == "8":
        d = "7" + d[1:]
    if len(d) == 10:
        d = "7" + d
    return d if 10 <= len(d) <= 15 else ""


def _auth_personal(user: str, password: str) -> str:
    """Личный вход: по почте ИЛИ по логину. Возвращает логин сотрудника (как в справочнике) или ''."""
    if not user or not password:
        return ""
    u = user.strip().lower()
    try:
        with sqlite3.connect(DB_PATH) as c:
            rows = c.execute("SELECT login,email,pw_hash FROM dict_users WHERE active=1 AND pw_hash<>''").fetchall()
    except Exception:
        return ""
    for lg, em, h in rows:
        if (lg and lg.lower() == u) or ((em or "").strip().lower() == u):
            if _verify_pw(h, password):
                return lg or (em or "").strip().lower()
    return ""


def _unauthorized(msg: str = "Требуется вход") -> Response:
    return JSONResponse({"detail": msg}, status_code=401, headers={"WWW-Authenticate": 'Basic realm="ID ITS", charset="UTF-8"'})


def _is_admin(login: str) -> bool:
    return bool(APP_USER) and login.lower() == APP_USER.lower()


APP_ROLES = ("pto", "manager", "surveyor", "foreman", "other")
_ROLE_RANK = {"pto": 5, "manager": 4, "surveyor": 3, "foreman": 2, "other": 1}
APP_ROLE_RU = {"pto": "ПТО", "manager": "Руководитель", "surveyor": "Геодезист", "foreman": "Прораб", "other": "Только просмотр"}


def _role_for_position(pos: str) -> str:
    """Роль в программе по должности (если её не задали вручную)."""
    t = (pos or "").lower()
    if "геодез" in t:
        return "surveyor"
    if any(k in t for k in ("прораб", "мастер", "производитель работ", "начальник участка")):
        return "foreman"
    if any(k in t for k in ("руководитель", "директор", "главный инженер", "начальник")):
        return "manager"
    if any(k in t for k in ("пто", "инженер", "исполнительн", "документ")):
        return "pto"
    return "other"


def _best_role(a: str, b: str) -> str:
    return a if _ROLE_RANK.get(a, 0) >= _ROLE_RANK.get(b, 0) else b


def _memberships(login: str) -> Optional[dict[str, str]]:
    """None — видит всё (общий вход администратора). Иначе {id объекта: роль} по действующему сроку участия."""
    if _is_admin(login):
        return None
    today = date.today().isoformat()
    try:
        with sqlite3.connect(DB_PATH) as c:
            rows = c.execute("""SELECT DISTINCT t.project_id, t.app_role FROM team t LEFT JOIN dict_users u ON u.id=t.user_id
                WHERE ((u.login<>'' AND lower(u.login)=lower(?)) OR (t.login<>'' AND lower(t.login)=lower(?)))
                AND (t.valid_from='' OR t.valid_from<=?) AND (t.valid_to='' OR t.valid_to>=?)""", (login, login, today, today)).fetchall()
    except Exception:
        return {}
    out: dict[str, str] = {}
    for pid, role in rows:
        if _ROLE_RANK.get(role, 0) >= _ROLE_RANK.get(out.get(pid, ""), 0):
            out[pid] = role
    return out


def _role_in(login: str, pid: str, sid: str) -> str:
    """Роль человека в конкретном разделе: личная настройка раздела, иначе роль на объекте."""
    today = date.today().isoformat()
    best = ""
    try:
        with sqlite3.connect(DB_PATH) as c:
            rows = c.execute("""SELECT DISTINCT t.name, t.app_role FROM team t LEFT JOIN dict_users u ON u.id=t.user_id
                WHERE t.project_id=? AND ((u.login<>'' AND lower(u.login)=lower(?)) OR (t.login<>'' AND lower(t.login)=lower(?)))
                AND (t.valid_from='' OR t.valid_from<=?) AND (t.valid_to='' OR t.valid_to>=?)""", (pid, login, login, today, today)).fetchall()
            for name, role in rows:
                if sid:
                    o = c.execute("SELECT role FROM team_sections WHERE project_id=? AND member_key=? AND section_id=?", (pid, name.strip().lower(), sid)).fetchone()
                    if o:
                        role = o[0]
                best = _best_role(best, role) if best else role
    except Exception:
        return ""
    return best


def _user_projects(login: str) -> Optional[set[str]]:
    m = _memberships(login)
    return None if m is None else set(m)


def _user_can_manage(login: str) -> bool:
    if _is_admin(login):
        return True
    try:
        with sqlite3.connect(DB_PATH) as c:
            r = c.execute("SELECT 1 FROM dict_users WHERE lower(login)=lower(?) AND app_role IN ('pto','manager') AND active=1", (login,)).fetchone()
    except Exception:
        return False
    return bool(r)


