def _project_of(c: sqlite3.Connection, kind: str, val: Any) -> Optional[str]:
    if not isinstance(val, str) or not val:
        return None
    if kind == "photo":
        r = c.execute("SELECT operation_id FROM photos WHERE id=?", (val,)).fetchone()
        if not r:
            return None
        op = r[0]
        return _project_of(c, "vhk", op[4:]) if op.startswith("vhk:") else (_project_of(c, "operation", op) or _project_of(c, "element", op))
    q = _PROJ_SQL.get(kind)
    if not q:
        return None
    r = c.execute(q, (val,)).fetchone()
    return r[0] if r else None


def _section_of(c: sqlite3.Connection, kind: str, val: Any) -> str:
    if not isinstance(val, str) or not val:
        return ""
    if kind == "photo":
        r = c.execute("SELECT operation_id FROM photos WHERE id=?", (val,)).fetchone()
        if not r:
            return ""
        op = r[0]
        return _section_of(c, "vhk", op[4:]) if op.startswith("vhk:") else (_section_of(c, "operation", op) or _section_of(c, "element", op))
    q = _SEC_SQL.get(kind)
    if not q:
        return ""
    r = c.execute(q, (val,)).fetchone()
    return (r[0] or "") if r else ""


def _walk_ids(obj: Any, out: list[tuple[str, str]], depth: int = 0) -> None:
    if depth > 4:
        return
    if isinstance(obj, list):
        for x in obj[:500]:
            _walk_ids(x, out, depth + 1)
    elif isinstance(obj, dict):
        for k, v in obj.items():
            kind = _BODY_KINDS.get(k)
            if kind:
                for x in (v if isinstance(v, list) else [v]):
                    if isinstance(x, str):
                        out.append((kind, x))
            elif isinstance(v, (list, dict)):
                _walk_ids(v, out, depth + 1)


async def _request_scopes(request: Request) -> set[tuple[str, str]]:
    """Все объекты, которых касается запрос: по пути, параметрам и телу запроса (операции, акты, строки журналов, фото…)."""
    refs: list[tuple[str, str]] = []
    path = request.url.path
    for rx, kind in _PATH_KINDS:
        m = rx.match(path)
        if m:
            refs.append((kind, m.group(1)))
    for k, kind in _QUERY_KINDS.items():
        v = request.query_params.get(k)
        if v:
            refs.append((kind, v))
    if request.method in ("POST", "PUT", "PATCH", "DELETE") and "json" in request.headers.get("content-type", "") and int(request.headers.get("content-length", "0") or 0) < 2_000_000:
        try:
            _walk_ids(json.loads(await request.body() or b"null"), refs)
        except ValueError:
            pass
    scopes: set[tuple[str, str]] = set()
    if refs:
        with sqlite3.connect(DB_PATH) as c:
            for kind, val in refs:
                pid = _project_of(c, kind, val)
                if pid:
                    scopes.add((pid, _section_of(c, kind, val)))
    return scopes


