def _role_may_write(role: str, method: str, path: str, body_keys: Optional[set[str]] = None) -> bool:
    """Что может записывать роль. Не названное в правилах — только ПТО. Руководитель может менять у акта только статус (подписать, в архив)."""
    if role == "pto":
        return True
    for m, rx, roles in _WRITE_RULES:
        if (m == "*" or m == method) and rx.match(path):
            return role in roles
    if role == "manager" and method == "PUT" and re.match(r"^/api/acts/[^/]+$", path) and body_keys is not None and body_keys <= {"status", "reason", "base"}:
        return True
    return False


async def _guarded(request: Request, call_next):
    login = getattr(request.state, "user", "") or ""
    mem = _memberships(login)
    if mem is None:
        return await call_next(request)
    path, method = request.url.path, request.method
    if path.startswith("/api/admin"):
        return JSONResponse({"detail": "Недостаточно прав: действие доступно только администратору"}, status_code=403)
    scopes = await _request_scopes(request)
    for pid, _sid in scopes:
        if pid not in mem:
            return JSONResponse({"detail": "Нет доступа к этому объекту"}, status_code=403)
    if method not in ("GET", "HEAD", "OPTIONS") and path not in ("/api/profile/password", "/api/whatsnew/ack"):
        body_keys: Optional[set[str]] = None
        if method == "PUT" and path.startswith("/api/acts/"):
            try:
                b = json.loads(await request.body() or b"null")
                body_keys = set(b.keys()) if isinstance(b, dict) else None
            except ValueError:
                body_keys = None
        if scopes:
            for pid, sid in scopes:
                role = _role_in(login, pid, sid) or mem[pid]
                if not _role_may_write(role, method, path, body_keys):
                    who = {"foreman": "Прораб может отмечать работы, добавлять фото и записи входного контроля", "surveyor": "Геодезист может загружать файлы съёмки и формировать схемы", "manager": "Руководитель может менять статусы документов (подписать, в архив), состав команды и состав раздела", "other": "Роль «Только просмотр» не позволяет менять данные"}.get(role, "Недостаточно прав")
                    return JSONResponse({"detail": who}, status_code=403)
        elif not _user_can_manage(login):
            return JSONResponse({"detail": "Недостаточно прав: действие доступно ПТО и администратору"}, status_code=403)
    return await call_next(request)


# ---- блокировка входа: после LOCK_AFTER неверных паролей подряд по одному логину — пауза LOCK_SECS
LOCK_AFTER, LOCK_SECS = 5, 900
_locks: dict[str, list[float]] = {}  # логин → [неудач подряд, заблокирован до]


def _lock_left(login: str) -> int:
    v = _locks.get(login.lower())
    return int(v[1] - time.time()) if v and v[1] > time.time() else 0


def _lock_fail(login: str) -> bool:
    if len(_locks) > 5000:
        _locks.clear()
    v = _locks.setdefault(login.lower(), [0, 0.0])
    if v[1] and v[1] <= time.time():
        v[0], v[1] = 0, 0.0
    v[0] += 1
    if v[0] >= LOCK_AFTER:
        v[1] = time.time() + LOCK_SECS
        return True
    return False


_AUDIT_FIELDS = ("id", "at", "user", "method", "path", "entity", "entity_id", "section_id", "project_id", "action", "summary", "diff_json")


def _audit_hash(prev: str, vals: Any) -> str:
    return hashlib.sha256(("\x1f".join([prev, *[str(v) for v in vals]])).encode("utf-8")).hexdigest()


def _audit_ins(c: sqlite3.Connection, *vals: Any) -> None:
    """Запись в журнал правок с цепочкой хэшей: каждая запись хранит хэш предыдущей, правка задним числом ломает цепочку."""
    for _ in range(8):
        r = c.execute("SELECT hash FROM audit ORDER BY rowid DESC LIMIT 1").fetchone()
        prev = (r[0] if r else "") or ""
        try:
            c.execute("INSERT INTO audit (" + ",".join(_AUDIT_FIELDS) + ",prev_hash,hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)", (*vals, prev, _audit_hash(prev, vals)))
            return
        except sqlite3.IntegrityError:  # параллельная запись заняла это место в цепочке — читаем хвост заново
            continue
    raise RuntimeError("Не удалось записать в журнал правок")


def _sys_audit(summary: str, user: str = "") -> None:
    try:
        with sqlite3.connect(DB_PATH) as c:
            _audit_ins(c, str(uuid.uuid4()), now(), user[:80], "", "", "auth", "", "", "_sys", "Безопасность", summary[:300], "")  # _sys — не показывается в журналах объектов
    except Exception:  # noqa: BLE001
        pass


OPEN_PREFIXES = ("/reset", "/login", "/api/auth/")
COOKIE = "its_session"
SESSION_SECS = 30 * 86400


def _fp(login: str) -> str:
    """Отпечаток пароля: после смены пароля все прежние сессии перестают действовать."""
    if _is_admin(login):
        return hashlib.sha256(APP_PASSWORD_HASH.encode()).hexdigest()[:16]
    try:
        with sqlite3.connect(DB_PATH) as c:
            r = c.execute("SELECT pw_hash FROM dict_users WHERE active=1 AND pw_hash<>'' AND lower(login)=lower(?)", (login,)).fetchone()
    except Exception:
        return ""
    return hashlib.sha256(r[0].encode()).hexdigest()[:16] if r else ""


def _session_create(login: str, ua: str) -> str:
    token = secrets.token_urlsafe(32)
    t = time.time()
    with sqlite3.connect(DB_PATH) as c:
        c.execute("DELETE FROM sessions WHERE expires_at<?", (t,))
        c.execute("INSERT INTO sessions (token_hash,login,fp,created_at,expires_at,last_seen,ua) VALUES (?,?,?,?,?,?,?)",
                  (hashlib.sha256(token.encode()).hexdigest(), login, _fp(login), t, t + SESSION_SECS, t, ua[:200]))
    return token


def _session_user(token: str) -> str:
    if not token:
        return ""
    th = hashlib.sha256(token.encode()).hexdigest()
    t = time.time()
    hit = _ok_cache.get("s:" + th)
    if hit and hit[0] > t:
        return hit[1]
    try:
        with sqlite3.connect(DB_PATH) as c:
            r = c.execute("SELECT login,fp,expires_at,last_seen FROM sessions WHERE token_hash=?", (th,)).fetchone()
            if not r or r[2] < t or r[1] != _fp(r[0]):
                if r:
                    c.execute("DELETE FROM sessions WHERE token_hash=?", (th,))
                return ""
            if t - r[3] > 3600:  # скользящий срок: активный человек не разлогинивается
                c.execute("UPDATE sessions SET last_seen=?, expires_at=? WHERE token_hash=?", (t, t + SESSION_SECS, th))
    except Exception:
        return ""
    if len(_ok_cache) > 400:
        _ok_cache.clear()
    _ok_cache["s:" + th] = (t + 60, r[0])
    return r[0]


def _verify_login(user: str, password: str, ip: str) -> tuple[str, Optional[tuple[int, str]]]:
    """Проверка логина/пароля с блокировками. → (логин сотрудника, None) или ('', (код, сообщение))."""
    t = time.time()
    recent = [x for x in _fails.get(ip, []) if t - x < 300]
    _fails[ip] = recent
    if len(recent) >= 10:
        return "", (429, "Слишком много неверных попыток. Подождите 5 минут.")
    left = 0 if _is_admin(user) else _lock_left(user)
    if left:
        return "", (429, f"Вход заблокирован на {left // 60 + 1} мин. из-за неверных паролей. Восстановите пароль по почте (ссылка «Забыли пароль»).")
    canon = APP_USER if _check_password(user, password) else _auth_personal(user, password)
    if canon:
        _locks.pop(user.lower(), None)
        return canon, None
    _fails[ip].append(t)
    if user and not _is_admin(user) and _lock_fail(user):
        _sys_audit(f"Вход «{user[:40]}» заблокирован на {LOCK_SECS // 60} мин.: {LOCK_AFTER} неверных паролей подряд (адрес {ip})")
        return "", (429, f"Неверный пароль {LOCK_AFTER} раз подряд. Вход заблокирован на {LOCK_SECS // 60} мин. Восстановите пароль по почте (ссылка «Забыли пароль»).")
    return "", (401, "Неверный логин или пароль")


def _is_https(request: Request) -> bool:
    return request.url.scheme == "https" or request.headers.get("x-forwarded-proto", "") == "https" or "https" in request.headers.get("cf-visitor", "")


def _safe_next(n: str) -> str:
    return n if n.startswith("/") and not n.startswith("//") and "\\" not in n else "/"


@app.middleware("http")
async def basic_auth(request: Request, call_next):
    path = request.url.path
    if path in OPEN_PATHS or path.startswith(OPEN_PREFIXES):
        return await call_next(request)
    if not APP_USER or not APP_PASSWORD_HASH:
        return JSONResponse({"detail": "Доступ не настроен: задайте APP_USER и APP_PASSWORD_HASH"}, status_code=503)
    ip = request.headers.get("cf-connecting-ip") or (request.client.host if request.client else "?")
    request.state.user = ""
    user = _session_user(request.cookies.get(COOKIE, ""))
    if user:
        request.state.user = user
        return await _guarded(request, call_next)
    header = request.headers.get("authorization", "")
    if header.lower().startswith("basic "):
        t = time.time()
        key = hashlib.sha256(header.encode()).hexdigest()
        hit = _ok_cache.get(key)
        if hit and hit[0] > t:
            request.state.user = hit[1]
            return await _guarded(request, call_next)
        try:
            u, _, pw = base64.b64decode(header[6:]).decode("utf-8").partition(":")
        except Exception:
            u, pw = "", ""
        canon, err = _verify_login(u, pw, ip)
        if canon:
            if len(_ok_cache) > 400:
                _ok_cache.clear()
            _ok_cache[key] = (t + 3600, canon)
            request.state.user = canon
            return await _guarded(request, call_next)
        return JSONResponse({"detail": err[1]}, status_code=err[0])
    if request.method == "GET" and (path in ("/", "/m") or "text/html" in request.headers.get("accept", "")):
        nxt = path + (("?" + request.url.query) if request.url.query else "")
        return RedirectResponse("/login?next=" + urllib.parse.quote(nxt, safe="/"), status_code=302)
    return JSONResponse({"detail": "Требуется вход"}, status_code=401)


@app.post("/api/auth/login")
def auth_login(request: Request, payload: dict[str, Any]) -> Response:
    ip = request.headers.get("cf-connecting-ip") or (request.client.host if request.client else "?")
    canon, err = _verify_login(str(payload.get("login") or "").strip(), str(payload.get("password") or ""), ip)
    if err:
        return JSONResponse({"detail": err[1]}, status_code=err[0])
    token = _session_create(canon, request.headers.get("user-agent", ""))
    resp = JSONResponse({"message": "Вход выполнен", "next": _safe_next(str(payload.get("next") or "/"))})
    resp.set_cookie(COOKIE, token, max_age=SESSION_SECS, httponly=True, samesite="lax", secure=_is_https(request), path="/")
    return resp


@app.post("/api/auth/logout")
def auth_logout(request: Request) -> Response:
    tok = request.cookies.get(COOKIE, "")
    if tok:
        th = hashlib.sha256(tok.encode()).hexdigest()
        with sqlite3.connect(DB_PATH) as c:
            c.execute("DELETE FROM sessions WHERE token_hash=?", (th,))
        _ok_cache.pop("s:" + th, None)
    resp = JSONResponse({"message": "Вы вышли"})
    resp.delete_cookie(COOKIE, path="/")
    return resp


