@app.get("/login", response_class=HTMLResponse)
def login_page(request: Request) -> Response:
    if _session_user(request.cookies.get(COOKIE, "")):
        return RedirectResponse(_safe_next(request.query_params.get("next", "/")), status_code=302)
    return HTMLResponse(LOGIN_HTML.replace("__VER__", app.version))


@contextmanager
def db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.create_function("lower", 1, lambda v: v.lower() if isinstance(v, str) else v, deterministic=True)  # встроенный lower() не понимает кириллицу
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="microseconds")


