def _learn_catalog(c: sqlite3.Connection, title: str, system: str) -> None:
    """Названия разделов и систем, которых нет в справочниках, добавляются туда."""
    t = " ".join((title or "").split())
    if t and not c.execute("SELECT 1 FROM dict_sectypes WHERE lower(name)=lower(?)", (t,)).fetchone():
        c.execute("INSERT INTO dict_sectypes (id,name,code,kind,created_at) VALUES (?,?,?,?,?)", (str(uuid.uuid4()), t[:300], "", "Свой", now()))
    for tok in re.split(r"[,;]", system or ""):
        tok = tok.strip()
        if tok and not c.execute("SELECT 1 FROM dict_systems WHERE lower(name)=lower(?)", (tok,)).fetchone():
            c.execute("INSERT INTO dict_systems (id,name,created_at) VALUES (?,?,?)", (str(uuid.uuid4()), tok[:80], now()))


def _create_section(c: sqlite3.Connection, project_id: str, code: str, title: str, system: str = "") -> str:
    sid = str(uuid.uuid4())
    try:
        c.execute("INSERT INTO sections VALUES (?,?,?,?,?,?)", (sid, project_id, code.strip(), title.strip(), system.strip(), now()))
    except sqlite3.IntegrityError as exc:
        raise HTTPException(409, "Раздел с таким шифром в проекте уже есть") from exc
    _learn_catalog(c, title, system)
    c.execute("INSERT INTO revisions (id,revision,change_summary,created_by,created_at,section_id) VALUES (?,?,?,?,?,?)",
              (str(uuid.uuid4()), "ПР-01", "Начальная редакция раздела. Состав работ уточнить по проекту и смете.", "ПТО", now(), sid))
    c.execute("INSERT INTO schema_versions (id,section_id,version,reason,state_json,created_by,created_at) VALUES (?,?,?,?,?,?,?)",
              (str(uuid.uuid4()), sid, 1, "Создана начальная версия исполнительной схемы", "[]", "ПТО", now()))
    c.execute("INSERT INTO documents (id,document_type,number,status,created_at,section_id) VALUES (?,?,?,?,?,?)",
              (str(uuid.uuid4()), "АОСР", "Черновик", "Черновик", now(), sid))
    return sid


def _check_participant(p: "ParticipantIn") -> None:
    if p.role not in ROLE_KEYS:
        raise HTTPException(400, f"Неизвестная роль участника: {p.role}")
    for fld, lens, title in (("inn", (10, 12), "ИНН"), ("ogrn", (13, 15), "ОГРН")):
        v = getattr(p, fld).strip()
        if v and not (v.isdigit() and len(v) in lens):
            raise HTTPException(400, f"{title} участника «{dict((r[0], r[1]) for r in ROLES)[p.role]}»: нужно {' или '.join(map(str, lens))} цифр")


def _save_participants(c: sqlite3.Connection, project_id: str, parts: list["ParticipantIn"]) -> None:
    for p in parts:
        _check_participant(p)
    c.execute("DELETE FROM participants WHERE project_id=?", (project_id,))
    for p in parts:
        vals = [getattr(p, f).strip() for f in PART_FIELDS]
        if any(vals):
            c.execute("INSERT INTO participants (id,project_id,role," + ",".join(PART_FIELDS) + ",created_at) VALUES (?,?,?," + ",".join("?" * len(PART_FIELDS)) + ",?)",
                      (str(uuid.uuid4()), project_id, p.role, *vals, now()))
    _relink(c)


def _missing_roles(c: sqlite3.Connection, project_id: str) -> list[str]:
    have = {r["role"]: r for r in c.execute("SELECT * FROM participants WHERE project_id=?", (project_id,))}
    out = []
    for key, label, core in ROLES:
        if core and not (have.get(key) and have[key]["org_name"] and (have[key]["rep_name"] or key not in SIGNERS)):
            out.append(label)
    return out


@app.on_event("startup")
def startup() -> None:
    init_db()
    for nm in ("pending", "boots"):  # обновление через программу успешно стартовало
        try:
            (OVERRIDE_DIR / nm).unlink(missing_ok=True)
        except Exception:  # noqa: BLE001
            pass
    try:  # краткие названия из наборов — для объектов, у которых своё краткое имя ещё не задано
        with db() as c:
            for f in SEEDS_DIR.glob("*.json"):
                o = json.loads(f.read_text(encoding="utf-8")).get("object") or {}
                if o.get("short_name") and o.get("object_name"):
                    c.execute("UPDATE projects SET short_name=? WHERE object_name=? AND short_name=''", (o["short_name"], o["object_name"].strip()))
    except Exception:  # noqa: BLE001
        pass
    threading.Thread(target=_backup_loop, daemon=True).start()
    try:  # «Позиции сметы», созданные из материалов (ПЭ, Колодцы, укрытие манжет…), без отметок — скрываем: материал не работа
        with db() as c:
            for r in c.execute("SELECT e.id,e.planned_note FROM elements e WHERE e.kind='Позиция сметы' AND e.enabled=1").fetchall():
                code = (r["planned_note"] or "").rpartition(" · ")[2].strip() if " · " in (r["planned_note"] or "") else ""
                if code and _is_material(code, "") and not c.execute("SELECT 1 FROM events ev JOIN operations o ON o.id=ev.operation_id WHERE o.element_id=? LIMIT 1", (r["id"],)).fetchone():
                    c.execute("UPDATE elements SET enabled=0 WHERE id=?", (r["id"],))
    except Exception:  # noqa: BLE001
        pass
    try:  # авторы файлов, которых нет ни среди пользователей, ни среди команды (имя из браузера) — убираем
        with db() as c:
            known = {str(r[0]).strip().lower() for r in c.execute("SELECT name FROM team UNION SELECT login FROM team UNION SELECT name FROM dict_users UNION SELECT login FROM dict_users") if r[0]}
            for r in c.execute("SELECT id,uploaded_by FROM source_files WHERE uploaded_by<>''").fetchall():
                u = r["uploaded_by"].strip().lower()
                if u not in known and u not in ("папка сервера", "система", "пто") and u != (APP_USER or "").lower():
                    c.execute("UPDATE source_files SET uploaded_by='' WHERE id=?", (r["id"],))
    except Exception:  # noqa: BLE001
        pass
    try:  # разбор, прерванный перезапуском, — продолжаем
        with db() as c:
            todo = [(r["id"], r["name"]) for r in c.execute("SELECT id,name FROM source_files WHERE status='analyzing'")]
        for fid, nm in todo:
            _start_analysis(fid, nm)
    except Exception:  # noqa: BLE001
        pass


