def _display_name(name: str) -> str:
    """Автоматическое краткое имя (если своё не задано): вид объекта + место, напр. «Универсальный склад · ст-ца Грушевская»."""
    n = " ".join(name.split())
    parts = [x.strip() for x in n.split(",") if x.strip()]
    head = parts[0] if parts else n
    words = head.split()
    kind = " ".join(words[:2]) if len(head) > 40 and len(words) > 2 else head
    place = next((seg for seg in reversed(parts[1:]) if len(re.findall(r"[A-Za-zА-Яа-яЁё]", seg)) >= 4), "")
    out = f"{kind} · {place}" if place else kind
    return out if len(out) <= 60 else out[:58].rstrip() + "…"


