def _section(c: sqlite3.Connection, section_id: Optional[str]) -> sqlite3.Row:
    # Раздел обязателен: молчаливый выбор «первого проекта» приводил к работе не с тем объектом.
    if not section_id:
        raise HTTPException(400, "Не указан раздел (параметр section). Обновите страницу и выберите объект.")
    q = "SELECT s.*, p.object_name, p.address FROM sections s JOIN projects p ON p.id=s.project_id "
    row = c.execute(q + "WHERE s.id=?", (section_id,)).fetchone()
    if not row:
        raise HTTPException(404, "Раздел не найден. Создайте проект.")
    return row


@app.get("/api/roles")
def roles() -> list[dict[str, Any]]:
    return [{"key": k, "label": l, "core": core, "signs": k in SIGNERS} for k, l, core in ROLES]


@app.get("/api/projects")
def projects_list(request: Request) -> list[dict[str, Any]]:
    allowed = _user_projects(getattr(request.state, "user", "") or "")
    with db() as c:
        out = []
        for p in c.execute("SELECT * FROM projects ORDER BY created_at"):
            if allowed is not None and p["id"] not in allowed:
                continue
            secs = [dict(s) for s in c.execute("SELECT id,code,title,system FROM sections WHERE project_id=? ORDER BY created_at", (p["id"],))]
            fc = c.execute("SELECT COUNT(*), COALESCE(SUM(kind='dxf_project'),0) FROM source_files WHERE project_id=?", (p["id"],)).fetchone()
            out.append({"id": p["id"], "object_name": p["object_name"], "address": p["address"], "sections": secs,
                        "short_name": p["short_name"], "display_name": p["short_name"] or _display_name(p["object_name"]),
                        "archived": bool(p["archived"]), "files": fc[0], "dxf_project": fc[1],
                        "missing_roles": len(_missing_roles(c, p["id"]))})
        return out


@app.post("/api/projects", status_code=201)
def create_project(payload: ProjectIn) -> dict[str, str]:
    with db() as c:
        pid = str(uuid.uuid4())
        oname, oshort, oaddr = " ".join(payload.object_name.split()), payload.short_name.strip(), payload.address.strip()
        if payload.object_id:
            ob = c.execute("SELECT * FROM dict_objects WHERE id=?", (payload.object_id,)).fetchone()
            if not ob:
                raise HTTPException(404, "Объект не найден в справочнике")
            oid, oname, oshort, oaddr = ob["id"], ob["name"], ob["short_name"], ob["address"]
        else:
            if not oname:
                raise HTTPException(422, "Укажите название объекта")
            ex = c.execute("SELECT id FROM dict_objects WHERE lower(name)=lower(?)", (oname,)).fetchone()
            oid = ex["id"] if ex else str(uuid.uuid4())
            if not ex:
                c.execute("INSERT INTO dict_objects (id,name,short_name,address,created_at) VALUES (?,?,?,?,?)", (oid, oname, oshort[:60], oaddr, now()))
        if c.execute("SELECT 1 FROM projects WHERE object_id=? AND archived=0", (oid,)).fetchone():
            raise HTTPException(409, "Проект по этому объекту уже есть. Новый раздел добавляется в существующем проекте («Данные объекта» → разделы проекта)")
        c.execute("INSERT INTO projects (id,object_name,address,created_at,short_name,object_id) VALUES (?,?,?,?,?,?)", (pid, oname, oaddr, now(), oshort[:60], oid))
        sid = _create_section(c, pid, payload.section.code, payload.section.title, payload.section.system)
        _save_participants(c, pid, payload.participants)
        started = _take_staged(c, pid, sid, payload.staged, "")
    for fid, nm in started:
        _start_analysis(fid, nm)
    _cleanup_stage()
    return {"project_id": pid, "section_id": sid, "message": "Проект создан"}


@app.get("/api/projects/{project_id}")
def project_detail(project_id: str) -> dict[str, Any]:
    with db() as c:
        p = c.execute("SELECT * FROM projects WHERE id=?", (project_id,)).fetchone()
        if not p:
            raise HTTPException(404, "Проект не найден")
        have = {r["role"]: dict(r) for r in c.execute("SELECT * FROM participants WHERE project_id=?", (project_id,))}
        parts = []
        for key, label, core in ROLES:
            row = have.get(key, {})
            parts.append({"role": key, "label": label, "core": core, **{f: row.get(f, "") for f in PART_FIELDS}})
        secs = [dict(s) for s in c.execute("SELECT id,code,title,system FROM sections WHERE project_id=? ORDER BY created_at", (project_id,))]
        return {"id": p["id"], "object_name": p["object_name"], "address": p["address"], "sections": secs,
                "short_name": p["short_name"], "display_name": p["short_name"] or _display_name(p["object_name"]), "archived": bool(p["archived"]),
                "participants": parts, "missing_roles": _missing_roles(c, project_id),
                "our_role": p["our_role"], "team": _team(c, project_id)}


def _team(c: sqlite3.Connection, project_id: str) -> list[dict[str, Any]]:
    return [dict(r) for r in c.execute("SELECT id,name,position,app_role,role_manual,login,user_id,org_name,valid_from,valid_to FROM team WHERE project_id=? ORDER BY sort_order,created_at", (project_id,))]


@app.get("/api/me")
def me(request: Request, project: str = "") -> dict[str, Any]:
    """Кто вошёл и какой человек из команды объекта ему соответствует (по логину)."""
    login = getattr(request.state, "user", "") or ""
    with db() as c:
        team = _team(c, project) if project else []
        member = next((m for m in team if m["login"] and m["login"].lower() == login.lower()), None)
        if not member and login:
            r = c.execute("SELECT name,position,app_role,login FROM team WHERE lower(login)=lower(?) LIMIT 1", (login,)).fetchone()
            member = dict(r) if r else None
        if not member and login:
            r = c.execute("SELECT name,position,app_role,login FROM dict_users WHERE lower(login)=lower(?) AND active=1 LIMIT 1", (login,)).fetchone()
            member = dict(r) if r else None
    return {"login": login, "member": member, "team": team}


@app.get("/api/projects/{project_id}/team")
def team_get(project_id: str) -> list[dict[str, Any]]:
    with db() as c:
        return _team(c, project_id)


_APPROLE_RU = {"pto": "ПТО", "manager": "руководитель", "surveyor": "геодезист", "foreman": "прораб", "other": "только просмотр"}


def _member_line(m: dict[str, Any]) -> str:
    per = (("с " + m["valid_from"]) if m.get("valid_from") else "") + ((" по " + m["valid_to"]) if m.get("valid_to") else "")
    return ", ".join(x for x in (m.get("position", ""), m.get("org_name", ""), "роль в программе: " + _APPROLE_RU.get(m.get("app_role", ""), ""), ("логин " + m["login"]) if m.get("login") else "", ("участие " + per.strip()) if per else "") if x)


def _team_audit(request: Request, c: sqlite3.Connection, pid: str, before: list[dict[str, Any]], after: list[dict[str, Any]]) -> None:
    b = {m["name"].lower(): m for m in before}
    a = {m["name"].lower(): m for m in after}
    diff: dict[str, list[str]] = {}
    parts: list[str] = []
    for k, m in a.items():
        if k not in b:
            diff["Добавлен в команду: " + m["name"]] = ["", _member_line(m)]
            parts.append("добавлен " + m["name"])
        elif _member_line(b[k]) != _member_line(m):
            diff["Изменены данные: " + m["name"]] = [_member_line(b[k]), _member_line(m)]
            parts.append("изменены данные " + m["name"])
    for k, m in b.items():
        if k not in a:
            diff["Убран из команды: " + m["name"]] = [_member_line(m), ""]
            parts.append("убран " + m["name"])
    if diff:
        audit(request, c, "team", pid, "update", "Команда объекта: " + "; ".join(parts), diff, project_id=pid)
    else:
        request.state.audited = True


@app.put("/api/projects/{project_id}/team")
def team_put(request: Request, project_id: str, payload: list[TeamMember]) -> dict[str, Any]:
    with db() as c:
        if not c.execute("SELECT 1 FROM projects WHERE id=?", (project_id,)).fetchone():
            raise HTTPException(404, "Проект не найден")
        team_before = _team(c, project_id)
        c.execute("DELETE FROM team WHERE project_id=?", (project_id,))
        for m in payload:
            if len(m.name.split()) < 2:
                raise HTTPException(422, "Укажите фамилию, имя и отчество (если есть) полностью: «" + m.name.strip() + "»")
            if not m.position.strip():
                raise HTTPException(422, "Укажите должность: «" + m.name.strip() + "» — должность и ФИО обязательны для записей в журнале")
            for dv in (m.valid_from, m.valid_to):
                if dv:
                    try:
                        date.fromisoformat(dv)
                    except ValueError:
                        raise HTTPException(422, "Дата участия «" + dv + "» указана неверно (нужен вид ГГГГ-ММ-ДД)")
            if m.valid_from and m.valid_to and m.valid_to < m.valid_from:
                raise HTTPException(422, "«" + m.name.strip() + "»: дата окончания участия раньше даты начала")
        for i, m in enumerate(payload):
            u = c.execute("SELECT id,login,org_name FROM dict_users WHERE id=?", (m.user_id,)).fetchone() if m.user_id else None
            if not u:
                u = c.execute("SELECT id,login,org_name FROM dict_users WHERE lower(name)=lower(?) LIMIT 1", (m.name.strip(),)).fetchone()
            # нет в справочниках — добавляем туда (организация, должность, сотрудник)
            og, ps_, nm_ = m.org_name.strip(), m.position.strip(), " ".join(m.name.split())
            if og and not c.execute("SELECT 1 FROM dict_orgs WHERE lower(name)=lower(?)", (og,)).fetchone():
                c.execute("INSERT INTO dict_orgs (id,name,created_at) VALUES (?,?,?)", (str(uuid.uuid4()), og, now()))
            if ps_ and not c.execute("SELECT 1 FROM dict_positions WHERE lower(name)=lower(?)", (ps_,)).fetchone():
                c.execute("INSERT INTO dict_positions (id,name,created_at) VALUES (?,?,?)", (str(uuid.uuid4()), ps_, now()))
            if not u:
                lg = m.login.strip()
                if lg and c.execute("SELECT 1 FROM dict_users WHERE lower(login)=lower(?)", (lg,)).fetchone():
                    raise HTTPException(409, "Логин «" + lg + "» уже есть у другого пользователя")
                uid_new = str(uuid.uuid4())
                c.execute("INSERT INTO dict_users (id,name,position,org_name,login,app_role,created_at) VALUES (?,?,?,?,?,?,?)", (uid_new, nm_, ps_, og, lg, m.app_role if m.app_role in APP_ROLES else _role_for_position(ps_), now()))
                u = c.execute("SELECT id,login,org_name FROM dict_users WHERE id=?", (uid_new,)).fetchone()
            uid = u["id"] if u else ""
            login = m.login.strip() or (u["login"] if u else "")
            org = m.org_name.strip() or (u["org_name"] if u else "")
            if m.app_role == "auto":  # по должности; если у сотрудника в справочнике роль задана вручную — берём её
                ur = c.execute("SELECT app_role,role_manual FROM dict_users WHERE id=?", (uid,)).fetchone() if uid else None
                role = ur["app_role"] if ur and ur["role_manual"] else _role_for_position(ps_)
                manual = 0
            else:
                role, manual = m.app_role, (1 if m.role_manual is None else int(m.role_manual))
            c.execute("INSERT INTO team (id,project_id,name,position,app_role,role_manual,login,user_id,org_name,sort_order,created_at,valid_from,valid_to) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
                      (str(uuid.uuid4()), project_id, m.name.strip(), m.position.strip(), role, manual, login, uid, org, i, now(), m.valid_from, m.valid_to))
        _relink(c)
        team_after = _team(c, project_id)
        _team_audit(request, c, project_id, team_before, team_after)
        return {"message": "Команда сохранена", "team": team_after}


@app.get("/api/projects/{project_id}/team-roles")
def team_roles_get(project_id: str) -> dict[str, Any]:
    """Права участников по разделам: по умолчанию роль на объекте, можно задать свою роль в отдельном разделе."""
    with db() as c:
        if not c.execute("SELECT 1 FROM projects WHERE id=?", (project_id,)).fetchone():
            raise HTTPException(404, "Проект не найден")
        secs = [dict(r) for r in c.execute("SELECT id,code,title FROM sections WHERE project_id=? ORDER BY created_at", (project_id,))]
        ov: dict[str, dict[str, str]] = {}
        for r in c.execute("SELECT member_key,section_id,role FROM team_sections WHERE project_id=?", (project_id,)):
            ov.setdefault(r["member_key"], {})[r["section_id"]] = r["role"]
        members = [{"name": m["name"], "position": m["position"], "role": m["app_role"], "key": m["name"].strip().lower()} for m in _team(c, project_id)]
        return {"sections": secs, "members": members, "overrides": ov, "roles": {k: APP_ROLE_RU[k] for k in APP_ROLES}}


@app.put("/api/projects/{project_id}/team-roles")
def team_roles_put(request: Request, project_id: str, payload: dict[str, Any]) -> dict[str, str]:
    """payload: {key: участник (ФИО в нижнем регистре), roles: {section_id: роль | ''}} — пустая роль возвращает «как на объекте»."""
    key = str(payload.get("key") or "").strip().lower()
    roles = payload.get("roles") or {}
    with db() as c:
        team = {m["name"].strip().lower(): m for m in _team(c, project_id)}
        if key not in team:
            raise HTTPException(404, "Участника нет в команде объекта")
        secs = {r["id"]: r["code"] for r in c.execute("SELECT id,code FROM sections WHERE project_id=?", (project_id,))}
        before = {r["section_id"]: r["role"] for r in c.execute("SELECT section_id,role FROM team_sections WHERE project_id=? AND member_key=?", (project_id, key))}
        for sid, role in roles.items():
            if sid not in secs:
                raise HTTPException(422, "Раздел не из этого объекта")
            if role and role not in APP_ROLES:
                raise HTTPException(422, "Неизвестная роль")
            c.execute("DELETE FROM team_sections WHERE project_id=? AND member_key=? AND section_id=?", (project_id, key, sid))
            if role and role != team[key]["app_role"]:
                c.execute("INSERT INTO team_sections (project_id,member_key,section_id,role) VALUES (?,?,?,?)", (project_id, key, sid, role))
        after = {r["section_id"]: r["role"] for r in c.execute("SELECT section_id,role FROM team_sections WHERE project_id=? AND member_key=?", (project_id, key))}
        diff = {f"Раздел {secs.get(k, k)}": [APP_ROLE_RU.get(before.get(k, ""), "как на объекте"), APP_ROLE_RU.get(after.get(k, ""), "как на объекте")] for k in secs if before.get(k) != after.get(k)}
        if diff:
            audit(request, c, "team", project_id, "update", f"Права по разделам: {team[key]['name']}", diff, project_id=project_id)
    return {"message": "Сохранено"}


@app.put("/api/projects/{project_id}")
def update_project(request: Request, project_id: str, payload: ProjectUpdate) -> dict[str, str]:
    with db() as c:
        p0 = c.execute("SELECT * FROM projects WHERE id=?", (project_id,)).fetchone()
        if not p0:
            raise HTTPException(404, "Проект не найден")
        _p_before = dict(p0)
        if payload.object_name is not None:
            c.execute("UPDATE projects SET object_name=? WHERE id=?", (payload.object_name.strip(), project_id))
        if payload.address is not None:
            c.execute("UPDATE projects SET address=? WHERE id=?", (payload.address.strip(), project_id))
        if payload.short_name is not None:
            c.execute("UPDATE projects SET short_name=? WHERE id=?", (payload.short_name.strip(), project_id))
        if payload.our_role is not None:
            if payload.our_role and payload.our_role not in ROLE_KEYS:
                raise HTTPException(400, "Неизвестная роль")
            c.execute("UPDATE projects SET our_role=? WHERE id=?", (payload.our_role, project_id))
        if payload.archived is not None:
            c.execute("UPDATE projects SET archived=? WHERE id=?", (1 if payload.archived else 0, project_id))
        pr = c.execute("SELECT object_id,object_name,short_name,address FROM projects WHERE id=?", (project_id,)).fetchone()
        if pr["object_id"] and (payload.object_name is not None or payload.address is not None or payload.short_name is not None):
            try:
                c.execute("UPDATE dict_objects SET name=?, short_name=?, address=? WHERE id=?", (pr["object_name"], pr["short_name"], pr["address"], pr["object_id"]))
            except sqlite3.IntegrityError:
                raise HTTPException(409, "Объект с таким названием уже есть в справочнике")
        p1 = dict(c.execute("SELECT * FROM projects WHERE id=?", (project_id,)).fetchone())
        rl = {k: l for k, l, _ in ROLES}
        _lab = {"object_name": "Название объекта", "short_name": "Краткое наименование", "address": "Адрес", "our_role": "Наша роль на объекте", "archived": "В архиве"}
        _fm = lambda k, v: (rl.get(v, v) if k == "our_role" else (("да" if v else "нет") if k == "archived" else str(v or "")))
        pdf = {_lab[k]: [_fm(k, _p_before.get(k)), _fm(k, p1.get(k))] for k in _lab if str(_p_before.get(k) or "") != str(p1.get(k) or "")}
        if pdf:
            audit(request, c, "project", project_id, "update", "Данные объекта изменены: " + ", ".join(pdf), pdf, project_id=project_id)
        else:
            request.state.audited = True
    return {"message": "Сохранено"}


def _part_lines(c: sqlite3.Connection, pid: str) -> dict[str, str]:
    lab = {k: l for k, l, _ in ROLES}
    out: dict[str, str] = {}
    for r in c.execute("SELECT * FROM participants WHERE project_id=?", (pid,)):
        out[lab.get(r["role"], r["role"])] = "; ".join(x for x in (r["org_name"], (r["rep_position"] + " " + r["rep_name"]).strip(), ("ОГРН " + r["ogrn"]) if r["ogrn"] else "", ("ИНН " + r["inn"]) if r["inn"] else "", r["address"], r["phone"], r["sro"], r["rep_order"]) if x)
    return out


@app.put("/api/projects/{project_id}/participants")
def save_participants(request: Request, project_id: str, payload: list[ParticipantIn]) -> dict[str, Any]:
    with db() as c:
        if not c.execute("SELECT 1 FROM projects WHERE id=?", (project_id,)).fetchone():
            raise HTTPException(404, "Проект не найден")
        pbefore = _part_lines(c, project_id)
        _save_participants(c, project_id, payload)
        pafter = _part_lines(c, project_id)
        pd = {lab: [pbefore.get(lab, ""), pafter.get(lab, "")] for lab in dict.fromkeys(list(pbefore) + list(pafter)) if pbefore.get(lab, "") != pafter.get(lab, "")}
        if pd:
            audit(request, c, "participants", project_id, "update", "Участники строительства изменены: " + ", ".join(pd), pd, project_id=project_id)
        else:
            request.state.audited = True
        return {"message": "Участники сохранены", "missing_roles": _missing_roles(c, project_id)}


