class SectionUpdate(BaseModel):
    code: Optional[str] = Field(default=None, min_length=1, max_length=80)
    title: Optional[str] = Field(default=None, min_length=1, max_length=300)
    system: Optional[str] = Field(default=None, max_length=200)


@app.put("/api/sections/{section_id}")
def update_section(request: Request, section_id: str, payload: SectionUpdate) -> dict[str, str]:
    with db() as c:
        s0 = c.execute("SELECT * FROM sections WHERE id=?", (section_id,)).fetchone()
        if not s0:
            raise HTTPException(404, "Раздел не найден")
        new = {k: (getattr(payload, k).strip() if getattr(payload, k) is not None else s0[k]) for k in ("code", "title", "system")}
        if not new["code"] or not new["title"]:
            raise HTTPException(400, "Шифр и наименование раздела не могут быть пустыми")
        try:
            c.execute("UPDATE sections SET code=?, title=?, system=? WHERE id=?", (new["code"], new["title"], new["system"], section_id))
        except sqlite3.IntegrityError as exc:
            raise HTTPException(409, "Раздел с таким шифром в этом проекте уже есть") from exc
        lab = {"code": "Шифр", "title": "Наименование", "system": "Система"}
        diff = {lab[k]: [s0[k], new[k]] for k in lab if s0[k] != new[k]}
        if diff:
            audit(request, c, "section", section_id, "update", "Данные раздела изменены: " + ", ".join(diff), diff, project_id=s0["project_id"])
        else:
            request.state.audited = True
    return {"message": "Сохранено"}


@app.delete("/api/projects/{project_id}")
def delete_project(project_id: str) -> dict[str, str]:
    with db() as c:
        if c.execute("""SELECT 1 FROM events e JOIN operations o ON o.id=e.operation_id JOIN elements el ON el.id=o.element_id
                        JOIN sections s ON s.id=el.section_id WHERE s.project_id=? LIMIT 1""", (project_id,)).fetchone():
            raise HTTPException(409, "В проекте есть отметки выполнения — удалить нельзя")
        sids = [r["id"] for r in c.execute("SELECT id FROM sections WHERE project_id=?", (project_id,))]
        pids: list[str] = []
        for sid in sids:
            pids += [r["id"] for r in c.execute("SELECT id FROM photos WHERE operation_id IN (SELECT op.id FROM operations op JOIN elements el ON el.id=op.element_id WHERE el.section_id=?)", (sid,))]
            c.execute("DELETE FROM photos WHERE operation_id IN (SELECT op.id FROM operations op JOIN elements el ON el.id=op.element_id WHERE el.section_id=?)", (sid,))
            c.execute("DELETE FROM operations WHERE element_id IN (SELECT id FROM elements WHERE section_id=?)", (sid,))
            for t in ("elements", "revisions", "schema_versions", "documents"):
                c.execute(f"DELETE FROM {t} WHERE section_id=?", (sid,))
        c.execute("DELETE FROM sections WHERE project_id=?", (project_id,))
        c.execute("DELETE FROM participants WHERE project_id=?", (project_id,))
        c.execute("DELETE FROM team WHERE project_id=?", (project_id,))
        fids = [r["id"] for r in c.execute("SELECT id FROM source_files WHERE project_id=?", (project_id,))]
        c.execute("DELETE FROM source_files WHERE project_id=?", (project_id,))
        c.execute("DELETE FROM projects WHERE id=?", (project_id,))
    for fid in fids:
        try:
            (FILES_DIR / fid).unlink()
        except OSError:
            pass
    for pid in pids:
        try:
            (PHOTOS_DIR / pid).unlink()
        except OSError:
            pass
    return {"message": "Проект удалён"}


@app.get("/api/overview")
def overview(request: Request, section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        s = _section(c, section)
        sid = s["id"]
        locked = _list_locked(request, c, s)
        total = c.execute("SELECT COUNT(*) FROM elements WHERE section_id=? AND enabled=1 AND scope=''", (sid,)).fetchone()[0]
        ops = c.execute("SELECT COUNT(*) FROM operations o JOIN elements el ON el.id=o.element_id WHERE el.section_id=? AND el.enabled=1 AND el.scope=''", (sid,)).fetchone()[0]
        done = c.execute("""SELECT COUNT(*) FROM operations o JOIN elements el ON el.id=o.element_id
                            WHERE el.section_id=? AND el.enabled=1 AND el.scope=''
                            AND (SELECT e.event_type FROM events e WHERE e.operation_id=o.id ORDER BY e.created_at DESC LIMIT 1)='complete'""", (sid,)).fetchone()[0]
        docs = c.execute("SELECT COUNT(*) FROM documents WHERE section_id=? AND status!='Принят'", (sid,)).fetchone()[0]
        ver = c.execute("SELECT COALESCE(MAX(version),0) FROM schema_versions WHERE section_id=?", (sid,)).fetchone()[0]
        rev = c.execute("SELECT revision FROM revisions WHERE section_id=? ORDER BY created_at DESC LIMIT 1", (sid,)).fetchone()
        project = {"object_name": s["object_name"], "address": s["address"], "section_code": s["code"], "section_title": s["title"],
                   "system": s["system"], "revision": rev["revision"] if rev else "—", "project_id": s["project_id"]}
        return {"project": project, "elements": total, "operations": ops, "completed": done, "documents_pending": docs,
                "list_locked": locked, "list_locked_msg": LIST_LOCKED_MSG if locked else "",
                "wz_notices": _wz2_notices_for(c, sid, getattr(request.state, "user", "") or ""),
                "schema_version": ver, "missing_roles": _missing_roles(c, s["project_id"]),
                "out_of_order": c.execute("""SELECT COUNT(*) FROM events e JOIN operations o ON o.id=e.operation_id JOIN elements el ON el.id=o.element_id
                                          WHERE el.section_id=? AND e.note LIKE '[ВНЕ ОЧЕРЕДИ]%'""", (sid,)).fetchone()[0],
                "dxf_project": c.execute("SELECT COUNT(*) FROM source_files WHERE project_id=? AND kind='dxf_project'", (s["project_id"],)).fetchone()[0]}


def _elements(c: sqlite3.Connection, section_id: str) -> list[dict[str, Any]]:
    rows = c.execute("""
      SELECT el.*, op.id operation_id, op.title operation_title, op.code operation_code,
        (SELECT e.event_type FROM events e WHERE e.operation_id=op.id ORDER BY e.created_at DESC LIMIT 1) event_type,
        (SELECT e.performed_on FROM events e WHERE e.operation_id=op.id ORDER BY e.created_at DESC LIMIT 1) performed_on,
        (SELECT e.actor FROM events e WHERE e.operation_id=op.id ORDER BY e.created_at DESC LIMIT 1) actor,
        (SELECT e.note FROM events e WHERE e.operation_id=op.id ORDER BY e.created_at DESC LIMIT 1) note,
        (SELECT COUNT(*) FROM photos ph WHERE ph.operation_id=op.id) photos, op.hidden hidden_raw, op.code ocode_
      FROM elements el JOIN operations op ON op.element_id=el.id
      WHERE el.enabled=1 AND COALESCE(el.scope,'')='' AND el.section_id=? ORDER BY el.block, el.created_at, el.code, op.sort_order
    """, (section_id,)).fetchall()
    result: dict[str, dict[str, Any]] = {}
    for row in rows:
        item = dict(row)
        key = item["id"]
        if key not in result:
            result[key] = {k: item[k] for k in ("id", "code", "name", "kind", "block", "planned_note", "source", "weight")}
            result[key]["operations"] = []
        op_d = {k: item[k] for k in ("operation_id", "operation_title", "operation_code", "event_type", "performed_on", "actor", "note", "photos")}
        op_d["hidden"] = is_hidden_work(item["hidden_raw"], item["operation_code"], item["operation_title"], item["name"])
        result[key]["operations"].append(op_d)
    return list(result.values())


@app.get("/api/elements")
def elements(request: Request, section: Optional[str] = None) -> list[dict[str, Any]]:
    with db() as c:
        sec = _section(c, section)
        if _list_locked(request, c, sec):
            return []          # прорабу перечень не показываем, пока ПТО не нажал «Завершить» (сообщение — в /api/overview)
        return _elements(c, sec["id"])


@app.post("/api/elements", status_code=201)
def add_element(payload: ElementIn, section: Optional[str] = None) -> dict[str, str]:
    eid = str(uuid.uuid4())
    try:
        with db() as c:
            sid = _section(c, section)["id"]
            c.execute("INSERT INTO elements (id,section_id,code,name,kind,block,planned_note,enabled,created_at) VALUES (?,?,?,?,?,?,?,1,?)", (eid, sid, payload.code.strip(), payload.name.strip(), payload.kind.strip(), payload.block.strip(), payload.planned_note.strip(), now()))
            for order, (code, title) in enumerate((("install", "Монтаж выполнен"), ("survey", "Исполнительная съёмка получена"), ("test", "Испытание / проверка выполнены")), 1):
                c.execute("INSERT INTO operations (id,element_id,code,title,sort_order) VALUES (?,?,?,?,?)", (str(uuid.uuid4()), eid, code, title, order))
    except sqlite3.IntegrityError as exc:
        raise HTTPException(409, "Код объекта в этом разделе уже существует") from exc
    return {"id": eid, "message": "Элемент добавлен"}


@app.post("/api/events", status_code=201)
def add_event(request: Request, payload: EventIn) -> dict[str, Any]:
    with db() as c:
        sr = c.execute("SELECT s.* FROM operations o JOIN elements el ON el.id=o.element_id JOIN sections s ON s.id=el.section_id WHERE o.id=?", (payload.operation_id,)).fetchone()
        if sr and _list_locked(request, c, sr):
            raise HTTPException(423, LIST_LOCKED_MSG)
        existing = c.execute("SELECT id FROM events WHERE client_request_id=?", (payload.client_request_id,)).fetchone()
        if existing:
            return {"id": existing["id"], "message": "Повторная отправка распознана; запись не продублирована"}
        op = c.execute("SELECT id FROM operations WHERE id=?", (payload.operation_id,)).fetchone()
        if not op:
            raise HTTPException(404, "Операция не найдена")
        last = c.execute("SELECT event_type FROM events WHERE operation_id=? ORDER BY created_at DESC LIMIT 1", (payload.operation_id,)).fetchone()
        is_done = bool(last and last["event_type"] == "complete")
        event_type = payload.event_type or ("undo" if is_done else "complete")
        if event_type == "complete" and is_done:
            raise HTTPException(409, "Операция уже отмечена выполненной. Обновите страницу.")
        if event_type == "undo" and not is_done:
            raise HTTPException(409, "Отметка уже снята или не ставилась. Обновите страницу.")
        # --- контроль последовательности работ внутри элемента (по порядку операций перечня)
        ops = c.execute("""SELECT o.id, o.title,
            (SELECT e.event_type FROM events e WHERE e.operation_id=o.id ORDER BY e.created_at DESC LIMIT 1) last
            FROM operations o WHERE o.element_id=(SELECT element_id FROM operations WHERE id=?) ORDER BY o.sort_order""", (payload.operation_id,)).fetchall()
        idx = next(i for i, o in enumerate(ops) if o["id"] == payload.operation_id)
        violation = ""
        if event_type == "complete":
            miss = [o for o in ops[:idx] if o["last"] != "complete"]
            if miss:
                violation = f"Нарушена последовательность: сначала нужно отметить «{miss[0]['title']}»"
        else:
            later = [o for o in ops[idx + 1:] if o["last"] == "complete"]
            if later:
                violation = f"Нарушена последовательность: сначала снимите отметку «{later[-1]['title']}»"
        note = payload.note.strip()
        if violation:
            if not payload.out_of_order:
                raise HTTPException(409, violation)
            if not note:
                raise HTTPException(400, "Для отметки вне очереди укажите причину")
            note = "[ВНЕ ОЧЕРЕДИ] " + note
        event_id = str(uuid.uuid4())
        c.execute("INSERT INTO events VALUES (?,?,?,?,?,?,?,?)", (event_id, payload.operation_id, event_type, payload.performed_on.isoformat(), payload.actor.strip(), note, now(), payload.client_request_id))
        return {"id": event_id, "event_type": event_type, "message": "Отметка сохранена в истории"}


@app.get("/api/history")
def history(section: Optional[str] = None) -> dict[str, list[dict[str, Any]]]:
    with db() as c:
        sid = _section(c, section)["id"]
        revisions = [dict(r) for r in c.execute("SELECT * FROM revisions WHERE section_id=? ORDER BY created_at DESC", (sid,))]
        schemas = [dict(r) for r in c.execute("SELECT id,version,reason,created_by,created_at FROM schema_versions WHERE section_id=? ORDER BY version DESC", (sid,))]
        events = [dict(r) for r in c.execute("""SELECT e.*,o.title operation_title,el.code element_code FROM events e JOIN operations o ON o.id=e.operation_id JOIN elements el ON el.id=o.element_id WHERE el.section_id=? ORDER BY e.created_at DESC LIMIT 30""", (sid,))]
        return {"project_revisions": revisions, "schema_versions": schemas, "events": events}


def _ozhr_items(c: sqlite3.Connection, sec: sqlite3.Row) -> list[dict[str, Any]]:
    return ozhr_build(c, sec)["items"]


@app.get("/api/ozhr")
def ozhr(section: Optional[str] = None) -> dict[str, Any]:
    """Общий журнал работ (форма — приказ Минстроя России от 02.12.2022 № 1026/пр): раздел 1 — ИТР, раздел 3 — выполнение работ.
    Записи раздела 3 появляются по мере отметок, снятая отметка убирает запись."""
    with db() as c:
        return ozhr_build(c, _section(c, section))


def ozhr_build(c: sqlite3.Connection, sec: sqlite3.Row) -> dict[str, Any]:
    if True:
        sid = sec["id"]
        team = _team(c, sec["project_id"])
        wx = {r["day"]: r["text"] for r in c.execute("SELECT day,text FROM weather WHERE project_id=?", (sec["project_id"],))}
        pos = {m["name"]: m["position"] for m in team}
        rows = c.execute("""
          SELECT el.code element_code, el.name element_name, el.block, el.planned_note, o.id operation_id, o.title operation_title, o.sort_order,
                 e.performed_on, e.actor, e.note, e.created_at, e.id event_id,
                 (SELECT l.old_actor FROM event_actor_log l WHERE l.event_id=e.id ORDER BY l.at LIMIT 1) actor_orig
          FROM operations o JOIN elements el ON el.id=o.element_id
          JOIN events e ON e.id=(SELECT e2.id FROM events e2 WHERE e2.operation_id=o.id ORDER BY e2.created_at DESC LIMIT 1)
          WHERE el.section_id=? AND e.event_type='complete' ORDER BY e.performed_on, e.created_at""", (sid,)).fetchall()
        actmap: dict[str, list[dict[str, str]]] = {}
        for m in c.execute("""SELECT ao.operation_id, d.id, d.number, d.status FROM act_ops ao JOIN documents d ON d.id=ao.doc_id
                              WHERE d.section_id=? ORDER BY d.seq, d.created_at""", (sid,)):
            actmap.setdefault(m["operation_id"], []).append({"id": m["id"], "number": m["number"], "status": m["status"]})
        mats: dict[str, list[str]] = {}
        for m in c.execute("""SELECT ao.operation_id, ic.name, ic.doc_ref FROM act_ops ao JOIN act_batches ab ON ab.doc_id=ao.doc_id JOIN input_control ic ON ic.id=ab.vhk_id
                              WHERE ao.operation_id IN (SELECT o2.id FROM operations o2 JOIN elements e2 ON e2.id=o2.element_id WHERE e2.section_id=?)""", (sid,)):
            t = m["name"] + (f" ({m['doc_ref']})" if (m["doc_ref"] or "").strip() else "")
            if t not in mats.setdefault(m["operation_id"], []):
                mats[m["operation_id"]].append(t)
        items = []
        for i, r in enumerate(rows, 1):
            d = dict(r)
            d["n"] = i
            d["out_of_order"] = d["note"].startswith("[ВНЕ ОЧЕРЕДИ]")
            d["weather"] = wx.get(d["performed_on"], "")
            d["actor_position"] = pos.get(d["actor"], "")
            d["actor_ok"] = bool(d["actor_position"]) and len((d["actor"] or "").split()) >= 2
            d["work_name"] = f"{d['block']}: {d['element_name']} {d['element_code']} — {d['operation_title']}" + (f" ({d['planned_note']})" if d["planned_note"] else "")
            d["acts"] = actmap.get(d["operation_id"], [])
            if mats.get(d["operation_id"]):
                d["work_name"] += ". Применены: " + "; ".join(mats[d["operation_id"]])
            items.append(d)
        used = [r[0] for r in c.execute("SELECT DISTINCT text FROM weather WHERE text<>'' ORDER BY updated_at DESC LIMIT 30")]
        bad = sorted({(x["actor"] or "(не указан)") for x in items if not x["actor_ok"]})
        return {"items": items, "bad_actors": bad, "out_of_order": sum(1 for x in items if x["out_of_order"]), "staff": team, "weather_used": used,
                "section": {"code": sec["code"], "title": sec["title"], "object_name": sec["object_name"]}}



