OZHR_META_KEYS = ("number", "kind", "permit", "expertise", "gsn_org", "gsn_official", "gsn_order", "obj_info", "start", "end", "pages", "period_from", "period_to")


def _short_fio(n: str) -> str:
    w = n.replace(".", ". ").split()
    if len(w) >= 2 and len(w[1]) > 2:
        return w[0] + " " + "".join(x[0] + "." for x in w[1:3])
    return " ".join(w)


def _fd(d: str) -> str:
    return f"{d[8:10]}.{d[5:7]}.{d[:4]}" if d and len(d) >= 10 and d[4] == "-" else (d or "")


def _ozhr_meta(c: sqlite3.Connection, sid: str) -> dict[str, str]:
    r = c.execute("SELECT data_json FROM ozhr_meta WHERE section_id=?", (sid,)).fetchone()
    d = json.loads(r["data_json"]) if r else {}
    return {k: str(d.get(k, "")) for k in OZHR_META_KEYS}


def _ozhr_rows(c: sqlite3.Connection, sid: str) -> dict[int, list[dict[str, Any]]]:
    out: dict[int, list[dict[str, Any]]] = {2: [], 4: [], 6: []}
    for r in c.execute("SELECT * FROM ozhr_rows WHERE section_id=? ORDER BY part, sort_order, created_at", (sid,)):
        if r["part"] in out:
            out[r["part"]].append({"id": r["id"], **json.loads(r["data_json"] or "{}")})
    return out


def _ozhr_sign_person(ppl: dict[str, dict[str, Any]], role: str) -> str:
    p = ppl.get(role) or {}
    return ", ".join(x for x in (p.get("rep_position", ""), _short_fio(p.get("rep_name", ""))) if x)


def _ozhr_staff_manual(c: sqlite3.Connection, sid: str) -> dict[str, dict[str, str]]:
    r = c.execute("SELECT v FROM kv WHERE k=?", ("ozs1:" + sid,)).fetchone()
    try:
        return json.loads(r["v"]) if r else {}
    except ValueError:
        return {}


@app.put("/api/ozhr/staff")
def ozhr_staff_put(request: Request, payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    """Раздел 1 ОЖР: вручную задать дату окончания работ и подпись человека; пустое значение возвращает автоматический расчёт."""
    name = str(payload.get("name") or "").strip()
    end = str(payload.get("end") or "").strip()
    sign = " ".join(str(payload.get("sign") or "").split())[:200]
    if end and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", end):
        raise HTTPException(422, "Дата окончания — в формате ГГГГ-ММ-ДД")
    with db() as c:
        sec = _section(c, section)
        _doc_lock(c, sec["id"], "ozhr")
        if not c.execute("SELECT 1 FROM team WHERE project_id=? AND name=?", (sec["project_id"], name)).fetchone():
            raise HTTPException(404, "Такого человека нет в команде объекта")
        man = _ozhr_staff_manual(c, sec["id"])
        old = man.get(name, {})
        if end or sign:
            man[name] = {"end": end, "sign": sign}
        else:
            man.pop(name, None)
        c.execute("INSERT INTO kv (k,v) VALUES (?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v", ("ozs1:" + sec["id"], json.dumps(man, ensure_ascii=False)))
        audit(request, c, "ozhr", sec["id"], "update", f"ОЖР, раздел 1: «{_short_fio(name)}» — дата окончания и подпись изменены вручную",
              {"Дата окончания": [old.get("end", ""), end], "Подпись": [old.get("sign", ""), sign]}, section_id=sec["id"])
    return {"message": "Сохранено"}


def _ozhr_auto(c: sqlite3.Connection, sec: sqlite3.Row) -> dict[str, Any]:
    """Автоматические части журнала: раздел 1 (ИТР), раздел 2 (ЖВК), раздел 5 (подписанные акты и выданные схемы)."""
    sid, pid = sec["id"], sec["project_id"]
    ppl = _act_people(c, pid)
    p = c.execute("SELECT our_role FROM projects WHERE id=?", (pid,)).fetchone()
    our = (p["our_role"] if p else "") or ""
    org = (ppl.get(our) or ppl.get("contractor") or {}).get("org_name", "")
    rep_sign = _ozhr_sign_person(ppl, our if our in ppl else "contractor")
    first: dict[str, str] = {}
    for r in c.execute("SELECT e.actor, MIN(e.performed_on) d FROM events e JOIN operations o ON o.id=e.operation_id JOIN elements el ON el.id=o.element_id WHERE el.section_id=? AND e.event_type='complete' GROUP BY e.actor", (sid,)):
        first[r["actor"]] = r["d"] or ""
    staff = []
    j0 = min((v for v in first.values() if v), default="")
    last: dict[str, str] = {}
    tot = done = 0
    for r in c.execute("""SELECT e.actor, e.event_type, e.performed_on FROM operations o JOIN elements el ON el.id=o.element_id
                          JOIN events e ON e.id=(SELECT e2.id FROM events e2 WHERE e2.operation_id=o.id ORDER BY e2.created_at DESC LIMIT 1)
                          WHERE el.section_id=?""", (sid,)):
        tot += 1
        if r["event_type"] == "complete":
            done += 1
            last[r["actor"]] = max(last.get(r["actor"], ""), r["performed_on"] or "")
    tot_ops = c.execute("SELECT COUNT(*) FROM operations o JOIN elements el ON el.id=o.element_id WHERE el.section_id=?", (sid,)).fetchone()[0]
    all_done = bool(tot_ops) and done >= tot_ops
    manual = _ozhr_staff_manual(c, sid)
    for m in _team(c, pid):
        start = first.get(m["name"]) or j0
        # окончание: дата снятия с объекта; если её нет — последняя отметка человека, когда весь раздел выполнен; иначе пусто (человек ещё работает)
        end_iso = m.get("valid_to") or (last.get(m["name"], "") if all_done else "")
        ov = manual.get(m["name"], {})
        end = _fd(ov["end"]) if ov.get("end") else _fd(end_iso)
        sign = ov["sign"] if ov.get("sign") else (rep_sign if start else "")
        staff.append({"name": m["name"], "org": m.get("org_name") or org, "person": ", ".join(x for x in (_short_fio(m["name"]), m.get("position", "")) if x),
                      "start": ((_fd(start) + ", " + sec["title"]) if start else ""), "end": end, "sign": sign,
                      "end_manual": bool(ov.get("end")), "sign_manual": bool(ov.get("sign"))})
    vhk = c.execute("SELECT MIN(delivered_on) d, COUNT(*) n FROM input_control WHERE section_id=?", (sid,)).fetchone()
    sp2 = []
    if vhk and vhk["n"]:
        sp2.append({"journal": "Журнал входного контроля и контроля качества получаемых деталей, материалов, изделий, конструкций и оборудования, " + _fd(vhk["d"]),
                    "keeper": ", ".join(x for x in (org, rep_sign) if x), "handed_on": ""})
    signers = [", ".join(x for x in (v.get("rep_position", ""), _short_fio(v.get("rep_name", ""))) if x) for k, v in ppl.items() if k in SIGNERS and v.get("rep_name")]
    docs = []
    for r in c.execute("SELECT * FROM documents WHERE section_id=? AND document_type='АОСР' AND status IN ('Подписан','В архиве') ORDER BY seq, created_at", (sid,)):
        d = json.loads(r["data_json"] or "{}")
        docs.append({"name": f"Акт освидетельствования скрытых работ № {r['number']}" + (f" от {_fd(r['act_date'])}" if r["act_date"] else "") + (f", {d.get('work_name')}" if d.get("work_name") else ""),
                     "signed": (_fd((r["signed_at"] or "")[:10]) + "; " if r["signed_at"] else "") + "; ".join(signers)})
    for r in c.execute("SELECT key,issued_at FROM schemes WHERE section_id=? AND issued=1", (sid,)):
        k0, _, z0 = r["key"].partition("@")
        t = SCHEME_BY_KEY.get(k0)
        docs.append({"name": "Исполнительная схема: " + (t[1] if t else k0) + ", раздел " + sec["code"] + (f", {z0}" if z0 else ""), "signed": (_fd((r["issued_at"] or "")[:10]) + "; " if r["issued_at"] else "") + rep_sign})
    return {"staff": staff, "part2_auto": sp2, "part5": docs}


@app.post("/api/ozhr/reassign")
def ozhr_reassign(request: Request, payload: dict[str, Any], section: Optional[str] = None) -> dict[str, Any]:
    """Исправление исполнителя в записях раздела 3: одна запись или все записи прежнего исполнителя; история сохраняется."""
    to = " ".join(str(payload.get("to_actor") or "").split())
    reason = str(payload.get("reason") or "").strip()
    scope = payload.get("scope") or "one"
    if len(reason) < 5:
        raise HTTPException(422, "Укажите причину исправления (не короче 5 символов)")
    with db() as c:
        sec = _section(c, section)
        _doc_lock(c, sec["id"], "ozhr")
        m = c.execute("SELECT name,position FROM team WHERE project_id=? AND lower(name)=lower(?)", (sec["project_id"], to)).fetchone()
        if not m:
            raise HTTPException(422, "Исполнитель должен быть в команде проекта: добавьте его на странице объекта")
        if not (m["position"] or "").strip() or len(m["name"].split()) < 2:
            raise HTTPException(422, "У исполнителя должны быть указаны должность и ФИО полностью")
        ev = ozhr_build(c, sec)["items"]
        if scope == "all":
            frm = str(payload.get("from_actor") or "")
            targets = [x for x in ev if x["actor"] == frm]
        else:
            targets = [x for x in ev if x["operation_id"] == payload.get("operation_id")]
        targets = [x for x in targets if x["actor"] != m["name"]]
        if not targets:
            raise HTTPException(404, "Нет записей для исправления")
        for x in targets:
            c.execute("INSERT INTO event_actor_log (id,event_id,old_actor,new_actor,reason,by_user,at) VALUES (?,?,?,?,?,?,?)",
                      (str(uuid.uuid4()), x["event_id"], x["actor"], m["name"], reason, (getattr(request.state, "user", "") or "")[:80], now()))
            c.execute("UPDATE events SET actor=? WHERE id=?", (m["name"], x["event_id"]))
        olds = sorted({x["actor"] for x in targets})
        audit(request, c, "ozhr", sec["id"], "update", f"ОЖР, раздел 3: исполнитель «{'; '.join(olds)}» заменён на «{m['name']}» ({len(targets)} зап.)",
              {"Исполнитель": ["; ".join(olds), m["name"]], "Причина": ["", reason], "Записей": ["", str(len(targets))]}, section_id=sec["id"])
    return {"message": f"Исправлено записей: {len(targets)}", "count": len(targets)}


@app.get("/api/admin/audit/verify")
def audit_verify() -> dict[str, Any]:
    """Проверка цепочки хэшей журнала правок: найдёт изменённую или удалённую запись."""
    prev, n = "", 0
    with db() as c:
        for r in c.execute("SELECT rowid,prev_hash,hash,id,at,user,method,path,entity,entity_id,section_id,project_id,action,summary,diff_json FROM audit ORDER BY rowid"):
            n += 1
            if r["prev_hash"] != prev or r["hash"] != _audit_hash(prev, [r[k] for k in _AUDIT_FIELDS]):
                return {"ok": False, "checked": n, "broken_at": r["at"], "message": f"Журнал правок нарушен: запись № {n} от {r['at'][:19].replace('T', ' ')} изменена, или перед ней удалены записи."}
            prev = r["hash"]
    return {"ok": True, "checked": n, "message": f"Журнал правок цел: проверено записей — {n}, цепочка хэшей не нарушена."}


DOC_STATUSES = ("Черновик", "Готов к подписанию", "Подписан", "В архиве")
DOC_KINDS = {"ozhr": "Общий журнал работ", "vhk": "Журнал входного контроля", "schemes": "Исполнительные схемы"}
SIGNED = ("Подписан", "В архиве")


def _doc_status(c: sqlite3.Connection, sid: str, kind: str) -> dict[str, str]:
    r = c.execute("SELECT status,at,by_user FROM doc_status WHERE section_id=? AND kind=?", (sid, kind)).fetchone()
    return {"status": r["status"], "at": r["at"], "by": r["by_user"]} if r else {"status": "Черновик", "at": "", "by": ""}


def _doc_lock(c: sqlite3.Connection, sid: str, kind: str) -> None:
    st = _doc_status(c, sid, kind)["status"]
    if st in SIGNED:
        raise HTTPException(423, f"«{DOC_KINDS[kind]}» имеет статус «{st}» — правка закрыта. Чтобы изменить, верните статус «Черновик» (с указанием причины).")


@app.get("/api/doc-status")
def doc_status_get(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sid = _section(c, section)["id"]
        return {"statuses": list(DOC_STATUSES), "kinds": {k: {"title": t, **_doc_status(c, sid, k)} for k, t in DOC_KINDS.items()}}


class DocStatusIn(BaseModel):
    kind: Literal["ozhr", "vhk", "schemes"]
    status: Literal["Черновик", "Готов к подписанию", "Подписан", "В архиве"]
    reason: str = ""


@app.put("/api/doc-status")
def doc_status_put(request: Request, payload: DocStatusIn, section: Optional[str] = None) -> dict[str, str]:
    with db() as c:
        sec = _section(c, section)
        sid = sec["id"]
        cur = _doc_status(c, sid, payload.kind)["status"]
        new = payload.status
        if new == cur:
            return {"message": "Статус не изменился"}
        ci, ni = DOC_STATUSES.index(cur), DOC_STATUSES.index(new)
        reason = payload.reason.strip()
        if ni > ci:
            if ni != ci + 1:
                raise HTTPException(409, f"Статусы меняются по порядку: после «{cur}» — «{DOC_STATUSES[ci + 1]}»")
            if new == "Подписан":
                if payload.kind == "vhk" and not c.execute("SELECT 1 FROM input_control WHERE section_id=?", (sid,)).fetchone():
                    raise HTTPException(409, "В журнале входного контроля нет ни одной записи")
                if payload.kind == "schemes" and not c.execute("SELECT 1 FROM schemes WHERE section_id=? AND file_id IS NOT NULL", (sid,)).fetchone():
                    raise HTTPException(409, "Сначала сформируйте хотя бы одну схему")
        else:
            if len(reason) < 5:
                raise HTTPException(409, "Чтобы вернуть документ на прежний статус, укажите причину (не короче 5 символов)")
            if cur == "В архиве" and new != "Подписан":
                raise HTTPException(409, "Из архива документ возвращается в статус «Подписан»; дальше — по порядку")
        c.execute("INSERT INTO doc_status (section_id,kind,status,at,by_user) VALUES (?,?,?,?,?) ON CONFLICT(section_id,kind) DO UPDATE SET status=excluded.status, at=excluded.at, by_user=excluded.by_user",
                  (sid, payload.kind, new, now(), (getattr(request.state, "user", "") or "")[:80]))
        audit(request, c, "docstatus", sid + ":" + payload.kind, "update", f"{DOC_KINDS[payload.kind]}: статус «{cur}» → «{new}»",
              {"Статус": [cur, new], **({"Причина": ["", reason]} if reason else {})}, section_id=sid)
    return {"message": f"{DOC_KINDS[payload.kind]}: статус «{new}»"}


@app.get("/api/ozhr/extra")
def ozhr_extra(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        return {"meta": _ozhr_meta(c, sec["id"]), "rows": _ozhr_rows(c, sec["id"]), "auto": _ozhr_auto(c, sec),
                "cols": {str(k): [{"k": a, "t": b} for a, b in v] for k, v in OZHR_PARTS.items()}}


@app.put("/api/ozhr/meta")
def ozhr_meta_put(payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    with db() as c:
        sid = _section(c, section)["id"]
        _doc_lock(c, sid, "ozhr")
        cur = _ozhr_meta(c, sid)
        for k in OZHR_META_KEYS:
            if k in payload:
                cur[k] = str(payload[k] or "").strip()[:1000]
        c.execute("INSERT INTO ozhr_meta (section_id,data_json) VALUES (?,?) ON CONFLICT(section_id) DO UPDATE SET data_json=excluded.data_json", (sid, json.dumps(cur, ensure_ascii=False)))
    return {"message": "Сохранено"}


def _ozhr_clean(part: int, data: dict[str, Any]) -> dict[str, str]:
    if part not in OZHR_PARTS:
        raise HTTPException(422, "Нет такого раздела журнала")
    out = {k: str(data.get(k) or "").strip()[:2000] for k, _ in OZHR_PARTS[part]}
    if not any(out.values()):
        raise HTTPException(422, "Заполните хотя бы одну графу")
    return out


@app.post("/api/ozhr/rows", status_code=201)
def ozhr_row_add(request: Request, payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    part = int(payload.get("part") or 0)
    d = _ozhr_clean(part, payload.get("data") or {})
    with db() as c:
        sec = _section(c, section)
        _doc_lock(c, sec["id"], "ozhr")
        n = c.execute("SELECT COALESCE(MAX(sort_order),0)+1 FROM ozhr_rows WHERE section_id=? AND part=?", (sec["id"], part)).fetchone()[0]
        i = str(uuid.uuid4())
        c.execute("INSERT INTO ozhr_rows (id,section_id,part,data_json,sort_order,created_at) VALUES (?,?,?,?,?,?)", (i, sec["id"], part, json.dumps(d, ensure_ascii=False), n, now()))
        audit(request, c, "ozhr", i, "create", f"ОЖР, раздел {part}: добавлена запись", {"Запись": ["", " · ".join(v for v in d.values() if v)[:300]]}, section_id=sec["id"])
    return {"id": i}


@app.put("/api/ozhr/rows/{rid}")
def ozhr_row_put(request: Request, rid: str, payload: dict[str, Any]) -> dict[str, str]:
    with db() as c:
        old = c.execute("SELECT * FROM ozhr_rows WHERE id=?", (rid,)).fetchone()
        if not old:
            raise HTTPException(404, "Запись не найдена")
        d = _ozhr_clean(old["part"], payload.get("data") or {})
        _doc_lock(c, old["section_id"], "ozhr")
        c.execute("UPDATE ozhr_rows SET data_json=? WHERE id=?", (json.dumps(d, ensure_ascii=False), rid))
        audit(request, c, "ozhr", rid, "update", f"ОЖР, раздел {old['part']}: изменена запись", {"Запись": [" · ".join(v for v in json.loads(old["data_json"]).values() if v)[:300], " · ".join(v for v in d.values() if v)[:300]]}, section_id=old["section_id"])
    return {"message": "Сохранено"}


@app.delete("/api/ozhr/rows/{rid}")
def ozhr_row_del(request: Request, rid: str) -> dict[str, str]:
    with db() as c:
        old = c.execute("SELECT * FROM ozhr_rows WHERE id=?", (rid,)).fetchone()
        if not old:
            raise HTTPException(404, "Запись не найдена")
        _doc_lock(c, old["section_id"], "ozhr")
        c.execute("DELETE FROM ozhr_rows WHERE id=?", (rid,))
        audit(request, c, "ozhr", rid, "delete", f"ОЖР, раздел {old['part']}: удалена запись", {"Запись": [" · ".join(v for v in json.loads(old["data_json"]).values() if v)[:300], ""]}, section_id=old["section_id"])
    return {"message": "Удалено"}


def _org_full(p: Optional[dict[str, Any]]) -> str:
    if not p or not p.get("org_name"):
        return ""
    parts = [p["org_name"]] + (["ОГРН " + p["ogrn"]] if p.get("ogrn") else []) + (["ИНН " + p["inn"]] if p.get("inn") else []) + ([p["address"]] if p.get("address") else []) + (["тел. " + p["phone"]] if p.get("phone") else [])
    return ", ".join(parts)


def _rep_row(p: Optional[dict[str, Any]]) -> list[str]:
    if not p or not p.get("rep_name"):
        return []
    return [p["rep_name"], p.get("rep_position", ""), p.get("rep_order", ""), p.get("rep_nrs_id", ""), ""]


def build_ozhr_docx(c: sqlite3.Connection, sec: sqlite3.Row) -> bytes:
    import io
    from docx import Document
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn
    from docx.shared import Mm, Pt
    sid, pid = sec["id"], sec["project_id"]
    proj = c.execute("SELECT * FROM projects WHERE id=?", (pid,)).fetchone()
    ppl = _act_people(c, pid)
    meta, rows, auto = _ozhr_meta(c, sid), _ozhr_rows(c, sid), _ozhr_auto(c, sec)
    doc = Document()
    st = doc.styles["Normal"]
    st.font.name = "Times New Roman"
    st.font.size = Pt(11)
    st.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    sc = doc.sections[0]
    sc.page_width, sc.page_height = Mm(210), Mm(297)
    sc.left_margin, sc.right_margin, sc.top_margin, sc.bottom_margin = Mm(20), Mm(10), Mm(15), Mm(15)
    C, R = WD_ALIGN_PARAGRAPH.CENTER, WD_ALIGN_PARAGRAPH.RIGHT

    def para(text="", size=11, bold=False, align=None, before=0, after=4):
        p = doc.add_paragraph()
        p.paragraph_format.space_before, p.paragraph_format.space_after = Pt(before), Pt(after)
        if align is not None:
            p.alignment = align
        r = p.add_run(text)
        r.font.size, r.bold = Pt(size), bold
        return p

    def line(value, caption):
        p = para(value or " ", 11, after=0)
        pPr = p._p.get_or_add_pPr()
        b = OxmlElement("w:pBdr")
        bt = OxmlElement("w:bottom")
        for k, v in (("w:val", "single"), ("w:sz", "4"), ("w:space", "1"), ("w:color", "000000")):
            bt.set(qn(k), v)
        b.append(bt)
        pPr.append(b)
        para(caption, 8, align=C, after=6)

    def table(heads, data, widths, blank=2, size=8):
        t = doc.add_table(rows=2, cols=len(heads))
        t.style = "Table Grid"
        t.autofit = False

        def cell(cc, text, bold=False, center=False):
            cc.text = ""
            p = cc.paragraphs[0]
            p.paragraph_format.space_after = Pt(0)
            if center:
                p.alignment = C
            r = p.add_run(str(text))
            r.font.size, r.bold = Pt(size), bold
        for i, h in enumerate(heads):
            cell(t.rows[0].cells[i], h, False, True)
            cell(t.rows[1].cells[i], str(i + 1), False, True)
        trPr = t.rows[0]._tr.get_or_add_trPr()
        th = OxmlElement("w:tblHeader")
        th.set(qn("w:val"), "true")
        trPr.append(th)
        for rw in data:
            cs = t.add_row().cells
            for i, v in enumerate(rw):
                cell(cs[i], v, False, i == 0 or (isinstance(v, str) and len(v) <= 10 and "." in v))
        for _ in range(blank):
            t.add_row()
        for i, w in enumerate(widths):
            t.columns[i].width = Mm(w)
            for rr in t.rows:
                rr.cells[i].width = Mm(w)
        para("", after=6)

    def head(text, size=11):
        para(text, size, True, C, before=6, after=4)

    def sub(text):
        para(text, 11, False, C, before=6, after=4)
    # ---- титульный лист
    para("Форма (приложение № 1 к приказу Минстроя России от 02.12.2022 № 1026/пр)", 8, align=R)
    para("Общий журнал, в котором ведется учет выполнения работ по строительству, реконструкции, капитальному ремонту объекта капитального строительства", 13, True, C, before=14, after=8)
    para("№ " + (meta["number"] or "________"), 12, False, C, after=8)
    kind = meta["kind"] or "строительство"
    para("по", 11, after=0)
    line(kind, "(указать строительство, реконструкция, капитальный ремонт)")
    line(f"{proj['object_name']}" + (f", {proj['address']}" if proj["address"] else ""), "(наименование объекта капитального строительства, его почтовый или строительный адрес)")
    para("Застройщик", 11, after=0)
    line(_org_full(ppl.get("developer")), "(полное и (или) сокращенное наименование, ОГРН, ИНН, место нахождения юридического лица, телефон/факс, адрес электронной почты; для индивидуального предпринимателя — ФИО, адрес места жительства, ОГРНИП, ИНН)")
    line((ppl.get("developer") or {}).get("sro", ""), "(полное и (или) сокращенное наименование, ОГРН, ИНН саморегулируемой организации, членом которой является застройщик, если членство требуется)")
    heads_rep = ["№ п/п", "Фамилия, имя, отчество (последнее — при наличии)", "Должность (при наличии)", "Наименование, дата, номер документа, подтверждающего полномочие",
                 "Идентификационный номер в национальном реестре специалистов в области строительства (за исключением случаев, когда членство в саморегулируемых организациях в области инженерных изысканий, архитектурно-строительного проектирования, строительства, реконструкции, капитального ремонта объектов капитального строительства не требуется)", "Подпись"]
    w6 = [10, 40, 28, 32, 50, 20]
    w5 = [10, 55, 40, 50, 25]

    def rep_table(title, p, five=False):
        sub(title)
        r_ = _rep_row(p)
        if five:
            table([heads_rep[0], heads_rep[1], heads_rep[2], heads_rep[3], heads_rep[5]], [[1] + r_[:3] + [""]] if r_ else [], w5, blank=0 if r_ else 1)
        else:
            table(heads_rep, [[1] + r_] if r_ else [], w6, blank=0 if r_ else 1)
    rep_table("Уполномоченный представитель застройщика", ppl.get("developer"))
    para("Технический заказчик", 11, after=0)
    line(_org_full(ppl.get("tech_customer")), "(полное и (или) сокращенное наименование, ОГРН, ИНН, место нахождения юридического лица, телефон/факс, адрес электронной почты (при наличии))")
    line((ppl.get("tech_customer") or {}).get("sro", ""), "(полное и (или) сокращенное наименование, ОГРН, ИНН саморегулируемой организации, членом которой является юридическое лицо, если членство требуется)")
    rep_table("Уполномоченный представитель технического заказчика", ppl.get("tech_customer"))
    para("Лицо, ответственное за эксплуатацию здания, сооружения, или региональный оператор (заполняется в случае, если договор строительного подряда заключается с лицом, ответственным за эксплуатацию здания, сооружения, или региональным оператором)", 11, after=0)
    line("", "(наименование, ОГРН, ИНН, место нахождения, телефон/факс, адрес электронной почты (при наличии))")
    sub("Уполномоченный представитель лица, ответственного за эксплуатацию здания, сооружения, или регионального оператора (заполняется в случае, если договор строительного подряда заключается с лицом, ответственным за эксплуатацию здания, сооружения, или региональным оператором)")
    table(["№ п/п", "Фамилия, имя, отчество (последнее — при наличии)", "Должность (при наличии)", "Наименование, дата, номер документа, подтверждающего полномочие", "Подпись"], [], w5, blank=1)
    para("Сведения о выданном разрешении на строительство (заполняется в случае, если разрешение на строительство требуется в соответствии со статьей 51 Градостроительного кодекса Российской Федерации)", 11, after=0)
    line(meta["permit"], "(номер, дата выдачи разрешения на строительство, наименование органа исполнительной власти, государственной корпорации или органа местного самоуправления, выдавших разрешение)")
    para("Лицо, осуществляющее подготовку проектной документации", 11, after=0)
    line(_org_full(ppl.get("designer")), "(полное и (или) сокращенное наименование, ОГРН, ИНН, место нахождения юридического лица, телефон/факс, адрес электронной почты (при наличии))")
    line((ppl.get("designer") or {}).get("sro", ""), "(полное и (или) сокращенное наименование, ОГРН, ИНН саморегулируемой организации, членом которой является указанное лицо, если членство требуется)")
    sub("Уполномоченный представитель лица, осуществляющего подготовку проектной документации, по вопросам проверки соответствия выполняемых работ проектной документации (далее — авторский надзор)")
    a = ppl.get("author_supervision") or {}
    table(["№ п/п", "Полное и (или) сокращенное наименование или фамилия, имя, отчество (последнее — при наличии) лица, осуществляющего подготовку проектной документации, сведения о разделах проектной документации, подготовленных этим лицом", "Фамилия, имя, отчество (последнее — при наличии), должность (при наличии)", "Наименование, дата, номер документа, подтверждающего полномочие", "Идентификационный номер в национальном реестре специалистов в области архитектурно-строительного проектирования (за исключением случаев, когда членство в саморегулируемых организациях не требуется)", "Подпись"],
          [[1, a.get("org_name", ""), ", ".join(x for x in (a.get("rep_name", ""), a.get("rep_position", "")) if x), a.get("rep_order", ""), a.get("rep_nrs_id", ""), ""]] if a.get("rep_name") else [], w6, blank=0 if a.get("rep_name") else 1)
    para("Сведения о положительном заключении экспертизы проектной документации (заполняется в случае, если при строительстве, реконструкции объекта капитального строительства в соответствии со статьей 49 Градостроительного кодекса Российской Федерации проводится экспертиза проектной документации)", 11, after=0)
    line(meta["expertise"], "(номер и дата выдачи, орган или организация, его утвердившие)")
