# ---------------------------------------------------------------- условия производства работ: погода по координатам объекта (Open-Meteo)
WX_ARCHIVE = os.environ.get("APP_WX_ARCHIVE_URL", "https://archive-api.open-meteo.com/v1/archive")
WX_FORECAST = os.environ.get("APP_WX_FORECAST_URL", "https://api.open-meteo.com/v1/forecast")
WX_GEOCODE = os.environ.get("APP_GEOCODE_URL", "https://nominatim.openstreetmap.org/search")
WX_SOURCE = "Open-Meteo (реанализ ERA5 и метеомодели по координатам объекта)"


def _http_json(url: str) -> Any:
    req = urllib.request.Request(url, headers={"User-Agent": "ID-ITS/1.0 (as-built documentation)"})
    with urllib.request.urlopen(req, timeout=20) as r:
        return json.loads(r.read().decode("utf-8"))


def _geocode(address: str) -> Optional[tuple[str, str]]:
    q = address.strip()
    if not q:
        return None
    for variant in (q, re.sub(r"\b(?:ст-ца|станица|ст\.)\s*", "станица ", q, flags=re.I), ", ".join(q.split(",")[-3:])):
        try:
            res = _http_json(WX_GEOCODE + "?" + urllib.parse.urlencode({"q": variant, "format": "json", "limit": 1, "accept-language": "ru"}))
        except Exception:
            continue
        if res:
            return f"{float(res[0]['lat']):.5f}", f"{float(res[0]['lon']):.5f}"
    return None


def _wx_text(tmin: Any, tmax: Any, prec: Any, wind: Any, code: Any) -> str:
    def t(v: float) -> str:
        v = round(v)
        return ("+" if v > 0 else "−" if v < 0 else "") + str(abs(v))
    code = int(code) if code is not None else -1
    sky = ("ясно" if code == 0 else "малооблачно" if code == 1 else "переменная облачность" if code == 2 else "пасмурно" if code == 3 else
           "туман" if code in (45, 48) else "морось" if 51 <= code <= 57 else "дождь" if 61 <= code <= 67 or 80 <= code <= 82 else
           "снег" if 71 <= code <= 77 or code in (85, 86) else "гроза" if code >= 95 else "")
    parts = []
    if tmin is not None and tmax is not None:
        a, b = round(tmin), round(tmax)
        parts.append((t(a) if a == b else f"{t(a)}…{t(b)}") + " °C")
    if sky:
        parts.append(sky)
    if prec is not None and prec >= 0.2:
        parts.append(f"осадки {prec:.1f} мм".replace(".", ","))
    elif sky and code in (0, 1, 2, 3, 45, 48):
        parts.append("без осадков")
    if wind is not None:
        parts.append(f"ветер до {round(wind)} м/с")
    return ", ".join(parts)


def _wx_fetch(lat: str, lon: str, days: list[str]) -> dict[str, str]:
    out: dict[str, str] = {}
    today = date.today()
    old = [d for d in days if (today - date.fromisoformat(d)).days > 7]
    new = [d for d in days if d not in old]
    daily = "temperature_2m_max,temperature_2m_min,precipitation_sum,wind_speed_10m_max,weather_code"
    for base, ds in ((WX_ARCHIVE, old), (WX_FORECAST, new)):
        if not ds:
            continue
        url = base + "?" + urllib.parse.urlencode({"latitude": lat, "longitude": lon, "start_date": min(ds), "end_date": max(ds), "daily": daily,
                                                      "wind_speed_unit": "ms", "timezone": "Europe/Moscow"})
        try:
            j = _http_json(url)["daily"]
        except Exception:
            continue
        for i, d in enumerate(j.get("time", [])):
            if d in ds:
                tx = _wx_text(j["temperature_2m_min"][i], j["temperature_2m_max"][i], j["precipitation_sum"][i], j["wind_speed_10m_max"][i], j["weather_code"][i])
                if tx:
                    out[d] = tx
    return out


def wx_fill(c: sqlite3.Connection, sec: sqlite3.Row) -> dict[str, Any]:
    """Дозаполняет погоду за даты выполненных работ, по которым её нет (ручные записи не трогает)."""
    pid = sec["project_id"]
    p = c.execute("SELECT address,object_name,lat,lon FROM projects WHERE id=?", (pid,)).fetchone()
    days = sorted({r[0] for r in c.execute("SELECT DISTINCT e.performed_on FROM events e JOIN operations o ON o.id=e.operation_id JOIN elements el ON el.id=o.element_id WHERE el.section_id=? AND e.event_type='complete' AND e.performed_on<>''", (sec["id"],))})
    have = {r["day"] for r in c.execute("SELECT day FROM weather WHERE project_id=? AND text<>''", (pid,))}
    todo = [d for d in days if d not in have]
    if not todo:
        return {"filled": 0, "lat": p["lat"], "lon": p["lon"]}
    lat, lon = p["lat"], p["lon"]
    if not (lat and lon):
        g = _geocode(p["address"] or "")
        if not g:
            return {"filled": 0, "error": "Не удалось определить координаты объекта по адресу. Укажите их вручную («Координаты…»).", "lat": "", "lon": ""}
        lat, lon = g
        c.execute("UPDATE projects SET lat=?, lon=? WHERE id=?", (lat, lon, pid))
    got = _wx_fetch(lat, lon, todo)
    for d, tx in got.items():
        c.execute("INSERT INTO weather (project_id,day,text,updated_at,source) VALUES (?,?,?,?,'auto') ON CONFLICT(project_id,day) DO UPDATE SET text=excluded.text, updated_at=excluded.updated_at, source='auto' WHERE weather.text='' ",
                  (pid, d, tx, now()))
    res: dict[str, Any] = {"filled": len(got), "lat": lat, "lon": lon}
    if len(got) < len(todo):
        res["error"] = "Часть дат не получена (сервис погоды недоступен или данных за эти даты ещё нет) — повторите позже или внесите вручную."
    return res


@app.post("/api/weather/fill")
def weather_fill(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        return {**wx_fill(c, _section(c, section)), "source": WX_SOURCE}


@app.get("/api/weather/coords")
def weather_coords(section: Optional[str] = None) -> dict[str, str]:
    with db() as c:
        p = c.execute("SELECT lat,lon,address FROM projects WHERE id=?", (_section(c, section)["project_id"],)).fetchone()
        return {"lat": p["lat"], "lon": p["lon"], "address": p["address"]}


@app.put("/api/weather/coords")
def weather_coords_put(payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    try:
        lat, lon = float(str(payload.get("lat", "")).replace(",", ".")), float(str(payload.get("lon", "")).replace(",", "."))
    except ValueError as ex:
        raise HTTPException(422, "Координаты — числа, например 47.123 и 40.456") from ex
    if not (-90 <= lat <= 90 and -180 <= lon <= 180):
        raise HTTPException(422, "Широта −90…90, долгота −180…180")
    with db() as c:
        pid = _section(c, section)["project_id"]
        c.execute("UPDATE projects SET lat=?, lon=? WHERE id=?", (f"{lat:.5f}", f"{lon:.5f}", pid))
        c.execute("DELETE FROM weather WHERE project_id=? AND source='auto'", (pid,))
    return {"message": "Координаты сохранены; погода будет загружена заново"}


class WeatherIn(BaseModel):
    day: date
    text: str = Field(default="", max_length=200)


@app.put("/api/weather")
def weather_put(payload: WeatherIn, section: Optional[str] = None) -> dict[str, str]:
    with db() as c:
        pid = _section(c, section)["project_id"]
        if payload.text.strip():
            c.execute("INSERT INTO weather (project_id,day,text,updated_at,source) VALUES (?,?,?,?,'manual') ON CONFLICT(project_id,day) DO UPDATE SET text=excluded.text, updated_at=excluded.updated_at, source='manual'",
                      (pid, payload.day.isoformat(), payload.text.strip(), now()))
        else:
            c.execute("DELETE FROM weather WHERE project_id=? AND day=?", (pid, payload.day.isoformat()))
    return {"message": "Сохранено"}


# ---------------------------------------------------------------- автозаполнение по проекту
CIPHER_RE = re.compile(r"(?<![\w-])[А-ЯЁA-Z]{1,6}(?:-[А-ЯЁA-Z0-9]{1,8}){2,6}(?:\.[А-ЯЁA-Z0-9]{1,4})?(?![\w-])")
REGION_RE = re.compile(r"^(.*?)[,;]\s*((?:[А-ЯЁ][а-яё\-]+\s+(?:область|край)|Республика\s+[А-ЯЁ][а-яё\-]+|г\.\s*[А-ЯЁ]).*)$")
OBJ_WORDS = re.compile(r"склад|магазин|здани|комплекс|жил|школ|детск|центр|завод|цех|гараж|ферм|котельн|больниц|гостиниц|дом\b", re.I)


def _strip_q(t: str) -> str:
    return t.strip().strip("«»\"' ").rstrip(".").strip()


def extract_project_meta(lines: list[str], title_hint: str = "") -> dict[str, Any]:
    lines = [re.sub(r"\s+", " ", l).strip() for l in lines if l and l.strip()]
    meta: dict[str, Any] = {"object_name": "", "address": "", "short_name": "", "cipher": "", "section_title": title_hint, "found": []}
    # шифр
    cnt: dict[str, int] = {}
    for l in lines:
        for m in CIPHER_RE.finditer(l):
            v = m.group(0)
            if re.search(r"\d", v) and len(v) >= 8 and re.search(r"[А-ЯЁA-Z]", v):
                cnt[v] = cnt.get(v, 0) + 1
    if cnt:
        best = sorted(cnt.items(), key=lambda kv: (-kv[1], len(kv[0])))[0][0]
        meta["cipher"] = re.sub(r"\.(СО|СП|ПЗ)$", "", best)
        meta["found"].append("шифр")
    # название объекта: по подписи или по ключевым словам
    name = ""
    for i, l in enumerate(lines):
        m = re.match(r"^(?:Объект(?:\s+строительства)?|Наименование\s+объекта|Строительство)\s*[:\-–]\s*(.+)$", l, re.I)
        if m and len(m.group(1)) > 12:
            name = m.group(1); break
        if re.match(r"^(?:Объект|Наименование\s+объекта)\s*:?$", l, re.I) and i + 1 < len(lines) and len(lines[i + 1]) > 12:
            name = lines[i + 1]; break
    if not name:
        c2: dict[str, int] = {}
        for l in lines:
            if 40 <= len(l) <= 500 and OBJ_WORDS.search(l) and (l.startswith("«") or REGION_RE.match(l) or l[:1].isupper()):
                c2[l] = c2.get(l, 0) + 1
        if c2:
            name = sorted(c2.items(), key=lambda kv: (-kv[1], -len(kv[0])))[0][0]
    name = _strip_q(name)
    if name:
        meta["object_name"] = name
        meta["found"].append("объект")
        m = REGION_RE.match(name)
        if m:
            meta["address"] = _strip_q(m.group(2))
        meta["short_name"] = _display_name(name)[:60]
    if not meta["address"]:
        for i, l in enumerate(lines):
            m = re.match(r"^(?:Адрес(?:\s+объекта)?|Место(?:положение|\s+расположения))\s*[:\-–]\s*(.+)$", l, re.I)
            if m and len(m.group(1)) > 8:
                meta["address"] = _strip_q(m.group(1)); break
    if meta["address"]:
        meta["found"].append("адрес")
    if meta["section_title"]:
        meta["found"].append("раздел")
    return meta


def dxf_meta(path: Path) -> dict[str, Any]:
    g = dxf_geometry(path)
    texts = [t for l in g["layers"] for t in l["T"]]
    meta = extract_project_meta([t[4] for t in texts])
    # название раздела: строки штампа рядом с шифром («Наружные сети водоснабжения и» + «водоотведения»)
    cip = meta.get("cipher")
    if cip:
        anchors = [t for t in texts if t[4].startswith(cip)]
        if anchors:
            a = anchors[0]
            near = sorted((t for t in texts if abs(t[0] - a[0]) < 70 and -45 < t[1] - a[1] < 0), key=lambda t: -t[1])
            title = ""
            for t in near:
                tx = t[4].strip()
                if not title and re.match(r"^(Наружные|Внутренние|Сети|Водоснабжение|Водоотведение|Канализация|Теплоснабжение|Электроснабжение)", tx, re.I):
                    title = tx
                elif title and len(title) < 150 and len(tx) < 60 and tx[:1].islower() | tx.startswith("("):
                    title += " " + tx
                elif title:
                    break
            if title:
                meta["section_title"] = title.strip()
                if "раздел" not in meta["found"]:
                    meta["found"].append("раздел")
    return meta


def pdf_lines(path: Path) -> list[str]:
    try:
        from pypdf import PdfReader
    except ImportError:
        return []
    out: list[str] = []
    rd = PdfReader(str(path))
    for pg in rd.pages[:12]:
        try:
            out += (pg.extract_text() or "").splitlines()
        except Exception:  # noqa: BLE001
            continue
    return out


def file_meta(path: Path, name: str) -> dict[str, Any]:
    n = name.lower()
    try:
        if n.endswith(".dxf"):
            return dxf_meta(path)
        if n.endswith(".docx"):
            return extract_project_meta(doc_lines(name, path.read_bytes()))
        if n.endswith(".pdf"):
            ls = pdf_lines(path)
            if not ls:
                return {"found": [], "error": "в PDF нет текстового слоя (скан) — заполните поля вручную"}
            return extract_project_meta(ls)
    except HTTPException:
        raise
    except Exception as ex:  # noqa: BLE001
        return {"found": [], "error": f"{type(ex).__name__}: {ex}"[:200]}
    return {"found": []}


@app.post("/api/stage", status_code=201)
async def stage_file(request: Request, name: str) -> dict[str, Any]:
    """Файл, загруженный в окне «Новый проект» до создания проекта: сохраняем и сразу разбираем."""
    FILES_DIR.mkdir(parents=True, exist_ok=True)
    sid = uuid.uuid4().hex
    path = FILES_DIR / f"stage-{sid}"
    size = 0
    try:
        with open(path, "wb") as f:
            async for chunk in request.stream():
                size += len(chunk)
                if size > MAX_FILE:
                    raise HTTPException(413, "Файл больше 95 МБ — разделите или сожмите (zip)")
                f.write(chunk)
        if size == 0:
            raise HTTPException(400, "Пустой файл")
        nm = os.path.basename(name)[:200]
        (FILES_DIR / f"stage-{sid}.json").write_text(json.dumps({"name": nm, "size": size}, ensure_ascii=False), encoding="utf-8")
        meta = await run_in_threadpool(file_meta, path, nm)
        return {"stage_id": sid, "name": nm, "size": size, "kind": guess_kind(nm), "meta": meta}
    except BaseException:
        path.unlink(missing_ok=True)
        raise


def _take_staged(c: sqlite3.Connection, project_id: str, section_id: str, items: list["StagedIn"], who: str) -> list[tuple[str, str]]:
    started: list[tuple[str, str]] = []
    for it in items:
        if not re.fullmatch(r"[0-9a-f]{32}", it.id):
            continue
        path = FILES_DIR / f"stage-{it.id}"
        side = FILES_DIR / f"stage-{it.id}.json"
        if not path.exists() or not side.exists():
            continue
        info = json.loads(side.read_text(encoding="utf-8"))
        h = hashlib.sha256()
        with open(path, "rb") as f:
            for blk in iter(lambda: f.read(1 << 20), b""):
                h.update(blk)
        res = _store_path(c, project_id, section_id, it.kind or "", info["name"], path, info["size"], h.hexdigest(), who)
        side.unlink(missing_ok=True)
        if res.get("_start"):
            started.append((res["id"], info["name"]))
    return started


def _cleanup_stage() -> None:
    try:
        for p in FILES_DIR.glob("stage-*"):
            if time.time() - p.stat().st_mtime > 6 * 3600:
                p.unlink(missing_ok=True)
    except OSError:
        pass


# ---------------------------------------------------------------- перечень работ: предложения из проекта и сметы
STD_OPS = (("install", "Монтаж выполнен"), ("survey", "Исполнительная съёмка получена"), ("test", "Испытание / проверка выполнены"))
EST_OPS = (("done", "Работа выполнена"), ("accept", "Принято (акт / приёмка)"))


def _existing_codes(c: sqlite3.Connection, section_id: str) -> set[str]:
    return {_norm_code(r["code"]) for r in c.execute("SELECT code FROM elements WHERE section_id=?", (section_id,))}


_VALVE_RE = re.compile(r"установка\s+(задвижек|задвижки|вентил|клапан|кран|затвор|гидрант)", re.I)


def _valve_elements(p: dict[str, Any], have: set[str]) -> list[dict[str, Any]]:
    """Позиция сметы «Установка задвижек …, N шт» → отдельные элементы перечня по каждой единице арматуры."""
    name = p.get("name") or ""
    m = _VALVE_RE.search(name)
    try:
        n = int(round(float(p.get("qty") or 0)))
    except (TypeError, ValueError):
        return []
    if not m or n < 1 or n > 80 or not str(p.get("units") or "").lower().startswith("шт") or not p.get("n"):
        return []
    w = m.group(1).lower()
    title = "Задвижка" if w.startswith("задвиж") else "Гидрант" if w.startswith("гидрант") else "Затвор" if w.startswith("затвор") else "Кран / вентиль" if w.startswith(("вентил", "кран")) else "Клапан"
    d = re.search(r"(?:диаметром|ф|d|dn)\D{0,3}(\d{2,3})\s*мм|(\d{2,3})\s*мм", name, re.I)
    dn = next((x for x in (d.groups() if d else ()) if x), "")
    out = []
    for k in range(1, n + 1):
        code = f"Арм-{p['n']}-{k}"
        if _norm_code(code) in have:
            continue
        out.append({"code": code, "name": f"{title}{' DN' + dn if dn else ''} № {k}", "kind": "Арматура", "block": "Арматура",
                    "planned_note": f"поз. сметы {p['n']}: {name[:90]}", "source": "estimate",
                    "ops": [["install", "Установлена"], ["test", "Опрессовка / испытание"], ["survey", "Исполнительная съёмка"]]})
    return out


@app.get("/api/suggest-list")
def suggest_list(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        return _suggest_core(c, sec)


def _suggest_core(c: sqlite3.Connection, sec: sqlite3.Row, ignore_have: bool = False) -> dict[str, Any]:
    if True:
        have = set() if ignore_have else _existing_codes(c, sec["id"])
        files = c.execute("SELECT id,name,kind,analysis_json,status FROM source_files WHERE project_id=? AND section_id=?", (sec["project_id"], sec["id"])).fetchall()   # проект и смета относятся только к одному разделу
        wells: dict[str, dict[str, Any]] = {}
        est: list[dict[str, Any]] = []
        valves: list[dict[str, Any]] = []
        pending = 0
        snets = set(_sec_nets(sec))
        other_nets: dict[str, int] = {}

        def _foreign(code: str, own: bool) -> bool:
            """Шифр чужой сети (К1, К3 в разделе «К2, К2.1»): только если в файле есть шифры сетей раздела."""
            m = re.match(r"\s*([А-ЯA-Z]{1,2}\d+(?:\.\d+)?)\s*[-–]", code or "")
            if not (own and m and m.group(1) not in snets):
                return False
            other_nets[m.group(1)] = other_nets.get(m.group(1), 0) + 1
            return True

        def _has_own(codes: list[str]) -> bool:
            return bool(snets) and any((m := re.match(r"\s*([А-ЯA-Z]{1,2}\d+(?:\.\d+)?)\s*[-–]", x or "")) and m.group(1) in snets for x in codes)

        for f in files:
            if f["status"] == "analyzing":
                pending += 1
                continue
            a = json.loads(f["analysis_json"] or "{}")
            if f["kind"] == "dxf_project" and a.get("codes"):
                own = _has_own(a["codes"])
                for code in a["codes"]:
                    if _foreign(code, own):
                        continue
                    if _norm_code(code) in have or code in wells:
                        continue
                    prefix = re.match(r"К\d+(?:\.\d+)?", code)
                    wells[code] = {"code": code, "name": f"Колодец {code}", "kind": "Колодец", "block": f"Колодцы {prefix.group(0)}" if prefix else "Колодцы",
                                   "planned_note": "", "source": "project", "ops": OBJ_OPS["Колодец"], "file": f["name"]}
            if f["kind"] == "dxf_project" and a.get("ok") and str(f["name"]).lower().endswith(".dxf"):
                if "pipes" not in a:                       # участки труб берём из таблиц профилей; считаем один раз и запоминаем
                    try:
                        with _ANALYSIS_SLOT:
                            a["pipes"] = extract_pipes(_dxf_texts_xy(FILES_DIR / f["id"]))
                        c.execute("UPDATE source_files SET analysis_json=? WHERE id=?", (json.dumps(a, ensure_ascii=False), f["id"]))
                    except Exception:  # noqa: BLE001
                        a["pipes"] = []
                own_p = _has_own([p["from"] for p in a.get("pipes") or []])
                for p in a.get("pipes") or []:
                    code = f"{p['from']}–{p['to']}"
                    if _foreign(p["from"], own_p):
                        continue
                    if _norm_code(code) in have or code in wells:
                        continue
                    pre = re.match(r"К\d+(?:\.\d+)?", p["from"])
                    note = f"L={p['len']:g} м" + (f" · Ø{p['dn']}" if p.get("dn") else "") + " · по профилю проекта"
                    wells[code] = {"code": code, "name": f"Участок {p['from']} – {p['to']}", "kind": "Трубопровод", "block": f"Участки {pre.group(0)}" if pre else "Участки",
                                   "planned_note": note, "source": "project", "ops": OBJ_OPS["Трубопровод"], "file": f["name"]}
            if f["kind"] == "pdf" and str(f["name"]).lower().endswith(".pdf"):
                if "pipes" not in a:                       # участки из таблиц PDF-профилей; считаем один раз и запоминаем
                    try:
                        with _ANALYSIS_SLOT:
                            a["pipes"] = extract_pipes_pdf(_pdf_pages_words(FILES_DIR / f["id"]))
                        c.execute("UPDATE source_files SET analysis_json=? WHERE id=?", (json.dumps(a, ensure_ascii=False), f["id"]))
                    except Exception:  # noqa: BLE001
                        a["pipes"] = []
                fnet = re.search(r"Н([ВК]\d+)", str(f["name"]))
                for p in a.get("pipes") or []:
                    if fnet:                                # шифр сети — по имени файла проекта (НВ1 → В1), в штампе листа возможны опечатки
                        p = {**p, "net": fnet.group(1)}
                    pre = f"{p['net']}: " if p.get("net") else ""
                    code = f"{pre}{p['from']}–{p['to']}"
                    if _norm_code(code) in have or code in wells:
                        continue
                    note = f"L={p['len']:g} м" + (f" · {p['spec']}" if p.get("spec") else "") + " · по профилю проекта (PDF)"
                    wells[code] = {"code": code, "name": f"Участок {p['from']} – {p['to']}" + (f" ({p['net']})" if p.get("net") else ""), "kind": "Трубопровод",
                                   "block": f"Участки {p['net']}" if p.get("net") else "Участки", "planned_note": note, "source": "project",
                                   "ops": OBJ_OPS["Трубопровод"], "file": f["name"]}
                for p in a.get("pipes") or []:         # колодцы — точки профиля с номером «1», «2» …
                    for pt in (p["from"], p["to"]):
                        if re.fullmatch(r"\d{1,3}", pt):
                            wc = f"{p['net']}-К{pt}" if p.get("net") else f"К{pt}"
                            if _norm_code(wc) not in have and wc not in wells:
                                wells[wc] = {"code": wc, "name": f"Колодец № {pt}" + (f" ({p['net']})" if p.get("net") else ""), "kind": "Колодец",
                                             "block": f"Колодцы {p['net']}" if p.get("net") else "Колодцы", "planned_note": "по профилю проекта (PDF)", "source": "project",
                                             "ops": OBJ_OPS["Колодец"], "file": f["name"]}
                if "wells_table" not in a:                 # таблица колодцев: состав каждого колодца
                    try:
                        with _ANALYSIS_SLOT:
                            a["wells_table"] = extract_wells_table_pdf(_pdf_pages_words(FILES_DIR / f["id"]))
                        c.execute("UPDATE source_files SET analysis_json=? WHERE id=?", (json.dumps(a, ensure_ascii=False), f["id"]))
                    except Exception:  # noqa: BLE001
                        a["wells_table"] = []
                for wt in a.get("wells_table") or []:
                    wc = f"{wt['net']}-К{wt['n']}" if wt.get("net") else f"К{wt['n']}"
                    if _norm_code(wc) in have:
                        continue
                    comp = "; ".join(f"{k}×{v}" for k, v in wt["comp"].items())
                    wells[wc] = {"code": wc, "name": f"Колодец № {wt['n']}" + (f" ({wt['net']})" if wt.get("net") else ""), "kind": "Колодец",
                                 "block": f"Колодцы {wt['net']}" if wt.get("net") else "Колодцы",
                                 "planned_note": f"Состав: {comp}" + (f" · бетон на опоры {wt['conc']:g} м3" if wt.get("conc") else "") + (f" · глубина {wt['depth']} мм" if wt.get("depth") else "") + " · по таблице колодцев проекта",
                                 "source": "project", "ops": OBJ_OPS["Колодец"], "file": f["name"]}
                if "spec" not in a:                        # спецификация оборудования и изделий — считаем один раз и запоминаем
                    try:
                        with _ANALYSIS_SLOT:
                            a["spec"] = extract_spec_pdf(FILES_DIR / f["id"])
                        c.execute("UPDATE source_files SET analysis_json=? WHERE id=?", (json.dumps(a, ensure_ascii=False), f["id"]))
                    except Exception:  # noqa: BLE001
                        a["spec"] = []
                if "nodes" not in a:
                    try:
                        with _ANALYSIS_SLOT:
                            a["nodes"] = extract_node_titles_pdf(FILES_DIR / f["id"])
                        c.execute("UPDATE source_files SET analysis_json=? WHERE id=?", (json.dumps(a, ensure_ascii=False), f["id"]))
                    except Exception:  # noqa: BLE001
                        a["nodes"] = []
                for o in spec_objects(a.get("spec") or [], f["name"], have, a.get("nodes") or []):
                    if o["code"] not in wells:
                        wells[o["code"]] = o
            if f["kind"] == "estimate" and a.get("positions"):
                for p in a["positions"]:
                    code = f"См-{p['n']}" if p.get("n") else ""
                    if not code or _norm_code(code) in have:
                        continue
                    for v in _valve_elements(p, have):      # арматура из сметы — это материал, но объектом может стать
                        valves.append({**v, "file": f["name"]})
                    if _is_material(p.get("code") or "", ""):   # материалы — не работы: в перечень работ не попадают
                        continue
                    note = f"{p.get('qty', '')} {p.get('units', '')}".strip()
                    est.append({"code": code, "name": (p.get("name") or "")[:200], "kind": "Позиция сметы", "block": (p.get("chapter") or "Смета")[:80],
                                "planned_note": (note + (" · " + p["code"] if p.get("code") else "")).strip(), "source": "estimate",
                                "ops": [list(o) for o in EST_OPS], "file": f["name"]})
        if any(w["kind"] == "Арматура" for w in wells.values()):   # арматура есть в проекте — из сметы её не дублируем
            valves = []
        proj = sorted(wells.values(), key=lambda w: [int(x) if x.isdigit() else x for x in re.split(r"(\d+)", w["code"])])
        reference: list[dict[str, Any]] = []
        items, _ef = _work_items(c, sec, True)
        if items:       # смета загружена: в перечень идут только объекты, для которых в смете есть позиции; остальное — справочно
            cur = _alloc_elements(c, sec)
            sug = [_el_dict("sg:" + x["code"], x["code"], x["name"], x["kind"], x.get("block", ""), x.get("planned_note", ""), _sec_nets(sec)) for x in proj]
            cov = _covered_ids(items, cur + sug)
            keep = [x for x, e in zip(proj, sug) if e["id"] in cov or x["kind"] not in ("Колодец", "Трубопровод", "Арматура", "Фитинг", "Оборудование", "Деталь колодца", "Узел")]
            reference = [x for x in proj if x not in keep]
            proj = keep
        return {"project": proj, "reference": reference,
                "estimate": est, "valves": valves, "pending": pending, "section": sec["code"], "other_nets": other_nets}


class BulkItem(BaseModel):
    code: str = Field(min_length=1, max_length=120)
    name: str = Field(min_length=1, max_length=300)
    kind: str = Field(default="", max_length=60)
    block: str = Field(default="", max_length=100)
    planned_note: str = Field(default="", max_length=300)
    source: Literal["manual", "project", "estimate"] = "manual"
    ops: list[tuple[str, str]] = []
    weight: float = 1.0


@app.post("/api/elements/bulk", status_code=201)
def elements_bulk(items: list[BulkItem], section: Optional[str] = None) -> dict[str, Any]:
    added = skipped = 0
    with db() as c:
        sid = _section(c, section)["id"]
        have = _existing_codes(c, sid)
        for it in items:
            key = _norm_code(it.code)
            if key in have:
                skipped += 1
                continue
            have.add(key)
            eid = str(uuid.uuid4())
            c.execute("INSERT INTO elements (id,section_id,code,name,kind,block,planned_note,enabled,created_at,source,weight) VALUES (?,?,?,?,?,?,?,1,?,?,?)",
                      (eid, sid, it.code.strip(), it.name.strip(), it.kind.strip() or "Элемент", it.block.strip() or "Часть 1", it.planned_note.strip(), now(), it.source, max(it.weight, 0.01)))
            for order, (code, title) in enumerate(it.ops or STD_OPS, 1):
                c.execute("INSERT INTO operations (id,element_id,code,title,sort_order) VALUES (?,?,?,?,?)", (str(uuid.uuid4()), eid, code, title, order))
            added += 1
    return {"added": added, "skipped": skipped, "message": f"Добавлено: {added}" + (f", уже были в перечне: {skipped}" if skipped else "")}


class WeightIn(BaseModel):
    weight: float = Field(gt=0, le=1000000)


@app.put("/api/elements/{element_id}/weight")
def element_weight(element_id: str, payload: WeightIn) -> dict[str, str]:
    with db() as c:
        if not c.execute("SELECT 1 FROM elements WHERE id=?", (element_id,)).fetchone():
            raise HTTPException(404, "Элемент не найден")
        c.execute("UPDATE elements SET weight=? WHERE id=?", (payload.weight, element_id))
    return {"message": "Вес сохранён"}


OP_SHARE = {"install": 6.0, "survey": 1.0, "test": 3.0}


@app.get("/api/gantt")
def gantt(section: Optional[str] = None) -> dict[str, Any]:
    """Взвешенный прогресс по участкам: вес элемента × доля операции (монтаж 60 %, съёмка 10 %, испытание 30 %; остальные поровну)."""
    with db() as c:
        sid = _section(c, section)["id"]
        rows = c.execute("""
          SELECT el.id eid, el.block, el.weight, o.id oid, o.code ocode,
            (SELECT e.event_type FROM events e WHERE e.operation_id=o.id ORDER BY e.created_at DESC LIMIT 1) last,
            (SELECT e.performed_on FROM events e WHERE e.operation_id=o.id ORDER BY e.created_at DESC LIMIT 1) day
          FROM elements el JOIN operations o ON o.element_id=el.id WHERE el.enabled=1 AND el.scope='' AND el.section_id=? ORDER BY el.block, el.created_at, o.sort_order""", (sid,)).fetchall()
        per_el: dict[str, list[sqlite3.Row]] = {}
        for r in rows:
            per_el.setdefault(r["eid"], []).append(r)
        blocks: dict[str, dict[str, Any]] = {}
        for eid, ops in per_el.items():
            shares = [OP_SHARE.get(o["ocode"], 1.0) for o in ops]
            tot = sum(shares) or 1.0
            b = blocks.setdefault(ops[0]["block"] or "Без участка", {"block": ops[0]["block"] or "Без участка", "total": 0.0, "done": 0.0, "elements": 0, "ops": 0, "ops_done": 0, "start": None, "end": None})
            b["elements"] += 1
            for o, sh in zip(ops, shares):
                w = (ops[0]["weight"] or 1.0) * sh / tot
                b["total"] += w
                b["ops"] += 1
                if o["last"] == "complete":
                    b["done"] += w
                    b["ops_done"] += 1
                    if o["day"]:
                        b["start"] = min(b["start"] or o["day"], o["day"])
                        b["end"] = max(b["end"] or o["day"], o["day"])
        out = []
        for b in blocks.values():
            b["pct"] = round(100 * b["done"] / b["total"], 1) if b["total"] else 0.0
            b["total"] = round(b["total"], 3); b["done"] = round(b["done"], 3)
            out.append(b)
        tw = sum(b["total"] for b in out)
        dw = sum(b["done"] for b in out)
        days = [d for b in out for d in (b["start"], b["end"]) if d]
        return {"blocks": out, "pct": round(100 * dw / tw, 1) if tw else 0.0, "first": min(days) if days else None, "last": max(days) if days else None}


@app.get("/api/suggest")
def suggest_values(request: Request) -> dict[str, Any]:
    """Подсказки для полей: организации и представители, уже внесённые в другие объекты."""
    manage = _user_can_manage(getattr(request.state, "user", "") or "")
    with db() as c:
        orgs: dict[str, dict[str, str]] = {}
        people: dict[str, dict[str, str]] = {}
        for r in (c.execute("SELECT * FROM participants ORDER BY created_at DESC") if manage else []):  # данные других объектов — только ПТО/администратору
            d = dict(r)
            if d["org_name"] and d["org_name"] not in orgs:
                orgs[d["org_name"]] = {k: d[k] for k in ("org_name", "ogrn", "inn", "address", "phone", "sro")}
            if d["rep_name"] and d["rep_name"] not in people:
                people[d["rep_name"]] = {k: d[k] for k in ("rep_name", "rep_position", "rep_nrs_id", "rep_order", "org_name")}
        hid_o = {r[0] for r in c.execute("SELECT name FROM dict_orgs WHERE hidden=1")}
        hid_u = {r[0] for r in c.execute("SELECT name FROM dict_users WHERE active=0")}
        for n in hid_o:
            orgs.pop(n, None)
        for n in hid_u:
            people.pop(n, None)
        for r in c.execute("SELECT * FROM dict_orgs WHERE hidden=0 ORDER BY name"):
            orgs[r["name"]] = {"org_name": r["name"], "ogrn": r["ogrn"], "inn": r["inn"], "address": r["address"], "phone": r["phone"], "sro": r["sro"], "ours": r["ours"]}
        for r in c.execute("SELECT * FROM dict_users WHERE active=1 ORDER BY name"):
            people[r["name"]] = {"rep_name": r["name"], "rep_position": r["position"], "rep_nrs_id": r["rep_nrs_id"], "rep_order": r["rep_order"], "org_name": r["org_name"]}
        positions = [r["name"] for r in c.execute("SELECT name FROM dict_positions WHERE hidden=0 ORDER BY name")]
        users = [dict(r) for r in c.execute("SELECT id,name,position,org_name,login,app_role FROM dict_users WHERE active=1 ORDER BY name")]
        objects = [dict(r) for r in c.execute("SELECT o.id,o.name,o.short_name,o.address,(SELECT p.id FROM projects p WHERE p.object_id=o.id AND p.archived=0 LIMIT 1) project_id FROM dict_objects o WHERE o.hidden=0 ORDER BY lower(o.name)")]
        return {"orgs": list(orgs.values()), "people": list(people.values()), "positions": positions, "users": users, "objects": objects,
                "sectypes": [dict(r) for r in c.execute("SELECT name,code,kind FROM dict_sectypes WHERE hidden=0 ORDER BY CASE kind WHEN 'РД' THEN 0 ELSE 1 END, lower(name)")],
                "systems": [dict(r) for r in c.execute("SELECT name,descr FROM dict_systems WHERE hidden=0 ORDER BY lower(name)")]}


