DEFAULT_POSITIONS = ["Руководитель проекта", "Главный инженер", "Начальник участка", "Производитель работ (прораб)", "Мастер",
                     "Инженер ПТО", "Ведущий инженер ПТО", "Геодезист", "Инженер по технадзору", "Представитель заказчика",
                     "Представитель авторского надзора", "Главный инженер проекта", "Генеральный директор", "Директор"]


def seed_dicts(c: sqlite3.Connection) -> None:
    """Первичное наполнение справочников из уже внесённых данных (один раз, пока пусты)."""
    if not c.execute("SELECT 1 FROM dict_positions LIMIT 1").fetchone():
        names = list(DEFAULT_POSITIONS)
        names += [r[0] for r in c.execute("SELECT DISTINCT rep_position FROM participants WHERE rep_position<>''")]
        names += [r[0] for r in c.execute("SELECT DISTINCT position FROM team WHERE position<>''")]
        for n in dict.fromkeys(x.strip() for x in names if x and x.strip()):
            c.execute("INSERT OR IGNORE INTO dict_positions (id,name,created_at) VALUES (?,?,?)", (str(uuid.uuid4()), n, now()))
    if not c.execute("SELECT 1 FROM dict_orgs LIMIT 1").fetchone():
        for r in c.execute("SELECT * FROM participants WHERE org_name<>'' ORDER BY created_at DESC"):
            c.execute("INSERT OR IGNORE INTO dict_orgs (id,name,inn,ogrn,address,phone,sro,created_at) VALUES (?,?,?,?,?,?,?,?)",
                      (str(uuid.uuid4()), r["org_name"].strip(), r["inn"], r["ogrn"], r["address"], r["phone"], r["sro"], now()))
    if not c.execute("SELECT 1 FROM dict_users LIMIT 1").fetchone():
        seen = set()
        for r in c.execute("SELECT name,position,app_role,login FROM team ORDER BY created_at"):
            k = r["name"].strip().lower()
            if k in seen:
                continue
            seen.add(k)
            c.execute("INSERT INTO dict_users (id,name,position,org_name,login,app_role,created_at) VALUES (?,?,?,?,?,?,?)",
                      (str(uuid.uuid4()), r["name"].strip(), r["position"], "ООО \"ИТС\"" if True else "", r["login"], r["app_role"], now()))
        for r in c.execute("SELECT * FROM participants WHERE rep_name<>'' ORDER BY created_at DESC"):
            k = r["rep_name"].strip().lower()
            if k in seen:
                continue
            seen.add(k)
            c.execute("INSERT INTO dict_users (id,name,position,org_name,rep_nrs_id,rep_order,created_at) VALUES (?,?,?,?,?,?,?)",
                      (str(uuid.uuid4()), r["rep_name"].strip(), r["rep_position"], r["org_name"], r["rep_nrs_id"], r["rep_order"], now()))


def _relink(c: sqlite3.Connection) -> None:
    """Привязка записей к справочникам по идентификаторам (идемпотентно; дозаполняет только пустые связи)."""
    for tb, idc, namec in (("participants", "org_id", "org_name"), ("dict_users", "org_id", "org_name"), ("team", "org_id", "org_name"),
                           ("section_persons", "org_id", "org_name"), ("input_control", "supplier_id", "supplier")):
        c.execute(f"UPDATE {tb} SET {idc}=(SELECT o.id FROM dict_orgs o WHERE lower(o.name)=lower(trim({tb}.{namec})) LIMIT 1) "
                  f"WHERE {idc}='' AND trim({namec})<>'' AND EXISTS (SELECT 1 FROM dict_orgs o WHERE lower(o.name)=lower(trim({tb}.{namec})))")
    users = [(r["id"], (r["name"] or "").strip().lower(), (r["org_name"] or "").strip().lower()) for r in c.execute("SELECT id,name,org_name FROM dict_users")]

    def pick(name: str, org: str) -> str:
        cand = [u for u in users if u[1] == name.strip().lower()]
        if not cand:
            return ""
        same = [u for u in cand if u[2] == org.strip().lower()]
        return (same or cand)[0][0]

    for tb, uc, nc in (("participants", "rep_user_id", "rep_name"), ("section_persons", "user_id", "name")):
        for r in c.execute(f"SELECT id,{nc} n,org_name o FROM {tb} WHERE {uc}='' AND trim({nc})<>''").fetchall():
            uid = pick(r["n"], r["o"])
            if uid:
                c.execute(f"UPDATE {tb} SET {uc}=? WHERE id=?", (uid, r["id"]))


@app.get("/api/integrity")
def integrity(request: Request) -> dict[str, Any]:
    if not _user_can_manage(getattr(request.state, "user", "") or ""):
        raise HTTPException(403, "Недостаточно прав: проверка связей доступна ПТО и администратору")
    """Записи, которые ещё не связаны со справочниками (названия набраны вручную и не найдены)."""
    out: list[dict[str, str]] = []
    with db() as c:
        _relink(c)
        for r in c.execute("SELECT DISTINCT org_name n FROM participants WHERE org_name<>'' AND org_id=''"):
            out.append({"where": "Участники объектов", "what": "организация", "name": r["n"]})
        for r in c.execute("SELECT DISTINCT rep_name n FROM participants WHERE rep_name<>'' AND rep_user_id=''"):
            out.append({"where": "Участники объектов", "what": "подписант", "name": r["n"]})
        for r in c.execute("SELECT DISTINCT org_name n FROM section_persons WHERE org_name<>'' AND org_id=''"):
            out.append({"where": "Прочие лица разделов", "what": "организация", "name": r["n"]})
        for r in c.execute("SELECT DISTINCT supplier n FROM input_control WHERE supplier<>'' AND supplier_id=''"):
            out.append({"where": "ЖВК", "what": "поставщик", "name": r["n"]})
        for r in c.execute("SELECT DISTINCT name n FROM team WHERE user_id=''"):
            out.append({"where": "Команда объектов", "what": "сотрудник", "name": r["n"]})
    return {"items": out}


DICTS = {
    "orgs": ("dict_orgs", ("name", "inn", "ogrn", "address", "phone", "sro", "ours"), "name"),
    "positions": ("dict_positions", ("name",), "name"),
    "objects": ("dict_objects", ("name", "short_name", "address"), "name"),
    "sectypes": ("dict_sectypes", ("name", "code", "kind"), "name"),
    "systems": ("dict_systems", ("name", "descr"), "name"),
    "users": ("dict_users", ("name", "position", "org_name", "login", "app_role", "role_manual", "phone", "email", "rep_nrs_id", "rep_order", "active"), "name"),
}


@app.get("/api/dict/{kind}/{rid}/usage")
def dict_usage(kind: str, rid: str) -> dict[str, Any]:
    """Где и в какой роли встречается организация / человек: история участия по объектам."""
    labels = {k: lab for k, lab, _ in ROLES}
    out: list[dict[str, str]] = []
    with db() as c:
        if kind == "orgs":
            row = c.execute("SELECT name FROM dict_orgs WHERE id=?", (rid,)).fetchone()
            if not row:
                raise HTTPException(404, "Запись не найдена")
            for r in c.execute("SELECT p.id pid,p.object_name,p.short_name,p.our_role,p.archived,pa.role,pa.rep_name,pa.rep_position FROM participants pa JOIN projects p ON p.id=pa.project_id WHERE pa.org_id=? OR pa.org_name=? ORDER BY p.created_at", (rid, row["name"])):
                out.append({"project": r["short_name"] or _display_name(r["object_name"]), "archived": bool(r["archived"]), "role": labels.get(r["role"], r["role"]),
                            "who": (r["rep_position"] + " " + r["rep_name"]).strip(), "ours": r["our_role"] == r["role"]})
        elif kind == "users":
            row = c.execute("SELECT name FROM dict_users WHERE id=?", (rid,)).fetchone()
            if not row:
                raise HTTPException(404, "Запись не найдена")
            for r in c.execute("SELECT p.object_name,p.short_name,p.archived,t.position,t.app_role,t.org_name FROM team t JOIN projects p ON p.id=t.project_id WHERE t.user_id=? OR lower(t.name)=lower(?) ORDER BY p.created_at", (rid, row["name"])):
                out.append({"project": r["short_name"] or _display_name(r["object_name"]), "archived": bool(r["archived"]), "role": APP_ROLE_RU.get(r["app_role"], "Участник"),
                            "who": (r["position"] + (" · " + r["org_name"] if r["org_name"] else "")).strip(), "ours": False})
            for r in c.execute("SELECT p.object_name,p.short_name,p.archived,pa.role,pa.org_name,pa.rep_position FROM participants pa JOIN projects p ON p.id=pa.project_id WHERE pa.rep_user_id=? OR lower(pa.rep_name)=lower(?) ORDER BY p.created_at", (rid, row["name"])):
                out.append({"project": r["short_name"] or _display_name(r["object_name"]), "archived": bool(r["archived"]), "role": "Подписант: " + labels.get(r["role"], r["role"]),
                            "who": (r["rep_position"] + " · " + r["org_name"]).strip(" ·"), "ours": False})
        else:
            raise HTTPException(404, "Нет такого справочника")
    return {"name": row["name"], "items": out}


@app.get("/api/dict/{kind}")
def dict_list(request: Request, kind: str) -> list[dict[str, Any]]:
    if kind not in DICTS:
        raise HTTPException(404, "Нет такого справочника")
    tbl, cols, order = DICTS[kind]
    extra = "" if kind == "users" else ",hidden"
    with db() as c:
        out = [dict(r) for r in c.execute(f"SELECT id,{','.join(cols)}{extra} FROM {tbl} ORDER BY lower({order})")]
    manage = _user_can_manage(getattr(request.state, "user", "") or "")
    for r in out:
        if kind == "users":
            r["hidden"] = 0 if r["active"] else 1
            if not manage:  # контакты и логины видит только ПТО/администратор
                for k in ("phone", "email", "login", "rep_nrs_id", "rep_order"):
                    r.pop(k, None)
    return out


def _dict_clean(kind: str, data: dict[str, Any]) -> dict[str, Any]:
    tbl, cols, _ = DICTS[kind]
    out: dict[str, Any] = {}
    for k in cols:
        if k == "active":
            out[k] = 0 if data.get(k) in (0, False, "0") else 1
        elif k == "ours":
            out[k] = 1 if data.get(k) in (1, True, "1") else 0
        elif k == "role_manual":
            continue
        elif k == "app_role":
            v = str(data.get(k) or "auto")
            if v in APP_ROLES:
                out[k], out["role_manual"] = v, 1
            else:  # «авто» — роль определяется по должности
                out[k], out["role_manual"] = _role_for_position(str(data.get("position") or "")), 0
        else:
            out[k] = " ".join(str(data.get(k) or "").split())[:500] if k in ("name", "short_name") else str(data.get(k) or "").strip()[:500]
            if k == "short_name":
                out[k] = out[k][:60]
    if not out.get("name"):
        raise HTTPException(422, "Укажите наименование" if kind != "users" else "Укажите ФИО")
    if kind == "users":
        if out.get("phone") and not _norm_phone(out["phone"]):
            raise HTTPException(422, "Телефон указан неверно: нужно 10–11 цифр, например +7 900 123-45-67")
        if out.get("email") and not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", out["email"]):
            raise HTTPException(422, "Почта указана неверно")
        if out.get("email"):
            with db() as c0:
                for o in c0.execute("SELECT id,email FROM dict_users WHERE email<>''"):
                    if o["id"] != str(data.get("_id", "")) and o["email"].strip().lower() == out["email"].lower():
                        raise HTTPException(409, "Такая почта уже указана у другого пользователя")
            if not out.get("login"):
                out["login"] = out["email"].lower()  # почта — логин по умолчанию
    if kind == "users" and out["login"]:
        if APP_USER and out["login"].lower() == APP_USER.lower():
            raise HTTPException(409, "Этот логин занят служебным входом")
        with db() as c:
            if c.execute("SELECT 1 FROM dict_users WHERE lower(login)=lower(?) AND id<>?", (out["login"], str(data.get("_id", "")))).fetchone():
                raise HTTPException(409, "Такой логин уже есть у другого пользователя")
    return out


@app.post("/api/dict/{kind}")
def dict_add(kind: str, data: dict[str, Any]) -> dict[str, Any]:
    if kind not in DICTS:
        raise HTTPException(404, "Нет такого справочника")
    tbl, cols, _ = DICTS[kind]
    d = _dict_clean(kind, data)
    with db() as c:
        if kind != "users" and c.execute(f"SELECT 1 FROM {tbl} WHERE lower(name)=lower(?)", (d["name"],)).fetchone():
            raise HTTPException(409, "Такая запись уже есть")
        i = str(uuid.uuid4())
        c.execute(f"INSERT INTO {tbl} (id,{','.join(cols)},created_at) VALUES (?,{','.join('?' * len(cols))},?)", (i, *[d[k] for k in cols], now()))
    return {"id": i}


@app.put("/api/dict/{kind}/{rid}")
def dict_put(request: Request, kind: str, rid: str, data: dict[str, Any]) -> dict[str, str]:
    if kind not in DICTS:
        raise HTTPException(404, "Нет такого справочника")
    tbl, cols, _ = DICTS[kind]
    d = _dict_clean(kind, {**data, "_id": rid})
    with db() as c:
        old = c.execute(f"SELECT * FROM {tbl} WHERE id=?", (rid,)).fetchone()
        if not old:
            raise HTTPException(404, "Запись не найдена")
        if kind == "users" and old["pw_hash"] and not _is_admin(getattr(request.state, "user", "") or ""):
            for k in ("email", "login"):
                if d[k].lower() != (old[k] or "").lower():
                    raise HTTPException(403, "У пользователя с паролем почту и логин меняет только администратор (иначе можно перехватить чужой доступ)")
        if kind != "users" and c.execute(f"SELECT 1 FROM {tbl} WHERE lower(name)=lower(?) AND id<>?", (d["name"], rid)).fetchone():
            raise HTTPException(409, "Такая запись уже есть")
        c.execute(f"UPDATE {tbl} SET {','.join(k + '=?' for k in cols)} WHERE id=?", (*[d[k] for k in cols], rid))
        if kind == "users" and not d["role_manual"]:
            c.execute("UPDATE team SET app_role=? WHERE user_id=? AND role_manual=0", (d["app_role"], rid))
        if kind == "orgs" and old["name"] != d["name"]:
            _relink(c)
            for tb, idc, namec in (("participants", "org_id", "org_name"), ("dict_users", "org_id", "org_name"), ("team", "org_id", "org_name"),
                                   ("section_persons", "org_id", "org_name"), ("input_control", "supplier_id", "supplier")):
                c.execute(f"UPDATE {tb} SET {namec}=? WHERE {idc}=?", (d["name"], rid))
        if kind == "users":
            c.execute("UPDATE dict_users SET org_id='' WHERE id=?", (rid,))
            _relink(c)
            c.execute("UPDATE team SET name=? WHERE user_id=?", (d["name"], rid))
            c.execute("UPDATE participants SET rep_name=? WHERE rep_user_id=?", (d["name"], rid))
            c.execute("UPDATE section_persons SET name=? WHERE user_id=?", (d["name"], rid))
            c.execute("UPDATE team SET login=? WHERE user_id=? AND login=''", (d["login"], rid))
        if kind == "objects":
            c.execute("UPDATE projects SET object_name=?, short_name=?, address=? WHERE object_id=?", (d["name"], d["short_name"], d["address"], rid))
        if kind == "positions" and old["name"] != d["name"]:
            c.execute("UPDATE participants SET rep_position=? WHERE rep_position=?", (d["name"], old["name"]))
            c.execute("UPDATE team SET position=? WHERE position=?", (d["name"], old["name"]))
            c.execute("UPDATE dict_users SET position=? WHERE position=?", (d["name"], old["name"]))
    return {"message": "Сохранено"}


def _dict_used(c: sqlite3.Connection, kind: str, rid: str, name: str) -> int:
    q = lambda sql, *a: c.execute(sql, a).fetchone()[0]
    if kind == "orgs":
        return (q("SELECT COUNT(*) FROM participants WHERE org_id=? OR org_name=?", rid, name) + q("SELECT COUNT(*) FROM team WHERE org_id=? OR org_name=?", rid, name)
                + q("SELECT COUNT(*) FROM dict_users WHERE org_id=? OR org_name=?", rid, name) + q("SELECT COUNT(*) FROM section_persons WHERE org_id=? OR org_name=?", rid, name)
                + q("SELECT COUNT(*) FROM input_control WHERE supplier_id=? OR supplier=?", rid, name))
    if kind == "positions":
        return (q("SELECT COUNT(*) FROM participants WHERE rep_position=?", name) + q("SELECT COUNT(*) FROM team WHERE position=?", name)
                + q("SELECT COUNT(*) FROM dict_users WHERE position=?", name) + q("SELECT COUNT(*) FROM section_persons WHERE position=?", name))
    if kind == "objects":
        return q("SELECT COUNT(*) FROM projects WHERE object_id=?", rid)
    if kind == "users":
        return (q("SELECT COUNT(*) FROM team WHERE user_id=?", rid) + q("SELECT COUNT(*) FROM section_persons WHERE user_id=?", rid)
                + q("SELECT COUNT(*) FROM participants WHERE rep_user_id=? OR lower(rep_name)=lower(?)", rid, name))
    return 0


@app.delete("/api/dict/{kind}/{rid}")
def dict_del(kind: str, rid: str) -> dict[str, str]:
    if kind not in DICTS:
        raise HTTPException(404, "Нет такого справочника")
    tbl = DICTS[kind][0]
    with db() as c:
        row = c.execute(f"SELECT name FROM {tbl} WHERE id=?", (rid,)).fetchone()
        if not row:
            raise HTTPException(404, "Запись не найдена")
        used = _dict_used(c, kind, rid, row["name"])
        if used:
            raise HTTPException(409, f"Запись используется в данных ({used}) — удалить её нельзя, пока она связана с объектами и документами. Скройте её: она пропадёт из подсказок и списков, останется в документах, и её можно будет вернуть.")
        c.execute(f"DELETE FROM {tbl} WHERE id=?", (rid,))
    return {"message": "Удалено"}


class HideIn(BaseModel):
    hidden: bool


@app.put("/api/dict/{kind}/{rid}/hidden")
def dict_hide(kind: str, rid: str, payload: HideIn) -> dict[str, str]:
    if kind not in DICTS:
        raise HTTPException(404, "Нет такого справочника")
    tbl = DICTS[kind][0]
    with db() as c:
        if not c.execute(f"SELECT 1 FROM {tbl} WHERE id=?", (rid,)).fetchone():
            raise HTTPException(404, "Запись не найдена")
        if kind == "users":
            c.execute("UPDATE dict_users SET active=? WHERE id=?", (0 if payload.hidden else 1, rid))
        else:
            c.execute(f"UPDATE {tbl} SET hidden=? WHERE id=?", (1 if payload.hidden else 0, rid))
    if kind == "users":
        _ok_cache.clear()
    return {"message": "Скрыто" if payload.hidden else "Возвращено"}


