_UUID = r"([0-9a-fA-F-]{36})"


def _audit_scope(c: sqlite3.Connection, path: str, query: Any) -> tuple[str, str]:
    sid = pid = ""
    m = re.search(r"/api/sections/" + _UUID, path)
    sid = m.group(1) if m else (query.get("section") or "")
    m = re.search(r"/api/projects/" + _UUID, path)
    pid = m.group(1) if m else (query.get("project") or "")
    if sid and not pid:
        r = c.execute("SELECT project_id FROM sections WHERE id=?", (sid,)).fetchone()
        pid = r["project_id"] if r else ""
    return sid, pid


def audit(request: Request, c: sqlite3.Connection, entity: str, eid: str, action: str, summary: str,
          diff: Any = None, section_id: str = "", project_id: str = "") -> None:
    request.state.audited = True
    if section_id and not project_id:
        r = c.execute("SELECT project_id FROM sections WHERE id=?", (section_id,)).fetchone()
        project_id = r["project_id"] if r else ""
    _audit_ins(c, str(uuid.uuid4()), now(), (getattr(request.state, "user", "") or "")[:80], request.method, request.url.path[:200], entity, eid, section_id, project_id,
               action, summary[:300], json.dumps(diff, ensure_ascii=False)[:8000] if diff is not None else "")


def _diff(before: dict[str, Any], after: dict[str, Any], labels: dict[str, str]) -> dict[str, list[str]]:
    out: dict[str, list[str]] = {}
    for k, v in after.items():
        if str(before.get(k, "") or "") != str(v or ""):
            out[labels.get(k, k)] = [str(before.get(k, "") or "")[:500], str(v or "")[:500]]
    return out


def _mask(o: Any) -> Any:
    if isinstance(o, dict):
        return {k: ("***" if re.search(r"pass|pw|token|секрет", k, re.I) else _mask(v)) for k, v in o.items()}
    if isinstance(o, list):
        return [_mask(x) for x in o[:60]]
    return o


@app.middleware("http")
async def audit_mw(request: Request, call_next):
    m, path = request.method, request.url.path
    track = m in ("POST", "PUT", "DELETE", "PATCH") and path.startswith("/api/") and not path.startswith(_AUDIT_SKIP)
    body = b""
    if track and "json" in request.headers.get("content-type", "") and int(request.headers.get("content-length", "0") or 0) < 65536:
        body = await request.body()
    resp = await call_next(request)
    if track and resp.status_code < 400 and not getattr(request.state, "audited", False):
        try:
            known = next((lb for mm, rx, lb in _AUDIT_LABELS if mm == m and re.search(rx, path)), None)
            label = known or {"POST": "Добавление", "PUT": "Изменение", "DELETE": "Удаление", "PATCH": "Изменение"}.get(m, m) + " (служебное действие)"
            diff = None
            if body:
                try:
                    obj = json.loads(body)
                    if isinstance(obj, dict) and (obj.get("name") or obj.get("org_name")):
                        diff = {"Наименование": ["", str(obj.get("name") or obj.get("org_name"))[:200]]}
                        label += ": «" + str(obj.get("name") or obj.get("org_name"))[:80] + "»"
                    elif not known:
                        diff = {"Технические данные": json.dumps(_mask(obj), ensure_ascii=False)[:1500], "Адрес запроса": m + " " + path}
                except ValueError:
                    pass
            with db() as c:
                sid, pid = _audit_scope(c, path, request.query_params)
                ent = path.split("/")[2] if len(path.split("/")) > 2 else ""
                _audit_ins(c, str(uuid.uuid4()), now(), (getattr(request.state, "user", "") or "")[:80], m, path[:200], ent, "", sid, pid, "", label,
                           json.dumps(diff, ensure_ascii=False) if diff else "")
        except Exception:  # noqa: BLE001
            pass
    return resp


@app.get("/api/audit")
def audit_list(request: Request, section: Optional[str] = None, limit: int = 300) -> dict[str, Any]:
    login = getattr(request.state, "user", "") or ""
    is_admin = bool(APP_USER) and login.lower() == APP_USER.lower()    # служебные записи безопасности (почта, коды, блокировки) видит только администратор
    with db() as c:
        sec = _section(c, section)
        rows = c.execute("SELECT * FROM audit WHERE section_id=? OR (section_id='' AND (project_id=? OR project_id='' OR (project_id='_sys' AND ?=1))) ORDER BY at DESC LIMIT ?", (sec["id"], sec["project_id"], 1 if is_admin else 0, max(1, min(limit, 1000)))).fetchall()
        items = []
        for r in rows:
            try:
                diff = json.loads(r["diff_json"]) if r["diff_json"] else None
            except ValueError:
                diff = None
            items.append({"at": r["at"], "user": r["user"], "summary": r["summary"], "entity": r["entity"], "diff": diff, "level": "раздел" if r["section_id"] else ("объект" if r["project_id"] else "общее")})
    return {"items": items, "section": sec["code"]}


# ---------------------------------------------------------------- Резервные копии
DATA_BACKUP_DIR = Path(os.getenv("APP_DATA_BACKUP_DIR", str(DB_PATH.parent / "backups")))
KEEP_AUTO, KEEP_MANUAL = 14, 10
_BK_LOCK = threading.Lock()


def _bk_stamp() -> str:
    return datetime.now().strftime("%Y%m%d-%H%M%S")


def make_db_backup(prefix: str = "db") -> Path:
    """Согласованный снимок базы (SQLite backup API) в сжатом виде; старые снимки удаляются."""
    with _BK_LOCK:
        DATA_BACKUP_DIR.mkdir(parents=True, exist_ok=True)
        tmp = DATA_BACKUP_DIR / f"tmp-{uuid.uuid4().hex}.sqlite3"
        src, dst = sqlite3.connect(DB_PATH), sqlite3.connect(tmp)
        try:
            with dst:
                src.backup(dst)
        finally:
            src.close(); dst.close()
        out = DATA_BACKUP_DIR / f"{prefix}-{_bk_stamp()}.sqlite3.gz"
        with open(tmp, "rb") as f, gzip.open(out, "wb", compresslevel=6) as g:
            shutil.copyfileobj(f, g)
        tmp.unlink(missing_ok=True)
        for pf, keep in (("db", KEEP_AUTO), ("dbm", KEEP_MANUAL), ("pre", 5)):
            for old in sorted(DATA_BACKUP_DIR.glob(f"{pf}-*.sqlite3.gz"), key=lambda x: x.stat().st_mtime)[:-keep]:
                old.unlink(missing_ok=True)
        return out


def _bk_list() -> list[dict[str, Any]]:
    out = []
    if DATA_BACKUP_DIR.exists():
        for f in sorted(DATA_BACKUP_DIR.glob("*.sqlite3.gz"), key=lambda x: x.stat().st_mtime, reverse=True):
            kind = {"db": "авто", "dbm": "вручную", "pre": "перед восстановлением"}.get(f.name.split("-")[0], "")
            out.append({"name": f.name, "size": f.stat().st_size, "at": datetime.fromtimestamp(f.stat().st_mtime).strftime("%Y-%m-%d %H:%M"), "kind": kind})
    return out


def _bk_loop_body() -> None:
    last = max((f.stat().st_mtime for f in DATA_BACKUP_DIR.glob("*.sqlite3.gz")), default=0) if DATA_BACKUP_DIR.exists() else 0
    if time.time() - last > 22 * 3600:
        make_db_backup("db")


def _backup_loop() -> None:
    time.sleep(90)
    while True:
        try:
            _bk_loop_body()
        except Exception:  # noqa: BLE001
            pass
        try:
            _drive_sync_cycle()
        except Exception:  # noqa: BLE001
            pass
        time.sleep(1800)


def _last_download() -> str:
    try:
        return (DATA_BACKUP_DIR / "last_download.txt").read_text(encoding="utf-8").strip()
    except OSError:
        return ""


@app.get("/api/admin/backup")
def backup_info(request: Request) -> dict[str, Any]:
    _require_admin(request)
    ld = _last_download()
    days = None
    if ld:
        try:
            days = (datetime.now() - datetime.fromisoformat(ld)).days
        except ValueError:
            days = None
    size = 0
    for d in (FILES_DIR, PHOTOS_DIR):
        if d.exists():
            size += sum(f.stat().st_size for f in d.rglob("*") if f.is_file())
    return {"items": _bk_list(), "last_download": ld, "days_since_download": days, "data_size": size + (DB_PATH.stat().st_size if DB_PATH.exists() else 0), "keep_auto": KEEP_AUTO, "drive": _drive_status()}


@app.post("/api/admin/backup")
def backup_make(request: Request) -> dict[str, Any]:
    _require_admin(request)
    f = make_db_backup("dbm")
    return {"name": f.name, "message": "Копия базы создана"}


def _bk_path(name: str) -> Path:
    if not re.fullmatch(r"(db|dbm|pre)-\d{8}-\d{6}\.sqlite3\.gz", name):
        raise HTTPException(400, "Недопустимое имя копии")
    p = DATA_BACKUP_DIR / name
    if not p.exists():
        raise HTTPException(404, "Копия не найдена")
    return p


@app.get("/api/admin/backup/db/{name}")
def backup_get(request: Request, name: str) -> FileResponse:
    _require_admin(request)
    p = _bk_path(name)
    return FileResponse(p, media_type="application/gzip", filename=name)


@app.post("/api/admin/backup/restore")
def backup_restore(request: Request, name: str) -> dict[str, str]:
    _require_admin(request)
    p = _bk_path(name)
    tmp = DATA_BACKUP_DIR / f"restore-{uuid.uuid4().hex}.sqlite3"
    with gzip.open(p, "rb") as g, open(tmp, "wb") as f:
        shutil.copyfileobj(g, f)
    chk = sqlite3.connect(tmp)
    try:
        ok = chk.execute("PRAGMA integrity_check").fetchone()[0] == "ok" and chk.execute("SELECT COUNT(*) FROM projects").fetchone() is not None
    except sqlite3.DatabaseError:
        ok = False
    finally:
        chk.close()
    if not ok:
        tmp.unlink(missing_ok=True)
        raise HTTPException(422, "Копия повреждена — восстановление отменено")
    make_db_backup("pre")  # текущее состояние сохраняем перед заменой
    for suf in ("-wal", "-shm"):
        Path(str(DB_PATH) + suf).unlink(missing_ok=True)
    os.replace(tmp, DB_PATH)
    _restart_soon()
    return {"message": "База восстановлена из копии " + name + ". Программа перезапускается (около 15 секунд)."}


# ---- Выгрузка копий на Google Диск через скрипт Google Apps Script (работает от имени владельца Диска, ключей Google не нужно)
APPS_SCRIPT = r"""// ИД ИТС — приёмник резервных копий. Вставьте в script.google.com, замените ключ, разверните как «Веб-приложение».
const TOKEN = 'ЗАМЕНИТЕ_НА_СВОЙ_КЛЮЧ';

function doPost(e) {
  var r = {ok: false};
  try {
    var q = JSON.parse(e.postData.contents);
    if (q.token !== TOKEN) throw new Error('Неверный ключ');
    if (q.action === 'mail') {
      MailApp.sendEmail({to: q.to, subject: q.subject, body: q.body, name: 'ИД ИТС'});
      return ContentService.createTextOutput(JSON.stringify({ok: true})).setMimeType(ContentService.MimeType.JSON);
    }
    var root = DriveApp.getFolderById(q.folder);
    var dir = root;
    if (q.sub) {
      var it = root.getFoldersByName(q.sub);
      dir = it.hasNext() ? it.next() : root.createFolder(q.sub);
    }
    if (q.action === 'ping') {
      r = {ok: true, folder: root.getName()};
    } else if (q.action === 'prune') {
      var files = [], fi = dir.getFiles();
      while (fi.hasNext()) { var f = fi.next(); if (f.getName().indexOf(q.prefix) === 0) files.push(f); }
      files.sort(function (a, b) { return b.getDateCreated() - a.getDateCreated(); });
      for (var i = q.keep; i < files.length; i++) files[i].setTrashed(true);
      r = {ok: true, removed: Math.max(0, files.length - q.keep)};
    } else if (q.action === 'session') {
      var res = UrlFetchApp.fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable', {
        method: 'post', contentType: 'application/json; charset=UTF-8', muteHttpExceptions: true,
        headers: {Authorization: 'Bearer ' + ScriptApp.getOAuthToken(), 'X-Upload-Content-Type': q.mime || 'application/octet-stream'},
        payload: JSON.stringify({name: q.name, parents: [dir.getId()]})
      });
      if (res.getResponseCode() !== 200) throw new Error('Диск: ' + res.getContentText());
      r = {ok: true, upload_url: res.getAllHeaders()['Location']};
    }
  } catch (err) { r = {ok: false, error: String(err)}; }
  return ContentService.createTextOutput(JSON.stringify(r)).setMimeType(ContentService.MimeType.JSON);
}
"""
_DRIVE_LOCK = threading.Lock()
_ALLOW_ANY_URL = os.getenv("APP_DRIVE_ALLOW_ANY") == "1"  # только для тестов


def _kv_get(k: str, d: str = "") -> str:
    with db() as c:
        r = c.execute("SELECT v FROM kv WHERE k=?", (k,)).fetchone()
    return r["v"] if r else d


def _kv_set(k: str, v: str) -> None:
    with db() as c:
        c.execute("INSERT INTO kv (k,v) VALUES (?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v", (k, v))


def _folder_id(link: str) -> str:
    link = (link or "").strip()
    m = re.search(r"/folders/([\w-]+)", link) or re.search(r"[?&]id=([\w-]+)", link)
    if m:
        return m.group(1)
    return link if re.fullmatch(r"[\w-]{15,}", link) else ""


def _drive_cfg(need_enabled: bool = True) -> Optional[dict[str, str]]:
    cfg = {k: _kv_get("drive_" + k) for k in ("link", "url", "token", "enabled")}
    cfg["folder"] = _folder_id(cfg["link"])
    if not (cfg["folder"] and cfg["url"] and cfg["token"]):
        return None
    if need_enabled and cfg["enabled"] != "1":
        return None
    return cfg


def _drive_post(cfg: dict[str, str], payload: dict[str, Any]) -> dict[str, Any]:
    body = json.dumps({**payload, "token": cfg["token"], "folder": cfg["folder"]}).encode()
    req = urllib.request.Request(cfg["url"], data=body, headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=90) as r:  # ответ Apps Script приходит через перенаправление — urllib его выполняет
        raw = r.read()
    try:
        j = json.loads(raw)
    except ValueError as ex:
        raise RuntimeError("Скрипт ответил не так, как ожидалось: проверьте адрес развёртывания и доступ «Все»") from ex
    if not j.get("ok"):
        raise RuntimeError(j.get("error") or "ошибка скрипта")
    return j


def _drive_upload(cfg: dict[str, str], path: Path, name: str, sub: str) -> None:
    size = path.stat().st_size
    if size == 0:
        return
    mime = "application/gzip" if name.endswith(".gz") else "application/octet-stream"
    j = _drive_post(cfg, {"action": "session", "name": name, "sub": sub, "mime": mime})
    u = urllib.parse.urlsplit(j["upload_url"])
    if not _ALLOW_ANY_URL and (u.scheme != "https" or u.hostname not in ("www.googleapis.com", "googleapis.com")):
        raise RuntimeError("Скрипт вернул неожиданный адрес загрузки")
    Conn = http.client.HTTPSConnection if u.scheme == "https" else http.client.HTTPConnection
    target = u.path + ("?" + u.query if u.query else "")
    CH = 8 * 1024 * 1024
    pos = 0
    with open(path, "rb") as f:
        while pos < size:
            f.seek(pos)
            chunk = f.read(CH)
            end = pos + len(chunk) - 1
            conn = Conn(u.netloc, timeout=180)
            try:
                conn.request("PUT", target, body=chunk, headers={"Content-Length": str(len(chunk)), "Content-Range": f"bytes {pos}-{end}/{size}"})
                r = conn.getresponse(); r.read()
                st, rng = r.status, r.getheader("Range") or ""
            finally:
                conn.close()
            if st in (200, 201):
                return
            if st == 308:
                m = re.search(r"-(\d+)$", rng)
                pos = int(m.group(1)) + 1 if m else 0
                continue
            raise RuntimeError(f"Диск ответил {st}")
    raise RuntimeError("Загрузка не завершилась")


def _drive_pending(c: sqlite3.Connection) -> list[tuple[Path, str, str, str]]:
    """Что ещё не выгружено: (путь, имя на Диске, подпапка, ключ)."""
    done = {r["path"]: (r["size"], r["mtime"]) for r in c.execute("SELECT path,size,mtime FROM drive_sync")}
    out: list[tuple[Path, str, str, str]] = []
    if DATA_BACKUP_DIR.exists():
        for f in sorted(DATA_BACKUP_DIR.glob("*.sqlite3.gz"), key=lambda x: x.stat().st_mtime):
            k = "db/" + f.name
            if not f.name.startswith("pre-") and k not in done:
                out.append((f, f.name, "db", k))
    for base, sub in ((PHOTOS_DIR, "photos"), (FILES_DIR, "files")):
        if base.exists():
            for f in sorted(base.rglob("*")):
                if not f.is_file() or f.name.startswith("tmp-"):
                    continue
                st = f.stat()
                rel = str(f.relative_to(base)).replace(os.sep, "__")
                k = sub + "/" + rel
                if k not in done or done[k][0] != st.st_size:
                    out.append((f, rel, sub, k))
    return out


def _drive_sync_cycle(force_cfg: bool = False) -> dict[str, Any]:
    cfg = _drive_cfg(need_enabled=not force_cfg)
    if not cfg or not _DRIVE_LOCK.acquire(blocking=False):
        return {"started": False}
    t0, budget, n = time.time(), 800 * 1024 * 1024, 0
    try:
        with db() as c:
            todo = _drive_pending(c)
        for path, name, sub, key in todo:
            if time.time() - t0 > 1500 or budget <= 0:
                break
            st = path.stat()
            _drive_upload(cfg, path, name, sub)
            with db() as c:
                c.execute("INSERT INTO drive_sync (path,size,mtime,uploaded_at) VALUES (?,?,?,?) ON CONFLICT(path) DO UPDATE SET size=excluded.size, mtime=excluded.mtime, uploaded_at=excluded.uploaded_at", (key, st.st_size, st.st_mtime, now()))
            budget -= st.st_size
            n += 1
        if any(k.startswith("db/") for _, _, _, k in todo):
            try:
                _drive_post(cfg, {"action": "prune", "sub": "db", "prefix": "db", "keep": 40})
            except Exception:  # noqa: BLE001
                pass
        _kv_set("drive_last_ok", now())
        _kv_set("drive_last_error", "")
        return {"started": True, "uploaded": n}
    except Exception as ex:  # noqa: BLE001
        _kv_set("drive_last_error", f"{now()[:16].replace('T', ' ')}: {str(ex)[:300]}")
        return {"started": True, "error": str(ex)}
    finally:
        _DRIVE_LOCK.release()


def _drive_status() -> dict[str, Any]:
    cfg = _drive_cfg(need_enabled=False)
    pend = 0
    if cfg:
        with db() as c:
            pend = len(_drive_pending(c))
    return {"configured": bool(cfg), "enabled": _kv_get("drive_enabled") == "1", "link": _kv_get("drive_link"), "url": _kv_get("drive_url"),
            "token_set": bool(_kv_get("drive_token")), "last_ok": _kv_get("drive_last_ok"), "last_error": _kv_get("drive_last_error"),
            "pending": pend, "running": _DRIVE_LOCK.locked()}


class DriveIn(BaseModel):
    link: str = Field(default="", max_length=600)
    url: str = Field(default="", max_length=600)
    token: str = Field(default="", max_length=200)
    enabled: bool = False


@app.get("/api/admin/backup/drive/script")
def drive_script(request: Request) -> dict[str, str]:
    _require_admin(request)
    return {"script": APPS_SCRIPT}


@app.put("/api/admin/backup/drive")
def drive_save(request: Request, p: DriveIn) -> dict[str, Any]:
    _require_admin(request)
    url = p.url.strip()
    if url and not _ALLOW_ANY_URL and not re.match(r"^https://script\.google\.com/macros/s/[\w-]+/exec$", url):
        raise HTTPException(422, "Адрес скрипта должен выглядеть как https://script.google.com/macros/s/…/exec (копируется при развёртывании)")
    if p.link.strip() and not _folder_id(p.link):
        raise HTTPException(422, "В ссылке не найден идентификатор папки Google Диска")
    _kv_set("drive_link", p.link.strip())
    _kv_set("drive_url", url)
    if p.token.strip():
        _kv_set("drive_token", p.token.strip())
    _kv_set("drive_enabled", "1" if p.enabled else "0")
    cfg = _drive_cfg(need_enabled=False)
    if not cfg:
        raise HTTPException(422, "Заполните ссылку на папку, адрес скрипта и ключ")
    try:
        j = _drive_post(cfg, {"action": "ping"})
    except Exception as ex:  # noqa: BLE001
        raise HTTPException(422, "Связаться со скриптом не удалось: " + str(ex)[:300]) from ex
    _kv_set("drive_last_error", "")
    return {"message": "Связь есть. Папка: «" + str(j.get("folder", "")) + "»" + (". Автовыгрузка включена." if p.enabled else ". Автовыгрузка выключена.")}


@app.post("/api/admin/backup/drive/run")
def drive_run(request: Request) -> dict[str, Any]:
    _require_admin(request)
    if not _drive_cfg(need_enabled=False):
        raise HTTPException(422, "Сначала настройте выгрузку на Google Диск")
    if _DRIVE_LOCK.locked():
        return {"message": "Выгрузка уже идёт"}
    make_db_backup("dbm")
    threading.Thread(target=_drive_sync_cycle, args=(True,), daemon=True).start()
    return {"message": "Выгрузка запущена. Большие объёмы переносятся постепенно — состояние видно в окне «Резервные копии»."}


class _ZipSink:
    """Приёмник для потоковой упаковки: архив отдаётся по мере создания, а не после полной сборки."""
    def __init__(self) -> None:
        self.buf = bytearray(); self.pos = 0

    def write(self, b: bytes) -> int:
        self.buf += b; self.pos += len(b); return len(b)

    def tell(self) -> int:
        return self.pos

    def flush(self) -> None:
        pass

    def take(self) -> bytes:
        d = bytes(self.buf); self.buf.clear(); return d


def _full_zip_iter(db_snapshot: Path):
    sink = _ZipSink()
    zf = zipfile.ZipFile(sink, "w", zipfile.ZIP_DEFLATED, allowZip64=True)

    def add(path: Path, arc: str, deflate: bool):
        zi = zipfile.ZipInfo.from_file(path, arc)
        zi.compress_type = zipfile.ZIP_DEFLATED if deflate else zipfile.ZIP_STORED
        with open(path, "rb") as src, zf.open(zi, "w", force_zip64=True) as dst:
            while True:
                chunk = src.read(1 << 20)
                if not chunk:
                    break
                dst.write(chunk)
                d = sink.take()
                if d:
                    yield d

    try:
        yield from add(db_snapshot, "id_nvk.sqlite3", True)
        for base, arc in ((FILES_DIR, "files"), (PHOTOS_DIR, "photos")):
            if base.exists():
                for f in sorted(base.rglob("*")):
                    if f.is_file() and not f.name.startswith("tmp-"):
                        yield from add(f, arc + "/" + str(f.relative_to(base)).replace(os.sep, "/"), False)
        info = "Полная копия ИД ИТС от %s. Версия программы %s.\nid_nvk.sqlite3 — база; files — исходные файлы; photos — фото.\n" % (datetime.now().strftime("%d.%m.%Y %H:%M"), app.version)
        zf.writestr("README.txt", info)
    finally:
        zf.close()
        d = sink.take()
        if d:
            yield d
        db_snapshot.unlink(missing_ok=True)


@app.get("/api/admin/backup/full")
def backup_full(request: Request) -> StreamingResponse:
    _require_admin(request)
    DATA_BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    snap = DATA_BACKUP_DIR / f"tmp-{uuid.uuid4().hex}.sqlite3"
    src, dst = sqlite3.connect(DB_PATH), sqlite3.connect(snap)
    try:
        with dst:
            src.backup(dst)
    finally:
        src.close(); dst.close()
    (DATA_BACKUP_DIR / "last_download.txt").write_text(datetime.now().isoformat(timespec="seconds"), encoding="utf-8")
    fn = f"ID_ITS_full_backup_{datetime.now().strftime('%Y-%m-%d_%H%M')}.zip"
    return StreamingResponse(_full_zip_iter(snap), media_type="application/zip", headers={"Content-Disposition": f'attachment; filename="{fn}"'})


