_RN_KEY = lambda v: tuple(int(x) for x in v.split("."))  # noqa: E731


@app.get("/api/whatsnew")
def whatsnew(request: Request) -> dict[str, Any]:
    login = (getattr(request.state, "user", "") or "").lower()
    cur = app.version
    with db() as c:
        r = c.execute("SELECT version FROM app_seen WHERE login=?", (login,)).fetchone()
    seen = r["version"] if r else ""
    if seen:
        items = [(v, n) for v, n in RELEASE_NOTES if _RN_KEY(v) > _RN_KEY(seen) and _RN_KEY(v) <= _RN_KEY(cur)]
    else:
        items = [(v, n) for v, n in RELEASE_NOTES if _RN_KEY(v) <= _RN_KEY(cur)][:1]
    items.sort(key=lambda x: _RN_KEY(x[0]), reverse=True)
    return {"version": cur, "show": bool(items) and bool(login), "releases": [{"version": v, "notes": n} for v, n in items[:6]]}


class SeenIn(BaseModel):
    version: str = Field(max_length=40)


@app.post("/api/whatsnew/ack")
def whatsnew_ack(request: Request, p: SeenIn) -> dict[str, str]:
    login = (getattr(request.state, "user", "") or "").lower()
    if not login or not re.fullmatch(r"[\d.]+", p.version):
        raise HTTPException(422, "Неверная версия")
    with db() as c:
        c.execute("INSERT INTO app_seen (login, version) VALUES (?,?) ON CONFLICT(login) DO UPDATE SET version=excluded.version", (login, p.version))
    return {"ok": "1"}


# ---------------------------------------------------------------- Обновление программы из интерфейса
OVERRIDE_DIR = Path(os.getenv("APP_OVERRIDE_DIR", "/data/app_override"))
BACKUP_DIR = Path(os.getenv("APP_BACKUP_DIR", "/data/app_backups"))
APP_FILE = Path(__file__).resolve()


def _app_version_of(text: str) -> str:
    m = re.search(r'FastAPI\(title="[^"]*",\s*version="([\d.]+)"', text)
    return m.group(1) if m else ""


def _require_admin(request: Request) -> None:
    login = getattr(request.state, "user", "") or ""
    if not APP_USER or login.lower() != APP_USER.lower():
        raise HTTPException(403, "Обновлять программу может только администратор (общий служебный вход)")


def _restart_soon() -> None:
    def go() -> None:
        time.sleep(1.5)
        os._exit(3)  # контейнер перезапустится (restart: unless-stopped) и возьмёт новый файл
    threading.Thread(target=go, daemon=True).start()


@app.get("/api/admin/update")
def update_info(request: Request) -> dict[str, Any]:
    _require_admin(request)
    backs = []
    if BACKUP_DIR.exists():
        for f in sorted(BACKUP_DIR.glob("app-*.py"), key=lambda f: f.stat().st_mtime, reverse=True)[:3]:
            backs.append({"name": f.name, "version": _app_version_of(f.read_text(encoding="utf-8", errors="replace")), "size": f.stat().st_size})
    return {"version": app.version, "backups": backs, "override": (OVERRIDE_DIR / "app.py").exists()}


def _apply_app_py(text: str) -> str:
    try:
        ast.parse(text)
    except SyntaxError as ex:
        raise HTTPException(422, f"Файл не является корректной программой: {ex}") from ex
    if "FastAPI(" not in text or "/api/health" not in text:
        raise HTTPException(422, "Это не файл программы ИД ИТС (app.py)")
    ver = _app_version_of(text)
    if not ver:
        raise HTTPException(422, "В файле не найдена версия")
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    cur = APP_FILE.read_text(encoding="utf-8")
    (BACKUP_DIR / f"app-{app.version}-{datetime.now().strftime('%Y%m%d-%H%M%S')}.py").write_text(cur, encoding="utf-8")
    for old in sorted(BACKUP_DIR.glob("app-*.py"), key=lambda f: f.stat().st_mtime)[:-10]:
        old.unlink(missing_ok=True)
    OVERRIDE_DIR.mkdir(parents=True, exist_ok=True)
    (OVERRIDE_DIR / "boots").unlink(missing_ok=True)
    (OVERRIDE_DIR / "app.py").write_text(text, encoding="utf-8")
    (OVERRIDE_DIR / "pending").write_text(now(), encoding="utf-8")
    _restart_soon()
    return ver


@app.post("/api/admin/update")
async def update_upload(request: Request, name: str = "app.py") -> dict[str, Any]:
    _require_admin(request)
    body = await request.body()
    if not body or len(body) > 8_000_000:
        raise HTTPException(422, "Файл пустой или слишком большой")
    if name.lower().endswith((".tgz", ".tar.gz")):
        import io, tarfile
        try:
            with tarfile.open(fileobj=io.BytesIO(body), mode="r:gz") as t:
                m = next((x for x in t.getmembers() if x.isfile() and x.name.split("/")[-1] == "app.py"), None)
                if not m:
                    raise HTTPException(422, "В архиве нет app.py")
                text = t.extractfile(m).read().decode("utf-8")  # type: ignore[union-attr]
        except HTTPException:
            raise
        except Exception as ex:  # noqa: BLE001
            raise HTTPException(422, f"Не удалось прочитать архив: {ex}") from ex
    else:
        try:
            text = body.decode("utf-8")
        except UnicodeDecodeError as ex:
            raise HTTPException(422, "Файл должен быть app.py в кодировке UTF-8") from ex
    ver = _apply_app_py(text)
    return {"message": f"Обновление принято: версия {ver}. Программа перезапускается (около 15 секунд).", "version": ver}


UPDATE_URL = os.getenv("ID_UPDATE_URL", "https://drive.usercontent.google.com/download?id=1A3bIpXiM-saRdQu_6xJO5IkPVNmcgU1z&export=download&confirm=t")


def _ver_tuple(v: str) -> tuple[int, ...]:
    try:
        return tuple(int(x) for x in v.split("."))
    except ValueError:
        return (0,)


@app.post("/api/admin/update/check")
def update_check(request: Request, apply: int = 0) -> dict[str, Any]:
    """Проверка обновления на Google Диске (та же папка, что у крона на сервере); apply=1 — установить найденную версию."""
    _require_admin(request)
    import urllib.request
    try:
        with urllib.request.urlopen(urllib.request.Request(UPDATE_URL, headers={"User-Agent": "id-its-update"}), timeout=40) as r:
            raw = r.read(8_000_001)
    except Exception as ex:  # noqa: BLE001
        raise HTTPException(502, f"Не удалось получить файл с Google Диска: {type(ex).__name__}. Проверьте доступ программы в интернет.") from ex
    if len(raw) < 100_000 or len(raw) > 8_000_000:
        raise HTTPException(502, "С Диска пришёл не файл программы (возможно, закрыт доступ по ссылке)")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as ex:
        raise HTTPException(502, "Файл на Диске повреждён (не UTF-8)") from ex
    ver = _app_version_of(text)
    if not ver:
        raise HTTPException(502, "В файле на Диске не найдена версия")
    if _ver_tuple(ver) <= _ver_tuple(app.version):
        return {"newer": False, "current": app.version, "remote": ver, "message": f"Установлена последняя версия ({app.version}). На Диске: {ver}."}
    if not apply:
        return {"newer": True, "current": app.version, "remote": ver, "message": f"На Диске найдена версия {ver} (сейчас {app.version})."}
    _apply_app_py(text)
    return {"newer": True, "current": app.version, "remote": ver, "version": ver, "message": f"Обновление принято: версия {ver}. Программа перезапускается (около 15 секунд)."}


@app.post("/api/admin/rollback")
def update_rollback(request: Request, name: str) -> dict[str, Any]:
    _require_admin(request)
    f = BACKUP_DIR / Path(name).name
    if not f.exists() or not f.name.startswith("app-"):
        raise HTTPException(404, "Резервная копия не найдена")
    allowed = {x.name for x in sorted(BACKUP_DIR.glob("app-*.py"), key=lambda f: f.stat().st_mtime, reverse=True)[:3]}
    if f.name not in allowed:
        raise HTTPException(409, "Откат возможен только к трём последним версиям: более старая может не подойти к текущей базе данных")
    try:
        make_db_backup("pre")  # снимок базы перед откатом — на случай несовместимости
    except Exception:
        pass
    ver = _apply_app_py(f.read_text(encoding="utf-8"))
    return {"message": f"Возврат к версии {ver}. Программа перезапускается.", "version": ver}


# ---------------------------------------------------------------- Восстановление пароля по почте
_reset_hits: dict[str, list[float]] = {}


MAIL_CFG = DB_PATH.parent / "mail.json"  # настройки почты из окна администратора (вне базы, не попадают в её копии)


def _mail_cfg() -> dict[str, Any]:
    """Настройки почты: из окна администратора, иначе из переменных APP_SMTP_*."""
    try:
        d = json.loads(MAIL_CFG.read_text(encoding="utf-8")) if MAIL_CFG.exists() else {}
    except (OSError, ValueError):
        d = {}
    if d.get("via") == "google":
        return {"via": "google", "host": "", "port": 465, "ssl": True, "user": "", "password": "", "from": ""}
    if d.get("host"):
        return {"via": "", "host": d["host"], "port": int(d.get("port") or 465), "ssl": bool(d.get("ssl")), "user": d.get("user", ""), "password": d.get("password", ""), "from": d.get("from") or d.get("user", "")}
    return {"via": "", "host": os.getenv("APP_SMTP_HOST", ""), "port": int(os.getenv("APP_SMTP_PORT", "587") or 587), "ssl": os.getenv("APP_SMTP_SSL") == "1",
            "user": os.getenv("APP_SMTP_USER", ""), "password": os.getenv("APP_SMTP_PASSWORD", ""), "from": os.getenv("APP_SMTP_FROM") or os.getenv("APP_SMTP_USER", "")}


def _send_mail(to: str, subject: str, body: str) -> None:
    """Отправка письма: SMTP из переменных APP_SMTP_*; для проверок — запись в папку APP_MAIL_OUTBOX."""
    from email.message import EmailMessage
    msg = EmailMessage()
    cfg = _mail_cfg()
    msg["To"], msg["Subject"], msg["From"] = to, subject, cfg["from"] or "id-its@localhost"
    msg.set_content(body)
    out = os.getenv("APP_MAIL_OUTBOX", "")
    if out:
        Path(out).mkdir(parents=True, exist_ok=True)
        (Path(out) / f"{int(time.time() * 1000)}.eml").write_text(msg.as_string(), encoding="utf-8")
        return
    if cfg["via"] == "google":
        g = _google_mail_cfg()
        if not g:
            raise RuntimeError("Не подключён Google-скрипт: сначала настройте «Резервные копии» (адрес и ключ скрипта)")
        _drive_post(g, {"action": "mail", "to": to, "subject": subject, "body": body})
        return
    import smtplib
    host, port = cfg["host"], cfg["port"]

    def _open(src: Any) -> Any:
        kw = {"source_address": src} if src else {}
        if port == 465:  # 465 — сразу защищённое соединение; остальные порты (587) — STARTTLS
            return smtplib.SMTP_SSL(host, port, timeout=20, **kw)
        sv = smtplib.SMTP(host, port, timeout=20, **kw)
        sv.starttls()
        return sv

    try:
        srv = _open(None)
    except OSError as first:
        if getattr(first, "errno", None) not in (101, 97, 99):  # «сеть недоступна» чаще всего из-за IPv6 — пробуем только IPv4
            raise
        srv = _open(("0.0.0.0", 0))
    try:
        if cfg["user"]:
            srv.login(cfg["user"], cfg["password"])
        srv.send_message(msg)
    finally:
        srv.quit()


def _google_mail_cfg() -> Optional[dict[str, str]]:
    cfg = {k: _kv_get("drive_" + k) for k in ("url", "token")}
    if not (cfg["url"] and cfg["token"]):
        return None
    cfg["folder"] = ""
    return cfg


def _mail_configured() -> bool:
    c = _mail_cfg()
    return bool(os.getenv("APP_MAIL_OUTBOX") or c["host"] or (c["via"] == "google" and _google_mail_cfg()))


def _net_diag(host: str, port: int) -> str:
    """Что видит программа в сети: адреса сервера почты и доступ в интернет вообще."""
    import socket
    out: list[str] = []
    try:
        infos = socket.getaddrinfo(host, port, socket.AF_UNSPEC, socket.SOCK_STREAM)
    except OSError as e:
        return f"Имя {host} не определяется ({e}): у программы нет DNS или выхода в сеть."
    seen = set()
    for fam, _, _, _, sa in infos:
        if sa[0] in seen:
            continue
        seen.add(sa[0])
        try:
            with socket.create_connection((sa[0], sa[1]), timeout=5):
                out.append(f"{'IPv6' if fam == socket.AF_INET6 else 'IPv4'} {sa[0]}: соединение есть")
        except OSError as e:
            out.append(f"{'IPv6' if fam == socket.AF_INET6 else 'IPv4'} {sa[0]}: {e.strerror or e}")
    try:
        with socket.create_connection(("1.1.1.1", 443), timeout=5):
            out.append("выход в интернет (1.1.1.1:443): есть")
    except OSError as e:
        out.append(f"выход в интернет (1.1.1.1:443): {e.strerror or e}")
    return "; ".join(out)


def _mail_error_text(exc: Exception) -> str:
    import smtplib
    import ssl as _ssl
    cfg = _mail_cfg()
    if cfg["via"] == "google" and ("идентификатор файла" in str(exc) or "ошибка скрипта" in str(exc)):
        return "В Google всё ещё работает СТАРЫЙ текст скрипта (он не знает про письма). Вставьте в script.google.com текст из файла google_script.js, сохраните, затем «Развернуть → Управление развертываниями → ✏️ → Версия: Новая версия → Развернуть»."
    if cfg["via"] == "google":
        return "Google-скрипт: " + (str(exc)[:300] or exc.__class__.__name__) + ". Проверьте, что в script.google.com вставлен новый текст скрипта, создана новая версия развёртывания и выдано разрешение на отправку почты."
    if isinstance(exc, smtplib.SMTPAuthenticationError):
        return "Почтовый сервер не принял логин или пароль. Проверьте адрес ящика (" + cfg["user"] + ") и пароль приложения: нужен именно пароль приложения из Яндекс ID, а не обычный пароль ящика."
    if isinstance(exc, (_ssl.SSLError, ConnectionResetError)) or "WRONG_VERSION" in str(exc) or "wrong version" in str(exc).lower():
        return f"Не удалось установить защищённое соединение с {cfg['host']}:{cfg['port']}. Для Яндекса порт 465."
    if isinstance(exc, (TimeoutError, OSError)) and "timed out" in str(exc).lower():
        return f"Сервер {cfg['host']}:{cfg['port']} не отвечает (время ожидания вышло). Проверьте сервер и порт."
    if isinstance(exc, OSError):
        return f"Не удалось подключиться к {cfg['host']}:{cfg['port']}: {exc}. Диагностика сети: {_net_diag(cfg['host'], cfg['port'])}."
    if isinstance(exc, smtplib.SMTPSenderRefused):
        return "Сервер не разрешил отправку от адреса «" + cfg["from"] + "». Адрес отправителя должен совпадать с ящиком."
    return (str(exc)[:200] or exc.__class__.__name__)


@app.get("/api/admin/mail")
def admin_mail_get() -> dict[str, Any]:
    c = _mail_cfg()
    return {"via": c["via"], "google_ready": bool(_google_mail_cfg()), "host": c["host"], "port": c["port"], "ssl": c["ssl"], "user": c["user"], "from": c["from"], "password_set": bool(c["password"]), "configured": _mail_configured(), "source": "окно" if MAIL_CFG.exists() else ("переменные запуска" if c["host"] else "")}


@app.put("/api/admin/mail")
def admin_mail_put(request: Request, payload: dict[str, Any]) -> dict[str, str]:
    old = _mail_cfg()
    if payload.get("via") == "google":
        if not _google_mail_cfg():
            raise HTTPException(409, "Сначала подключите Google-скрипт в окне «Резервные копии» (адрес и ключ)")
        MAIL_CFG.parent.mkdir(parents=True, exist_ok=True)
        MAIL_CFG.write_text(json.dumps({"via": "google"}), encoding="utf-8")
        _sys_audit("Настройки почты: отправка через Google-скрипт", getattr(request.state, "user", ""))
        return {"message": "Почта будет отправляться через Google-скрипт"}
    host = str(payload.get("host") or "").strip()
    if not host:  # пустой сервер = отключить отправку писем
        MAIL_CFG.unlink(missing_ok=True)
        _sys_audit("Настройки почты очищены", getattr(request.state, "user", ""))
        return {"message": "Настройки почты очищены"}
    pw = str(payload.get("password") or "") or old["password"]  # пустой пароль в форме = оставить прежний
    try:
        port = int(payload.get("port") or 465)
    except ValueError:
        raise HTTPException(422, "Порт — число, например 465")
    cfg = {"host": host, "port": port, "ssl": bool(payload.get("ssl")), "user": str(payload.get("user") or "").strip(), "password": pw, "from": str(payload.get("from") or "").strip()}
    MAIL_CFG.parent.mkdir(parents=True, exist_ok=True)
    MAIL_CFG.write_text(json.dumps(cfg, ensure_ascii=False), encoding="utf-8")
    try:
        os.chmod(MAIL_CFG, 0o600)
    except OSError:
        pass
    _sys_audit(f"Настройки почты изменены: сервер {host}:{port}, ящик {cfg['user']}", getattr(request.state, "user", ""))
    return {"message": "Настройки почты сохранены"}


@app.post("/api/admin/mail/test")
async def admin_mail_test(payload: dict[str, Any]) -> dict[str, str]:
    to = str(payload.get("to") or "").strip()
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", to):
        raise HTTPException(422, "Укажите адрес, на который отправить тестовое письмо")
    if not _mail_configured():
        raise HTTPException(409, "Сначала сохраните настройки почты")
    try:
        await run_in_threadpool(_send_mail, to, "ИД ИТС: проверка почты", "Это тестовое письмо из программы ИД ИТС. Если вы его получили, почта настроена верно.\n")
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(424, "Не удалось отправить: " + _mail_error_text(exc)) from exc
    return {"message": "Письмо отправлено на " + to + ". Проверьте ящик (и «Спам»)."}


def _rate(key: str, limit: int, window: int) -> bool:
    t = time.time()
    if len(_reset_hits) > 5000:
        _reset_hits.clear()
    v = [x for x in _reset_hits.get(key, []) if t - x < window]
    if len(v) >= limit:
        _reset_hits[key] = v
        return False
    v.append(t)
    _reset_hits[key] = v
    return True


def _user_by_email(c: sqlite3.Connection, email: str) -> Optional[sqlite3.Row]:
    e = (email or "").strip().lower()
    if not e or "@" not in e:
        return None
    for r in c.execute("SELECT id,name,login,phone,email FROM dict_users WHERE active=1 AND email<>''"):
        if r["email"].strip().lower() == e:
            return r
    return None


def _code_hash(uid: str, code: str) -> str:
    return hashlib.sha256((uid + ":" + code).encode()).hexdigest()


@app.post("/api/auth/reset/request")
async def auth_reset_request(request: Request, payload: dict[str, Any]) -> dict[str, str]:
    ip = request.headers.get("cf-connecting-ip") or (request.client.host if request.client else "?")
    if not _rate("ip:" + ip, 20, 3600):
        raise HTTPException(429, "Слишком много запросов. Попробуйте позже.")
    if not _mail_configured():
        raise HTTPException(409, "Отправка почты на сервере не настроена. Обратитесь к администратору.")
    generic = {"message": "Если такая почта есть в системе, на неё отправлен код (действует 15 минут). Проверьте и папку «Спам»."}
    phone = str(payload.get("email") or "")
    with db() as c:
        u = _user_by_email(c, phone)
        if not u or not (u["email"] or "").strip() or not _rate("u:" + u["id"], 3, 3600):
            why = "такой почты нет ни у одного сотрудника" if not u else ("у сотрудника не заполнена почта" if not (u["email"] or "").strip() else "больше 3 запросов за час")
            _sys_audit(f"Запрос кода на {phone[:60]}: письмо не отправлено — {why}")
            return generic
        code = f"{secrets.randbelow(10 ** 6):06d}"
        c.execute("DELETE FROM auth_codes WHERE user_id=?", (u["id"],))
        c.execute("INSERT INTO auth_codes (id,user_id,code_hash,expires_at,tries,created_at) VALUES (?,?,?,?,0,?)", (str(uuid.uuid4()), u["id"], _code_hash(u["id"], code), time.time() + 900, time.time()))
        email = u["email"].strip()
        name = u["name"]
    try:
        await run_in_threadpool(_send_mail, email, "ИД ИТС: код для входа", f"Здравствуйте, {name}!\n\nКод для установки или смены пароля в программе ИД ИТС: {code}\nКод действует 15 минут. Если вы его не запрашивали — просто проигнорируйте письмо.\n")
    except Exception as exc:  # noqa: BLE001
        _sys_audit(f"Не удалось отправить код на почту: {_mail_error_text(exc)}")
        raise HTTPException(424, "Не удалось отправить письмо. Обратитесь к администратору.") from exc
    _sys_audit(f"Код для входа отправлен на {email}", name)
    return generic


@app.post("/api/auth/reset/confirm")
def auth_reset_confirm(request: Request, payload: dict[str, Any]) -> dict[str, str]:
    ip = request.headers.get("cf-connecting-ip") or (request.client.host if request.client else "?")
    if not _rate("ipc:" + ip, 30, 3600):
        raise HTTPException(429, "Слишком много попыток. Попробуйте позже.")
    code, pw = str(payload.get("code") or "").strip(), str(payload.get("password") or "")
    if len(pw) < 8:
        raise HTTPException(422, "Пароль — не короче 8 символов")
    with db() as c:
        u = _user_by_email(c, str(payload.get("email") or ""))
        bad = HTTPException(403, "Код неверный или устарел. Запросите новый.")
        if not u:
            raise bad
        r = c.execute("SELECT * FROM auth_codes WHERE user_id=?", (u["id"],)).fetchone()
        if not r or r["expires_at"] < time.time() or r["tries"] >= 5:
            raise bad
        if not hmac.compare_digest(r["code_hash"], _code_hash(u["id"], code)):
            c.execute("UPDATE auth_codes SET tries=tries+1 WHERE id=?", (r["id"],))
            c.commit()
            raise bad
        c.execute("UPDATE dict_users SET pw_hash=? WHERE id=?", (_hash_pw(pw), u["id"]))
        c.execute("DELETE FROM auth_codes WHERE user_id=?", (u["id"],))
        lg = u["login"] or u["email"].strip().lower()
    for k in [k for k in _locks if k in (lg.lower(), u["email"].strip().lower())]:
        _locks.pop(k, None)
    _ok_cache.clear()
    _sys_audit(f"Пароль пользователя «{u['name']}» установлен через код из почты", lg)
    return {"message": "Пароль сохранён. Теперь войдите: логин — ваша почта, пароль — новый."}


