class PwChange(BaseModel):
    old: str = Field(default="", max_length=200)
    new: str = Field(min_length=6, max_length=200)


@app.post("/api/profile/password")
def profile_password(request: Request, payload: PwChange) -> dict[str, str]:
    login = getattr(request.state, "user", "") or ""
    if APP_USER and login.lower() == APP_USER.lower():
        raise HTTPException(409, "Это общий служебный вход — его пароль задаёт администратор сервера. Создайте личную учётную запись в «Справочники → Пользователи».")
    with db() as c:
        r = c.execute("SELECT id,pw_hash FROM dict_users WHERE lower(login)=lower(?) AND active=1", (login,)).fetchone()
        if not r or not _verify_pw(r["pw_hash"], payload.old):
            raise HTTPException(403, "Текущий пароль указан неверно")
        c.execute("UPDATE dict_users SET pw_hash=? WHERE id=?", (_hash_pw(payload.new), r["id"]))
    _ok_cache.clear()
    return {"message": "Пароль изменён. Войдите заново с новым паролем."}


class PwReset(BaseModel):
    password: str = Field(default="", max_length=200)


@app.post("/api/dict/users/{rid}/password")
def user_reset_password(request: Request, rid: str, payload: PwReset) -> dict[str, str]:
    """Сброс/установка пароля сотруднику — только администратором (общий служебный вход)."""
    login = getattr(request.state, "user", "") or ""
    if not APP_USER or login.lower() != APP_USER.lower():
        raise HTTPException(403, "Сбросить пароль может только администратор")
    with db() as c:
        r = c.execute("SELECT login,name FROM dict_users WHERE id=?", (rid,)).fetchone()
        if not r:
            raise HTTPException(404, "Пользователь не найден")
        if not r["login"]:
            raise HTTPException(409, "Сначала задайте логин пользователя")
        pw = payload.password.strip() or "".join(secrets.choice("abcdefghjkmnpqrstuvwxyz23456789") for _ in range(10))
        if len(pw) < 6:
            raise HTTPException(422, "Пароль — не короче 6 символов")
        c.execute("UPDATE dict_users SET pw_hash=? WHERE id=?", (_hash_pw(pw), rid))
    _ok_cache.clear()
    return {"login": r["login"], "password": pw}


# ---------------------------------------------------------------- Состав раздела (части: участки, колодцы, узлы)
ZONE_TERMS = ("Часть",)      # раздел состоит из составных частей: участков, колодцев, узлов


def _zone_term(c: sqlite3.Connection, pid: str) -> str:
    r = c.execute("SELECT v FROM kv WHERE k=?", ("zone_term:" + pid,)).fetchone()
    return r["v"] if r and r["v"] in ZONE_TERMS else "Часть"


_NODE_FAMS = {"arm", "ins", "flange", "bush", "filter", "meter", "gauge"}     # задвижки, краны, фланцы, втулки, фильтры, счётчики, манометры
_NODE_PART = ("Арматура", "Фитинг", "Оборудование")     # задвижки, краны, фланцы, комплектующие — составные части узла


def _zone_list(c: sqlite3.Connection, sid: str) -> list[dict[str, Any]]:
    out: dict[str, dict[str, Any]] = {}
    for r in c.execute("SELECT name,sort_order FROM zones WHERE section_id=? ORDER BY sort_order,name", (sid,)):
        out[r["name"]] = {"name": r["name"], "order": r["sort_order"], "elements": [], "node": bool(re.match(r"\s*узел", r["name"], re.I)), "comp": {}}
    for r in c.execute("SELECT id,code,name,kind,block,planned_note FROM elements WHERE section_id=? AND enabled=1 ORDER BY created_at,code", (sid,)):
        z = out.setdefault(r["block"] or "", {"name": r["block"] or "", "order": 10**6, "elements": [], "node": bool(re.match(r"\s*узел", r["block"] or "", re.I)), "comp": {}})
        z["elements"].append({"id": r["id"], "code": r["code"]})
        if r["kind"] == "Узел":
            z["node"] = True
        if r["kind"] in _NODE_PART:
            lb = (_obj_class(r["name"]) or (r["kind"],))[0]
            z["comp"][lb] = round(z["comp"].get(lb, 0) + _el_qty(r["planned_note"]), 4)
    return sorted(out.values(), key=lambda z: (z["order"], z["name"]))


def _zone_name(raw: Any) -> str:
    n = " ".join(str(raw or "").split())[:80]
    if not n:
        raise HTTPException(422, "Укажите название")
    return n


@app.get("/api/zones")
def zones_get(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        return {"term": _zone_term(c, sec["project_id"]), "terms": list(ZONE_TERMS), "zones": _zone_list(c, sec["id"])}


@app.put("/api/zones/term")
def zones_term(request: Request, payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    t = str(payload.get("term") or "")
    if t not in ZONE_TERMS:
        raise HTTPException(422, "Допустимые названия: " + ", ".join(ZONE_TERMS))
    with db() as c:
        sec = _section(c, section)
        c.execute("INSERT INTO kv (k,v) VALUES (?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v", ("zone_term:" + sec["project_id"], t))
        audit(request, c, "zone", sec["id"], "update", f"Деление раздела называется «{t}»", None, section_id=sec["id"])
    return {"message": "Сохранено"}


@app.post("/api/zones")
def zones_add(request: Request, payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    name = _zone_name(payload.get("name"))
    with db() as c:
        sec = _section(c, section)
        if any(z["name"].lower() == name.lower() for z in _zone_list(c, sec["id"])):
            raise HTTPException(409, "Такая запись уже есть")
        n = c.execute("SELECT COALESCE(MAX(sort_order),0)+1 FROM zones WHERE section_id=?", (sec["id"],)).fetchone()[0]
        c.execute("INSERT INTO zones (section_id,name,sort_order) VALUES (?,?,?)", (sec["id"], name, n))
        if payload.get("node"):       # узел — составная часть раздела: заводим объект «Узел» с операциями узла
            k = c.execute("SELECT COUNT(*) FROM elements WHERE section_id=? AND kind='Узел'", (sec["id"],)).fetchone()[0] + 1
            eid = str(uuid.uuid4())
            c.execute("INSERT INTO elements (id,section_id,code,name,kind,block,planned_note,enabled,created_at,source,weight) VALUES (?,?,?,?,?,?,?,1,?,?,1)",
                      (eid, sec["id"], f"У{k}", name, "Узел", name, "", now(), "manual"))
            for order, (code, title) in enumerate(OBJ_OPS["Узел"], 1):
                c.execute("INSERT INTO operations (id,element_id,code,title,sort_order) VALUES (?,?,?,?,?)", (str(uuid.uuid4()), eid, code, title, order))
        audit(request, c, "zone", sec["id"], "create", f"{_zone_term(c, sec['project_id'])}: добавлена «{name}»", {"Название": ["", name]}, section_id=sec["id"])
    return {"message": "Добавлено"}


@app.post("/api/zones/rename")
def zones_rename(request: Request, payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    old, new = str(payload.get("old") or ""), _zone_name(payload.get("new"))
    with db() as c:
        sec = _section(c, section)
        c.execute("UPDATE elements SET block=? WHERE section_id=? AND block=?", (new, sec["id"], old))
        c.execute("DELETE FROM zones WHERE section_id=? AND name=?", (sec["id"], new))
        c.execute("UPDATE zones SET name=? WHERE section_id=? AND name=?", (new, sec["id"], old))
        if not c.execute("SELECT 1 FROM zones WHERE section_id=? AND name=?", (sec["id"], new)).fetchone():
            n = c.execute("SELECT COALESCE(MAX(sort_order),0)+1 FROM zones WHERE section_id=?", (sec["id"],)).fetchone()[0]
            c.execute("INSERT INTO zones (section_id,name,sort_order) VALUES (?,?,?)", (sec["id"], new, n))
        for k in ("schemes",):  # схемы по захватке хранятся под ключом «этап@захватка»
            for r in c.execute("SELECT id,key FROM schemes WHERE section_id=? AND key LIKE ?", (sec["id"], "%@" + old)).fetchall():
                c.execute("UPDATE schemes SET key=? WHERE id=?", (r["key"][: -len(old)] + new, r["id"]))
        audit(request, c, "zone", sec["id"], "update", f"{_zone_term(c, sec['project_id'])}: «{old}» → «{new}»", {"Название": [old, new]}, section_id=sec["id"])
    return {"message": "Переименовано"}


@app.post("/api/zones/delete")
def zones_delete(request: Request, payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    name = str(payload.get("name") or "")
    with db() as c:
        sec = _section(c, section)
        if c.execute("SELECT 1 FROM elements WHERE section_id=? AND block=? AND enabled=1", (sec["id"], name)).fetchone():
            raise HTTPException(409, "В ней есть элементы: сначала перенесите их в другую")
        c.execute("DELETE FROM zones WHERE section_id=? AND name=?", (sec["id"], name))
        audit(request, c, "zone", sec["id"], "delete", f"{_zone_term(c, sec['project_id'])}: удалена «{name}»", {"Название": [name, ""]}, section_id=sec["id"])
    return {"message": "Удалено"}


@app.post("/api/zones/attach-nodes")
def zones_attach_nodes(request: Request, section: Optional[str] = None) -> dict[str, Any]:
    """Задвижки, краны, фланцы и комплектующие относятся к узлам. Привязываем только однозначно: узел той же сети (по шифру «В1-…»), если он один; иначе выбирает ПТО («Перенести…»)."""
    with db() as c:
        sec = _section(c, section)
        nodes = [e for e in c.execute("SELECT code,block FROM elements WHERE section_id=? AND enabled=1 AND kind='Узел'", (sec["id"],))]
        net = lambda code: (code or "").split("-")[0] if "-" in (code or "") else ""  # noqa: E731
        by_net: dict[str, list[str]] = {}
        for n in nodes:
            by_net.setdefault(net(n["code"]), []).append(n["block"])
        node_blocks = {n["block"] for n in nodes}
        moved = left = 0
        for e in c.execute("SELECT id,code,name,block FROM elements WHERE section_id=? AND enabled=1 AND kind IN ('Арматура','Фитинг','Оборудование')", (sec["id"],)).fetchall():
            if e["block"] in node_blocks or (_obj_class(e["name"]) or ("", "", "", ""))[3] not in _NODE_FAMS:
                continue
            cand = by_net.get(net(e["code"]), []) if net(e["code"]) in by_net else (list(node_blocks) if len(node_blocks) == 1 else [])
            if len(set(cand)) == 1:
                c.execute("UPDATE elements SET block=? WHERE id=?", (cand[0], e["id"]))
                moved += 1
            else:
                left += 1
        audit(request, c, "zone", sec["id"], "update", f"Состав раздела: к узлам отнесено элементов — {moved}", None, section_id=sec["id"])
    return {"message": f"К узлам отнесено: {moved}" + (f"; без однозначного узла осталось: {left} — перенесите вручную («Перенести…»)" if left else ""), "moved": moved, "left": left}


@app.post("/api/zones/move")
def zones_move(request: Request, payload: dict[str, Any], section: Optional[str] = None) -> dict[str, str]:
    ids = [str(x) for x in (payload.get("element_ids") or [])][:2000]
    zone = _zone_name(payload.get("zone"))
    if not ids:
        raise HTTPException(422, "Выберите элементы")
    with db() as c:
        sec = _section(c, section)
        rows = [r for r in c.execute(f"SELECT id,code,block FROM elements WHERE section_id=? AND id IN ({','.join('?' * len(ids))})", (sec["id"], *ids))]
        if not rows:
            raise HTTPException(404, "Элементы не найдены в этом разделе")
        c.execute(f"UPDATE elements SET block=? WHERE section_id=? AND id IN ({','.join('?' * len(ids))})", (zone, sec["id"], *ids))
        if not c.execute("SELECT 1 FROM zones WHERE section_id=? AND name=?", (sec["id"], zone)).fetchone():
            n = c.execute("SELECT COALESCE(MAX(sort_order),0)+1 FROM zones WHERE section_id=?", (sec["id"],)).fetchone()[0]
            c.execute("INSERT INTO zones (section_id,name,sort_order) VALUES (?,?,?)", (sec["id"], zone, n))
        audit(request, c, "zone", sec["id"], "update", f"{_zone_term(c, sec['project_id'])} «{zone}»: перенесено элементов — {len(rows)}",
              {"Элементы": [", ".join(f"{r['code']} ({r['block']})" for r in rows[:12]), zone]}, section_id=sec["id"])
    return {"message": f"Перенесено элементов: {len(rows)}"}


# ---------------------------------------------------------------- Исполнительные схемы
# key, название, пояснение, фильтр элементов (kind), фильтр операций (regex по названию / коды)
SCHEME_DEFS = [
    ("plan", "План сетей по факту", "Все элементы перечня; на проектном чертеже выделяются выполненные (монтаж / работа выполнена)", None, None, ("install", "done")),
    ("wells", "Устройство колодцев", "Колодцы перечня: выполненные выделяются на проектном чертеже", "Колодец", None, ("install", "done")),
    ("s1", "Схема: разработка грунта", "СП 45.13330.2017. Берутся операции перечня со словами «разработка, траншея, котлован»", None, r"разработ|траншe?|траншеи|котлован|выемк", None),
    ("s2", "Схема: устройство основания", "Операции «основание, подготовка, песчаное основание»", None, r"основани|подготовк|песчан\w* основ", None),
    ("s3", "Схема: прокладка трубопровода", "СП 129.13330.2019. Операции «прокладка, укладка, монтаж труб»", None, r"прокладк|укладк|монтаж труб|трубопровод", None),
    ("s4", "Схема: обратная засыпка песком", "Операции «присыпка, засыпка песком»", None, r"присып|засыпк\w* песк|песчан\w* засып", None),
    ("s5", "Схема: обратная засыпка грунтом", "Операции «обратная засыпка, засыпка грунтом»", None, r"обратн\w* засып|засыпк\w* грунт", None),
    ("prof", "Фактические профили", "Нужна съёмка: фактические отметки земли и лотков подставляются из геодезических схем", None, None, ("survey",)),
]
SCHEME_BY_KEY = {d[0]: d for d in SCHEME_DEFS}


def _skey(key: str, zone: str = "") -> str:
    """Ключ схемы в базе: этап или «этап@захватка» (схема по одной захватке)."""
    return f"{key}@{zone}" if zone else key


def _scheme_progress(c: sqlite3.Connection, section_id: str, key: str, zone: str = "") -> dict[str, Any]:
    _, _, _, kind, rx, codes = SCHEME_BY_KEY[key]
    rows = c.execute("""
      SELECT el.id eid, el.code ecode, el.kind ekind, el.block eblock, o.code ocode, o.title otitle,
        (SELECT e.event_type FROM events e WHERE e.operation_id=o.id ORDER BY e.created_at DESC LIMIT 1) last,
        (SELECT MAX(e.created_at) FROM events e WHERE e.operation_id=o.id) lastat
      FROM elements el JOIN operations o ON o.element_id=el.id WHERE el.enabled=1 AND el.scope='' AND el.section_id=?""", (section_id,)).fetchall()
    total = done = 0
    done_codes: set[str] = set()
    all_codes: set[str] = set()
    last_at = ""
    for r in rows:
        if zone and (r["eblock"] or "") != zone:
            continue
        if kind and (r["ekind"] or "").lower() != kind.lower():
            continue
        if rx:
            if not re.search(rx, r["otitle"], re.I):
                continue
        elif codes and r["ocode"] not in codes:
            continue
        total += 1
        all_codes.add(r["ecode"])
        if r["last"] == "complete":
            done += 1
            done_codes.add(r["ecode"])
            last_at = max(last_at, r["lastat"] or "")
    return {"total": total, "done": done, "pct": round(done * 100 / total) if total else 0, "done_codes": sorted(done_codes), "all_codes": sorted(all_codes), "last_at": last_at}


def _scheme_rows(c: sqlite3.Connection, sec: sqlite3.Row, zone: str = "") -> dict[str, Any]:
    pf = c.execute("SELECT id,name FROM source_files WHERE project_id=? AND section_id=? AND kind='dxf_project' AND status='ready'", (sec["project_id"], sec["id"])).fetchall()
    sv = c.execute("SELECT COUNT(*) FROM source_files WHERE project_id=? AND section_id=? AND kind='dxf_survey'", (sec["project_id"], sec["id"])).fetchone()[0]
    items = []
    for key, title, hint, *_ in SCHEME_DEFS:
        pr = _scheme_progress(c, sec["id"], key, zone)
        row = c.execute("SELECT * FROM schemes WHERE section_id=? AND key=?", (sec["id"], _skey(key, zone))).fetchone()
        fid = row["file_id"] if row else None
        if fid and not c.execute("SELECT 1 FROM source_files WHERE id=?", (fid,)).fetchone():
            fid = None
        if not pf:
            state = "Нет DXF проекта"
        elif row and row["issued"]:
            state = "Выпущена"
        elif not pr["total"]:
            state = "Нет операций этапа в перечне"
        elif pr["pct"] >= 100:
            state = "Готова к выпуску"
        elif pr["done"]:
            state = f"Дополняется фактом · {pr['pct']}%"
        else:
            state = "Черновик по проекту"
        stale = bool(fid and row and pr["last_at"] and pr["last_at"] > row["built_at"])
        items.append({"key": key, "title": title, "hint": hint, "total": pr["total"], "done": pr["done"], "pct": pr["pct"], "state": state, "file_id": fid,
                      "version": row["version"] if row else 0, "built_at": row["built_at"] if row else "", "stale": stale,
                      "issued": bool(row and row["issued"]), "needs_survey": key == "prof"})
    return {"schemes": items, "has_project": bool(pf), "survey": sv, "section": sec["code"], "zone": zone,
            "zones": [z["name"] for z in _zone_list(c, sec["id"]) if z["elements"]], "term": _zone_term(c, sec["project_id"])}


@app.get("/api/schemes")
def schemes_list(section: Optional[str] = None, zone: str = "") -> dict[str, Any]:
    with db() as c:
        return _scheme_rows(c, _section(c, section), zone.strip())


def _text_hits(geoms: list[tuple[int, dict[str, Any]]], codes: set[str]) -> dict[str, list[tuple[int, float, float, float]]]:
    norm = {_norm_code(x): x for x in codes}
    hits: dict[str, list[tuple[int, float, float, float]]] = {}
    for gi, g in geoms:
        for ly in g["layers"]:
            for x, y, h, rot, txt in ly["T"]:
                k = _norm_code(txt)
                if k in norm:
                    hits.setdefault(norm[k], []).append((gi, x, y, h))
    return hits


def build_scheme_dxf(c: sqlite3.Connection, sec: sqlite3.Row, key: str, path: Path, zone: str = "") -> dict[str, Any]:
    import ezdxf, gzip
    pr = _scheme_progress(c, sec["id"], key, zone)
    files = c.execute("SELECT id,name FROM source_files WHERE project_id=? AND section_id=? AND kind='dxf_project' AND status='ready' ORDER BY name", (sec["project_id"], sec["id"])).fetchall()
    if not files:
        raise HTTPException(409, "Сначала загрузите DXF проекта")
    geoms: list[tuple[int, dict[str, Any]]] = []
    for i, f in enumerate(files):
        try:
            gp = build_geom(f["id"])
            geoms.append((i, json.loads(gzip.decompress(gp.read_bytes()).decode("utf-8"))))
        except Exception:  # noqa: BLE001
            continue
    if not geoms:
        raise HTTPException(500, "Не удалось прочитать DXF проекта")
    doc = ezdxf.new("R2010")
    doc.styles.add("ISOCPEUR", font="isocpeur.ttf")
    for nm, col in (("ПРОЕКТ", 8), ("ПРОЕКТ_ТЕКСТ", 9), ("ФАКТ_ИТС", 3), ("ФАКТ_ПОДПИСЬ", 3), ("НЕ_ВЫПОЛНЕНО", 1), ("ЗАМЕЧАНИЯ", 7)):
        doc.layers.add(nm, color=col)
    msp = doc.modelspace()
    offs: dict[int, float] = {}
    x0 = 0.0
    for gi, g in geoms:
        e = g.get("ext") or [0, 0, 100, 100]
        offs[gi] = x0 - e[0]
        msp.add_text(files[gi]["name"], dxfattribs={"layer": "ЗАМЕЧАНИЯ", "height": max((e[3] - e[1]) / 80, 2), "insert": (x0, e[3] + (e[3] - e[1]) * 0.03), "style": "ISOCPEUR"})
        x0 += (e[2] - e[0]) * 1.1 + 50
    for gi, g in geoms:
        dx = offs[gi]
        for ly in g["layers"]:
            if ly.get("off"):
                continue
            L = ly["L"]
            for i in range(0, len(L) - 3, 4):
                msp.add_line((L[i] + dx, L[i + 1]), (L[i + 2] + dx, L[i + 3]), dxfattribs={"layer": "ПРОЕКТ"})
            for p in ly["P"]:
                msp.add_lwpolyline([(p[i] + dx, p[i + 1]) for i in range(0, len(p) - 1, 2)], dxfattribs={"layer": "ПРОЕКТ"})
            C = ly["C"]
            for i in range(0, len(C) - 2, 3):
                msp.add_circle((C[i] + dx, C[i + 1]), C[i + 2], dxfattribs={"layer": "ПРОЕКТ"})
            A = ly["A"]
            for i in range(0, len(A) - 4, 5):
                msp.add_arc((A[i] + dx, A[i + 1]), A[i + 2], A[i + 3], A[i + 4], dxfattribs={"layer": "ПРОЕКТ"})
            for x, y, h, rot, txt in ly["T"]:
                msp.add_text(txt[:200], dxfattribs={"layer": "ПРОЕКТ_ТЕКСТ", "height": max(h, 0.5), "rotation": rot, "insert": (x + dx, y), "style": "ISOCPEUR"})
    allc = set(pr["all_codes"])
    hits = _text_hits(geoms, allc)
    done = set(pr["done_codes"])
    found_done = 0
    for code, pts in hits.items():
        ok = code in done
        for gi, x, y, h in pts:
            r = max(h * 2.2, 2.0)
            lay = "ФАКТ_ИТС" if ok else "НЕ_ВЫПОЛНЕНО"
            msp.add_circle((x + offs[gi] + h * 1.5, y + h * 0.4), r, dxfattribs={"layer": lay, "lineweight": 50 if ok else 13})
            if ok:
                msp.add_circle((x + offs[gi] + h * 1.5, y + h * 0.4), r * 0.55, dxfattribs={"layer": lay, "lineweight": 50})
        if ok:
            found_done += 1
    missing = sorted(done - set(hits))
    d = SCHEME_BY_KEY[key]
    note = f"{d[1]} · {sec['code']}" + (f" · {_zone_term(c, sec['project_id']).lower()} «{zone}»" if zone else "") + f" · выполнено {pr['done']} из {pr['total']} · сформирована {now()[:10]} · черновик, без рамки и штампа"
    ext0 = geoms[0][1].get("ext") or [0, 0, 100, 100]
    msp.add_text(note, dxfattribs={"layer": "ЗАМЕЧАНИЯ", "height": max((ext0[3] - ext0[1]) / 70, 2.5), "insert": (0, ext0[1] - (ext0[3] - ext0[1]) * 0.05), "style": "ISOCPEUR"})
    doc.saveas(str(path))
    return {"done": pr["done"], "total": pr["total"], "pct": pr["pct"], "marked": found_done, "not_found": missing}


def _build_scheme(c: sqlite3.Connection, sec: sqlite3.Row, key: str, who: str = "", zone: str = "") -> dict[str, Any]:
    tmp = FILES_DIR / f"tmp-{uuid.uuid4().hex}"
    FILES_DIR.mkdir(parents=True, exist_ok=True)
    res = build_scheme_dxf(c, sec, key, tmp, zone)
    size = tmp.stat().st_size
    sha = hashlib.sha256(tmp.read_bytes()).hexdigest()
    row = c.execute("SELECT * FROM schemes WHERE section_id=? AND key=?", (sec["id"], _skey(key, zone))).fetchone()
    ver = (row["version"] if row else 0) + 1
    fid = str(uuid.uuid4())
    tmp.replace(FILES_DIR / fid)
    title = SCHEME_BY_KEY[key][1].replace(":", "")
    name = f"{title}_{sec['code']}" + (f"_{zone}" if zone else "") + f"_v{ver}.dxf"
    c.execute("INSERT INTO source_files (id,project_id,section_id,kind,name,size,sha256,uploaded_by,uploaded_at,analysis_json,status) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
              (fid, sec["project_id"], sec["id"], "scheme", name[:200], size, sha, (who or "система")[:80], now(), "{}", "ready"))
    if row:
        if row["file_id"]:
            c.execute("DELETE FROM source_files WHERE id=?", (row["file_id"],))
            for suf in ("", ".geom.gz"):
                (FILES_DIR / (row["file_id"] + suf)).unlink(missing_ok=True)
        c.execute("UPDATE schemes SET file_id=?, version=?, built_at=?, built_pct=?, issued=0, issued_at='' WHERE id=?", (fid, ver, now(), res["pct"], row["id"]))
    else:
        c.execute("INSERT INTO schemes (id,section_id,key,file_id,version,built_at,built_pct) VALUES (?,?,?,?,?,?,?)", (str(uuid.uuid4()), sec["id"], _skey(key, zone), fid, ver, now(), res["pct"]))
    res["file_id"] = fid
    res["version"] = ver
    return res


@app.post("/api/schemes/{key}/build")
def scheme_build(request: Request, key: str, section: Optional[str] = None, zone: str = "") -> dict[str, Any]:
    if key not in SCHEME_BY_KEY:
        raise HTTPException(404, "Нет такой схемы")
    with db() as c:
        sec = _section(c, section)
        _doc_lock(c, sec["id"], "schemes")
        res = _build_scheme(c, sec, key, getattr(request.state, "user", "") or "", zone.strip())
    msg = f"Схема сформирована (версия {res['version']}): выполнено {res['done']} из {res['total']}"
    if res["not_found"]:
        msg += f"; на чертеже не найдены подписи: {', '.join(res['not_found'][:6])}" + (" …" if len(res["not_found"]) > 6 else "")
    return {"message": msg, **res}


class SchemeIssue(BaseModel):
    issued: bool


@app.put("/api/schemes/{key}/issued")
def scheme_issue(key: str, payload: SchemeIssue, section: Optional[str] = None, zone: str = "") -> dict[str, str]:
    with db() as c:
        sec = _section(c, section)
        _doc_lock(c, sec["id"], "schemes")
        row = c.execute("SELECT * FROM schemes WHERE section_id=? AND key=?", (sec["id"], _skey(key, zone.strip()))).fetchone()
        if not row or not row["file_id"]:
            raise HTTPException(409, "Сначала сформируйте схему")
        c.execute("UPDATE schemes SET issued=?, issued_at=? WHERE id=?", (int(payload.issued), now() if payload.issued else "", row["id"]))
    return {"message": "Схема отмечена как выпущенная" if payload.issued else "Схема возвращена в работу"}


def auto_first_draft(project_id: str) -> None:
    """Сразу после разбора DXF проекта: первый черновик «План сетей» (проект без факта)."""
    try:
        with db() as c:
            sec = c.execute("SELECT s.*, p.object_name, p.address FROM sections s JOIN projects p ON p.id=s.project_id WHERE s.project_id=? ORDER BY s.created_at LIMIT 1", (project_id,)).fetchone()
            if sec and not c.execute("SELECT 1 FROM schemes WHERE section_id=? AND key='plan' AND file_id IS NOT NULL", (sec["id"],)).fetchone():
                _build_scheme(c, sec, "plan", "система")
    except Exception:  # noqa: BLE001
        pass


# ---------------------------------------------------------------- Прочие лица раздела (для документов)
class SectionPersonIn(BaseModel):
    name: str = Field(min_length=1, max_length=200)
    position: str = Field(default="", max_length=200)
    org_name: str = Field(default="", max_length=300)
    user_id: str = Field(default="", max_length=60)
    note: str = Field(default="", max_length=300)


def _section_persons(c: sqlite3.Connection, section_id: str) -> list[dict[str, Any]]:
    return [dict(r) for r in c.execute("SELECT id,user_id,name,position,org_name,note FROM section_persons WHERE section_id=? ORDER BY sort_order,created_at", (section_id,))]


def persons_for_act(c: sqlite3.Connection, section_id: str) -> tuple[str, str]:
    ps = _section_persons(c, section_id)
    lines = [", ".join(x for x in (p["position"], p["org_name"], p["name"]) if x) for p in ps]
    return "\n".join(lines), "; ".join(p["name"] for p in ps)


@app.get("/api/projects/{project_id}/section-persons")
def section_persons_all(project_id: str) -> dict[str, list[dict[str, Any]]]:
    with db() as c:
        return {r["id"]: _section_persons(c, r["id"]) for r in c.execute("SELECT id FROM sections WHERE project_id=?", (project_id,))}


@app.get("/api/sections/{section_id}/persons")
def section_persons_get(section_id: str) -> list[dict[str, Any]]:
    with db() as c:
        return _section_persons(c, section_id)


@app.post("/api/sections/{section_id}/persons", status_code=201)
def section_persons_add(section_id: str, p: SectionPersonIn) -> dict[str, Any]:
    created: list[str] = []
    with db() as c:
        if not c.execute("SELECT 1 FROM sections WHERE id=?", (section_id,)).fetchone():
            raise HTTPException(404, "Раздел не найден")
        u = c.execute("SELECT id,position,org_name FROM dict_users WHERE id=?", (p.user_id,)).fetchone() if p.user_id else None
        nm, ps, og = " ".join(p.name.split()), p.position.strip(), p.org_name.strip()
        # не нашли в справочниках — добавляем туда (сначала всегда предлагается справочник)
        if not u:
            for r in c.execute("SELECT id,position,org_name FROM dict_users WHERE lower(name)=lower(?)", (nm,)).fetchall():
                if not og or not r["org_name"] or r["org_name"].lower() == og.lower():
                    u = r
                    break
        if og and not c.execute("SELECT 1 FROM dict_orgs WHERE lower(name)=lower(?)", (og,)).fetchone():
            c.execute("INSERT INTO dict_orgs (id,name,created_at) VALUES (?,?,?)", (str(uuid.uuid4()), og, now()))
            created.append("организация «" + og + "»")
        if ps and not c.execute("SELECT 1 FROM dict_positions WHERE lower(name)=lower(?)", (ps,)).fetchone():
            c.execute("INSERT INTO dict_positions (id,name,created_at) VALUES (?,?,?)", (str(uuid.uuid4()), ps, now()))
            created.append("должность «" + ps + "»")
        if not u:
            uid_ = str(uuid.uuid4())
            c.execute("INSERT INTO dict_users (id,name,position,org_name,created_at) VALUES (?,?,?,?,?)", (uid_, nm, ps, og, now()))
            u = c.execute("SELECT id,position,org_name FROM dict_users WHERE id=?", (uid_,)).fetchone()
            created.append("сотрудник «" + nm + "»")
        n = c.execute("SELECT COALESCE(MAX(sort_order),0)+1 FROM section_persons WHERE section_id=?", (section_id,)).fetchone()[0]
        i = str(uuid.uuid4())
        c.execute("INSERT INTO section_persons (id,section_id,user_id,name,position,org_name,note,sort_order,created_at) VALUES (?,?,?,?,?,?,?,?,?)",
                  (i, section_id, u["id"] if u else "", nm, ps or (u["position"] if u else ""), og or (u["org_name"] if u else ""), p.note.strip(), n, now()))
        _relink(c)
    return {"id": i, "created": created}


@app.delete("/api/section-persons/{pid}")
def section_persons_del(pid: str) -> dict[str, str]:
    with db() as c:
        if not c.execute("DELETE FROM section_persons WHERE id=?", (pid,)).rowcount:
            raise HTTPException(404, "Запись не найдена")
    return {"message": "Убрано"}


