# ---------------------------------------------------------------- Ожидаемые по смете материалы к поставке (ЖВК)
_EXP_CACHE: dict[tuple[str, float], dict[str, Any]] = {}
_TOK = re.compile(r"[a-zа-яё]+|\d+(?:[.,]\d+)?")


_UNIT_ALIAS = {"погм": "м", "пм": "м", "мп": "м", "мпог": "м", "метр": "м", "метров": "м", "кубм": "м³", "куб": "м³", "м3": "м³", "м2": "м²", "кв": "м²", "штук": "шт", "шт": "шт", "компл": "компл", "комплект": "компл", "тн": "т", "тонн": "т", "тонна": "т"}


def _unit_norm(u: str) -> str:
    x = re.sub(r"[\s.]+", "", (u or "").lower()).replace("³", "3").replace("²", "2")
    return _UNIT_ALIAS.get(x, x)


def _name_norm(n: str) -> str:
    return re.sub(r"\s+", " ", (n or "").strip().lower().replace("ё", "е"))


def _tokens(n: str) -> list[str]:
    t = _TOK.findall((n or "").lower().replace("ё", "е").replace(",", "."))
    return [x for x in t if len(x) > 1 or x.isdigit()]


def _item_key(group: str, name: str, units: str, code: str) -> str:
    return hashlib.sha1("|".join([group, _name_norm(name), _unit_norm(units), code if group == "res" else ""]).encode()).hexdigest()[:12]


def _expected_items(c: sqlite3.Connection, sec: sqlite3.Row) -> dict[str, Any]:
    """Что нужно поставить по сметам раздела: материалы-позиции (синие в ГрандСмете, оборудование) и ресурсные материалы расценок."""
    items: dict[str, dict[str, Any]] = {}
    files: list[str] = []
    q = "SELECT id,name FROM source_files WHERE project_id=? AND kind='estimate' AND section_id=? ORDER BY uploaded_at"
    for f in c.execute(q, (sec["project_id"], sec["id"])).fetchall():
        fp = FILES_DIR / f["id"]
        if not fp.exists():
            continue
        ck = (f["id"], fp.stat().st_mtime)
        if ck not in _EXP_CACHE:
            try:
                _EXP_CACHE[ck] = estimate_table(fp)
            except Exception:  # noqa: BLE001
                _EXP_CACHE[ck] = {"chapters": []}
        files.append(f["name"])
        for ch in _EXP_CACHE[ck]["chapters"]:
            for r in ch["rows"]:
                if r["t"] != "p":
                    continue
                if "Blue" in (r.get("flags") or "") or (r["code"] or "").lower().startswith("оборудование"):
                    ents = [("mat", r["name"], r["units"], r["qty"], r["code"])]
                else:
                    ents = [("res", x["name"], x["units"], x["total"], x["code"]) for x in r["res"] if x["tag"] == "Mat" and "NotCount" not in x["opt"]]
                for grp, name, units, qty, code in ents:
                    if not qty:
                        continue
                    k = _item_key(grp, name, units, code)
                    it = items.setdefault(k, {"key": k, "group": grp, "name": name.strip(), "units": units.strip(), "code": code if grp == "res" else "",
                                              "supplier": code if grp == "mat" else "", "need": 0.0, "src": []})
                    it["need"] = round(it["need"] + qty, 4)
                    it["src"].append(f["name"].split(" (")[0] + " · поз. " + str(r["n"]))
    return {"items": list(items.values()), "files": files}


_QTY_RE = re.compile(r"^\s*(\d+(?:[\s]\d{3})*(?:[.,]\d+)?)\s*(.*)$")


def _parse_qty(t: str) -> tuple[float, str]:
    m = _QTY_RE.match(t or "")
    if not m:
        return 0.0, ""
    return _num(m.group(1)), m.group(2).strip()


_STOP = {"для", "при", "или", "без", "под", "над", "dn", "od", "sn", "pn", "sdr", "мм", "шт", "пог", "упак", "тип", "вид", "марка", "серия"}


def _wtok(n: str) -> set[tuple[str, str]]:
    out: set[tuple[str, str]] = set()
    for t in re.findall(r"[a-zа-я]+|\d+(?:\.\d+)?", (n or "").lower().replace("ё", "е").replace(",", ".")):
        if t[0].isdigit():
            out.add(("n", t))
        elif len(t) >= 3 and t not in _STOP:
            out.add(("w", t[:5]))
    return out


def _wgt(t: tuple[str, str]) -> float:
    return (0.3 if len(t[1]) < 2 else 2.0) if t[0] == "n" else 1.0


# --- Сопоставление названия из документа с позициями сметы
# Схема, принятая для сопоставления товаров (product matching / entity resolution): нормализация → слова с весом TF-IDF по корпусу сметы →
# отдельное сравнение размеров/чисел (DN, 315/263, 250 — главный признак различия товаров) → нечёткое совпадение слов (опечатки, падежи)
# → порог и запас над вторым кандидатом. Подтверждённые пользователем связи («обучение») имеют приоритет.
_SYN = {"пэ": "полиэтилен", "пнд": "полиэтилен", "пвд": "полиэтилен", "пп": "полипропилен", "пвх": "поливинилхлорид", "ст": "стальн", "сталь": "стальн", "стальная": "стальн",
        "гофр": "гофри", "жб": "железобетон", "ж/б": "железобетон", "упл": "уплотн"}
_NSTOP = {"для", "при", "или", "без", "под", "над", "мм", "шт", "пог", "упак", "тип", "вид", "марка", "серия", "компл", "комплект", "изд", "россия", "гост", "ту",
          "с", "со", "и", "на", "в", "по", "из", "от", "до", "dn", "od", "sn", "pn", "sdr", "ду", "диам", "диаметр", "длина", "длиной"}


def _mnorm(n: str) -> str:
    t = (n or "").lower().replace("ё", "е").replace("×", "x").replace("*", "x")
    t = re.sub(r"(?<=\d)\s*[хx]\s*(?=\d)", "x", t)
    t = re.sub(r"(?<=\d),(?=\d)", ".", t)
    return t


def _mparse(n: str) -> tuple[list[str], set[str]]:
    words: list[str] = []
    nums: set[str] = set()
    for w in re.findall(r"[a-zа-я]+|\d+(?:\.\d+)?", _mnorm(n)):
        if w[0].isdigit():
            nums.add(w.rstrip("0").rstrip(".") if "." in w else w)
            continue
        w = _SYN.get(w, w)
        if w in _NSTOP or (len(w) < 3 and w not in _SYN.values()):
            continue
        words.append(w if len(w) <= 5 else w[:5])
    return words, nums


class _Matcher:
    _cache: dict[tuple[str, ...], "_Matcher"] = {}

    @classmethod
    def get(cls, items: list[dict[str, Any]]) -> "_Matcher":
        k = tuple(i["key"] + "|" + i["name"] for i in items)
        m = cls._cache.get(k)
        if m is None:
            if len(cls._cache) > 8:
                cls._cache.clear()
            m = cls._cache[k] = cls(items)
        return m

    def __init__(self, items: list[dict[str, Any]]) -> None:
        self.items = items
        self.parsed = {i["key"]: _mparse(i["name"]) for i in items}
        df: dict[str, int] = {}
        for words, _ in self.parsed.values():
            for w in set(words):
                df[w] = df.get(w, 0) + 1
        self.n = max(len(items), 1)
        self.df = df

    def idf(self, w: str) -> float:
        import math
        return math.log(1 + self.n / (1 + self.df.get(w, 0)))

    def score(self, item: dict[str, Any], name: str, unit: str = "") -> float:
        iw, inum = self.parsed.get(item["key"]) or _mparse(item["name"])
        qw, qnum = _mparse(name)
        if not iw or not qw:
            return 0.0
        qs = set(qw)
        hit: set[str] = set()
        for w in set(iw):
            if w in qs:
                hit.add(w)
            else:
                import difflib
                if any(len(w) >= 4 and difflib.SequenceMatcher(None, w, q).ratio() >= 0.82 for q in qs):
                    hit.add(w)
        if not hit:
            return 0.0                       # общего слова нет — предлагать нечего
        si = sum(self.idf(w) for w in set(iw))
        sq = sum(self.idf(w) for w in qs)
        sh = sum(self.idf(w) for w in hit)
        recall, prec = sh / si, min(1.0, sh / sq) if sq else 0.0
        sc = 0.75 * recall + 0.25 * prec
        big_i = {x for x in inum if len(x.split(".")[0]) >= 2}
        big_q = {x for x in qnum if len(x.split(".")[0]) >= 2}
        if big_i:
            share = len(big_i & big_q) / len(big_i)
            if share:
                share = max(share, 0.7)       # в счёте часто указан один из размеров (DN 250 без OD 209)
            if big_q:
                sc *= 0.35 + 0.65 * share if share else 0.3     # размеры есть с обеих сторон: не совпали — другой товар
            else:
                sc *= 0.75
        elif big_q and not big_i:
            sc *= 0.9
        if unit and item.get("units") and _unit_norm(unit) != _unit_norm(item["units"]):
            sc *= 0.6
        return round(min(sc, 1.0), 3)


def _score(item: dict[str, Any], name: str, unit: str = "") -> float:
    return _Matcher.get([item]).score(item, name, unit)


def _suggest(name: str, unit: str, items: list[dict[str, Any]], n: int = 3, learned: Optional[dict[str, str]] = None) -> list[dict[str, Any]]:
    m = _Matcher.get(items)
    out = [{"key": i["key"], "score": round(m.score(i, name, unit) * (1.0 if i.get("group") == "mat" else 0.7), 3)} for i in items]
    lk = (learned or {}).get(_mnorm(name).strip())
    if lk:
        for o in out:
            if o["key"] == lk:
                o["score"] = 1.0
    out.sort(key=lambda x: -x["score"])
    return [x for x in out[:n] if x["score"] >= 0.3]


def _auto_match(name: str, items: list[dict[str, Any]]) -> str:
    if not items:
        return ""
    m = _Matcher.get(items)
    sc = sorted(((m.score(i, name), i["key"]) for i in items), reverse=True)
    if sc[0][0] >= 0.6 and (len(sc) < 2 or sc[0][0] - sc[1][0] >= 0.1):
        return sc[0][1]
    return ""


@app.get("/api/vhk-expected")
def vhk_expected(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        ex = _expected_items(c, sec)
        its = ex["items"]
        byk = {i["key"]: i for i in its}
        links = {r["vhk_id"]: r["item_key"] for r in c.execute("SELECT vhk_id,item_key FROM vhk_link WHERE section_id=?", (sec["id"],))}
        for i in its:
            i["got"] = 0.0
            i["entries"] = []
        unlinked: list[dict[str, Any]] = []
        for r in c.execute("SELECT id,delivered_on,name,qty,supplier FROM input_control WHERE section_id=? ORDER BY delivered_on, created_at", (sec["id"],)):
            manual = r["id"] in links
            k = links[r["id"]] if manual else _auto_match(r["name"], its)
            n, u = _parse_qty(r["qty"])
            e = {"id": r["id"], "date": r["delivered_on"], "name": r["name"], "qty": r["qty"], "supplier": r["supplier"], "manual": manual, "n": n, "unit": u, "counted": False}
            it = byk.get(k)
            if it is None:
                e["none"] = manual and k == ""
                unlinked.append(e)
                continue
            if n and (not u or _unit_norm(u) == _unit_norm(it["units"])):
                it["got"] = round(it["got"] + n, 4)
                e["counted"] = True
            it["entries"].append(e)
        for i in its:
            need, got = i["need"], i["got"]
            i["left"] = round(max(need - got, 0), 4)
            i["pct"] = round(min(got / need * 100, 999), 1) if need else 0
            i["state"] = "none" if got <= 0 else ("full" if got >= need * 0.999 else "part")
            if got > need * 1.001:
                i["state"] = "over"
            i["src"] = i["src"][:12]
        return {"items": its, "files": ex["files"], "unlinked": unlinked, "section": sec["code"], "over": [x for x in unlinked if x.get("none")]}


class VhkLinkIn(BaseModel):
    vhk_id: str = Field(min_length=1, max_length=64)
    item_key: str = Field(default="", max_length=40)   # "" = не относится к смете; "auto" = вернуть автоподбор


@app.post("/api/vhk-expected/link")
def vhk_link(request: Request, p: VhkLinkIn, section: Optional[str] = None) -> dict[str, str]:
    with db() as c:
        sec = _section(c, section)
        if not c.execute("SELECT 1 FROM input_control WHERE id=? AND section_id=?", (p.vhk_id, sec["id"])).fetchone():
            raise HTTPException(404, "Запись журнала не найдена")
        if p.item_key == "auto":
            c.execute("DELETE FROM vhk_link WHERE vhk_id=?", (p.vhk_id,))
        else:
            if p.item_key and p.item_key not in {i["key"] for i in _expected_items(c, sec)["items"]}:
                raise HTTPException(404, "Такой позиции нет в смете")
            c.execute("INSERT INTO vhk_link (vhk_id,section_id,item_key,linked_by,linked_at) VALUES (?,?,?,?,?) ON CONFLICT(vhk_id) DO UPDATE SET item_key=excluded.item_key, linked_by=excluded.linked_by, linked_at=excluded.linked_at",
                      (p.vhk_id, sec["id"], p.item_key, getattr(request.state, "user", "") or "", now()))
        return {"ok": "1"}


# ---------------------------------------------------------------- Анализ выполнения работ: объёмы по смете и фактически выполненные
def _est_tables(c: sqlite3.Connection, sec: sqlite3.Row) -> list[tuple[str, dict[str, Any], str, str]]:
    """Таблицы текущих редакций действующих смет раздела: (имя файла, таблица, id сметы, название сметы)."""
    out: list[tuple[str, dict[str, Any], str, str]] = []
    _sync_estimates(c, sec["project_id"])
    for rv in _active_revisions(c, sec):
        fp = FILES_DIR / rv["file_id"]
        if not fp.exists():
            continue
        f = c.execute("SELECT name FROM source_files WHERE id=?", (rv["file_id"],)).fetchone()
        ck = (rv["file_id"], fp.stat().st_mtime)
        if ck not in _EXP_CACHE:
            try:
                _EXP_CACHE[ck] = estimate_table(fp)
            except Exception:  # noqa: BLE001
                _EXP_CACHE[ck] = {"chapters": []}
        out.append((f["name"] if f else rv["title"], _EXP_CACHE[ck], rv["est_id"], rv["title"]))
    return out


def _work_key(chapter: str, r: dict[str, Any]) -> str:
    return hashlib.sha1("|".join(["w", chapter, str(r["n"]), r["code"], _name_norm(r["name"]), _unit_norm(r["units"])]).encode()).hexdigest()[:12]


def _is_material(code: str, flags: Optional[str] = "") -> bool:
    """Работа или материал по шифру позиции: работы — ГЭСН/ФЕР/ТЕР (в т. ч. ГЭСНр, ГЭСНм), «ИТС-…» и числовые шифры
    перевозки/погрузки (45-1, 02-15-1-03-0001); всё остальное («ПЭ», «Колодцы», «Метизы», ФССЦ, оборудование …) — материалы."""
    c = (code or "").strip()
    if re.match(r"(?i)(гэсн|фер|тер|итс-)", c):
        return False
    if re.fullmatch(r"\d{1,2}(?:-\d+)+", c):
        return False
    return True


# ---------------------------------------------------------------- сети раздела, вид колодца, множитель единицы (v.87)
def _sec_nets(sec: sqlite3.Row) -> list[str]:
    """Сети раздела из поля «Система» («К2, К2.1» → [К2.1, К2]); длинные шифры первыми, чтобы К2.1 не читалась как К2."""
    try:
        sysf = sec["system"] or ""
    except (IndexError, KeyError):
        sysf = ""
    nets = {m.group(1) for m in re.finditer(r"(?<![\w.])([А-ЯA-Z]{1,2}\d+(?:\.\d+)?)(?![\w.])", sysf)}
    return sorted(nets, key=lambda x: (-len(x), x))


def _net_in_text(text: str, nets: list[str]) -> str:
    """Сеть, названная в заголовке главы/подраздела сметы («Трубы К2.1» → К2.1). Только если в разделе больше одной сети."""
    if len(nets) < 2:
        return ""
    for n in nets:
        if re.search(r"(?<![\w.])" + re.escape(n) + r"(?![\w.]|\.\d)", text or ""):
            return n
    return ""


def _code_net(code: str, nets: list[str]) -> str:
    """Сеть объекта по началу шифра («К2.1-7 – К2.1-14» → К2.1, «К2-Дк.1» → К2). Только если в разделе больше одной сети."""
    if len(nets) < 2:
        return ""
    for n in nets:
        if re.match(r"\s*" + re.escape(n) + r"\s*[-–:]", code or ""):
            return n
    return ""


def _net_els(it: dict[str, Any], els: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Объекты той же сети, что и позиция сметы; объекты без определённой сети остаются кандидатами."""
    n = it.get("net") or ""
    if not n:
        return els
    return [e for e in els if not e.get("net") or e["net"] == n]


def _base_kind(kind: str) -> str:
    """Базовый вид объекта: «Колодец ж/б Ø1500», «Колодец дождеприёмный Ø1000», «Колодец-гаситель …» → «Колодец»."""
    return "Колодец" if re.match(r"\s*колодец", kind or "", re.I) else (kind or "")


def _well_sub(text: str) -> str:
    """Тип колодца: rain — дождеприёмный, linear — линейный (сборный канализационный), '' — не определён."""
    t = (text or "").lower().replace("ё", "е")
    if "дождеприем" in t:
        return "rain"
    if re.search(r"линейн|канализационн\w* колодц|колодц\w* канализац", t):
        return "linear"
    return ""


def _pit_dims(note: str) -> tuple[float, float]:
    """Объём котлована (a×b×(верх − дно)) и высота колодца по примечанию проекта; 0, если данных нет."""
    t = (note or "").replace(",", ".")
    m = re.search(r"котлован\s*(\d+(?:\.\d+)?)\s*[×xх]\s*(\d+(?:\.\d+)?)", t)
    dn = re.search(r"дно\s+проект\s*(\d+(?:\.\d+)?)", t)
    up = re.search(r"земля\s*(\d+(?:\.\d+)?)", t) or re.search(r"верх\s+проект\s*(\d+(?:\.\d+)?)", t)
    h = float(up.group(1)) - float(dn.group(1)) if up and dn else 0.0
    if h <= 0 or h > 15:
        return 0.0, 0.0
    vol = float(m.group(1)) * float(m.group(2)) * h if m else 0.0
    return round(vol, 4), round(h, 4)


def _unit_mult(units: str, kunit: float = 0.0) -> float:
    """Множитель единицы сметы: KUnit из XML, иначе число в единице («100 м» → 100, «1000 м3» → 1000), иначе 1."""
    if kunit and kunit > 0:
        return float(kunit)
    m = re.match(r"\s*(\d+(?:[.,]\d+)?)\s*[^\d\s]", units or "")
    return float(m.group(1).replace(",", ".")) if m else 1.0


def _work_items(c: sqlite3.Connection, sec: sqlite3.Row, mats: bool = False) -> tuple[list[dict[str, Any]], list[str]]:
    items: list[dict[str, Any]] = []
    nets = _sec_nets(sec)
    files: list[str] = []
    for fname, t, est_id, est_title in _est_tables(c, sec):
        files.append(fname)
        meta = _est_rows_of(t, est_id) if t.get("chapters") else []
        _rv = c.execute("SELECT id FROM estimate_revisions WHERE estimate_id=? AND is_current=1", (est_id,)).fetchone()
        _um = {r[0]: r[1] for r in c.execute("SELECT match_key,row_uid FROM estimate_rows WHERE revision_id=?", (_rv[0],))} if _rv else {}
        k = 0
        for ch in t["chapters"]:
            sub = ""
            for r in ch["rows"]:
                if r["t"] == "h":
                    sub = r["name"]
                    continue
                if r["t"] != "p":
                    continue
                m = meta[k]
                k += 1
                if not r["qty"] or (not mats and ("Blue" in (r.get("flags") or "") or "Green" in (r.get("flags") or "") or (r["code"] or "").lower().startswith("оборудование"))):
                    continue          # материалы и оборудование — в окне «Ожидаемые материалы»; здесь только работы
                items.append({"key": _um.get(m["mk"], m["mk"]), "key_old": m["key_old"], "est": est_title, "chapter": ch["caption"], "sub": sub, "n": r["n"], "code": r["code"], "name": r["name"].strip(),
                              "units": r["units"].strip(), "plan": round(float(r["qty"]), 4), "plan_s": m["qty"], "formula": m["formula"],
                              "mat": _is_material(r["code"], r.get("flags")),
                              "net": _net_in_text(ch["caption"] + " " + sub, nets), "kunit": _unit_mult(r["units"], r.get("kunit") or 0.0)})
    _attach_companions(items)
    return items, files


def _attach_companions(items: list[dict[str, Any]]) -> None:
    """Смета ставит под каждой работой материалы, которые на неё расходуются: они точно называют объект, к которому относится работа."""
    cur: Optional[dict[str, Any]] = None
    for it in items:
        if not it["mat"]:
            cur = it
            it["comp"] = []
        elif cur is not None and cur["chapter"] == it["chapter"] and cur.get("sub") == it.get("sub") and cur["est"] == it["est"]:
            cur["comp"].append({"name": it["name"], "qty": it["plan"], "units": it["units"]})


_FLAG_RX = {"es": r"закладн|электросвар|электронагрев", "steel": r"стал|12х18|нерж", "sewer": r"канализ|оранж", "corr": r"гофр|профилированн"}


def _flags(text: str) -> set[str]:
    """Признаки детали по названию: электросварная (закладные нагреватели), стальная, канализационная."""
    t = (text or "").lower()
    return {k for k, rx in _FLAG_RX.items() if re.search(rx, t)}


def _flags_ok(item_name: str, el: dict[str, Any]) -> bool:
    """Совместима ли деталь проекта с названием позиции: сталь и канализация должны совпасть; «электросварная»/«сварная» — если названы."""
    fi, fe = _flags(item_name), el.get("flags") or set()
    for k in ("steel", "sewer"):
        if (k in fi) != (k in fe):
            return False
    low = (item_name or "").lower()
    if "es" in fi and "es" not in fe:
        return False
    if re.search(r"сварн", low) and "es" not in fi and "es" in fe:
        return False
    return True


class WaFact(BaseModel):
    item_key: str = Field(min_length=1, max_length=40)
    qty: float = Field(gt=0, le=1e9)
    performed_on: str = Field(min_length=10, max_length=10)
    note: str = Field(default="", max_length=300)
    client_request_id: Optional[str] = Field(default=None, max_length=64)


_EARTH_RX = re.compile(r"разработка грунта|засыпк|погрузк|перевозк|грунт|котлован", re.I)


def _rule_kind(name: str, sub: str = "") -> str:
    """Как позиция сметы делится между участками: wells — по числу колодцев, line — по длине трассы, '' — вручную."""
    nm = (name or "").lower()
    if re.search(r"пробивк\w*.*колодц|отверсти\w*\s+в\s+колодц", (sub or "").lower()):
        return "wells"        # раздел сметы «Пробивка отверстий в колодцах»: работы и трубы-патрубки относятся к колодцам
    if re.match(r"\s*колодц", (sub or "").lower()) and _EARTH_RX.search(nm):
        return "wells"        # подраздел «Колодцы линейные / дождеприёмные» в земляных работах: котлованы колодцев, не траншея
    if re.search(r"усилен\w*\s+сборных\s+железобетон", nm):
        return "wells"
    if "колодц" in nm and "траншe" not in nm and "траншеи" not in nm:
        return "wells"
    if re.search(r"узл\w*\s+(?:обвязк|учет|учёт)|обвязк\w*\s+узл|монтаж\w*\s+узл", nm):
        return "nodes"
    if re.search(r"стальной соединительный элемент|^обойма|бетон на обойму|горловин|стремянк|скоб", nm):
        return "wells"
    if re.search(r"укладка трубопровод|прокладка трубопровод|укладка труб|разработка грунта|основани\w* под трубопровод|засыпка|погрузка|перевозка|промывк|дезинфекц|испытани\w* трубопровод|^труба\s+(?:пэ|полиэт)", nm) and "котлован" not in nm and "колодц" not in nm:
        return "line"
    return ""


def _wells_tables(c: sqlite3.Connection, sec: sqlite3.Row) -> dict[tuple[str, str], dict[str, Any]]:
    """Таблицы колодцев из PDF проектов раздела: {(сеть, № колодца): состав}. Считаются один раз и запоминаются в анализе файла."""
    out: dict[tuple[str, str], dict[str, Any]] = {}
    for f in c.execute("SELECT id,name,kind,analysis_json,status FROM source_files WHERE project_id=? AND section_id=?", (sec["project_id"], sec["id"])).fetchall():
        if f["kind"] == "estimate" or f["status"] == "analyzing" or not str(f["name"]).lower().endswith(".pdf"):
            continue
        try:
            a = json.loads(f["analysis_json"] or "{}")
            if "wells_table" not in a:
                with _ANALYSIS_SLOT:
                    a["wells_table"] = extract_wells_table_pdf(_pdf_pages_words(FILES_DIR / f["id"]))
                c.execute("UPDATE source_files SET analysis_json=? WHERE id=?", (json.dumps(a, ensure_ascii=False), f["id"]))
        except Exception:  # noqa: BLE001
            continue
        for wt in a.get("wells_table") or []:
            out[(wt.get("net") or "", str(wt["n"]))] = wt
    return out


def _alloc_elements(c: sqlite3.Connection, sec: sqlite3.Row) -> list[dict[str, Any]]:
    """Участки и колодцы перечня (позиции сметы «См-N» не входят): то, между чем делится смета."""
    out = []
    wtabs = _wells_tables(c, sec)
    snets = _sec_nets(sec)
    for r in c.execute("SELECT id,code,name,kind,block,planned_note FROM elements WHERE section_id=? AND enabled=1 AND scope='' AND code NOT LIKE 'См-%' ORDER BY block, code", (sec["id"],)):
        r = {**dict(r), "kind_full": r["kind"], "kind": _base_kind(r["kind"])}
        m = re.search(r"L\s*=\s*(\d+(?:[.,]\d+)?)\s*м", r["planned_note"] or "")
        cl = _obj_class(r["name"] + " " + (r["planned_note"] or "")) if r["kind"] in ("Арматура", "Фитинг", "Оборудование", "Деталь колодца") else None
        out.append({"id": r["id"], "code": r["code"], "name": r["name"], "kind": r["kind"], "block": r["block"], "len": float(m.group(1).replace(",", ".")) if m else 0.0,
                    "fam": cl[3] if cl else "", "label": cl[0] if cl else "", "dn": sorted(_dn_set(r["name"] + " " + (r["planned_note"] or ""))), "qty": _el_qty(r["planned_note"]), "flags": _flags(r["name"] + " " + (r["planned_note"] or ""))})
        out[-1]["marks"] = {_norm_mark(k): int(v) for k, v in re.findall(r"([A-Za-zА-Яа-я0-9. ]+?)×(\d+)", (r["planned_note"] or "").split("Состав:")[-1].split("·")[0])} if "Состав:" in (r["planned_note"] or "") else {}
        mc = re.search(r"бетон на опоры\s*(\d+(?:[.,]\d+)?)", r["planned_note"] or "")
        out[-1]["conc"] = float(mc.group(1).replace(",", ".")) if mc else 0.0
        if r["kind"] == "Колодец" and not out[-1]["marks"]:     # колодец без записанного состава — берём из таблицы колодцев проекта
            wt = None
            nm_ = re.match(r"\s*([A-Za-zА-Яа-я]+\d+)\s*[-:.]?\s*К?\s*(\d+)\s*$", r["code"] or "") or re.search(r"([A-Za-zА-Яа-я]+\d+)\D+(\d{1,3})\s*$", r["code"] or "")
            if nm_:
                wt = wtabs.get((nm_.group(1), nm_.group(2)))
            if not wt:
                mm = re.search(r"№\s*(\d+)", r["name"] or "")
                nets = {k[0] for k in wtabs}
                if mm and len(nets) == 1:
                    wt = wtabs.get((next(iter(nets)), mm.group(1)))
            if wt:
                out[-1]["marks"] = {_norm_mark(k): int(v) for k, v in wt["comp"].items()}
                out[-1]["conc"] = float(wt.get("conc") or 0)
        if out[-1]["len"] and not out[-1]["dn"]:
            out[-1]["dn"] = sorted(_dn_set(r["planned_note"] or ""))
        out[-1]["kind_full"] = r["kind_full"]
        out[-1]["net"] = _code_net(r["code"], snets)
        if out[-1]["kind"] == "Колодец":
            out[-1]["wsub"] = _well_sub(r["kind_full"] + " " + r["name"] + " " + (r["planned_note"] or ""))
            out[-1]["pit"], out[-1]["height"] = _pit_dims(r["planned_note"] or "")
    return out


_COMP_KEYS = [(r"люк.*(?:тм\b|тип\s*тм)", "Люк ТМ"), (r"люк.*(?:3634|гост|тяжел\w*\s+т\b|в-1-60|тип\s*т\b)", "Люк ГОСТ"), (r"люк.*с250", "Люк ТМ")]


def _comp_key(item_name: str) -> str:
    """Марка изделия колодца из названия позиции сметы (как в таблице колодцев проекта) или ''."""
    nm = item_name or ""
    low = nm.lower()
    for rx, k in _COMP_KEYS:
        if re.search(rx, low):
            return _norm_mark(k)
    m = re.search(r"\d?ПП\d+(?:-\d)?|КС\d+\.\d|ПН\d+|КО\d+", nm, re.I)
    if m:
        return _norm_mark(m.group(0))
    return "conc" if re.search(r"бетон на (?:упор|опор)", low) else ""


def _comp_match(item_name: str, els: list[dict[str, Any]]) -> list[tuple[dict[str, Any], float]]:
    """Изделия колодцев (кольца, плиты, люки, бетон на опоры) → колодцы по таблице колодцев проекта; вес — число изделий данной марки."""
    nm = (item_name or "")
    low = nm.lower()
    key = _comp_key(nm)
    if key and key != "conc":
        return [(e, float(e["marks"][key])) for e in els if e.get("marks") and key in e["marks"]]
    if "бетон на упор" in low or "бетон на опор" in low:
        return [(e, e["conc"]) for e in els if e.get("conc")]
    return []


def _match_objects(item_name: str, els: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Объекты проекта, которым соответствует позиция сметы: тот же класс (задвижка, фланец, тройник …) и совместимый диаметр."""
    cl = _obj_class(item_name)
    if not cl:
        return []
    dn = _dn_set(item_name)
    got = [e for e in els if e["fam"] == cl[3]]
    if cl[3] == "arm":      # «задвижек или клапанов» — только названные виды арматуры; «вентилей и клапанов» — краны тоже
        nm = item_name.lower()
        labs = {lb for rx, lb, _k, _a, fm, _o in _OBJ_CLASSES if fm == "arm" and re.search(rx, nm)}
        if "Кран / вентиль" in labs and "Клапан" not in labs:
            labs.add("Клапан")
        if "Клапан" in labs and "Кран / вентиль" not in labs and "вентил" in nm:
            labs.add("Кран / вентиль")
        got2 = [e for e in got if e.get("label") in labs]
        got = got2 or got
    got = [e for e in got if _flags_ok(item_name, e)]
    if dn:
        exact = [e for e in got if e["dn"] and dn & set(e["dn"])]
        if not exact:
            rg = _dn_range(item_name)       # «до 63 мм», «свыше 110 до 160 мм»: по наибольшему диаметру детали
            exact = [e for e in got if rg and e["dn"] and rg[0] < max(int(x) for x in e["dn"]) <= rg[1]]
        got = exact or [e for e in got if not e["dn"] and "sewer" not in (e.get("flags") or set())]
    nm = item_name.lower()
    pos = {lb: (re.search(rx, nm).start() if re.search(rx, nm) else 999) for rx, lb, *_ in _OBJ_CLASSES}
    return sorted(got, key=lambda e: (pos.get(e.get("label"), 999), e.get("code", "")))


@app.get("/api/alloc")
def alloc_list(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        items, files = _work_items(c, sec, True)
        els = _alloc_elements(c, sec)
        al: dict[str, list[dict[str, Any]]] = {}
        for r in c.execute("SELECT item_key,element_id,qty,mode FROM work_alloc WHERE section_id=?", (sec["id"],)):
            al.setdefault(r["item_key"], []).append({"element_id": r["element_id"], "qty": r["qty"], "mode": r["mode"]})
        rows = []
        for it in items:
            a = al.get(it["key"], [])
            got = round(sum(x["qty"] for x in a), 4)
            extra: dict[str, Any] = {"net": it.get("net", ""), "kunit": it.get("kunit", 1.0), "plan_phys": round(it["plan"] * (it.get("kunit") or 1.0), 4)}
            if _rule_kind(it["name"], it.get("sub", "")) == "line" and re.fullmatch(r"(?:\d+\s*)?м\.?", (it["units"] or "").strip().lower()):
                g, _w = _alloc_group(it, els)
                if g and _dn_range(it["name"]) and not re.search(r"грунт|засыпк|песок|погрузк|перевозк", it["name"].lower()):
                    pl = round(sum(e["len"] for e in g), 2)
                    extra.update({"proj_len": pl, "len_diff": round(extra["plan_phys"] - pl, 2)})   # длина по проекту против сметы (в метрах)
            rows.append({**{k: it[k] for k in ("key", "chapter", "n", "code", "name", "units", "plan", "mat")}, **extra, "sub": it.get("sub", ""), "rule": _row_rule(it, els), "cand": [e["id"] for e in _alloc_group(it, els)[0]], "cls": (_obj_class(it["name"]) or ("", "", "", ""))[3], "alloc": a, "allocated": got, "free": round(it["plan"] - got, 4)})
        return {"wells_comp": sum(1 for e in els if e["kind"] == "Колодец" and e.get("marks")), "rows": rows, "elements": els, "files": files, "lines": sum(1 for e in els if e["kind"] != "Колодец" and e["len"] > 0), "wells": sum(1 for e in els if e["kind"] == "Колодец")}


_COUNT_UNITS = {"шт", "компл", "комплект", "пар", "пара", "уст", "узел", "опора"}


def _countable(units: str) -> bool:
    """Штучные единицы: количество целое, дробной части быть не может."""
    return (units or "").strip().lower().replace(".", "").replace(" ", "") in _COUNT_UNITS


def _row_rule(it: dict[str, Any], els: list[dict[str, Any]]) -> str:
    els = _net_els(it, els)
    r = _rule_kind(it["name"], it.get("sub", ""))
    if r:
        return r
    if _comp_match(it["name"], els):
        return "comp"
    if _comp_elements(it, els):
        return "obj"
    if _pipe_cands(it, els):
        return "pipe"
    return "obj" if _match_objects(it["name"], els) else ""


def _alloc_parts(it: dict[str, Any], group: list[dict[str, Any]], w: list[float]) -> Optional[list[float]]:
    """Объёмы по объектам группы или None, если раскладка без решения ПТО недопустима: поровну не делим, штучные не дробим."""
    tot = sum(w)
    if not group or tot <= 0:
        return None
    kind = _rule_kind(it["name"], it.get("sub", ""))
    countable = _countable(it.get("units", ""))
    bc = it.get("_by_comp")
    if bc and len(bc) == len(group) and not kind:
        if abs(sum(bc) - it["plan"]) < 0.0051:
            return [float(x) for x in bc]          # смета: работа = сумма материалов под ней
        if all(abs(x - it["plan"]) < 0.0051 for x in bc):
            return [float(it["plan"])] * len(group)  # каждый материал под работой — на весь объём работы
    if not kind and not bc and (_obj_class(it["name"]) or ("", "", "", ""))[3] in ("", "plug") and _PIPE_OP.search(it["name"]):
        return [float(it["plan"])] if len(group) == 1 else None   # труб несколько — как делить, решает ПТО
    if kind in ("wells", "nodes") and len(set(w)) <= 1:        # равные веса — это деление поровну: только «по одной на объект» при точном совпадении числа
        if not (countable and abs(it["plan"] - len(group)) < 1e-9):
            return None
        return [1.0] * len(group)
    qs, left = [], it["plan"]
    for i, wi in enumerate(w):
        q = round(left, 4) if i == len(w) - 1 else round(it["plan"] * wi / tot, 4)
        left -= q
        qs.append(max(q, 0.0))
    if countable and any(abs(q - round(q)) > 1e-9 for q in qs):
        return None
    return qs


_WELD_FAMS = {"bush", "coupl", "tee", "bend", "red", "saddle"}
_PIPE_OP = re.compile(r"резк\w*\s+(?:полиэтилен|труб)|сварк\w*\s+(?:полиэтилен|труб)|заглуш|футляр|кожух|заделк|протаскив|антикоррозион|изоляц", re.I)


def _narrow(mt: dict[str, Any], cands: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Из подходящих объектов оставить те, что точнее всего соответствуют материалу: то же наименование, те же диаметры, тот же способ сварки, то же количество."""
    import difflib
    nn = lambda x: re.sub(r"[^0-9a-zа-я]+", "", (x or "").lower())  # noqa: E731
    mn, fm, dm = nn(mt["name"]), _flags(mt["name"]), _dn_set(mt["name"])
    for pred in (lambda e: nn(e["name"]) == mn,
                 lambda e: set(e["dn"]) == dm,
                 lambda e: ("es" in (e.get("flags") or set())) == ("es" in fm),
                 lambda e: abs(e["qty"] - mt["qty"]) < 1e-9):
        if len(cands) <= 1:
            break
        f = [e for e in cands if pred(e)]
        cands = f or cands
    if len(cands) > 1:
        r = {e["id"]: difflib.SequenceMatcher(None, nn(e["name"]), mn).ratio() for e in cands}
        top = max(r.values())
        cands = [e for e in cands if r[e["id"]] >= top - 0.02]
    return cands


def _comp_elements(it: dict[str, Any], els: list[dict[str, Any]]) -> list[tuple[dict[str, Any], float]]:
    """Объекты проекта по материалам, которые смета ставит под работой: (объект, количество материала)."""
    wcl = _obj_class(it["name"])
    welding = bool(re.search(r"сварк", it["name"].lower()))
    out: list[tuple[dict[str, Any], float]] = []
    seen: set[str] = set()
    for mt in it.get("comp") or []:
        cl = _obj_class(mt["name"])
        if not cl or (wcl and cl[3] != wcl[3]) or (not wcl and not (welding and cl[3] in _WELD_FAMS)):
            continue
        cands = _narrow(mt, [e for e in _match_objects(mt["name"], els) if e["id"] not in seen])
        if len(cands) > 1:
            same = [e for e in cands if e["qty"] == 1]
            if len(same) != len(cands) or mt["qty"] != int(mt["qty"]) or not 0 < mt["qty"] <= len(cands):
                continue                  # неоднозначно: решает ПТО
            for e in cands[:int(mt["qty"])]:
                if e["id"] not in seen:
                    seen.add(e["id"])
                    out.append((e, 1.0))
        elif cands and cands[0]["id"] not in seen:
            seen.add(cands[0]["id"])
            out.append((cands[0], float(mt["qty"])))
    return out


def _pipe_cands(it: dict[str, Any], els: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Резка, сварка, заглушки, футляры: относятся к трубе — участки трубопровода нужного диаметра (диаметр из названия вида работ или заголовка раздела сметы)."""
    cl = _obj_class(it["name"])
    if not _PIPE_OP.search(it["name"]) or (cl and cl[3] != "plug"):
        return []
    pipes = [e for e in els if e["kind"] == "Трубопровод" and e["len"] > 0 and e["dn"]]
    m = re.search(r"(?:ф|d|dn)\s*(\d{2,3})", it.get("sub") or "", re.I)
    if m:
        return [e for e in pipes if m.group(1) in e["dn"]]
    rg = _dn_range(it["name"])
    return [e for e in pipes if rg and any(rg[0] < int(x) <= rg[1] for x in e["dn"])]


def _alloc_group(it: dict[str, Any], els: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[float]]:
    """Объекты проекта, между которыми делится позиция сметы, и их веса."""
    els = _net_els(it, els)                    # раздел из нескольких сетей: позиция главы «… К2.1» — только на объекты К2.1
    lines = [e for e in els if e["kind"] != "Колодец" and e["len"] > 0]
    wells = [e for e in els if e["kind"] == "Колодец"]
    kind = _rule_kind(it["name"], it.get("sub", ""))
    if kind == "line":
        rg = _dn_range(it["name"]) if not re.search(r"грунт|засыпк|песок|погрузк|перевозк", it["name"].lower()) else None
        lines_it = [e for e in lines if any(rg[0] < int(x) <= rg[1] for x in e["dn"])] if rg else lines
        if rg and "corr" in _flags(it["name"]):          # профилированная (гофрированная) труба — только гофрированные участки
            lines_it = [e for e in lines_it if "corr" in (e.get("flags") or set())]
        elif rg and re.search(r"напорн", it["name"].lower()):
            lines_it = [e for e in lines_it if "corr" not in (e.get("flags") or set())]
        return lines_it, [e["len"] for e in lines_it]
    if kind == "wells":
        ws = _well_sub(it["name"] + " " + it.get("sub", ""))
        if ws and any(e.get("wsub") == "rain" for e in wells):   # дождеприёмные выделены в проекте: остальные колодцы — линейные
            wells = [e for e in wells if (e.get("wsub") == "rain") == (ws == "rain")]
        unit = (it.get("units") or "").lower()
        if wells and _EARTH_RX.search(it["name"]) and all(e.get("pit") for e in wells):
            return wells, [float(e["pit"]) for e in wells]          # земляные работы колодцев — пропорционально объёму котлована
        if wells and "м3" in unit and re.search(r"устройств\w*.*колодц", it["name"].lower()) and all(e.get("height") for e in wells):
            return wells, [float(e["height"]) for e in wells]       # устройство колодцев (м3) — пропорционально высоте колодца
        return wells, [1.0] * len(wells)
    if kind == "nodes":
        nodes = [e for e in els if e["kind"] == "Узел"]
        return nodes, [1.0] * len(nodes)
    cm = _comp_match(it["name"], els)
    if cm:
        return [e for e, _ in cm], [x for _, x in cm]
    ce = _comp_elements(it, els)
    if ce:
        it["_by_comp"] = [q for _, q in ce]
        return [e for e, _ in ce], [q for _, q in ce]
    pc = _pipe_cands(it, els)
    if pc:
        return pc, [e["len"] for e in pc]
    group = _match_objects(it["name"], els)
    if group and all(e["qty"] == 1 for e in group) and it["plan"] == int(it["plan"]) and 0 < it["plan"] <= len(group):
        group = group[:int(it["plan"])]        # штучные объекты: по одной единице, в порядке названных видов
    return group, [e["qty"] for e in group]


def _el_dict(eid: str, code: str, name: str, kind: str, block: str, note: str, nets: Optional[list[str]] = None) -> dict[str, Any]:
    """Объект перечня в виде, пригодном для сопоставления со сметой (из строки БД или из предложения)."""
    note = note or ""
    kind_full, kind = kind, _base_kind(kind)
    m = re.search(r"L\s*=\s*(\d+(?:[.,]\d+)?)\s*м", note)
    cl = _obj_class(name + " " + note) if kind in ("Арматура", "Фитинг", "Оборудование", "Деталь колодца") else None
    e = {"id": eid, "code": code, "name": name, "kind": kind, "block": block, "len": float(m.group(1).replace(",", ".")) if m else 0.0,
         "fam": cl[3] if cl else "", "label": cl[0] if cl else "", "dn": sorted(_dn_set(name + " " + note)), "qty": _el_qty(note), "flags": _flags(name + " " + note)}
    e["marks"] = {_norm_mark(k): int(v) for k, v in re.findall(r"([A-Za-zА-Яа-я0-9. ]+?)×(\d+)", note.split("Состав:")[-1].split("·")[0])} if "Состав:" in note else {}
    mc = re.search(r"бетон на опоры\s*(\d+(?:[.,]\d+)?)", note)
    e["conc"] = float(mc.group(1).replace(",", ".")) if mc else 0.0
    if e["len"] and not e["dn"]:
        e["dn"] = sorted(_dn_set(note))
    e["kind_full"] = kind_full
    e["net"] = _code_net(code, nets or [])
    if kind == "Колодец":
        e["wsub"] = _well_sub(kind_full + " " + name + " " + note)
        e["pit"], e["height"] = _pit_dims(note)
    return e


def _covered_ids(items: list[dict[str, Any]], els: list[dict[str, Any]]) -> set[str]:
    """Объекты, для которых в смете нашлась хотя бы одна позиция."""
    got: set[str] = set()
    for it in items:
        g, w = _alloc_group(it, els)
        if g and sum(w) > 0:
            got.update(e["id"] for e in g)
    return got


@app.post("/api/alloc/auto")
def alloc_auto(request: Request, section: Optional[str] = None, reset: int = 0) -> dict[str, Any]:
    """Предложение раскладки: позиции по длине делятся между участками пропорционально длине, по колодцам — поровну. Ручные строки не трогаем."""
    with db() as c:
        sec = _section(c, section)
        return _alloc_auto_core(c, sec, (getattr(request.state, "user", "") or "")[:80], reset)


def _alloc_auto_core(c: sqlite3.Connection, sec: sqlite3.Row, who: str, reset: int = 0) -> dict[str, Any]:
    if True:
        items, _ = _work_items(c, sec, True)
        els = _alloc_elements(c, sec)
        lines = [e for e in els if e["kind"] != "Колодец" and e["len"] > 0]
        wells = [e for e in els if e["kind"] == "Колодец"]
        if reset:          # ПТО явно просит предложить заново: подтверждённые и ручные строки раздела тоже сбрасываются
            c.execute("DELETE FROM work_alloc WHERE section_id=? AND mode='manual'", (sec["id"],))
        manual = {r[0] for r in c.execute("SELECT DISTINCT item_key FROM work_alloc WHERE section_id=? AND mode='manual'", (sec["id"],))}
        c.execute("DELETE FROM work_alloc WHERE section_id=? AND mode='auto'", (sec["id"],))
        done = skipped = needs_pto = 0
        used: dict[str, float] = {}
        mism: list[dict[str, Any]] = []
        for it in items:
            if it["key"] in manual:
                skipped += 1
                continue
            ck = _comp_key(it["name"]) if not _rule_kind(it["name"], it.get("sub", "")) else ""
            if ck:
                # изделия колодцев: количество на колодец — ровно по таблице колодцев проекта, без пересчёта под смету
                cm = _comp_match(it["name"], _net_els(it, els))
                tbl = round(sum(x for _, x in cm), 4)
                npos = sum(1 for i2 in items if _comp_key(i2["name"]) == ck and (i2.get("net") or "") == (it.get("net") or ""))
                if cm and npos == 1 and abs(tbl - it["plan"]) < 0.0051:
                    for e, q in cm:
                        c.execute("INSERT INTO work_alloc (id,section_id,item_key,element_id,qty,mode,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?)",
                                  (str(uuid.uuid4()), sec["id"], it["key"], e["id"], float(q), "auto", who, now()))
                    done += 1
                else:
                    needs_pto += 1
                    mism.append({"n": it["n"], "name": it["name"], "units": it["units"], "estimate": it["plan"], "table": tbl, "positions_with_mark": npos, "wells_in_table": len(cm)})
                continue
            group, w = _alloc_group(it, els)
            qs = _alloc_parts(it, group, w)
            if qs is not None and it.get("_by_comp"):
                if any(used.get(e["id"], 0.0) + q > e["qty"] + 1e-9 for e, q in zip(group, qs)):
                    qs = None               # в проекте таких деталей меньше, чем в смете: расхождение проекта и сметы решает ПТО, сами не подгоняем
                    mism.append({"n": it["n"], "name": it["name"], "units": it["units"], "estimate": it["plan"], "table": sum(e["qty"] for e in group), "positions_with_mark": 1, "wells_in_table": len(group)})
                else:
                    for e, q in zip(group, qs):
                        used[e["id"]] = used.get(e["id"], 0.0) + q
            if qs is None:
                if group and sum(w) > 0:
                    needs_pto += 1          # без таблицы состава и без однозначного соответствия — не распределяем, решает ПТО
                continue
            for e, q in zip(group, qs):
                c.execute("INSERT INTO work_alloc (id,section_id,item_key,element_id,qty,mode,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?)",
                          (str(uuid.uuid4()), sec["id"], it["key"], e["id"], q, "auto", who, now()))
            done += 1
        return {"message": f"Раскладка предложена по {done} позициям" + (f"; ручные оставлены ({skipped})" if skipped else "") + (f"; без решения ПТО: {needs_pto} — изделия колодцев берутся только по таблице колодцев проекта, при несовпадении со сметой или нескольких позициях одной марки решает ПТО (поровну и дробными штуками не делим)" if needs_pto else "") + f". Участков с длиной: {len(lines)}, колодцев: {len(wells)}.", "done": done, "needs_pto": needs_pto, "table_mismatch": mism}


@app.post("/api/alloc/confirm")
def alloc_confirm(request: Request, section: Optional[str] = None) -> dict[str, Any]:
    """ПТО подтверждает предложенное сопоставление: авто-строки становятся ручными (повторное «Предложить» их не трогает)."""
    with db() as c:
        sec = _section(c, section)
        n = c.execute("SELECT COUNT(DISTINCT item_key) FROM work_alloc WHERE section_id=? AND mode='auto'", (sec["id"],)).fetchone()[0]
        c.execute("UPDATE work_alloc SET mode='manual', updated_by=?, updated_at=? WHERE section_id=? AND mode='auto'", ((getattr(request.state, "user", "") or "")[:80], now(), sec["id"]))
    return {"message": f"Подтверждено позиций сметы: {n}"}


class AllocSet(BaseModel):
    item_key: str = Field(min_length=1, max_length=40)
    parts: list[dict[str, Any]] = Field(default_factory=list, max_length=2000)   # [{element_id, qty}]


@app.put("/api/alloc")
def alloc_set(request: Request, p: AllocSet, section: Optional[str] = None) -> dict[str, Any]:
    """Ручная раскладка одной позиции: заменяет все её строки, помечает как ручную."""
    with db() as c:
        sec = _section(c, section)
        items, _ = _work_items(c, sec, True)
        it = next((i for i in items if i["key"] == p.item_key), None)
        if not it:
            raise HTTPException(422, "Такой позиции нет в смете раздела")
        ids = {r[0] for r in c.execute("SELECT id FROM elements WHERE section_id=?", (sec["id"],))}
        rows = []
        for x in p.parts:
            try:
                q = float(x.get("qty") or 0)
            except (TypeError, ValueError):
                raise HTTPException(422, "Объём должен быть числом") from None
            if str(x.get("element_id")) not in ids:
                raise HTTPException(422, "Участок не найден в перечне раздела")
            if q < 0:
                raise HTTPException(422, "Объём не может быть отрицательным")
            if q > 0 and _countable(it.get("units", "")) and abs(q - round(q)) > 1e-9:
                raise HTTPException(422, "Штучная позиция не может иметь дробное количество на объекте")
            if q > 0:
                rows.append((str(x["element_id"]), round(q, 4)))
        c.execute("DELETE FROM work_alloc WHERE section_id=? AND item_key=?", (sec["id"], p.item_key))
        who = (getattr(request.state, "user", "") or "")[:80]
        for eid, q in rows:
            c.execute("INSERT INTO work_alloc (id,section_id,item_key,element_id,qty,mode,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?)", (str(uuid.uuid4()), sec["id"], p.item_key, eid, q, "manual", who, now()))
        tot = round(sum(q for _, q in rows), 4)
        return {"allocated": tot, "free": round(it["plan"] - tot, 4)}


# ================================================================ v.88: мастер «Перечень работ» — 4 шага
_WIZ_DDL = """
CREATE TABLE IF NOT EXISTS list_wizard (
  section_id TEXT PRIMARY KEY,
  s1_at TEXT NOT NULL DEFAULT '', s1_by TEXT NOT NULL DEFAULT '', s1_json TEXT NOT NULL DEFAULT '{}',
  s2_at TEXT NOT NULL DEFAULT '', s2_by TEXT NOT NULL DEFAULT '', s2_fp TEXT NOT NULL DEFAULT '',
  s3_at TEXT NOT NULL DEFAULT '', s3_by TEXT NOT NULL DEFAULT '', s3_fp TEXT NOT NULL DEFAULT '', s3_json TEXT NOT NULL DEFAULT '{}',
  s4_at TEXT NOT NULL DEFAULT '', s4_by TEXT NOT NULL DEFAULT '', s4_fp TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT ''
);
"""
SCOPES = {"": "Наша работа", "excluded": "Не делаем (исключено заказчиком)", "other": "Другой подрядчик"}


def _init_wizard(c: sqlite3.Connection) -> None:
    """Идемпотентно: таблица состояния мастера и колонки статуса объёма у элементов перечня."""
    c.executescript(_WIZ_DDL)
    _ensure_cols(c, "elements", {"scope": "TEXT NOT NULL DEFAULT ''", "scope_note": "TEXT NOT NULL DEFAULT ''", "scope_by": "TEXT NOT NULL DEFAULT ''", "scope_at": "TEXT NOT NULL DEFAULT ''"})
    _ensure_cols(c, "list_wizard", {"handed_at": "TEXT NOT NULL DEFAULT ''", "handed_by": "TEXT NOT NULL DEFAULT ''"})
    c.execute("CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL DEFAULT '')")
    if not c.execute("SELECT 1 FROM kv WHERE k='wizard_v89_grandfather'").fetchone():
        # v.89: разделы, где перечень уже был до мастера, считаются переданными прорабу — полевая работа не блокируется
        sids = [r[0] for r in c.execute("SELECT DISTINCT section_id FROM elements WHERE enabled=1 AND section_id IS NOT NULL")]
        for sid in sids:
            c.execute("INSERT OR IGNORE INTO list_wizard (section_id) VALUES (?)", (sid,))
            c.execute("UPDATE list_wizard SET handed_at=?, handed_by='перечень до мастера (v.89)', updated_at=? WHERE section_id=? AND handed_at=''", (now(), now(), sid))
        c.execute("INSERT INTO kv (k,v) VALUES ('wizard_v89_grandfather',?)", (json.dumps({"at": now(), "sections": len(sids)}),))


LIST_LOCKED_MSG = "Перечень готовит ПТО. Отмечать работы можно будет после того, как ПТО завершит подготовку перечня (шаг 4 «Завершить»)."
_LIST_LOCK_ROLES = {"foreman", "other"}


def _list_locked(request: Request, c: sqlite3.Connection, sec: Any) -> bool:
    """Прораб и только-просмотр не видят и не отмечают перечень раздела, пока ПТО не передал его (шаг 4 мастера)."""
    login = getattr(request.state, "user", "") or ""
    mem = _memberships(login) if login else None
    if mem is None:
        return False
    role = _role_in(login, sec["project_id"], sec["id"]) or mem.get(sec["project_id"], "")
    if role not in _LIST_LOCK_ROLES:
        return False
    r = c.execute("SELECT handed_at FROM list_wizard WHERE section_id=?", (sec["id"],)).fetchone()
    return not (r and r[0])


def _list_fp(c: sqlite3.Connection, sid: str) -> str:
    """Отпечаток перечня раздела: меняется при добавлении, правке, отключении объекта или смене статуса объёма."""
    h = hashlib.sha1()
    for r in c.execute("SELECT id,code,name,kind,block,planned_note,scope FROM elements WHERE section_id=? AND enabled=1 ORDER BY id", (sid,)):
        h.update("\x1f".join(str(x or "") for x in r).encode("utf-8") + b"\x1e")
    return h.hexdigest()[:16]


def _match_fp(c: sqlite3.Connection, sid: str) -> str:
    """Отпечаток для сопоставления: перечень + загруженные сметы раздела (новая/удалённая смета — сопоставление устарело)."""
    revs = [r[0] for r in c.execute("SELECT sha256 FROM source_files WHERE section_id=? AND kind='estimate' ORDER BY sha256", (sid,))]
    return _list_fp(c, sid) + ":" + hashlib.sha1("|".join(revs).encode()).hexdigest()[:8]


def _wiz_row(c: sqlite3.Connection, sid: str) -> dict[str, Any]:
    r = c.execute("SELECT * FROM list_wizard WHERE section_id=?", (sid,)).fetchone()
    return dict(r) if r else {k: "" for k in ("s1_at", "s1_by", "s2_at", "s2_by", "s2_fp", "s3_at", "s3_by", "s3_fp", "s4_at", "s4_by", "s4_fp", "handed_at", "handed_by")} | {"s1_json": "{}", "s3_json": "{}"}


def _wiz_set(c: sqlite3.Connection, sid: str, **kv: str) -> None:
    c.execute("INSERT OR IGNORE INTO list_wizard (section_id) VALUES (?)", (sid,))
    kv["updated_at"] = now()
    c.execute("UPDATE list_wizard SET " + ",".join(f"{k}=?" for k in kv) + " WHERE section_id=?", (*kv.values(), sid))


def _match_counts(sid: str) -> dict[str, Any]:
    d = alloc_list(sid)
    rows, els = d["rows"], d["elements"]
    full = lambda L: sum(1 for r in L if r["alloc"] and abs(r["free"]) <= 0.001)  # noqa: E731
    W = [r for r in rows if not r["mat"]]
    M = [r for r in rows if r["mat"]]
    used = {x["element_id"] for r in rows for x in r["alloc"]}
    return {"works": len(W), "works_ok": full(W), "mats": len(M), "mats_ok": full(M), "objects": len(els), "objects_ok": sum(1 for e in els if e["id"] in used),
            "works_part": sum(1 for r in W if r["alloc"] and abs(r["free"]) > 0.001), "mats_part": sum(1 for r in M if r["alloc"] and abs(r["free"]) > 0.001),
            "wells": sum(1 for e in els if (e["kind"] or "").startswith("Колодец")), "wells_ok": sum(1 for e in els if (e["kind"] or "").startswith("Колодец") and e["id"] in used),
            "left_works": len(W) - full(W), "left_mats": len(M) - full(M), "left_objects": sum(1 for e in els if e["id"] not in used)}


def _wizard_state(c: sqlite3.Connection, sec: sqlite3.Row) -> dict[str, Any]:
    sid = sec["id"]
    w = _wiz_row(c, sid)
    n_el = c.execute("SELECT COUNT(*) FROM elements WHERE section_id=? AND enabled=1", (sid,)).fetchone()[0]
    sc = {r[0] or "": r[1] for r in c.execute("SELECT scope, COUNT(*) FROM elements WHERE section_id=? AND enabled=1 GROUP BY scope", (sid,))}
    kinds = {r[0]: r[1] for r in c.execute("SELECT kind, COUNT(*) FROM elements WHERE section_id=? AND enabled=1 AND scope='' GROUP BY kind ORDER BY 2 DESC", (sid,))}
    files = {r[0]: r[1] for r in c.execute("SELECT kind, COUNT(*) FROM source_files WHERE section_id=? GROUP BY kind", (sid,))}
    lfp, mfp = _list_fp(c, sid), _match_fp(c, sid)
    s1_done = bool(w["s1_at"]) or n_el > 0
    s1 = {"n": 1, "title": "Сформировать перечень", "status": "done" if s1_done else "work",
          "derived": bool(not w["s1_at"] and n_el > 0), "at": w["s1_at"], "by": w["s1_by"], "found": json.loads(w["s1_json"] or "{}"),
          "counters": {"project_files": sum(v for k, v in files.items() if k in ("dxf_project", "pdf")), "estimate_files": files.get("estimate", 0), "elements": n_el}}
    s2_done = bool(w["s2_at"])
    changed = s2_done and w["s2_fp"] != lfp
    s2 = {"n": 2, "title": "Проверить и подтвердить перечень", "status": "locked" if not s1_done else ("done" if s2_done and not changed else "work"),
          "changed_after_confirm": changed, "at": w["s2_at"], "by": w["s2_by"],
          "counters": {"total": n_el, "ours": sc.get("", 0), "excluded": sc.get("excluded", 0), "other": sc.get("other", 0), "kinds": kinds}}
    s3_done = bool(w["s3_at"])
    s3_stale = s3_done and w["s3_fp"] != mfp
    can3 = s2_done
    s3 = {"n": 3, "title": "Сопоставить со сметой автоматически", "status": "locked" if not can3 else ("stale" if s3_stale else ("done" if s3_done else "work")),
          "at": w["s3_at"], "by": w["s3_by"], "result": json.loads(w["s3_json"] or "{}"), "estimate_files": files.get("estimate", 0)}
    s4_done = bool(w["s4_at"])
    can4 = s3_done and not s3_stale
    s4 = {"n": 4, "title": "Ручное сопоставление", "status": "locked" if not can4 else ("stale" if s4_done and w["s4_fp"] != mfp else ("done" if s4_done else "work")),
          "at": w["s4_at"], "by": w["s4_by"]}
    if s3_done and s3_stale and s4_done:
        s4["status"] = "stale"
    if can3 and (s3_done or can4):
        try:
            mc = _match_counts(sid)
            s3["counters"] = mc
            s4["counters"] = {"left_works": mc["left_works"], "left_objects": mc["left_objects"], "left_mats": mc["left_mats"]}
        except HTTPException:
            pass
    steps = [s1, s2, s3, s4]
    cur_step = next((s["n"] for s in steps if s["status"] in ("work", "stale")), 4)
    return {"section": sec["code"], "steps": steps, "current": cur_step, "handed_to_foreman": bool(w.get("handed_at")), "handed_at": w.get("handed_at", ""),
            "handed_by": w.get("handed_by", ""), "scopes": SCOPES}


@app.get("/api/wizard")
def wizard_get(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        return _wizard_state(c, _section(c, section))


@app.post("/api/wizard/analyze")
def wizard_analyze(request: Request, section: Optional[str] = None) -> dict[str, Any]:
    """Шаг 1: анализ файлов проекта раздела — что найдено (новые объекты по видам, чужие сети, позиции сметы без объекта)."""
    with db() as c:
        sec = _section(c, section)
        s = _suggest_core(c, sec)
        found = {"new_project": len(s["project"]), "new_by_kind": dict(collections.Counter(x["kind"] for x in s["project"])),
                 "reference": len(s.get("reference") or []), "estimate_positions": len(s.get("estimate") or []), "valves": len(s.get("valves") or []),
                 "other_nets": s.get("other_nets") or {}, "pending": s.get("pending", 0), "at": now()}
        _wiz_set(c, sec["id"], s1_json=json.dumps(found, ensure_ascii=False))
        return {"found": found, "state": _wizard_state(c, sec)}


class WizStep(BaseModel):
    step: int = Field(ge=1, le=4)
    action: Literal["done", "reopen"] = "done"


@app.post("/api/wizard/step")
def wizard_step(request: Request, p: WizStep, section: Optional[str] = None) -> dict[str, Any]:
    """Отметить шаг выполненным (1 — перечень сформирован, 2 — подтверждён, 4 — передан прорабу) или вернуть в работу."""
    who = (getattr(request.state, "user", "") or "")[:80]
    with db() as c:
        sec = _section(c, section)
        sid = sec["id"]
        st = _wizard_state(c, sec)
        s = st["steps"][p.step - 1]
        if p.action == "reopen":
            _wiz_set(c, sid, **{f"s{p.step}_at": "", f"s{p.step}_by": ""})
            audit(request, c, "wizard", sid, "reopen", f"Мастер перечня: шаг {p.step} возвращён в работу", section_id=sid)
            return _wizard_state(c, sec)
        if s["status"] == "locked":
            raise HTTPException(409, "Сначала завершите предыдущий шаг")
        if p.step == 1:
            if not st["steps"][0]["counters"]["elements"]:
                raise HTTPException(409, "В перечне нет ни одного объекта: добавьте объекты из проекта или вручную")
            _wiz_set(c, sid, s1_at=now(), s1_by=who)
        elif p.step == 2:
            if not st["steps"][1]["counters"]["ours"]:
                raise HTTPException(409, "В перечне нет объектов нашей работы — подтверждать нечего")
            _wiz_set(c, sid, s2_at=now(), s2_by=who, s2_fp=_list_fp(c, sid))
        elif p.step == 3:
            raise HTTPException(422, "Шаг 3 выполняется кнопкой «Сопоставить со сметой автоматически»")
        else:
            if st["steps"][3]["status"] == "locked":
                raise HTTPException(409, "Сначала выполните автоматическое сопоставление (шаг 3)")
            _wiz_set(c, sid, s4_at=now(), s4_by=who, s4_fp=_match_fp(c, sid), handed_at=now(), handed_by=who)
            _wz2_snapshot(c, sid, 4, "confirm", "Шаг 4 завершён — передано прорабу", who or "ПТО")
        audit(request, c, "wizard", sid, f"step{p.step}", f"Мастер перечня: шаг {p.step} «{s['title']}» выполнен", section_id=sid)
        return _wizard_state(c, sec)


@app.post("/api/wizard/match")
def wizard_match(request: Request, section: Optional[str] = None) -> dict[str, Any]:
    """Шаг 3: автоматическое сопоставление (ручные и подтверждённые строки не трогаются); после — счётчики. Шаг 4 сбрасывается."""
    who = (getattr(request.state, "user", "") or "")[:80]
    with db() as c:
        sec = _section(c, section)
        st = _wizard_state(c, sec)
        if st["steps"][2]["status"] == "locked":
            raise HTTPException(409, "Сначала подтвердите перечень (шаг 2)")
        _wz2_snapshot(c, sec["id"], 3, "before-auto", "Перед автосопоставлением", who or "ПТО")
        res = _alloc_auto_core(c, sec, who, 0)
    mc = _match_counts(sec["id"])
    with db() as c:
        _wiz_set(c, sec["id"], s3_at=now(), s3_by=who, s3_fp=_match_fp(c, sec["id"]), s3_json=json.dumps({**{k: res.get(k) for k in ("done", "needs_pto")}, **mc, "message": res.get("message", "")[:400]}, ensure_ascii=False),
                 s4_at="", s4_by="", s4_fp="")
        _wz2_snapshot(c, sec["id"], 3, "confirm", "Автосопоставление выполнено", who or "ПТО")
        audit(request, c, "wizard", sec["id"], "step3", f"Мастер перечня: автосопоставление — работ {mc['works_ok']}/{mc['works']}, объектов {mc['objects_ok']}/{mc['objects']}", section_id=sec["id"])
        return {"message": res.get("message", ""), "counters": mc, "state": _wizard_state(c, sec)}


@app.get("/api/wizard/list")
def wizard_list(section: Optional[str] = None) -> dict[str, Any]:
    """Шаг 2: все объекты перечня раздела со статусом объёма (включая «не делаем» и «другой подрядчик»)."""
    with db() as c:
        sec = _section(c, section)
        rows = [dict(r) for r in c.execute("""SELECT el.id, el.code, el.name, el.kind, el.block, el.planned_note, el.scope, el.scope_note, el.scope_by, el.scope_at, el.source,
            (SELECT COUNT(*) FROM operations o WHERE o.element_id=el.id) ops,
            (SELECT COUNT(*) FROM events e JOIN operations o ON o.id=e.operation_id WHERE o.element_id=el.id) marks
            FROM elements el WHERE el.section_id=? AND el.enabled=1 ORDER BY el.block, el.code""", (sec["id"],))]
        return {"elements": rows, "scopes": SCOPES}


class ElementEdit(BaseModel):
    code: Optional[str] = Field(default=None, min_length=1, max_length=120)
    name: Optional[str] = Field(default=None, min_length=1, max_length=300)
    kind: Optional[str] = Field(default=None, min_length=1, max_length=80)
    block: Optional[str] = Field(default=None, max_length=120)
    planned_note: Optional[str] = Field(default=None, max_length=2000)
    scope: Optional[Literal["", "excluded", "other"]] = None
    scope_note: Optional[str] = Field(default=None, max_length=300)


@app.put("/api/elements/{element_id}")
def element_edit(request: Request, element_id: str, p: ElementEdit) -> dict[str, Any]:
    """Правка объекта перечня ПТО (шаг 2 мастера): реквизиты и статус объёма. При «не делаем / другой подрядчик» снимаются привязки сметы к объекту."""
    who = (getattr(request.state, "user", "") or "")[:80]
    with db() as c:
        el = c.execute("SELECT * FROM elements WHERE id=?", (element_id,)).fetchone()
        if not el:
            raise HTTPException(404, "Объект не найден")
        upd: dict[str, Any] = {}
        for k in ("code", "name", "kind", "block", "planned_note", "scope_note"):
            v = getattr(p, k)
            if v is not None and v.strip() != (el[k] or ""):
                upd[k] = v.strip()
        if p.scope is not None and p.scope != (el["scope"] or ""):
            upd.update(scope=p.scope, scope_by=who, scope_at=now())
        if "code" in upd and c.execute("SELECT 1 FROM elements WHERE section_id=? AND code=? AND id<>?", (el["section_id"], upd["code"], element_id)).fetchone():
            raise HTTPException(409, "Код объекта в этом разделе уже существует")
        if not upd:
            return {"message": "Без изменений"}
        c.execute("UPDATE elements SET " + ",".join(f"{k}=?" for k in upd) + " WHERE id=?", (*upd.values(), element_id))
        wz = {k: upd[k] for k in ("name", "kind", "scope") if k in upd} | ({"key": upd["code"]} if "code" in upd else {}) | ({"note": upd["planned_note"]} if "planned_note" in upd else {})
        if wz:   # мастер 2.0: правка через прежнюю форму отражается в рабочем перечне
            c.execute("UPDATE wz_items SET " + ",".join(f"{k}=?" for k in wz) + " WHERE element_id=? AND layer='object'", (*wz.values(), element_id))
        unl = 0
        if upd.get("scope") in ("excluded", "other"):
            unl = c.execute("DELETE FROM work_alloc WHERE element_id=?", (element_id,)).rowcount
        audit(request, c, "element", element_id, "edit", f"Перечень: {el['code']} — " + ", ".join(f"{k}: {upd[k]}" for k in upd if k not in ("scope_by", "scope_at"))[:250],
              {k: [el[k] if k in el.keys() else "", v] for k, v in upd.items()}, section_id=el["section_id"])
        return {"message": "Сохранено" + (f"; снято привязок сметы: {unl}" if unl else ""), "unlinked": unl}


# ================================================================ v.90: мастер 2.0 — каркас (Ф0): рабочий перечень, снимки, откат
_WZ2_DDL = """
CREATE TABLE IF NOT EXISTS wz_items (
  id TEXT PRIMARY KEY, section_id TEXT NOT NULL, layer TEXT NOT NULL, key TEXT NOT NULL, parent_id TEXT NOT NULL DEFAULT '',
  name TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL DEFAULT '', qty REAL, note TEXT NOT NULL DEFAULT '',
  data_json TEXT NOT NULL DEFAULT '{}', source_file_id TEXT NOT NULL DEFAULT '', locator TEXT NOT NULL DEFAULT '',
  origin TEXT NOT NULL DEFAULT 'manual', state TEXT NOT NULL DEFAULT 'accepted', scope TEXT NOT NULL DEFAULT '',
  element_id TEXT NOT NULL DEFAULT '', operation_id TEXT NOT NULL DEFAULT '', sort INTEGER NOT NULL DEFAULT 0, run_id TEXT NOT NULL DEFAULT '',
  updated_by TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS ix_wz_items_sec ON wz_items (section_id, layer);
CREATE UNIQUE INDEX IF NOT EXISTS ux_wz_items_key ON wz_items (section_id, layer, key);
CREATE TABLE IF NOT EXISTS wz_history (
  id TEXT PRIMARY KEY, section_id TEXT NOT NULL, item_id TEXT NOT NULL, item_kind TEXT NOT NULL DEFAULT 'item', action TEXT NOT NULL,
  before_json TEXT NOT NULL DEFAULT '', after_json TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', by TEXT NOT NULL DEFAULT '', at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_wz_hist ON wz_history (section_id, item_id, at);
CREATE TABLE IF NOT EXISTS wz_snapshots (
  id TEXT PRIMARY KEY, section_id TEXT NOT NULL, step INTEGER NOT NULL, kind TEXT NOT NULL DEFAULT 'confirm', reason TEXT NOT NULL DEFAULT '',
  stats_json TEXT NOT NULL DEFAULT '{}', data BLOB, by TEXT NOT NULL DEFAULT '', at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_wz_snap ON wz_snapshots (section_id, step, at);
CREATE TABLE IF NOT EXISTS wz_groups (
  id TEXT PRIMARY KEY, section_id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'group', parent_id TEXT NOT NULL DEFAULT '',
  sort INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', origin TEXT NOT NULL DEFAULT 'manual', updated_by TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS wz_group_members (group_id TEXT NOT NULL, item_id TEXT NOT NULL, sort INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (group_id, item_id));
CREATE TABLE IF NOT EXISTS wz_state (
  section_id TEXT NOT NULL, step TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'todo', fp TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '',
  confirmed_at TEXT NOT NULL DEFAULT '', confirmed_by TEXT NOT NULL DEFAULT '', snapshot_id TEXT NOT NULL DEFAULT '', PRIMARY KEY (section_id, step)
);
"""
WZ2_STEPS = [("1", "Перечень работ по проекту"), ("2", "Укрупнённый состав"), ("3", "Сопоставление со сметой"), ("4", "Ручное сопоставление")]
WZ2_SUB = [("1.0", "Источники", "Ф0"), ("1.1", "Нормативы", "Ф2"), ("1.2", "Виды работ и объёмы", "Ф0"), ("1.3", "Материалы", "Ф2"), ("1.4", "Замечания и сверка", "Ф2")]
_WZ_ITEM_COLS = ("id", "section_id", "layer", "key", "parent_id", "name", "kind", "unit", "qty", "note", "data_json", "source_file_id", "locator", "origin", "state", "scope",
                 "element_id", "operation_id", "sort", "run_id", "updated_by", "updated_at")
_WZ_GROUP_COLS = ("id", "section_id", "name", "kind", "parent_id", "sort", "note", "origin", "updated_by", "updated_at")
_WZ_EDITABLE = ("name", "kind", "unit", "qty", "note", "state", "scope", "key")


def _init_wz2(c: sqlite3.Connection) -> None:
    c.executescript(_WZ2_DDL)
    for sid in [r[0] for r in c.execute("SELECT DISTINCT section_id FROM elements WHERE section_id IS NOT NULL")]:
        _wz2_migrate(c, sid)


def _wz2_migrate(c: sqlite3.Connection, sid: str, who: str = "миграция v.90") -> bool:
    """Идемпотентно: перенос опубликованного перечня (elements/operations/block) в рабочий перечень мастера 2.0 + снимок «Миграция»."""
    if c.execute("SELECT 1 FROM wz_state WHERE section_id=? AND step='migrated'", (sid,)).fetchone():
        return False
    t = now()
    els = c.execute("SELECT * FROM elements WHERE section_id=? AND enabled=1 ORDER BY block, created_at, code", (sid,)).fetchall()
    gid_by_block: dict[str, str] = {}
    for i, e in enumerate(els):
        oid = str(uuid.uuid4())
        c.execute("INSERT INTO wz_items (id,section_id,layer,key,name,kind,note,origin,state,scope,element_id,sort,updated_by,updated_at,data_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                  (oid, sid, "object", e["code"], e["name"], e["kind"], e["planned_note"] or "", "legacy", "accepted", e["scope"] or "", e["id"], i, who, t,
                   json.dumps({"weight": e["weight"], "source": e["source"]}, ensure_ascii=False)))
        for o in c.execute("SELECT * FROM operations WHERE element_id=? ORDER BY sort_order", (e["id"],)).fetchall():
            c.execute("INSERT INTO wz_items (id,section_id,layer,key,parent_id,name,kind,origin,state,element_id,operation_id,sort,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                      (str(uuid.uuid4()), sid, "work", e["code"] + "/" + o["code"], oid, o["title"], o["code"], "legacy", "accepted", e["id"], o["id"], o["sort_order"], who, t))
        b = (e["block"] or "").strip()
        if b:
            if b not in gid_by_block:
                gid_by_block[b] = str(uuid.uuid4())
                c.execute("INSERT INTO wz_groups (id,section_id,name,kind,sort,origin,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?)", (gid_by_block[b], sid, b, "group", len(gid_by_block), "legacy", who, t))
            c.execute("INSERT OR IGNORE INTO wz_group_members (group_id,item_id,sort) VALUES (?,?,?)", (gid_by_block[b], oid, i))
    lw = c.execute("SELECT * FROM list_wizard WHERE section_id=?", (sid,)).fetchone()
    s1 = "done" if els else "todo"
    for st, status, note in (("1", s1, "перенесено из прежнего перечня" if els else ""), ("1.0", s1, ""), ("1.1", "todo", ""), ("1.2", s1, ""), ("1.3", "todo", ""), ("1.4", "todo", ""),
                             ("2", "done" if gid_by_block else "todo", "участки перенесены из прежнего перечня" if gid_by_block else "")):
        c.execute("INSERT OR REPLACE INTO wz_state (section_id,step,status,note,confirmed_at,confirmed_by) VALUES (?,?,?,?,?,?)", (sid, st, status, note, t if status == "done" else "", who if status == "done" else ""))
    snap1 = _wz2_snapshot(c, sid, 1, "migration", "Миграция в мастер 2.0", who)
    snap2 = _wz2_snapshot(c, sid, 2, "migration", "Миграция в мастер 2.0", who)
    c.execute("UPDATE wz_state SET fp=?, snapshot_id=? WHERE section_id=? AND step='1'", (_wz2_fp(c, sid, 1), snap1, sid))
    c.execute("UPDATE wz_state SET fp=?, snapshot_id=? WHERE section_id=? AND step='2'", (_wz2_fp(c, sid, 2), snap2, sid))
    if els and not (lw and lw["s2_at"]):   # прежний перечень считается подтверждённым — автосопоставление доступно сразу
        _wiz_set(c, sid, s1_at=t, s1_by=who, s2_at=t, s2_by=who, s2_fp=_list_fp(c, sid))
    c.execute("INSERT OR REPLACE INTO wz_state (section_id,step,status,note,confirmed_at,confirmed_by) VALUES (?,?,?,?,?,?)",
              (sid, "migrated", "done", json.dumps({"objects": len(els), "groups": len(gid_by_block), "had_wizard": bool(lw)}, ensure_ascii=False), t, who))
    return True


def _wz2_adopt(c: sqlite3.Connection, sid: str, who: str = "прежний перечень") -> int:
    """Объекты и работы, добавленные в перечень прежними способами (вручную, из проекта, наборы), — в рабочий перечень, чтобы публикация их не выключила."""
    n = 0
    known_el = {r[0]: r[1] for r in c.execute("SELECT element_id, id FROM wz_items WHERE section_id=? AND layer='object' AND element_id<>''", (sid,))}
    known_op = {r[0] for r in c.execute("SELECT operation_id FROM wz_items WHERE section_id=? AND layer='work' AND operation_id<>''", (sid,))}
    for e in c.execute("SELECT * FROM elements WHERE section_id=? AND enabled=1", (sid,)).fetchall():
        oid = known_el.get(e["id"])
        if not oid:
            ex = c.execute("SELECT id FROM wz_items WHERE section_id=? AND layer='object' AND key=?", (sid, e["code"])).fetchone()
            if ex:
                oid = ex[0]
                c.execute("UPDATE wz_items SET element_id=? WHERE id=?", (e["id"], oid))
            else:
                oid = str(uuid.uuid4())
                c.execute("INSERT INTO wz_items (id,section_id,layer,key,name,kind,note,origin,state,scope,element_id,sort,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                          (oid, sid, "object", e["code"], e["name"], e["kind"], e["planned_note"] or "", "legacy", "accepted", e["scope"] or "", e["id"], 9000, who, now()))
                _wz2_hist(c, sid, oid, "adopt", None, {"key": e["code"], "name": e["name"]}, who)
                n += 1
        for o in c.execute("SELECT * FROM operations WHERE element_id=?", (e["id"],)).fetchall():
            if o["id"] in known_op:
                continue
            key = e["code"] + "/" + o["code"]
            ex = c.execute("SELECT id FROM wz_items WHERE section_id=? AND layer='work' AND key=?", (sid, key)).fetchone()
            if ex:
                c.execute("UPDATE wz_items SET operation_id=?, element_id=?, parent_id=? WHERE id=?", (o["id"], e["id"], oid, ex[0]))
            else:
                c.execute("INSERT INTO wz_items (id,section_id,layer,key,parent_id,name,kind,origin,state,element_id,operation_id,sort,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                          (str(uuid.uuid4()), sid, "work", key, oid, o["title"], o["code"], "legacy", "accepted", e["id"], o["id"], o["sort_order"], who, now()))
                n += 1
    return n


def _wz2_rows(c: sqlite3.Connection, sid: str, step: int) -> dict[str, Any]:
    if step in (3, 4):   # шаги 3–4: привязки сметы к объектам перечня
        return {"alloc": [dict(r) for r in c.execute("SELECT * FROM work_alloc WHERE section_id=? ORDER BY item_key, element_id", (sid,))]}
    if step == 1:
        return {"items": [dict(r) for r in c.execute("SELECT * FROM wz_items WHERE section_id=? ORDER BY layer, sort, key", (sid,))]}
    return {"groups": [dict(r) for r in c.execute("SELECT * FROM wz_groups WHERE section_id=? ORDER BY sort, name", (sid,))],
            "members": [dict(r) for r in c.execute("SELECT m.* FROM wz_group_members m JOIN wz_groups g ON g.id=m.group_id WHERE g.section_id=? ORDER BY m.group_id, m.sort", (sid,))]}


def _wz2_fp(c: sqlite3.Connection, sid: str, step: int) -> str:
    d = _wz2_rows(c, sid, step)
    if step == 1:
        payload = [(r["id"], r["key"], r["parent_id"], r["name"], r["kind"], r["unit"], r["qty"], r["note"], r["state"], r["scope"]) for r in d["items"] if r["layer"] in ("object", "work")]
    else:
        payload = [(g["id"], g["name"], g["kind"], g["parent_id"], g["sort"]) for g in d["groups"]] + [(m["group_id"], m["item_id"]) for m in d["members"]]
    return hashlib.sha1(json.dumps(payload, ensure_ascii=False, sort_keys=True, default=str).encode()).hexdigest()[:16]


def _wz2_stats(c: sqlite3.Connection, sid: str, step: int) -> dict[str, Any]:
    if step == 1:
        r = {f"{a}_{b}": n for a, b, n in c.execute("SELECT layer, state, COUNT(*) FROM wz_items WHERE section_id=? GROUP BY 1,2", (sid,))}
        r["objects"] = sum(v for k, v in r.items() if k.startswith("object_") and not k.endswith("rejected"))
        r["works"] = sum(v for k, v in r.items() if k.startswith("work_") and not k.endswith("rejected"))
        r["norms"] = sum(v for k, v in r.items() if k.startswith("norm_") and not k.endswith("rejected"))
        r["materials"] = sum(v for k, v in r.items() if k.startswith("material_") and not k.endswith("rejected"))
        r["remarks_open"] = c.execute("SELECT COUNT(*) FROM wz_remarks WHERE section_id=? AND status IN ('open','clarify')", (sid,)).fetchone()[0] if c.execute("SELECT 1 FROM sqlite_master WHERE name='wz_remarks'").fetchone() else 0
        return r
    if step in (3, 4):
        return {"alloc": c.execute("SELECT COUNT(*) FROM work_alloc WHERE section_id=?", (sid,)).fetchone()[0],
                "manual": c.execute("SELECT COUNT(*) FROM work_alloc WHERE section_id=? AND mode<>'auto'", (sid,)).fetchone()[0]}
    return {"groups": c.execute("SELECT COUNT(*) FROM wz_groups WHERE section_id=?", (sid,)).fetchone()[0],
            "members": c.execute("SELECT COUNT(*) FROM wz_group_members m JOIN wz_groups g ON g.id=m.group_id WHERE g.section_id=?", (sid,)).fetchone()[0]}


def _wz2_snapshot(c: sqlite3.Connection, sid: str, step: int, kind: str, reason: str, who: str) -> str:
    snap = str(uuid.uuid4())
    data = gzip.compress(json.dumps(_wz2_rows(c, sid, step), ensure_ascii=False, default=str).encode("utf-8"))
    c.execute("INSERT INTO wz_snapshots (id,section_id,step,kind,reason,stats_json,data,by,at) VALUES (?,?,?,?,?,?,?,?,?)",
              (snap, sid, step, kind, reason[:300], json.dumps(_wz2_stats(c, sid, step), ensure_ascii=False), data, who, now()))
    return snap


def _wz2_load_snap(c: sqlite3.Connection, sid: str, snap_id: str) -> tuple[sqlite3.Row, dict[str, Any]]:
    r = c.execute("SELECT * FROM wz_snapshots WHERE id=? AND section_id=?", (snap_id, sid)).fetchone()
    if not r:
        raise HTTPException(404, "Снимок не найден")
    return r, json.loads(gzip.decompress(r["data"]).decode("utf-8"))


def _wz2_hist(c: sqlite3.Connection, sid: str, iid: str, action: str, before: Any, after: Any, who: str, reason: str = "", kind: str = "item") -> None:
    c.execute("INSERT INTO wz_history (id,section_id,item_id,item_kind,action,before_json,after_json,reason,by,at) VALUES (?,?,?,?,?,?,?,?,?,?)",
              (str(uuid.uuid4()), sid, iid, kind, action, json.dumps(before, ensure_ascii=False, default=str) if before is not None else "",
               json.dumps(after, ensure_ascii=False, default=str) if after is not None else "", reason[:300], who, now()))


def _wz2_put_item(c: sqlite3.Connection, row: dict[str, Any]) -> None:
    c.execute("INSERT OR REPLACE INTO wz_items (" + ",".join(_WZ_ITEM_COLS) + ") VALUES (" + ",".join("?" * len(_WZ_ITEM_COLS)) + ")", tuple(row.get(k) for k in _WZ_ITEM_COLS))


def _wz2_marks_for(c: sqlite3.Connection, element_ids: set[str], operation_ids: set[str]) -> dict[str, int]:
    """Сколько отметок прораба и актов затронет изменение (объекты и операции опубликованного перечня)."""
    ops = set(operation_ids)
    for eid in element_ids:
        ops |= {r[0] for r in c.execute("SELECT id FROM operations WHERE element_id=?", (eid,))}
    if not ops:
        return {"marks": 0, "acts": 0, "operations": 0}
    q = ",".join("?" * len(ops))
    return {"marks": c.execute(f"SELECT COUNT(*) FROM events WHERE operation_id IN ({q})", tuple(ops)).fetchone()[0],
            "acts": c.execute(f"SELECT COUNT(DISTINCT doc_id) FROM act_ops WHERE operation_id IN ({q})", tuple(ops)).fetchone()[0], "operations": len(ops)}


def _wz2_plan(c: sqlite3.Connection, sid: str, target: list[dict[str, Any]], ids: Optional[set[str]]) -> dict[str, Any]:
    """Разница «текущий рабочий перечень → целевой» (по всем пунктам или только по ids) и затронутые отметки прораба."""
    cur = {r["id"]: dict(r) for r in c.execute("SELECT * FROM wz_items WHERE section_id=?", (sid,))}
    tgt = {r["id"]: r for r in target}
    scope_ids = set(cur) | set(tgt) if ids is None else ids
    add = [i for i in scope_ids if i in tgt and i not in cur]
    rem = [i for i in scope_ids if i in cur and i not in tgt]
    chg = [i for i in scope_ids if i in cur and i in tgt and any(str(cur[i].get(k)) != str(tgt[i].get(k)) for k in _WZ_EDITABLE + ("parent_id",))]
    # отметки затрагиваются, если объект/работа уходит из перечня или выключается
    gone = [cur[i] for i in rem] + [tgt[i] for i in chg if tgt[i]["state"] in ("rejected",) or tgt[i]["scope"] in ("excluded", "other")]
    marks = _wz2_marks_for(c, {g["element_id"] for g in gone if g["layer"] == "object" and g["element_id"]}, {g["operation_id"] for g in gone if g["layer"] == "work" and g["operation_id"]})
    return {"add": add, "remove": rem, "change": chg, "counts": {"add": len(add), "remove": len(rem), "change": len(chg)}, **marks}


def _wz2_apply(c: sqlite3.Connection, sid: str, target: list[dict[str, Any]], plan: dict[str, Any], who: str, reason: str) -> None:
    tgt = {r["id"]: r for r in target}
    for i in plan["remove"]:
        b = dict(c.execute("SELECT * FROM wz_items WHERE id=?", (i,)).fetchone())
        c.execute("DELETE FROM wz_items WHERE id=?", (i,))
        c.execute("DELETE FROM wz_group_members WHERE item_id=?", (i,))
        _wz2_hist(c, sid, i, "rollback-remove", b, None, who, reason)
    for i in plan["add"] + plan["change"]:
        b = c.execute("SELECT * FROM wz_items WHERE id=?", (i,)).fetchone()
        c.execute("DELETE FROM wz_items WHERE section_id=? AND layer=? AND key=? AND id<>?", (sid, tgt[i]["layer"], tgt[i]["key"], i))  # ключ занят новым пунктом — уступает
        _wz2_put_item(c, {**tgt[i], "updated_by": who, "updated_at": now()})
        _wz2_hist(c, sid, i, "rollback-restore", dict(b) if b else None, tgt[i], who, reason)


def _wz2_mark_downstream(c: sqlite3.Connection, sid: str, from_step: int, why: str) -> None:
    for st in range(from_step, 3):
        r = c.execute("SELECT status FROM wz_state WHERE section_id=? AND step=?", (sid, str(st))).fetchone()
        if r and r[0] == "done":
            c.execute("UPDATE wz_state SET status=?, note=? WHERE section_id=? AND step=?", ("work" if st == from_step else "stale", why[:200], sid, str(st)))
        elif not r:
            c.execute("INSERT INTO wz_state (section_id,step,status,note) VALUES (?,?,?,?)", (sid, str(st), "work", why[:200]))


def _wz2_publish(c: sqlite3.Connection, sec: Any, who: str) -> dict[str, Any]:
    """Рабочий перечень → опубликованный (elements/operations), который видят прораб и сопоставление. Ничего не удаляется с отметками:
    объект, ушедший из перечня, выключается (enabled=0, история отметок остаётся); работа без отметок удаляется, с отметками — остаётся."""
    sid = sec["id"]
    _wz2_adopt(c, sid)
    items = [dict(r) for r in c.execute("SELECT * FROM wz_items WHERE section_id=? ORDER BY layer DESC, sort", (sid,))]
    objs = [i for i in items if i["layer"] == "object" and i["state"] != "rejected"]
    grp = {r[0]: r[1] for r in c.execute("SELECT m.item_id, g.name FROM wz_group_members m JOIN wz_groups g ON g.id=m.group_id WHERE g.section_id=? ORDER BY g.sort", (sid,))}
    res = collections.Counter()
    keep_el: set[str] = set()
    for o in objs:
        blk = grp.get(o["id"], "")
        eid = o["element_id"]
        row = c.execute("SELECT * FROM elements WHERE id=?", (eid,)).fetchone() if eid else None
        if not row:
            row = c.execute("SELECT * FROM elements WHERE section_id=? AND code=?", (sid, o["key"])).fetchone()
        if row:
            eid = row["id"]
            new = {"code": o["key"], "name": o["name"], "kind": o["kind"], "planned_note": o["note"], "scope": o["scope"], "enabled": 1}
            if blk:
                new["block"] = blk
            diff = {k: v for k, v in new.items() if str(row[k] or "") != str(v or "")}
            if diff:
                c.execute("UPDATE elements SET " + ",".join(f"{k}=?" for k in diff) + " WHERE id=?", (*diff.values(), eid))
                res["el_changed"] += 1
        else:
            eid = str(uuid.uuid4())
            c.execute("INSERT INTO elements (id,section_id,code,name,kind,block,planned_note,enabled,created_at,source,scope) VALUES (?,?,?,?,?,?,?,1,?,?,?)",
                      (eid, sid, o["key"], o["name"], o["kind"] or "Элемент", blk or "Часть 1", o["note"], now(), "manual", o["scope"]))
            res["el_added"] += 1
        if eid != o["element_id"]:
            c.execute("UPDATE wz_items SET element_id=? WHERE id=?", (eid, o["id"]))
        keep_el.add(eid)
        works = [w for w in items if w["layer"] == "work" and w["parent_id"] == o["id"] and w["state"] != "rejected"]
        keep_op: set[str] = set()
        for n, w in enumerate(works, 1):
            code = w["kind"] or w["key"].split("/")[-1]
            op = c.execute("SELECT * FROM operations WHERE id=?", (w["operation_id"],)).fetchone() if w["operation_id"] else None
            if not op:
                op = c.execute("SELECT * FROM operations WHERE element_id=? AND code=?", (eid, code)).fetchone()
            if op:
                if op["title"] != w["name"] or op["sort_order"] != (w["sort"] or n):
                    c.execute("UPDATE operations SET title=?, sort_order=? WHERE id=?", (w["name"], w["sort"] or n, op["id"]))
                    res["op_changed"] += 1
                opid = op["id"]
            else:
                opid = str(uuid.uuid4())
                c.execute("INSERT INTO operations (id,element_id,code,title,sort_order) VALUES (?,?,?,?,?)", (opid, eid, code, w["name"], w["sort"] or n))
                res["op_added"] += 1
            if opid != w["operation_id"] or eid != w["element_id"]:
                c.execute("UPDATE wz_items SET operation_id=?, element_id=? WHERE id=?", (opid, eid, w["id"]))
            keep_op.add(opid)
        for op in c.execute("SELECT id FROM operations WHERE element_id=?", (eid,)).fetchall():
            if op["id"] not in keep_op:
                if c.execute("SELECT 1 FROM events WHERE operation_id=? UNION SELECT 1 FROM act_ops WHERE operation_id=?", (op["id"], op["id"])).fetchone():
                    res["op_kept_marked"] += 1
                else:
                    c.execute("DELETE FROM operations WHERE id=?", (op["id"],))
                    res["op_removed"] += 1
    for e in c.execute("SELECT id FROM elements WHERE section_id=? AND enabled=1", (sid,)).fetchall():
        if e["id"] not in keep_el:
            c.execute("UPDATE elements SET enabled=0 WHERE id=?", (e["id"],))
            c.execute("DELETE FROM work_alloc WHERE element_id=?", (e["id"],))
            res["el_disabled"] += 1
    return dict(res)


def _wz2_state(c: sqlite3.Connection, sec: Any) -> dict[str, Any]:
    sid = sec["id"]
    _wz2_migrate(c, sid)
    if _wz2_adopt(c, sid):
        c.execute("UPDATE wz_state SET status='work', note='в перечень добавлены объекты вне мастера' WHERE section_id=? AND step='1' AND status='done'", (sid,))
    st = {r["step"]: dict(r) for r in c.execute("SELECT * FROM wz_state WHERE section_id=?", (sid,))}
    def g(k: str) -> dict[str, Any]:
        return st.get(k) or {"status": "todo", "note": "", "confirmed_at": "", "confirmed_by": "", "fp": ""}
    s1, s2 = g("1"), g("2")
    if s1["status"] == "done" and s1["fp"] != _wz2_fp(c, sid, 1):
        s1 = {**s1, "status": "work", "note": "изменён после подтверждения"}
    if s2["status"] == "done" and (s2["fp"] != _wz2_fp(c, sid, 2)):
        s2 = {**s2, "status": "work", "note": "изменён после подтверждения"}
    if s1["status"] != "done" and s2["status"] == "done":
        s2 = {**s2, "status": "stale", "note": "шаг 1 изменён — проверьте состав"}
    old = _wizard_state(c, sec)
    o3, o4 = old["steps"][2], old["steps"][3]
    up_ok = s1["status"] == "done" and s2["status"] == "done"
    def lk(stt: str) -> str:
        return stt if up_ok else ("stale" if stt in ("done", "stale") else "locked")
    steps = [
        {"n": 1, "title": WZ2_STEPS[0][1], "status": s1["status"] if s1["status"] != "todo" else "work", "note": s1["note"], "at": s1["confirmed_at"], "by": s1["confirmed_by"],
         "stats": _wz2_stats(c, sid, 1), "sub": [{"id": k, "title": t, "phase": ph, **{x: g(k)[x] for x in ("status", "note")}} for k, t, ph in WZ2_SUB]},
        {"n": 2, "title": WZ2_STEPS[1][1], "status": "locked" if s1["status"] != "done" and s2["status"] == "todo" else (s2["status"] if s2["status"] != "todo" else "work"),
         "note": s2["note"], "at": s2["confirmed_at"], "by": s2["confirmed_by"], "stats": _wz2_stats(c, sid, 2)},
        {"n": 3, "title": WZ2_STEPS[2][1], "status": lk(o3["status"]), "counters": o3.get("counters"), "at": o3.get("at"), "result": o3.get("result")},
        {"n": 4, "title": WZ2_STEPS[3][1], "status": lk(o4["status"]), "counters": o4.get("counters"), "at": o4.get("at")},
    ]
    snaps = [dict(r) for r in c.execute("SELECT id,step,kind,reason,stats_json,by,at FROM wz_snapshots WHERE section_id=? ORDER BY at DESC LIMIT 60", (sid,))]
    cur = next((s["n"] for s in steps if s["status"] in ("work", "stale")), 4)
    return {"section": sec["code"], "steps": steps, "current": cur, "snapshots": snaps, "handed_to_foreman": old["handed_to_foreman"], "scopes": SCOPES}


def _who(request: Request) -> str:
    return (getattr(request.state, "user", "") or "")[:80] or "ПТО"


@app.get("/api/wz2")
def wz2_get(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        return _wz2_state(c, _section(c, section))


@app.get("/api/wz2/items")
def wz2_items(section: Optional[str] = None, layer: str = "", q: str = "", state: str = "", group: str = "") -> dict[str, Any]:
    with db() as c:
        sid = _section(c, section)["id"]
        _wz2_migrate(c, sid)
        _wz2_adopt(c, sid)
        rows = [dict(r) for r in c.execute("SELECT * FROM wz_items WHERE section_id=? ORDER BY sort, key", (sid,))]
        mem = {r[0]: r[1] for r in c.execute("SELECT m.item_id, g.id FROM wz_group_members m JOIN wz_groups g ON g.id=m.group_id WHERE g.section_id=?", (sid,))}
        objs = {r["id"]: r for r in rows if r["layer"] == "object"}
        marks = {r[0]: r[1] for r in c.execute("SELECT o.id, COUNT(e.id) FROM operations o JOIN elements el ON el.id=o.element_id JOIN events e ON e.operation_id=o.id WHERE el.section_id=? GROUP BY o.id", (sid,))}
        for r in rows:
            r["group_id"] = mem.get(r["id"]) or mem.get(r["parent_id"], "")
            r["marks"] = marks.get(r["operation_id"], 0) if r["layer"] == "work" else sum(marks.get(w["operation_id"], 0) for w in rows if w["parent_id"] == r["id"])
            r["parent_key"] = objs[r["parent_id"]]["key"] if r["parent_id"] in objs else ""
        ql = q.lower()
        out = [r for r in rows if (not layer or r["layer"] == layer) and (not state or r["state"] == state or (state == "excluded" and r["scope"]))
               and (not group or r["group_id"] == group) and (not ql or ql in (r["key"] + " " + r["name"] + " " + r["parent_key"]).lower())]
        return {"items": out, "total": len(rows)}


class Wz2ItemIn(BaseModel):
    layer: Literal["object", "work", "material", "norm", "source"] = "work"
    key: Optional[str] = Field(default=None, max_length=160)
    parent_id: Optional[str] = Field(default=None, max_length=64)
    name: Optional[str] = Field(default=None, max_length=300)
    kind: Optional[str] = Field(default=None, max_length=80)
    unit: Optional[str] = Field(default=None, max_length=20)
    qty: Optional[float] = None
    note: Optional[str] = Field(default=None, max_length=2000)
    state: Optional[Literal["proposed", "accepted", "edited", "rejected"]] = None
    scope: Optional[Literal["", "excluded", "other"]] = None


@app.post("/api/wz2/items", status_code=201)
def wz2_item_add(request: Request, p: Wz2ItemIn, section: Optional[str] = None) -> dict[str, Any]:
    who = _who(request)
    with db() as c:
        sid = _section(c, section)["id"]
        if not (p.key or "").strip() or not (p.name or "").strip():
            raise HTTPException(422, "Укажите шифр и наименование")
        key = p.key.strip()
        if p.layer == "work" and p.parent_id:
            par = c.execute("SELECT key FROM wz_items WHERE id=? AND section_id=?", (p.parent_id, sid)).fetchone()
            if not par:
                raise HTTPException(404, "Объект не найден")
            key = par[0] + "/" + key if "/" not in key else key
        if c.execute("SELECT 1 FROM wz_items WHERE section_id=? AND layer=? AND key=?", (sid, p.layer, key)).fetchone():
            raise HTTPException(409, "Пункт с таким шифром уже есть")
        row = {k: "" for k in _WZ_ITEM_COLS} | {"id": str(uuid.uuid4()), "section_id": sid, "layer": p.layer, "key": key, "parent_id": p.parent_id or "", "name": p.name.strip(),
               "kind": p.kind or "", "unit": p.unit or "", "qty": p.qty, "note": p.note or "", "data_json": "{}", "origin": "manual", "state": "accepted", "scope": p.scope or "",
               "sort": 999, "updated_by": who, "updated_at": now()}
        _wz2_put_item(c, row)
        _wz2_hist(c, sid, row["id"], "add", None, row, who)
        return {"id": row["id"], "message": "Пункт добавлен"}


@app.put("/api/wz2/items/{item_id}")
def wz2_item_edit(request: Request, item_id: str, p: Wz2ItemIn) -> dict[str, Any]:
    who = _who(request)
    with db() as c:
        r = c.execute("SELECT * FROM wz_items WHERE id=?", (item_id,)).fetchone()
        if not r:
            raise HTTPException(404, "Пункт не найден")
        b = dict(r)
        upd = {k: getattr(p, k) for k in _WZ_EDITABLE if getattr(p, k, None) is not None and getattr(p, k) != b[k]}
        if not upd:
            return {"message": "Без изменений"}
        if "state" not in upd and b["state"] in ("proposed", "accepted") and b["origin"] != "manual":
            upd["state"] = "edited"
        upd |= {"updated_by": who, "updated_at": now()}
        c.execute("UPDATE wz_items SET " + ",".join(f"{k}=?" for k in upd) + " WHERE id=?", (*upd.values(), item_id))
        _wz2_hist(c, b["section_id"], item_id, "edit", b, {**b, **upd}, who)
        return {"message": "Сохранено"}


class Wz2Bulk(BaseModel):
    ids: list[str] = Field(min_length=1, max_length=5000)
    state: Optional[Literal["proposed", "accepted", "edited", "rejected"]] = None
    scope: Optional[Literal["", "excluded", "other"]] = None
    group_id: Optional[str] = None


@app.post("/api/wz2/items/bulk")
def wz2_bulk(request: Request, p: Wz2Bulk, section: Optional[str] = None) -> dict[str, Any]:
    """Массовые действия: принять / отклонить / статус объёма / перенести в группу."""
    who = _who(request)
    n = 0
    with db() as c:
        sid = _section(c, section)["id"]
        if p.group_id is not None and p.group_id and not c.execute("SELECT 1 FROM wz_groups WHERE id=? AND section_id=?", (p.group_id, sid)).fetchone():
            raise HTTPException(404, "Группа не найдена")
        for iid in p.ids:
            r = c.execute("SELECT * FROM wz_items WHERE id=? AND section_id=?", (iid, sid)).fetchone()
            if not r:
                continue
            b = dict(r)
            upd = {k: v for k, v in (("state", p.state), ("scope", p.scope)) if v is not None and v != b[k]}
            if upd:
                c.execute("UPDATE wz_items SET " + ",".join(f"{k}=?" for k in upd) + ", updated_by=?, updated_at=? WHERE id=?", (*upd.values(), who, now(), iid))
                _wz2_hist(c, sid, iid, "bulk", b, {**b, **upd}, who)
                n += 1
            if p.group_id is not None:
                old = c.execute("SELECT group_id FROM wz_group_members WHERE item_id=?", (iid,)).fetchone()
                c.execute("DELETE FROM wz_group_members WHERE item_id=?", (iid,))
                if p.group_id:
                    c.execute("INSERT OR IGNORE INTO wz_group_members (group_id,item_id,sort) VALUES (?,?,?)", (p.group_id, iid, b["sort"]))
                _wz2_hist(c, sid, iid, "group", {"group_id": old[0] if old else ""}, {"group_id": p.group_id}, who, kind="member")
                n += 1
        return {"changed": n, "message": f"Изменено: {n}"}


class Wz2GroupIn(BaseModel):
    name: str = Field(min_length=1, max_length=160)
    kind: str = Field(default="group", max_length=40)
    parent_id: str = Field(default="", max_length=64)
    note: str = Field(default="", max_length=500)


@app.post("/api/wz2/groups", status_code=201)
def wz2_group_add(request: Request, p: Wz2GroupIn, section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sid = _section(c, section)["id"]
        gid = str(uuid.uuid4())
        n = c.execute("SELECT COALESCE(MAX(sort),0)+1 FROM wz_groups WHERE section_id=?", (sid,)).fetchone()[0]
        c.execute("INSERT INTO wz_groups (id,section_id,name,kind,parent_id,sort,note,origin,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
                  (gid, sid, p.name.strip(), p.kind, p.parent_id, n, p.note, "manual", _who(request), now()))
        _wz2_hist(c, sid, gid, "add", None, p.model_dump(), _who(request), kind="group")
        return {"id": gid, "message": "Группа создана"}


@app.put("/api/wz2/groups/{gid}")
def wz2_group_edit(request: Request, gid: str, p: Wz2GroupIn) -> dict[str, Any]:
    with db() as c:
        g = c.execute("SELECT * FROM wz_groups WHERE id=?", (gid,)).fetchone()
        if not g:
            raise HTTPException(404, "Группа не найдена")
        c.execute("UPDATE wz_groups SET name=?, kind=?, parent_id=?, note=?, updated_by=?, updated_at=? WHERE id=?", (p.name.strip(), p.kind, p.parent_id, p.note, _who(request), now(), gid))
        _wz2_hist(c, g["section_id"], gid, "edit", dict(g), p.model_dump(), _who(request), kind="group")
        return {"message": "Сохранено"}


@app.delete("/api/wz2/groups/{gid}")
def wz2_group_del(request: Request, gid: str) -> dict[str, Any]:
    with db() as c:
        g = c.execute("SELECT * FROM wz_groups WHERE id=?", (gid,)).fetchone()
        if not g:
            raise HTTPException(404, "Группа не найдена")
        n = c.execute("DELETE FROM wz_group_members WHERE group_id=?", (gid,)).rowcount
        c.execute("DELETE FROM wz_groups WHERE id=?", (gid,))
        _wz2_hist(c, g["section_id"], gid, "delete", dict(g), None, _who(request), kind="group")
        return {"message": f"Группа удалена; пунктов без группы: {n}"}


@app.get("/api/wz2/groups")
def wz2_groups(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sid = _section(c, section)["id"]
        _wz2_migrate(c, sid)
        gs = [dict(r) for r in c.execute("""SELECT g.*, (SELECT COUNT(*) FROM wz_group_members m WHERE m.group_id=g.id) members FROM wz_groups g WHERE g.section_id=? ORDER BY g.sort, g.name""", (sid,))]
        free = c.execute("SELECT COUNT(*) FROM wz_items i WHERE i.section_id=? AND i.layer='object' AND i.state<>'rejected' AND i.id NOT IN (SELECT item_id FROM wz_group_members)", (sid,)).fetchone()[0]
        return {"groups": gs, "ungrouped_objects": free}


class Wz2Confirm(BaseModel):
    step: Literal["1", "1.0", "1.1", "1.2", "1.3", "1.4", "2"]
    action: Literal["done", "skip", "reopen"] = "done"


@app.post("/api/wz2/confirm")
def wz2_confirm(request: Request, p: Wz2Confirm, section: Optional[str] = None) -> dict[str, Any]:
    """Подтвердить подшаг/шаг. Подтверждение шага 1 или 2 — снимок + публикация в перечень прораба и сопоставления; следующие шаги — «устарело»."""
    who = _who(request)
    with db() as c:
        sec = _section(c, section)
        sid = sec["id"]
        _wz2_migrate(c, sid)
        pub: dict[str, Any] = {}
        if p.action == "reopen":
            c.execute("INSERT OR REPLACE INTO wz_state (section_id,step,status,note) VALUES (?,?,?,?)", (sid, p.step, "work", "возвращён в работу"))
        elif "." in p.step:
            c.execute("INSERT OR REPLACE INTO wz_state (section_id,step,status,note,confirmed_at,confirmed_by) VALUES (?,?,?,?,?,?)",
                      (sid, p.step, "done" if p.action == "done" else "skipped", "" if p.action == "done" else "пропущено", now(), who))
        else:
            n = int(p.step)
            if n == 2:
                s1 = _wz2_state(c, sec)["steps"][0]
                if s1["status"] != "done":
                    raise HTTPException(409, "Сначала подтвердите шаг 1")
            snap = _wz2_snapshot(c, sid, n, "confirm", f"Подтверждён шаг {n}", who)
            c.execute("INSERT OR REPLACE INTO wz_state (section_id,step,status,note,confirmed_at,confirmed_by,fp,snapshot_id) VALUES (?,?,?,?,?,?,?,?)",
                      (sid, p.step, "done", "", now(), who, _wz2_fp(c, sid, n), snap))
            if n == 1:
                for k, _t, _ph in WZ2_SUB:
                    c.execute("INSERT OR IGNORE INTO wz_state (section_id,step,status) VALUES (?,?,?)", (sid, k, "todo"))
            pub = _wz2_publish(c, sec, who)
            if n == 2:   # прежний мастер: «перечень подтверждён» — открывает автосопоставление
                _wiz_set(c, sid, s1_at=now(), s1_by=who, s2_at=now(), s2_by=who, s2_fp=_list_fp(c, sid))
            else:
                r2 = c.execute("SELECT status FROM wz_state WHERE section_id=? AND step='2'", (sid,)).fetchone()
                if r2 and r2[0] == "done" and pub:
                    c.execute("UPDATE wz_state SET status='stale', note='шаг 1 изменён — проверьте состав' WHERE section_id=? AND step='2'", (sid,))
            if pub and _wz2_handed(c, sid):
                ru = {"el_added": "добавлено объектов", "el_changed": "изменено объектов", "el_disabled": "выведено из перечня", "op_added": "добавлено работ", "op_changed": "изменено работ",
                      "op_removed": "удалено работ", "op_kept_marked": "оставлено работ с вашими отметками"}
                _wz2_notice(c, sid, "publish", "Перечень работ обновлён ПТО", "Изменения: " + ", ".join(f"{ru.get(k, k)} {v}" for k, v in pub.items()) + ". Ваши отметки сохранены в истории.", who)
            audit(request, c, "wizard2", sid, f"confirm{n}", f"Мастер 2.0: подтверждён шаг {n}; публикация: {json.dumps(pub, ensure_ascii=False)}"[:300], section_id=sid)
        return {"published": pub, "state": _wz2_state(c, sec)}


class Wz2Rollback(BaseModel):
    snapshot_id: str = Field(default="", max_length=64)
    mode: Literal["full", "items", "group", "file", "layer"] = "full"
    layer: str = Field(default="", max_length=20)
    ids: list[str] = Field(default_factory=list, max_length=5000)
    group_id: str = Field(default="", max_length=64)
    file_id: str = Field(default="", max_length=64)
    reason: str = Field(default="", max_length=300)
    confirm_marks: bool = False
    dry_run: bool = False


@app.post("/api/wz2/rollback")
def wz2_rollback(request: Request, p: Wz2Rollback, section: Optional[str] = None) -> dict[str, Any]:
    """Откат шага 1/2 целиком к снимку или частично (пункты / группа / файл-источник). Перед откатом — снимок «перед откатом» (откат можно отменить).
    Затронуты отметки прораба или акты — нужно подтверждение и причина; отметки не удаляются (история остаётся)."""
    who = _who(request)
    with db() as c:
        sec = _section(c, section)
        sid = sec["id"]
        _wz2_migrate(c, sid)
        if p.mode == "file":
            if not p.file_id:
                raise HTTPException(422, "Не указан файл-источник")
            rows = [dict(r) for r in c.execute("SELECT * FROM wz_items WHERE section_id=? AND source_file_id=?", (sid, p.file_id))]
            auto = [r for r in rows if r["origin"] == "auto" and r["state"] in ("proposed", "accepted")]
            kept = [r for r in rows if r not in auto]
            target = [r for r in (dict(x) for x in c.execute("SELECT * FROM wz_items WHERE section_id=?", (sid,))) if r["id"] not in {a["id"] for a in auto}]
            plan = _wz2_plan(c, sid, target, {a["id"] for a in auto})
            plan["kept_edited"] = len(kept)
            step, snap_row = 1, None
        else:
            if not p.snapshot_id:
                raise HTTPException(422, "Выберите снимок для отката")
            snap_row, data = _wz2_load_snap(c, sid, p.snapshot_id)
            step = snap_row["step"]
            if step in (3, 4):
                cur_a = {r["id"]: dict(r) for r in c.execute("SELECT * FROM work_alloc WHERE section_id=?", (sid,))}
                en = {r[0] for r in c.execute("SELECT id FROM elements WHERE section_id=? AND enabled=1", (sid,))}
                tgt_a = {r["id"]: r for r in data["alloc"] if r["element_id"] in en}
                plan = {"counts": {"alloc_add": len(set(tgt_a) - set(cur_a)), "alloc_remove": len(set(cur_a) - set(tgt_a)),
                                   "alloc_change": sum(1 for i in set(cur_a) & set(tgt_a) if any(str(cur_a[i][k]) != str(tgt_a[i][k]) for k in ("qty", "mode", "item_key", "element_id"))),
                                   "skipped_disabled": len(data["alloc"]) - len(tgt_a)}, "marks": 0, "acts": 0}
            elif step == 2:
                cur_g = {r["id"] for r in c.execute("SELECT id FROM wz_groups WHERE section_id=?", (sid,))}
                cur_m = {(r[0], r[1]) for r in c.execute("SELECT m.group_id, m.item_id FROM wz_group_members m JOIN wz_groups g ON g.id=m.group_id WHERE g.section_id=?", (sid,))}
                tg = {g["id"] for g in data["groups"]}
                tm = {(m["group_id"], m["item_id"]) for m in data["members"]}
                if p.mode == "group":
                    tm = {x for x in tm if x[0] == p.group_id} | {x for x in cur_m if x[0] != p.group_id}
                    tg = (cur_g - {p.group_id}) | ({p.group_id} & tg)
                plan = {"counts": {"groups_add": len(tg - cur_g), "groups_remove": len(cur_g - tg), "members_add": len(tm - cur_m), "members_remove": len(cur_m - tm)},
                        "marks": 0, "acts": 0, "operations": 0}
            else:
                target = data["items"]
                ids: Optional[set[str]] = None
                if p.mode == "items":
                    ids = set(p.ids)
                    ids |= {r["id"] for r in target if r["parent_id"] in ids} | {r[0] for r in c.execute("SELECT id FROM wz_items WHERE section_id=? AND parent_id IN (%s)" % ",".join("?" * len(p.ids)), (sid, *p.ids))} if p.ids else set()
                elif p.mode == "layer":
                    if p.layer not in ("object", "work", "norm", "material"):
                        raise HTTPException(422, "Не указан слой перечня")
                    ids = {r["id"] for r in target if r["layer"] == p.layer} | {r[0] for r in c.execute("SELECT id FROM wz_items WHERE section_id=? AND layer=?", (sid, p.layer))}
                elif p.mode == "group":
                    gm = {r[0] for r in c.execute("SELECT item_id FROM wz_group_members WHERE group_id=?", (p.group_id,))}
                    ids = gm | {r["id"] for r in target if r["parent_id"] in gm} | {r[0] for r in c.execute("SELECT id FROM wz_items WHERE section_id=? AND parent_id IN (SELECT item_id FROM wz_group_members WHERE group_id=?)", (sid, p.group_id))}
                if ids is not None:
                    tmap = {r["id"]: r for r in target}
                    cur = {r["id"]: dict(r) for r in c.execute("SELECT * FROM wz_items WHERE section_id=?", (sid,))}
                    target = [tmap[i] if i in tmap else cur[i] for i in (set(cur) | set(tmap)) if (i in ids and i in tmap) or (i not in ids and i in cur)]
                plan = _wz2_plan(c, sid, target, ids)
        out = {"step": step, "mode": p.mode, "counts": plan["counts"], "marks": plan.get("marks", 0), "acts": plan.get("acts", 0), "kept_edited": plan.get("kept_edited", 0),
               "snapshot": dict(snap_row) if snap_row is not None and False else (snap_row["at"] if snap_row is not None else "")}
        if p.dry_run:
            return {**out, "dry_run": True}
        if len(p.reason.strip()) < 3:
            raise HTTPException(422, "Укажите причину отката")
        if (out["marks"] or out["acts"]) and not p.confirm_marks:
            raise HTTPException(409, f"Откат затронет отметки прораба ({out['marks']}) и акты ({out['acts']}). Подтвердите: отметки сохранятся в истории, объекты уйдут из перечня после подтверждения шага.")
        before = _wz2_snapshot(c, sid, step, "before-rollback", f"Перед откатом: {p.reason.strip()}", who)
        if step in (3, 4):
            c.execute("DELETE FROM work_alloc WHERE section_id=?", (sid,))
            for r in tgt_a.values():
                c.execute("INSERT INTO work_alloc (id,section_id,item_key,element_id,qty,mode,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?)",
                          (r["id"], sid, r["item_key"], r["element_id"], r["qty"], r["mode"], r["updated_by"], r["updated_at"]))
            _wiz_set(c, sid, s3_fp=_match_fp(c, sid), s4_at="", s4_by="", s4_fp="")
            _wz2_hist(c, sid, "*", "rollback", {"snapshot": before}, {"snapshot": p.snapshot_id}, who, p.reason, kind="alloc")
        elif step == 2 and p.mode != "file":
            if p.mode == "group":
                c.execute("DELETE FROM wz_group_members WHERE group_id=?", (p.group_id,))
                c.execute("DELETE FROM wz_groups WHERE id=?", (p.group_id,))
                for g in data["groups"]:
                    if g["id"] == p.group_id:
                        c.execute("INSERT INTO wz_groups (" + ",".join(_WZ_GROUP_COLS) + ") VALUES (" + ",".join("?" * len(_WZ_GROUP_COLS)) + ")", tuple(g.get(k) for k in _WZ_GROUP_COLS))
                for m in data["members"]:
                    if m["group_id"] == p.group_id:
                        c.execute("DELETE FROM wz_group_members WHERE item_id=?", (m["item_id"],))
                        c.execute("INSERT OR IGNORE INTO wz_group_members (group_id,item_id,sort) VALUES (?,?,?)", (m["group_id"], m["item_id"], m["sort"]))
            else:
                c.execute("DELETE FROM wz_group_members WHERE group_id IN (SELECT id FROM wz_groups WHERE section_id=?)", (sid,))
                c.execute("DELETE FROM wz_groups WHERE section_id=?", (sid,))
                for g in data["groups"]:
                    c.execute("INSERT INTO wz_groups (" + ",".join(_WZ_GROUP_COLS) + ") VALUES (" + ",".join("?" * len(_WZ_GROUP_COLS)) + ")", tuple(g.get(k) for k in _WZ_GROUP_COLS))
                for m in data["members"]:
                    c.execute("INSERT OR IGNORE INTO wz_group_members (group_id,item_id,sort) VALUES (?,?,?)", (m["group_id"], m["item_id"], m["sort"]))
            _wz2_hist(c, sid, p.group_id or "*", "rollback", {"snapshot": before}, {"snapshot": p.snapshot_id}, who, p.reason, kind="groups")
        else:
            _wz2_apply(c, sid, target, plan, who, p.reason.strip())
        if step < 3 and not (p.mode == "layer" and p.layer in ("norm", "material")):   # нормативы и материалы не меняют перечень прораба
            _wz2_mark_downstream(c, sid, step, f"откат: {p.reason.strip()}")
        if _wz2_handed(c, sid):
            cn = out["counts"]
            what = (f"объектов/работ: вернётся {cn.get('add', 0)}, уберётся {cn.get('remove', 0)}, изменится {cn.get('change', 0)}" if step == 1 else
                    f"групп +{cn.get('groups_add', 0)}/−{cn.get('groups_remove', 0)}" if step == 2 else f"привязок сметы: +{cn.get('alloc_add', 0)}/−{cn.get('alloc_remove', 0)}")
            _wz2_notice(c, sid, "rollback", f"ПТО откатил шаг {step} перечня работ",
                        f"Причина: {p.reason.strip()}. Изменения: {what}." + (f" Затронуто ваших отметок: {out['marks']} — они сохранены в истории." if out["marks"] else "")
                        + (" Перечень у вас обновится после того, как ПТО заново подтвердит шаг." if step < 3 else " На перечень работ не влияет — изменено сопоставление со сметой."), who)
        audit(request, c, "wizard2", sid, "rollback", f"Мастер 2.0: откат шага {step} ({p.mode}); причина: {p.reason.strip()}; {json.dumps(out['counts'], ensure_ascii=False)}; отметок {out['marks']}"[:300], section_id=sid)
        return {**out, "undo_snapshot": before, "message": "Откат выполнен. Проверьте и подтвердите шаг заново — изменения попадут к прорабу после подтверждения.", "state": _wz2_state(c, sec)}


@app.get("/api/wz2/history")
def wz2_history(section: Optional[str] = None, item: str = "", limit: int = 200) -> dict[str, Any]:
    with db() as c:
        sid = _section(c, section)["id"]
        q = "SELECT id,item_id,item_kind,action,reason,by,at,before_json,after_json FROM wz_history WHERE section_id=?" + (" AND item_id=?" if item else "") + " ORDER BY at DESC LIMIT ?"
        return {"history": [dict(r) for r in c.execute(q, (sid, item, min(limit, 1000)) if item else (sid, min(limit, 1000)))]}


