@app.post("/api/work-analysis/fact", status_code=201)
def work_fact_add(request: Request, p: WaFact, section: Optional[str] = None) -> dict[str, str]:
    """Прежний вход экрана «Анализ выполнения»: пишет в fact_records (идемпотентно по client_request_id), старая таблица work_fact больше не пополняется."""
    r = fact_add(request, FactIn(row_uid=p.item_key, qty=repr(p.qty), performed_on=p.performed_on, note=p.note, client_request_id=p.client_request_id), section or "")
    return {"id": json.loads(r.body)["id"]}


@app.delete("/api/work-analysis/fact")
def work_fact_del(request: Request, id: str, section: Optional[str] = None) -> dict[str, str]:
    """Запись не удаляется: она отзывается и остаётся в истории."""
    with db() as c:
        sec = _section(c, section)
        r = c.execute("SELECT * FROM fact_records WHERE id=? AND section_id=?", (id, sec["id"])).fetchone()
        if not r:
            raise HTTPException(404, "Запись не найдена")
        if r["status"] not in ("submitted", "accepted", "rejected", "ambiguous", "orphan"):
            raise HTTPException(409, "Запись уже отозвана или исправлена")
        c.execute("UPDATE fact_records SET status='withdrawn', pto_by=?, pto_at=?, pto_note='отозвана' WHERE id=?", (_user(request), now(), id))
        audit(request, c, "fact", id, "withdraw", f"Факт отозван: {r['qty']} {r['unit']} от {r['performed_on']} (запись сохранена в истории)", None, section_id=sec["id"])
    return {"ok": "1"}


