# ================================================================ v.76: идентичность строк, комплекты (проект + смета), отношения смет
# ID строки редакции (estimate_rows.id) — идентификатор записи конкретной редакции. row_uid — устойчивая «линия» строки между редакциями (line_id).
# match_key — хэш реквизитов (глава, шифр, наименование, единица, порядковый повтор): ПРИЗНАК сопоставления, а не идентификатор.
# Совпадение признака с единственной строкой прежней редакции переносит линию; изменённые реквизиты и неоднозначные случаи — только после подтверждения.
_V76_DDL = """
CREATE TABLE IF NOT EXISTS work_kits (
  id TEXT PRIMARY KEY, project_id TEXT NOT NULL, section_id TEXT NOT NULL, title TEXT NOT NULL, method TEXT NOT NULL DEFAULT '',
  note TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS kit_docs (
  kit_id TEXT NOT NULL, file_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'proposed', basis TEXT NOT NULL DEFAULT '',
  decided_by TEXT NOT NULL DEFAULT '', decided_at TEXT NOT NULL DEFAULT '', PRIMARY KEY (kit_id, file_id)
);
CREATE TABLE IF NOT EXISTS kit_estimates (
  kit_id TEXT NOT NULL, estimate_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'proposed', basis TEXT NOT NULL DEFAULT '',
  decided_by TEXT NOT NULL DEFAULT '', decided_at TEXT NOT NULL DEFAULT '', PRIMARY KEY (kit_id, estimate_id)
);
CREATE TABLE IF NOT EXISTS estimate_relations (
  id TEXT PRIMARY KEY, a_id TEXT NOT NULL, b_id TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'unspecified', basis TEXT NOT NULL DEFAULT '',
  decided_by TEXT NOT NULL DEFAULT '', decided_at TEXT NOT NULL DEFAULT '', UNIQUE (a_id, b_id)
);
"""
REL_KINDS = {"unspecified": "не уточнено", "independent": "самостоятельные комплекты", "joint_parts": "совместно действующие части", "alternatives": "альтернативные варианты"}
REL_SUMMABLE = {"independent", "joint_parts"}
LINK_STATUS = {"proposed": "предложено", "confirmed": "подтверждено", "rejected": "отклонено"}


def _ensure_cols(c: sqlite3.Connection, table: str, cols: dict[str, str]) -> None:
    have = {r[1] for r in c.execute(f"PRAGMA table_info({table})")}
    for k, d in cols.items():
        if k not in have:
            c.execute(f"ALTER TABLE {table} ADD COLUMN {k} {d}")


def _match_key(chapter: str, r: dict[str, Any], occ: int) -> str:
    return hashlib.sha1("|".join(["m", chapter, r.get("code") or "", _name_norm(r.get("name") or ""), _unit_norm(r.get("units") or ""), str(occ)]).encode()).hexdigest()[:16]


def _backfill_match_keys(c: sqlite3.Connection) -> None:
    for rv in c.execute("SELECT DISTINCT revision_id FROM estimate_rows WHERE IFNULL(match_key,'')=''").fetchall():
        seen: dict[tuple, int] = {}
        for r in c.execute("SELECT rowid AS rid, chapter, code, name, unit FROM estimate_rows WHERE revision_id=? ORDER BY rowid", (rv[0],)).fetchall():
            sig = (r["chapter"], r["code"], _name_norm(r["name"]), _unit_norm(r["unit"]))
            occ = seen.get(sig, 0)
            seen[sig] = occ + 1
            c.execute("UPDATE estimate_rows SET match_key=?, match_status=CASE WHEN match_status='' THEN 'new' ELSE match_status END WHERE rowid=?",
                      (_match_key(r["chapter"], {"code": r["code"], "name": r["name"], "units": r["unit"]}, occ), r["rid"]))


def _init_v76(c: sqlite3.Connection) -> None:
    c.executescript(_V76_DDL)
    _ensure_cols(c, "estimate_rows", {"match_key": "TEXT NOT NULL DEFAULT ''", "match_status": "TEXT NOT NULL DEFAULT ''", "match_candidates_json": "TEXT NOT NULL DEFAULT '[]'", "match_basis": "TEXT NOT NULL DEFAULT ''"})
    c.execute("CREATE INDEX IF NOT EXISTS ix_estrows_mk ON estimate_rows (match_key)")
    _backfill_match_keys(c)
    # E7 снят: совпадение строк разных комплектов не признак дубля
    c.execute("UPDATE estimate_notes SET status='withdrawn', decided_by=CASE WHEN decided_by='' THEN 'система' ELSE decided_by END, decided_at=?, "
              "decision_note='снято: совпадение строк разных смет не является признаком дубля; повторный учёт проверяется по элементам, границам и объёмам' WHERE kind='dup_between' AND status='open'", (now(),))
    _init_v76b(c)


def _name_sim(a: str, b: str) -> float:
    ta, tb = _utok(a), _utok(b)
    if ta and tb:
        return len(ta & tb) / len(ta | tb)
    return 1.0 if _name_norm(a) == _name_norm(b) else 0.0


def _insert_rows(c: sqlite3.Connection, rid: str, rows: list[dict[str, Any]], prev_rev_id: Optional[str]) -> dict[str, int]:
    """Строки новой редакции + сопоставление с прежней. Возвращает счётчики статусов сопоставления."""
    prev: list[dict[str, Any]] = []
    if prev_rev_id:
        prev = [dict(r) for r in c.execute("SELECT id,row_uid,match_key,chapter,n,code,name,unit,qty,formula FROM estimate_rows WHERE revision_id=?", (prev_rev_id,))]
    by_key: dict[str, dict[str, Any]] = {}
    for p in prev:
        by_key.setdefault(p["match_key"], p)
    claimed: set[str] = set()
    for r in rows:
        r["line"], r["mstatus"], r["cands"], r["mbasis"], r["change"] = "", "new" if not prev_rev_id else "", [], "", "new"
    if prev_rev_id:
        for r in rows:                                   # 1) совпал признак (единственная строка с таким признаком)
            p = by_key.get(r["mk"])
            if p and p["row_uid"] not in claimed:
                r["line"], r["mstatus"], r["mbasis"] = p["row_uid"], "matched", "совпал признак: глава, шифр, наименование, единица, порядковый повтор"
                r["change"] = "same" if (p["qty"] == r["qty"] and p["formula"] == r["formula"]) else "changed"
                claimed.add(p["row_uid"])
        free = [p for p in prev if p["row_uid"] not in claimed]
        want: dict[str, list[dict[str, Any]]] = {}
        for r in rows:                                   # 2) реквизиты изменились: кандидаты по шифру и единице, мерой сходства наименования
            if r["line"]:
                continue
            cands = []
            for p in free:
                if p["code"] == r["code"] and _unit_norm(p["unit"]) == _unit_norm(r["unit"]):
                    s = _name_sim(r["name"], p["name"]) + (0.2 if p["chapter"] == r["chapter"] else 0) + (0.1 if p["n"] == r["n"] else 0)
                    if s >= 0.5:
                        cands.append((round(s, 2), p))
            cands.sort(key=lambda x: -x[0])
            r["cands"] = [{"line_id": p["row_uid"], "rev_row_id": p["id"], "n": p["n"], "name": p["name"][:120], "qty": p["qty"], "score": s} for s, p in cands[:5]]
            for s, p in cands:
                want.setdefault(p["row_uid"], []).append(r)
        for r in rows:
            if r["line"]:
                continue
            if not r["cands"]:
                r["mstatus"], r["mbasis"] = "added", "аналога в прежней редакции нет"
            elif len(r["cands"]) == 1 and len(want.get(r["cands"][0]["line_id"], [])) == 1:
                r["mstatus"], r["mbasis"] = "suggested", "единственный кандидат с изменёнными реквизитами — нужно подтверждение"
            else:
                r["mstatus"], r["mbasis"] = "ambiguous", "несколько кандидатов или кандидат нужен нескольким строкам — требуется проверка"
            r["change"] = "unmatched"
    cnt: dict[str, int] = {}
    for r in rows:
        line = r["line"] or str(uuid.uuid4())
        c.execute("INSERT OR IGNORE INTO estimate_rows (id,revision_id,row_uid,key_old,chapter,sub,n,code,name,unit,qty,formula,basis,flags,kind,kind_source,norm_base,norm_code,change,works_json,res_json,match_key,match_status,match_candidates_json,match_basis) "
                  "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                  (str(uuid.uuid4()), rid, line, r["key_old"], r["chapter"][:200], r["sub"][:200], r["n"], r["code"], r["name"], r["unit"], r["qty"], r["formula"], r["basis"][:300], r["flags"],
                   r["kind"], r["kind_source"], r["norm_base"], r["norm_code"], r["change"], json.dumps(r["works"], ensure_ascii=False), json.dumps(r["res"], ensure_ascii=False),
                   r["mk"], r["mstatus"], json.dumps(r["cands"], ensure_ascii=False), r["mbasis"]))
        cnt[r["mstatus"]] = cnt.get(r["mstatus"], 0) + 1
    return cnt


PROJECT_DOC_KINDS = ("pdf", "dxf_project")


def _kit_ok_estimates(c: sqlite3.Connection, section_id: str) -> Optional[set[str]]:
    """Сметы, допущенные к расчёту раздела: подтверждены и связь со сметой, и связь комплекта с проектной документацией.
    Пока в разделе не заведён ни один комплект — режим совместимости (все сметы раздела), об этом сообщает интерфейс."""
    kits = [r[0] for r in c.execute("SELECT id FROM work_kits WHERE section_id=?", (section_id,))]
    if not kits:
        return None
    out: set[str] = set()
    for k in kits:
        if c.execute("SELECT 1 FROM kit_docs WHERE kit_id=? AND status='confirmed'", (k,)).fetchone():
            out |= {r[0] for r in c.execute("SELECT estimate_id FROM kit_estimates WHERE kit_id=? AND status='confirmed'", (k,))}
    return out


def _rel_kind(c: sqlite3.Connection, a: str, b: str) -> str:
    r = c.execute("SELECT kind FROM estimate_relations WHERE (a_id=? AND b_id=?) OR (a_id=? AND b_id=?)", (a, b, b, a)).fetchone()
    return r[0] if r else "unspecified"


def _svod_groups(c: sqlite3.Connection, est_ids: list[str]) -> tuple[list[str], list[dict[str, str]]]:
    """Какие сметы можно суммировать: только попарно «самостоятельные комплекты» или «совместно действующие части». Остальные — отдельно."""
    inc: list[str] = []
    excl: list[dict[str, str]] = []
    for e in est_ids:
        bad = [(i, _rel_kind(c, e, i)) for i in inc if _rel_kind(c, e, i) not in REL_SUMMABLE]
        if bad:
            excl.append({"estimate_id": e, "with": bad[0][0], "kind": bad[0][1], "reason": "отношение со сметой «" + (c.execute("SELECT title FROM estimates WHERE id=?", (bad[0][0],)).fetchone() or [""])[0] + "»: " + REL_KINDS[bad[0][1]]})
        else:
            inc.append(e)
    return inc, excl


