@app.get("/api/double-count")
def double_count(section: str) -> dict[str, Any]:
    """Возможный повторный учёт: работы на одном элементе, связанные со строками одного вида нормы, с пересекающимися границами. Совпадение строк разных смет дублем не считается."""
    with db() as c:
        sec = _section(c, section)
        idx = _uid_index(c, sec)
        ws = []
        for w in c.execute("SELECT * FROM work_instances WHERE section_id=? AND element_id<>''", (sec["id"],)):
            for l in c.execute("SELECT row_uid FROM coverage_links WHERE work_id=?", (w["id"],)):
                r = idx.get(l["row_uid"])
                if r:
                    ws.append((w, r))
        out = []
        for i in range(len(ws)):
            for j in range(i + 1, len(ws)):
                (w1, r1), (w2, r2) = ws[i], ws[j]
                if w1["element_id"] != w2["element_id"] or w1["id"] == w2["id"]:
                    continue
                if not (r1["norm_code"] and r1["norm_code"] == r2["norm_code"]):
                    continue
                if w1["axis_len"] and w2["axis_len"]:
                    a1, b1 = _dec(w1["axis_from"]), _dec(w1["axis_from"]) + _dec(w1["axis_len"])
                    a2, b2 = _dec(w2["axis_from"]), _dec(w2["axis_from"]) + _dec(w2["axis_len"])
                    ov = min(b1, b2) - max(a1, a2)
                    if ov <= 0:
                        continue
                    out.append({"element_id": w1["element_id"], "works": [w1["title"], w2["title"]], "rows": [r1["est_title"] + " поз. " + r1["n"], r2["est_title"] + " поз. " + r2["n"]], "overlap": _dec_s(ov), "unit": w1["axis_unit"], "basis": "один элемент, одна норма, границы пересекаются"})
                else:
                    out.append({"element_id": w1["element_id"], "works": [w1["title"], w2["title"]], "rows": [r1["est_title"] + " поз. " + r1["n"], r2["est_title"] + " поз. " + r2["n"]], "overlap": None, "unit": "", "basis": "один элемент и одна норма, границы не заданы — проверить вручную"})
        return {"candidates": out}


# ---------------------------------------------------------------- Предложения: E/R с источниками и статусами (не исправляют смету и проект)
def _prop_basis_hash(kind: str, title: str, text: str, scope: Any, source_doc: str, locator: str, page: str, excerpt: str, targets: Any) -> str:
    """Хэш основания предложения: что именно и на каком пункте утверждается."""
    return hashlib.sha256(json.dumps([kind, title, text, scope, source_doc, locator, page, excerpt, targets], ensure_ascii=False, sort_keys=True).encode()).hexdigest()[:20]


def _prop_ctx_hash(c: sqlite3.Connection, project_id: str, targets: list[dict[str, Any]]) -> str:
    """Внешний контекст решения: файлы проекта (подтверждённые в комплектах), записи норм по целевым таблицам/шифрам, параметры целевых строк сметы."""
    parts: list[Any] = []
    parts.append(sorted(r["sha256"] for r in c.execute("SELECT DISTINCT f.sha256 FROM kit_docs d JOIN source_files f ON f.id=d.file_id JOIN work_kits k ON k.id=d.kit_id WHERE k.project_id=? AND d.status='confirmed'", (project_id,))))
    for t in targets:
        ty = t.get("type")
        if ty == "norm_table":
            tb = str(t.get("table", ""))
            parts.append(["nt", tb, hashlib.sha256("|".join(f"{r['code']}~{r['unit']}~{r['content_json']}" for r in c.execute("SELECT code,unit,content_json FROM norm_records WHERE table_code=? ORDER BY code", (tb,))).encode()).hexdigest()[:16]])
        elif ty == "norm_code":
            r = c.execute("SELECT unit,content_json FROM norm_records WHERE code=?", (str(t.get("code", "")),)).fetchone()
            parts.append(["nc", t.get("code"), hashlib.sha256(((r["unit"] + r["content_json"]) if r else "-").encode()).hexdigest()[:16]])
        elif ty == "estimate_row":
            rr = c.execute("SELECT r.code,r.name,r.unit,r.qty FROM estimate_rows r JOIN estimate_revisions v ON v.id=r.revision_id JOIN estimates e ON e.id=v.estimate_id "
                           "WHERE e.project_id=? AND e.ident=? AND v.is_current=1 AND r.n=?", (project_id, t.get("estimate_ident", ""), str(t.get("n", "")))).fetchone()
            parts.append(["er", t.get("estimate_ident"), t.get("n"), list(rr) if rr else None])
    return hashlib.sha256(json.dumps(parts, ensure_ascii=False, default=str).encode()).hexdigest()[:20]


def _prop_stale(c: sqlite3.Connection, r: sqlite3.Row) -> str:
    """Причина, по которой решённый статус больше не действует (пусто — действует)."""
    if r["status"] not in ("confirmed", "rejected") or not r["decided_hash"]:
        return ""
    cur = _prop_basis_hash(r["kind"], r["title"], r["text"], json.loads(r["scope_json"] or "{}"), r["source_doc"], r["locator"], r["page"], r["excerpt"], json.loads(r["targets_json"] or "[]"))
    if cur != r["decided_hash"]:
        return "изменено основание предложения (текст, пункт, область или источник)"
    if _prop_ctx_hash(c, r["project_id"], json.loads(r["targets_json"] or "[]")) != r["decided_ctx"]:
        return "изменился проект, норма или параметры целевой строки сметы после проверки"
    return ""


class PropIn(BaseModel):
    code: str = Field(min_length=1, max_length=40)
    kind: Literal["estimate_remark", "norm_rule", "project_remark", "project_conflict"]
    title: str = Field(min_length=1, max_length=300)
    text: str = Field(default="", max_length=2000)
    scope: dict[str, Any] = Field(default_factory=dict)
    source_doc: str = Field(default="", max_length=300)
    locator: str = Field(default="", max_length=200)
    page: str = Field(default="", max_length=40)
    excerpt: str = Field(default="", max_length=2000)
    targets: list[dict[str, Any]] = Field(default_factory=list, max_length=20)
    status: Literal["proposed", "needs_check", "confirmed", "rejected", "withdrawn"] = "proposed"
    check_note: str = Field(default="", max_length=600)
    graphic: bool = False                                                       # требование находится на чертеже/схеме, а не в тексте
    visual_status: Literal["", "unverified", "verified", "impossible"] = ""
    visual_note: str = Field(default="", max_length=800)


VIS_STATUS = {"unverified": "не проверено визуально", "verified": "сверено визуально", "impossible": "проверка невозможна", "": ""}


def _vis_check(code: str, graphic: bool, st: str, note: str, page: str, excerpt: str) -> str:
    """Графическое требование: «сверено» — только с точной страницей, фрагментом и описанием проверки; «невозможно» — только с причиной."""
    if not graphic:
        return ""
    st = st or "unverified"
    if st == "verified" and (not page.strip() or len(excerpt.strip()) < 10 or len(note.strip()) < 10):
        raise HTTPException(422, f"{code}: «сверено визуально» требует точную страницу, фрагмент и описание того, что и как сверено")
    if st == "impossible" and len(note.strip()) < 10:
        raise HTTPException(422, f"{code}: для «проверка невозможна» укажите причину")
    return st


@app.post("/api/admin/proposals/import")
def proposals_import(request: Request, items: list[PropIn], project: str) -> dict[str, int]:
    """Загрузка предложений (только администратор). Повторная загрузка обновляет текст и источники, но не меняет уже решённый статус."""
    n_new = n_upd = 0
    with db() as c:
        if not c.execute("SELECT 1 FROM projects WHERE id=?", (project,)).fetchone():
            raise HTTPException(404, "Объект не найден")
        for p in items:
            if p.kind == "norm_rule" and (not p.locator.strip() or not p.scope):
                raise HTTPException(422, f"{p.code}: у правила нормы должны быть точный пункт и область применения")
            vs = _vis_check(p.code, p.graphic, p.visual_status, p.visual_note, p.page, p.excerpt)
            ex = c.execute("SELECT id,status,visual_status FROM norm_proposals WHERE project_id=? AND code=?", (project, p.code)).fetchone()
            if ex:
                c.execute("UPDATE norm_proposals SET kind=?,title=?,text=?,scope_json=?,source_doc=?,locator=?,page=?,excerpt=?,targets_json=?,graphic=? WHERE id=?",
                          (p.kind, p.title, p.text, json.dumps(p.scope, ensure_ascii=False), p.source_doc, p.locator, p.page, p.excerpt, json.dumps(p.targets, ensure_ascii=False), int(p.graphic), ex["id"]))
                if p.graphic and not ex["visual_status"]:
                    c.execute("UPDATE norm_proposals SET visual_status=?, visual_note=?, visual_by=?, visual_at=? WHERE id=?", (vs, p.visual_note, _user(request) if vs != "unverified" else "", now() if vs != "unverified" else "", ex["id"]))
                n_upd += 1
            else:
                c.execute("INSERT INTO norm_proposals (id,project_id,code,kind,title,text,scope_json,source_doc,locator,page,excerpt,targets_json,status,check_note,created_by,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                          (str(uuid.uuid4()), project, p.code, p.kind, p.title, p.text, json.dumps(p.scope, ensure_ascii=False), p.source_doc, p.locator, p.page, p.excerpt, json.dumps(p.targets, ensure_ascii=False), p.status if not (p.graphic and vs != "verified" and p.status == "confirmed") else "proposed", p.check_note, _user(request), now()))
                if p.graphic:
                    c.execute("UPDATE norm_proposals SET graphic=1, visual_status=?, visual_note=?, visual_by=?, visual_at=? WHERE project_id=? AND code=?",
                              (vs, p.visual_note, _user(request) if vs != "unverified" else "", now() if vs != "unverified" else "", project, p.code))
                n_new += 1
        audit(request, c, "proposal", project, "import", f"Предложения загружены: новых {n_new}, обновлено {n_upd}", None, project_id=project)
    return {"new": n_new, "updated": n_upd}


def _prop_dict(r: sqlite3.Row, c: Optional[sqlite3.Connection] = None) -> dict[str, Any]:
    d = dict(r)
    stale = _prop_stale(c, r) if c is not None else ""
    d["stale"] = stale
    d["status_effective"] = "needs_check" if stale else r["status"]
    d["scope"] = json.loads(d.pop("scope_json") or "{}")
    d["targets"] = json.loads(d.pop("targets_json") or "[]")
    d["kind_label"] = PROP_KINDS.get(d["kind"], d["kind"])
    d["graphic"] = bool(d.get("graphic"))
    d["visual_label"] = VIS_STATUS.get(d.get("visual_status") or "", "") if d["graphic"] else ""
    d["status_label"] = PROP_STATUS.get(d["status_effective"], d["status_effective"]) + (" · требуется повторная проверка" if stale else "")
    for k in ("decided_hash", "decided_ctx"):
        d.pop(k, None)
    return d


@app.get("/api/proposals")
def proposals_list(project: str, kind: str = "", status: str = "", material: str = "", system: str = "", visual: str = "") -> dict[str, Any]:
    with db() as c:
        if not c.execute("SELECT 1 FROM projects WHERE id=?", (project,)).fetchone():
            raise HTTPException(404, "Объект не найден")
        rows = [_prop_dict(r, c) for r in c.execute("SELECT * FROM norm_proposals WHERE project_id=? ORDER BY CASE kind WHEN 'estimate_remark' THEN 0 ELSE 1 END, created_at, code", (project,)).fetchall()]
        n_unv = sum(1 for r in rows if r["graphic"] and r["visual_status"] in ("unverified", "") and r["status"] != "withdrawn")
        n_imp = sum(1 for r in rows if r["graphic"] and r["visual_status"] == "impossible" and r["status"] != "withdrawn")
        if visual == "unverified":
            rows = [r for r in rows if r["graphic"] and r["visual_status"] in ("unverified", "", "impossible") and r["status"] != "withdrawn"]
        if kind:
            rows = [r for r in rows if r["kind"] == kind]
        if status:
            rows = [r for r in rows if r["status_effective"] == status]
        if material:
            rows = [r for r in rows if material in (r["scope"].get("material") or [])]
        if system:
            rows = [r for r in rows if system == (r["scope"].get("system") or "")]
        return {"items": rows, "kinds": PROP_KINDS, "statuses": PROP_STATUS, "graphic_unverified": n_unv, "graphic_impossible": n_imp}


class PropDecision(BaseModel):
    status: Literal["proposed", "needs_check", "confirmed", "rejected"]
    check_note: str = Field(default="", max_length=600)


@app.put("/api/proposals/{pid}")
def proposal_decide(request: Request, pid: str, p: PropDecision, project: str) -> dict[str, str]:
    """Статус проверки выставляет специалист. Смета и проект при этом не меняются."""
    with db() as c:
        r = c.execute("SELECT * FROM norm_proposals WHERE id=? AND project_id=?", (pid, project)).fetchone()
        if not r:
            raise HTTPException(404, "Предложение не найдено")
        if r["status"] == "withdrawn":
            raise HTTPException(409, "Предложение снято и не пересматривается")
        if p.status in ("confirmed", "rejected") and len(p.check_note.strip()) < 3:
            raise HTTPException(422, "Укажите, чем проверено (кто, что сверено)")
        if p.status == "confirmed" and r["graphic"] and r["visual_status"] != "verified":
            raise HTTPException(409, "Графическое требование нельзя подтвердить, пока оно не сверено визуально с точной страницей и фрагментом (или проверка не признана невозможной и решение не принято иначе)")
        dh = _prop_basis_hash(r["kind"], r["title"], r["text"], json.loads(r["scope_json"] or "{}"), r["source_doc"], r["locator"], r["page"], r["excerpt"], json.loads(r["targets_json"] or "[]"))
        dc = _prop_ctx_hash(c, project, json.loads(r["targets_json"] or "[]"))
        c.execute("UPDATE norm_proposals SET status=?, check_note=?, checked_by=?, checked_at=?, decided_hash=?, decided_ctx=? WHERE id=?", (p.status, p.check_note.strip(), _user(request), now(), dh if p.status in ("confirmed", "rejected") else "", dc if p.status in ("confirmed", "rejected") else "", pid))
        audit(request, c, "proposal", pid, "decide", f"{r['code']}: {PROP_STATUS[p.status]}", None, project_id=project)
    return {"id": pid}


class PropVisual(BaseModel):
    status: Literal["unverified", "verified", "impossible"]
    note: str = Field(default="", max_length=800)
    page: str = Field(default="", max_length=40)
    excerpt: str = Field(default="", max_length=2000)


@app.put("/api/proposals/{pid}/visual")
def proposal_visual(request: Request, pid: str, p: PropVisual, project: str) -> dict[str, str]:
    """Визуальная сверка графического требования. «Сверено» — только с точной страницей, фрагментом и описанием; «невозможно» — с причиной."""
    with db() as c:
        r = c.execute("SELECT * FROM norm_proposals WHERE id=? AND project_id=?", (pid, project)).fetchone()
        if not r:
            raise HTTPException(404, "Предложение не найдено")
        if not r["graphic"]:
            raise HTTPException(409, "Это не графическое требование")
        page, exc = p.page.strip() or r["page"], p.excerpt.strip() or r["excerpt"]
        _vis_check(r["code"], True, p.status, p.note, page, exc)
        c.execute("UPDATE norm_proposals SET visual_status=?, visual_note=?, visual_by=?, visual_at=?, page=?, excerpt=? WHERE id=?",
                  (p.status, p.note.strip(), _user(request), now(), page, exc, pid))
        if p.status != "verified" and r["status"] == "confirmed":
            c.execute("UPDATE norm_proposals SET status='needs_check', decided_hash='', decided_ctx='' WHERE id=?", (pid,))
        audit(request, c, "proposal", pid, "visual", f"{r['code']}: {VIS_STATUS[p.status]}", None, project_id=project)
    return {"id": pid}


def _row_proposals(c: sqlite3.Connection, project_id: str, row: dict[str, Any], est_ident: str) -> list[dict[str, Any]]:
    out = []
    code = row.get("norm_code") or ""
    for r in c.execute("SELECT * FROM norm_proposals WHERE project_id=? AND status<>'withdrawn' ORDER BY code", (project_id,)).fetchall():
        hit = False
        for t in json.loads(r["targets_json"] or "[]"):
            if t.get("type") == "norm_table" and code and code.startswith(str(t.get("table", "")) + "-"):
                hit = True
            elif t.get("type") == "norm_code" and code and t.get("code") == code:
                hit = True
            elif t.get("type") == "estimate_row" and t.get("estimate_ident") == est_ident and str(t.get("n")) == str(row.get("n")) and (not t.get("code") or t.get("code") == row.get("code")):
                hit = True
        if hit:
            out.append(_prop_dict(r, c))
    return out


@app.get("/api/row-card")
def row_card(section: str, row_uid: str) -> dict[str, Any]:
    """Карточка строки сметы: строка и её идентичность, норма из каталога, правила и замечания с источниками, работы, покрытие, факты."""
    with db() as c:
        sec = _section(c, section)
        r = _uid_index(c, sec).get(row_uid)
        if not r:
            raise HTTPException(404, "Строка не найдена среди смет, допущенных к расчёту")
        est = c.execute("SELECT ident FROM estimates WHERE id=?", (r["est_id"],)).fetchone()
        norm = None
        if r["norm_code"]:
            nr = c.execute("SELECT * FROM norm_records WHERE base=? AND code=?", (r["norm_base"] or "ГЭСН", r["norm_code"])).fetchone()
            if nr:
                res = json.loads(nr["res_json"] or "[]")
                norm = {"base": nr["base"], "code": nr["code"], "full_name": ((nr["begin_name"] or "") + " " + (nr["end_name"] or "")).strip(), "unit": nr["unit"], "table": nr["table_code"] + " " + nr["table_name"],
                        "collection": nr["collection"] + " " + nr["collection_name"], "content": json.loads(nr["content_json"] or "[]"), "resources": len(res), "unit_match": _unit_norm(nr["unit"]) == _unit_norm(r["unit"])}
            else:
                norm = {"base": r["norm_base"] or "ГЭСН", "code": r["norm_code"], "missing": True}
        props = _row_proposals(c, sec["project_id"], r, est["ident"] if est else "")
        works = []
        for w in c.execute("SELECT w.* FROM work_instances w JOIN coverage_links l ON l.work_id=w.id WHERE l.row_uid=? AND w.section_id=?", (row_uid, sec["id"])):
            works.append({"id": w["id"], "title": w["title"], "kind": w["kind"], "approval": w["approval"], "element_id": w["element_id"]})
        facts = [_fact_dict(f) for f in c.execute("SELECT * FROM fact_records WHERE section_id=? AND row_uid=? ORDER BY performed_on, created_at", (sec["id"], row_uid))]
        notes = [dict(n) for n in c.execute("SELECT id,kind,severity,text,status FROM estimate_notes WHERE revision_id=(SELECT revision_id FROM estimate_rows WHERE id=?) AND row_uid=?", (r["id"], row_uid))]
        return {"row": {"rev_row_id": r["id"], "line_id": r["row_uid"], "estimate": r["est_title"], "rev_no": r["rev_no"], "chapter": r["chapter"], "sub": r["sub"], "n": r["n"], "code": r["code"], "name": r["name"], "unit": r["unit"],
                        "qty": r["qty"], "formula": r["formula"], "basis": r["basis"], "kind": r["kind"], "kind_source": r["kind_source"], "match_status": r["match_status"], "match_basis": r["match_basis"], "match_key": r["match_key"]},
                "norm": norm, "rules": [p for p in props if p["kind"] == "norm_rule"], "remarks": [p for p in props if p["kind"] != "norm_rule"], "works": works, "facts": facts, "notes": notes}


