    n = r["file_name"].lower()
    mt = "application/pdf" if n.endswith(".pdf") else ("image/png" if n.endswith(".png") else ("image/jpeg" if n.endswith((".jpg", ".jpeg")) else "application/octet-stream"))
    return FileResponse(fp, media_type=mt, content_disposition_type="inline" if mt != "application/octet-stream" else "attachment", filename=r["file_name"])


