# ---------------------------------------------------------------- Документы ЖВК: загрузка и распознавание
_VD_UNITS = r"(?:шт|м3|м³|м2|м²|пог\.?\s?м|п\.\s?м|мп|м|т|кг|г|л|компл|комплект|упак|уп|рул|пар[аы]?)"
_VD_A = re.compile(r"^(?:\d{1,3}[.)]?\s+)?(?P<n>[A-Za-zА-Яа-я].{3,}?)\s+(?P<u>" + _VD_UNITS + r")\.?\s+(?P<q>\d[\d\s]*(?:[.,]\d+)?)(?:\s|$)", re.I)
_VD_B = re.compile(r"^(?:\d{1,3}[.)]?\s+)?(?P<n>[A-Za-zА-Яа-я].{3,}?)\s+(?P<q>\d+(?:[.,]\d+)?)\s*(?P<u>" + _VD_UNITS + r")(?![A-Za-zА-Яа-я])\.?", re.I)
_VD_SKIP = re.compile(r"артикул|кол-во|товары \(|№ п|наименован|итого|всего|ндс|сумма|цена|стоимост|поставщик|покупатель|грузополуч|плательщик|адрес|договор|накладная|счёт|счет-ф|подпись", re.I)


_VD_NOTPOS = re.compile(r"^(?:счет|счёт|упд|универсальн|товарная|транспортн|акт\b|накладн|приложение|основание|получатель|банк|плательщик|продавец|покупатель|грузо|адрес|договор|исполнитель|заказчик)|бик\b|\bинн\b|\bкпп\b|р/с|к/с|корр\.|\bбанк\b|№\s*\S+\s+от\s|\bот\s+\d{1,2}\s+[а-я]+\s+\d{4}|всего наименован|на сумму", re.I)


def _vd_notpos(m: "re.Match[str]") -> bool:
    n = m.group("n")
    if _VD_NOTPOS.search(n):
        return True
    q, u = m.group("q").replace(" ", ""), m.group("u").lower()
    if u == "г" and re.fullmatch(r"(19|20)\d\d", q):      # «2026 г.» из даты
        return True
    return False


def _vd_lines(text: str) -> list[dict[str, str]]:
    out: list[dict[str, str]] = []
    prev: list[str] = []
    for ln in text.splitlines():
        t = " ".join(ln.split())
        if len(t) < 3:
            continue
        if _VD_NOTPOS.search(t[:90]):
            prev = []
            continue
        m = None
        if len(t) >= 6 and not (_VD_SKIP.search(t[:40]) and not re.search(r"\d", t[-12:])):
            m = _VD_B.match(t) or _VD_A.match(t)
        if m and _vd_notpos(m):
            m = None
        if m and len(re.findall(r"[A-Za-zА-Яа-я]", m.group("n"))) >= 4:
            name = m.group("n").strip(" .;,-–")
            if (name[:1].islower() or name[:1] == "(") and prev:   # название начиналось на предыдущей строке ячейки
                name = " ".join(re.sub(r"^\d{1,3}[.)]?\s+", "", x) for x in prev[-2:]) + " " + name
            out.append({"name": " ".join(name.split()), "qty": (m.group("q").replace(" ", "") + " " + m.group("u").replace(" ", "")).strip()})
            prev = []
        elif re.search(r"[A-Za-zА-Яа-я]{3}", t) and not _VD_SKIP.search(t[:40]):
            prev = (prev + [t])[-2:]
        else:
            prev = []
    return out


def _vd_table(rows: list[list[str]]) -> list[dict[str, str]]:
    hdr = -1
    for i, r in enumerate(rows[:12]):
        j = " | ".join(x.lower() for x in r)
        if ("наименован" in j or "товар" in j or "материал" in j) and ("кол" in j):
            hdr = i
            break
    if hdr < 0:
        return []
    h = [x.lower() for x in rows[hdr]]
    ni = next((k for k, x in enumerate(h) if "наименован" in x or "товар" in x or "материал" in x), -1)
    qi = next((k for k, x in enumerate(h) if "кол" in x), -1)
    ui = next((k for k, x in enumerate(h) if x.startswith("ед") or "ед. изм" in x or "ед.изм" in x), -1)
    out = []
    for r in rows[hdr + 1:]:
        if max(ni, qi) >= len(r):
            continue
        nm, q = r[ni].strip(), r[qi].strip()
        if not nm or not re.search(r"\d", q) or _VD_SKIP.match(nm.lower()) and "итого" in nm.lower():
            continue
        u = r[ui].strip() if 0 <= ui < len(r) else ""
        out.append({"name": nm, "qty": (q.replace(" ", "") + " " + u).strip()})
    return out


def _vd_meta(text: str, name: str) -> dict[str, str]:
    meta = {"date": "", "doc_no": "", "supplier": "", "kind": ""}
    _MON = {"января": 1, "февраля": 2, "марта": 3, "апреля": 4, "мая": 5, "июня": 6, "июля": 7, "августа": 8, "сентября": 9, "октября": 10, "ноября": 11, "декабря": 12}
    mt = re.search(r"\bот\s+[«\"]?(\d{1,2})[»\"]?\s+([а-я]+)\s+(\d{4})", text[:3000], re.I)
    if mt and mt.group(2).lower() in _MON:
        try:
            meta["date"] = date(int(mt.group(3)), _MON[mt.group(2).lower()], int(mt.group(1))).isoformat()
        except ValueError:
            pass
    m = None
    if not meta["date"]:
        clean = re.sub(r"постановлен\w+[^\n]{0,120}?\d{2}[.]\d{2}[.]\d{4}", " ", text, flags=re.I)
        cand = [x for x in re.finditer(r"(?:(?:от|дата)\s*[:]?\s*)?(\d{2})[.](\d{2})[.](\d{4})", clean) if 2015 <= int(x.group(3)) <= date.today().year + 1]
        m = next((x for x in cand if re.match(r"(?:от|дата)", x.group(0), re.I)), cand[0] if cand else None)
    if m:
        try:
            meta["date"] = date(int(m.group(3)), int(m.group(2)), int(m.group(1))).isoformat()
        except ValueError:
            pass
    nm_kind = re.match(r"\s*(УПД|сч[её]т на оплату|товарн\w+ накладн\w+|накладн\w+|ТТН)\s*(?:№|N|No)\s*([\w\-/]+)", name, re.I)
    k = re.search(r"(универсальн\w+ передаточн\w+ документ|УПД|сч[её]т на оплату|товарн\w+ накладн\w+|ТТН|накладн\w+|паспорт\w*|сертификат\w*|счет-фактур\w+|счёт-фактур\w+|акт приёмки|акт приемки)", text[:3000], re.I)
    if nm_kind:
        meta["kind"] = nm_kind.group(1).upper() if nm_kind.group(1).lower() == "упд" else nm_kind.group(1)
        meta["doc_no"] = nm_kind.group(2)
    elif k:
        meta["kind"] = k.group(1)
        m2 = None if nm_kind else re.search(re.escape(k.group(1)) + r"\s*(?:№|N|No)\s*([\w\-/]+)", text[:3000], re.I)
        if m2:
            meta["doc_no"] = m2.group(1)
    if not meta["doc_no"]:
        m3 = re.search(r"(?:№|N)\s*([\w\-/]{2,20})\s*от", text[:3000])
        if m3:
            meta["doc_no"] = m3.group(1)
    vt = re.search(r"(?:действител\w+|годен|срок\w*\s+действия|действует)\s*(?:до|по)\s*(\d{2})[.](\d{2})[.](\d{4})", text, re.I)
    if vt:
        try:
            meta["valid_to"] = date(int(vt.group(3)), int(vt.group(2)), int(vt.group(1))).isoformat()
        except ValueError:
            pass
    _ORG = r"((?:ООО|АО|ПАО|ЗАО|ИП)\s*[«\"“]?[^,\n;]{2,70}?[»\"”]?)(?=\s*(?:,|;|\n|ИНН|\(|$))"
    sm = re.search(r"(?:поставщик|продавец|исполнитель)\s*(?:\([^)]*\))?\s*[:.]?\s*" + _ORG, text[:4000], re.I)
    if not sm:
        for cand in re.finditer(_ORG, text[:4000]):
            ctx = text[max(0, cand.start() - 30):cand.end() + 40].lower()
            if re.search(r"банк|бик", ctx) or re.search(r"покупател|плательщик|получател|грузополуч", text[max(0, cand.start() - 25):cand.start()].lower()):
                continue
            sm = cand
            break
    if sm:
        meta["supplier"] = " ".join(sm.group(1).split())
    return meta


# --- Разбор таблицы счёта / накладной / УПД в PDF по координатам слов (колонки по шапке таблицы)
_OKEI = {"796": "шт", "006": "м", "055": "м2", "113": "м3", "168": "т", "166": "кг", "163": "г", "112": "л", "839": "компл", "778": "упак", "625": "лист", "736": "рул", "384": "упак"}


def _hdr_kind(w: str) -> str:
    t = w.lower().strip(".,:;()")
    if t in ("№", "п/п", "no"):
        return "num"
    if t in ("артикул", "код") or t.startswith("артикул"):
        return "art"
    if t in ("товары", "товар", "наименование", "номенклатура", "материалы", "материал") or t.startswith("наименован"):
        return "name"
    if t.startswith("кол"):
        return "qty"
    if t in ("ед", "единица", "ед-ца") or t.startswith("ед.") or t.startswith("единиц"):
        return "unit"
    if t.startswith("цена"):
        return "price"
    if t in ("сумма", "стоимость") or t.startswith("стоимост"):
        return "sum"
    return ""


def _pdf_words(path: Path, maxpages: int = 15) -> list[list[tuple[float, float, float, float, str]]]:
    pages: list[list[tuple[float, float, float, float, str]]] = []
    try:
        import pdfplumber  # type: ignore
        with pdfplumber.open(str(path)) as pdf:
            for pg in pdf.pages[:maxpages]:
                pages.append([(w["x0"], w["x1"], w["top"], w["bottom"], w["text"]) for w in pg.extract_words(x_tolerance=2, y_tolerance=2)])
        return pages
    except ImportError:
        pass
    from pypdf import PdfReader
    for pg in PdfReader(str(path)).pages[:maxpages]:
        fr: list[tuple[float, float, float, float, str]] = []

        def vis(text: str, cm: Any, tm: Any, fd: Any, fs: Any) -> None:
            if not text or not text.strip():
                return
            x = tm[4] * cm[0] + tm[5] * cm[2] + cm[4]
            y = tm[4] * cm[1] + tm[5] * cm[3] + cm[5]
            f = float(fs or 10)
            for m in re.finditer(r"\S+", text):
                fr.append((x + m.start() * f * 0.5, x + m.end() * f * 0.5, -y, -y + f, m.group()))
        pg.extract_text(visitor_text=vis)
        pages.append(fr)
    return pages


def _tbl_lines(words: list[tuple[float, float, float, float, str]]) -> list[dict[str, Any]]:
    lines: list[dict[str, Any]] = []
    for w in sorted(words, key=lambda w: (w[2], w[0])):
        h = max(w[3] - w[2], 6.0)
        if lines and abs(w[2] - lines[-1]["top"]) <= h * 0.6:
            lines[-1]["w"].append(w)
        else:
            lines.append({"top": w[2], "w": [w]})
    for ln in lines:
        ln["w"].sort(key=lambda w: w[0])
        ln["t_orig"] = " ".join(x[4] for x in ln["w"])
        ln["t"] = ln["t_orig"].lower()
    return lines


def _tbl_geo(lines: list[dict[str, Any]]) -> Optional[tuple[int, dict[str, tuple[float, float, float, float, str]]]]:
    for i in range(len(lines)):
        band = [lines[i]]
        for j in range(i + 1, min(i + 4, len(lines))):
            if lines[j]["top"] - band[-1]["top"] <= 30:
                band.append(lines[j])
            else:
                break
        hits: dict[str, tuple[float, float, float, float, str]] = {}
        for ln in band:
            for w in ln["w"]:
                k = _hdr_kind(w[4])
                if k and k not in hits:
                    hits[k] = w
        if "name" in hits and "qty" in hits:
            return i, hits
    return None


def _tbl_body(lines: list[dict[str, Any]], start: int, hits: dict[str, tuple[float, float, float, float, str]]) -> list[dict[str, str]]:
    rcols = {k: hits[k] for k in ("qty", "unit", "price", "sum") if k in hits}
    bound_r = min(w[0] for w in rcols.values()) - 10
    name_x0 = hits["name"][0] - 6
    centers = {k: (w[0] + w[1]) / 2 for k, w in rcols.items()}
    rows: list[dict[str, Any]] = []
    cur: Optional[dict[str, Any]] = None
    started = False
    after_hdr = False
    pre: list[str] = []
    for ln in lines[start:]:
        lw = ln["w"]
        left = [w for w in lw if w[1] <= name_x0 + 1]
        right = [w for w in lw if (w[0] + w[1]) / 2 >= bound_r]
        mid = [w for w in lw if w not in left and w not in right]
        if len(lw) >= 4 and sum(1 for w in lw if re.fullmatch(r"\d{1,2}[а-яa-z]?", w[4])) >= 0.8 * len(lw):
            after_hdr = True
            continue          # строка с номерами граф таблицы (1, 1а, 2, 2а, 3 …) в УПД
        has_num = any(re.fullmatch(r"\d{1,3}", w[4]) for w in left)
        has_q = any(re.search(r"\d", w[4]) for w in right)
        if not started:
            if not (has_num or has_q):
                if after_hdr and mid:
                    pre.append(" ".join(w[4] for w in mid))      # начало названия выше строки с номером
                continue          # продолжение шапки таблицы
            started = True
        if re.search(r"итого|всего|сумма прописью|в том числе|всего наименован", ln["t"]) and not has_num:
            break
        new = has_num if ("num" in hits or left) else (has_q and (cur is None or bool(cur["cols"].get("qty"))))
        if new and cur is not None and not cur["cols"].get("qty") and not has_q:
            new = False       # у предыдущей строки ещё нет количества — это продолжение её названия
        if new or cur is None:
            cur = {"name": list(pre) if not rows else [], "cols": {}, "art": []}
            rows.append(cur)
        cur["name"].append(" ".join(w[4] for w in mid))
        cur["art"] += [w[4] for w in left if not re.fullmatch(r"\d{1,3}", w[4]) or "art" in hits and w[0] > hits["art"][0] - 8]
        for w in right:
            k = min(centers, key=lambda c: abs(centers[c] - (w[0] + w[1]) / 2))
            cur["cols"].setdefault(k, []).append(w[4])
    out = []
    merged: list[dict[str, Any]] = []
    for r in rows:      # строка без количества — продолжение названия предыдущей
        if merged and not re.search(r"\d", "".join(r["cols"].get("qty", []))):
            merged[-1]["name"] += r["name"]
            for k, v in r["cols"].items():
                merged[-1]["cols"].setdefault(k, []).extend(v)
        else:
            merged.append(r)
    for r in merged:
        name = " ".join(" ".join(r["name"]).split())
        qty = "".join(r["cols"].get("qty", []))
        unit_w = [x for x in r["cols"].get("unit", []) if not x.isdigit() and not re.fullmatch(r"\d+[а-яa-z]", x)]
        unit = "".join(unit_w)
        mq = re.search(r"\d[\d.,]*", qty)
        if mq and not qty[:1].isdigit():
            qty = qty[mq.start():]
        if not unit:
            m = re.search(r"[A-Za-zА-Яа-я.]+$", qty)
            if m:
                unit, qty = m.group(0), qty[:m.start()]
        if len(re.findall(r"[A-Za-zА-Яа-я]", name)) >= 3 and re.search(r"\d", qty):
            out.append({"name": name.strip(" .;,-–"), "qty": (qty + " " + unit).strip()})
    return out


def _pdf_table(path: Path) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    geo: Optional[dict[str, tuple[float, float, float, float, str]]] = None
    for words in _pdf_words(path):
        lines = _tbl_lines(words)
        g = _tbl_geo(lines)
        if g:
            geo = g[1]
            rows += _tbl_body(lines, g[0] + 1, geo)
        elif geo:
            rows += _tbl_body(lines, 0, geo)
    return rows


def ocr_available() -> bool:
    return bool(shutil.which("tesseract"))


def _ocr_image(path: Path) -> str:
    import subprocess
    r = subprocess.run(["tesseract", str(path), "stdout", "-l", "rus+eng", "--psm", "6"], capture_output=True, text=True, timeout=120)
    return r.stdout or ""


def _ocr_pdf(path: Path) -> str:
    import subprocess
    import tempfile
    if not shutil.which("pdftoppm"):
        return ""
    with tempfile.TemporaryDirectory() as td:
        subprocess.run(["pdftoppm", "-r", "200", "-l", "8", "-png", str(path), td + "/p"], capture_output=True, timeout=180)
        return "\n".join(_ocr_image(Path(td) / f) for f in sorted(os.listdir(td)) if f.endswith(".png"))


_Q_RE = re.compile(r"паспорт|сертификат|свидетельств|декларац\w+\s+о\s+соответств|протокол\s+испытан|заключени\w+\s+о\s+качеств|санитарно|гигиеническ", re.I)
_I_RE = re.compile(r"накладн|упд|универсальн\w+\s+передаточн|сч[её]т|ттн|товарно-транспортн|акт\s+приём|акт\s+прием", re.I)


def _vd_class(name: str, text: str) -> str:
    """Приходный документ (накладная, УПД, счёт) или документ качества (паспорт, сертификат, свидетельство)."""
    head = name + " " + text[:1500]
    q, i = len(_Q_RE.findall(head)), len(_I_RE.findall(head))
    if _Q_RE.search(name) and not _I_RE.search(name):
        return "quality"
    return "quality" if q > i and q >= 1 else "income"


def _q_ref(meta: dict[str, Any], name: str) -> str:
    kind = (meta.get("kind") or "Документ качества").strip()
    kind = kind[:1].upper() + kind[1:]
    d = meta.get("date") or ""
    return kind + (" № " + meta["doc_no"] if meta.get("doc_no") else "") + (" от " + ".".join(reversed(d.split("-"))) if d else "") + ("" if meta.get("doc_no") else " (" + name[:40] + ")")


def _recognize(path: Path, name: str) -> dict[str, Any]:
    ext = name.rsplit(".", 1)[-1].lower() if "." in name else ""
    text, rows, method = "", [], "none"
    try:
        if ext == "pdf":
            from pypdf import PdfReader
            rd = PdfReader(str(path))
            text = "\n".join((pg.extract_text() or "") for pg in rd.pages[:40])
            method = "pdf-text" if text.strip() else "scan"
            if text.strip():
                try:
                    rows = _pdf_table(path)
                    if rows:
                        method = "pdf-table"
                        text = "\n".join(ln["t_orig"] for pw in _pdf_words(path, 3) for ln in _tbl_lines(pw)) or text
                except Exception:  # noqa: BLE001
                    rows = []
            if not text.strip() and ocr_available():
                text = _ocr_pdf(path)
                method = "ocr" if text.strip() else "scan"
        elif ext == "docx":
            import docx  # python-docx
            d = docx.Document(str(path))
            tb: list[list[str]] = []
            for t in d.tables:
                tb = [[c.text.strip() for c in r.cells] for r in t.rows]
                rows += _vd_table(tb)
            text = "\n".join(p_.text for p_ in d.paragraphs) + "\n" + "\n".join(" ".join(r) for t in d.tables for r in ([[c.text for c in rr.cells] for rr in t.rows]))
            method = "docx"
        elif ext in ("txt", "csv", "md"):
            raw = path.read_bytes()
            for enc in ("utf-8-sig", "cp1251"):
                try:
                    text = raw.decode(enc)
                    break
                except UnicodeDecodeError:
                    continue
            method = "text"
        elif ext == "xml":
            import xml.etree.ElementTree as ET
            root = ET.parse(str(path)).getroot()
            bits = []
            for el in root.iter():
                a = el.attrib
                if "НаимТов" in a:       # УПД / ТОРГ-12 в формате ФНС
                    q = a.get("КолТов", "")
                    un = a.get("НаимЕдИзм", "") or next((ch.get("НаимЕдИзм", "") for ch in el.iter() if ch.get("НаимЕдИзм")), "") or _OKEI.get(a.get("ОКЕИ_Тов", ""), "")
                    rows.append({"name": a["НаимТов"], "qty": (q + " " + un).strip()})
                if "НомерСчФ" in a or "НомерДок" in a:
                    bits.append("№ " + (a.get("НомерСчФ") or a.get("НомерДок", "")) + " от " + (a.get("ДатаСчФ") or a.get("ДатаДок", "")))
                if "НаимОрг" in a:
                    bits.append(a["НаимОрг"] + ",")
            text = " ".join(bits) + "\n" + " ".join(t.strip() for t in root.itertext() if t and t.strip())[:20000]
            method = "xml-upd" if rows else "xml"
        elif ext in ("jpg", "jpeg", "png", "tif", "tiff", "bmp", "webp", "heic"):
            method = "image"
            if ocr_available() and ext != "heic":
                text = _ocr_image(path)
                method = "ocr" if text.strip() else "image"
        else:
            method = "unknown"
    except Exception as ex:  # noqa: BLE001
        method, text = "error:" + type(ex).__name__, ""
    if not rows and text:
        rows = _vd_lines(text)
    return {"text": text, "cls": _vd_class(name, text), "rows": rows[:200], "meta": _vd_meta(text, name) if text else {"date": "", "doc_no": "", "supplier": "", "kind": ""}, "method": method}


@app.post("/api/vhk-docs", status_code=201)
async def vhk_doc_upload(request: Request, name: str, section: Optional[str] = None) -> dict[str, Any]:
    FILES_DIR.mkdir(parents=True, exist_ok=True)
    tmp = FILES_DIR / f"tmp-{uuid.uuid4().hex}"
    h, size = hashlib.sha256(), 0
    try:
        with open(tmp, "wb") as f:
            async for chunk in request.stream():
                size += len(chunk)
                if size > 40 * 1024 * 1024:
                    raise HTTPException(413, "Файл больше 40 МБ")
                h.update(chunk)
                f.write(chunk)
        if size == 0:
            raise HTTPException(400, "Пустой файл")
        nm = os.path.basename(name)[:200] or "документ"
        with db() as c:
            sec = _section(c, section)
            dup = c.execute("SELECT id FROM vhk_docs WHERE section_id=? AND sha256=?", (sec["id"], h.hexdigest())).fetchone()
            if dup:
                return {"id": dup["id"], "duplicate": True}
            did = str(uuid.uuid4())
            shutil.copyfile(tmp, FILES_DIR / ("vd-" + did))
        rec = await run_in_threadpool(_recognize, FILES_DIR / ("vd-" + did), nm)
        with db() as c:
            c.execute("INSERT INTO vhk_docs (id,section_id,name,size,sha256,method,meta_json,rows_json,text_head,uploaded_by,uploaded_at,cls) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
                      (did, sec["id"], nm, size, h.hexdigest(), rec["method"], json.dumps(rec["meta"], ensure_ascii=False), json.dumps(rec["rows"], ensure_ascii=False),
                       rec["text"][:20000], (getattr(request.state, "user", "") or "")[:80], now(), rec["cls"]))
        return {"id": did, "duplicate": False}
    finally:
        tmp.unlink(missing_ok=True)


@app.get("/api/vhk-docs")
def vhk_docs_list(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        num = {r["id"]: i + 1 for i, r in enumerate(c.execute("SELECT id FROM input_control WHERE section_id=? ORDER BY delivered_on, created_at", (sec["id"],)))}
        ent: dict[str, list[int]] = {}
        for tb in ("vhk_doc_rows", "vhk_quality"):
            for r in c.execute(f"SELECT r.doc_id, r.vhk_id FROM {tb} r JOIN vhk_docs d ON d.id=r.doc_id WHERE d.section_id=?", (sec["id"],)):
                if r["vhk_id"] in num:
                    ent.setdefault(r["doc_id"], []).append(num[r["vhk_id"]])
        out = []
        for r in c.execute("SELECT * FROM vhk_docs WHERE section_id=? ORDER BY uploaded_at DESC", (sec["id"],)):
            m = json.loads(r["meta_json"] or "{}")
            out.append({"id": r["id"], "name": r["name"], "method": r["method"], "at": r["uploaded_at"], "by": r["uploaded_by"], "size": r["size"],
                        "entries": sorted(ent.get(r["id"], [])), "filed": len(ent.get(r["id"], [])), "found": len(json.loads(r["rows_json"] or "[]")),
                        "kind": m.get("kind", ""), "doc_no": m.get("doc_no", ""), "doc_date": m.get("date", ""), "supplier": m.get("supplier", ""), "valid_to": m.get("valid_to", ""), "cls": r["cls"] or "income"})
        total = c.execute("SELECT COUNT(*) FROM input_control WHERE section_id=?", (sec["id"],)).fetchone()[0]
        with_doc = c.execute("SELECT COUNT(DISTINCT x) FROM (SELECT r.vhk_id x FROM vhk_doc_rows r JOIN input_control i ON i.id=r.vhk_id WHERE i.section_id=? UNION SELECT q.vhk_id FROM vhk_quality q JOIN input_control i ON i.id=q.vhk_id WHERE i.section_id=?)", (sec["id"], sec["id"])).fetchone()[0]
        with_q = c.execute("SELECT COUNT(DISTINCT q.vhk_id) FROM vhk_quality q JOIN input_control i ON i.id=q.vhk_id WHERE i.section_id=?", (sec["id"],)).fetchone()[0]
        return {"docs": out, "entries_total": total, "entries_with_doc": with_doc, "entries_with_quality": with_q}


def _vd_row(c: sqlite3.Connection, sec: sqlite3.Row, did: str) -> sqlite3.Row:
    r = c.execute("SELECT * FROM vhk_docs WHERE id=? AND section_id=?", (did, sec["id"])).fetchone()
    if not r:
        raise HTTPException(404, "Документ не найден")
    return r


@app.get("/api/vhk-docs/one")
def vhk_doc_one(id: str, section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        r = _vd_row(c, sec, id)
        its = _expected_items(c, sec)["items"]
        rows = json.loads(r["rows_json"] or "[]")
        learned = {_mnorm(l["name"]).strip(): l["item_key"] for l in c.execute(
            "SELECT i.name, k.item_key FROM vhk_link k JOIN input_control i ON i.id=k.vhk_id WHERE k.section_id=? AND k.item_key<>'' ORDER BY k.linked_at", (sec["id"],))}
        for x in rows:
            n_, u_ = _parse_qty(x.get("qty", ""))
            x["num"], x["unit"] = (n_ or ""), u_
            cs = _suggest(x["name"], u_, its, learned=learned)
            x["cands"] = cs
            top = cs[0]["score"] if cs else 0
            x["est"] = cs[0]["key"] if cs and top >= 0.6 and (len(cs) < 2 or top - cs[1]["score"] >= 0.1) else ""
        filed = [{"id": x["vhk_id"]} for x in c.execute("SELECT vhk_id FROM vhk_doc_rows WHERE doc_id=?", (id,))]
        meta = json.loads(r["meta_json"] or "{}")
        linked = {x["vhk_id"] for x in c.execute("SELECT vhk_id FROM vhk_quality WHERE doc_id=?", (id,))}
        jr = []
        dt = _wtok(r["text_head"] or "") | _wtok(r["name"])
        for n, e in enumerate(c.execute("SELECT id,name,qty,delivered_on,supplier FROM input_control WHERE section_id=? ORDER BY delivered_on, created_at", (sec["id"],)), 1):
            et = {t for t in _wtok(e["name"]) if t[0] == "w" or len(t[1]) >= 2}
            sc = round(sum(_wgt(t) for t in et & dt) / max(sum(_wgt(t) for t in et), 0.01), 2) if et else 0
            jr.append({"id": e["id"], "n": n, "name": e["name"], "qty": e["qty"], "date": e["delivered_on"], "supplier": e["supplier"], "score": sc, "linked": e["id"] in linked})
        return {"id": r["id"], "cls": r["cls"] or "income", "journal": jr, "ref": _q_ref(meta, r["name"]), "name": r["name"], "method": r["method"], "meta": meta, "rows": rows, "text": r["text_head"][:4000],
                "items": [{"key": i["key"], "name": i["name"], "units": i["units"], "group": i["group"]} for i in its], "filed": len(filed), "ocr": ocr_available()}


@app.get("/api/vhk-docs/file")
def vhk_doc_file(id: str, section: Optional[str] = None) -> FileResponse:
    with db() as c:
        sec = _section(c, section)
        r = _vd_row(c, sec, id)
    fp = FILES_DIR / ("vd-" + id)
    if not fp.exists():
        raise HTTPException(404, "Файл не найден")
    n = r["name"].lower()
    mt = "application/pdf" if n.endswith(".pdf") else ("image/png" if n.endswith(".png") else ("image/jpeg" if n.endswith((".jpg", ".jpeg")) else "application/octet-stream"))
    return FileResponse(fp, media_type=mt, content_disposition_type="inline" if mt != "application/octet-stream" else "attachment", filename=r["name"])


class VdClass(BaseModel):
    id: str
    cls: Literal["income", "quality"]


@app.post("/api/vhk-docs/class")
def vhk_doc_class(p: VdClass, section: Optional[str] = None) -> dict[str, str]:
    with db() as c:
        sec = _section(c, section)
        _vd_row(c, sec, p.id)
        if p.cls == "quality" and c.execute("SELECT 1 FROM vhk_doc_rows WHERE doc_id=?", (p.id,)).fetchone():
            raise HTTPException(409, "По документу уже созданы записи журнала — сменить тип нельзя")
        c.execute("UPDATE vhk_docs SET cls=? WHERE id=?", (p.cls, p.id))
    return {"ok": "1"}


class VdLinks(BaseModel):
    id: str
    vhk_ids: list[str] = Field(default_factory=list, max_length=500)
    ref: str = Field(default="", max_length=200)


@app.post("/api/vhk-docs/links")
def vhk_doc_links(request: Request, p: VdLinks, section: Optional[str] = None) -> dict[str, Any]:
    """Привязка документа качества к записям ЖВК; название документа попадает в графу «Документ изготовителя»."""
    with db() as c:
        sec = _section(c, section)
        dr = _vd_row(c, sec, p.id)
        _doc_lock(c, sec["id"], "vhk")
        ok = {x["id"] for x in c.execute("SELECT id FROM input_control WHERE section_id=?", (sec["id"],))}
        want = {x for x in p.vhk_ids if x in ok}
        have = {x["vhk_id"] for x in c.execute("SELECT vhk_id FROM vhk_quality WHERE doc_id=?", (p.id,))}
        ref = (p.ref or _q_ref(json.loads(dr["meta_json"] or "{}"), dr["name"])).strip()
        for vid in want - have:
            c.execute("INSERT OR IGNORE INTO vhk_quality (doc_id,vhk_id) VALUES (?,?)", (p.id, vid))
            row = c.execute("SELECT doc_ref,name FROM input_control WHERE id=?", (vid,)).fetchone()
            cur = (row["doc_ref"] or "").strip()
            if ref not in cur:
                c.execute("UPDATE input_control SET doc_ref=?, updated_at=? WHERE id=?", ((cur + "; " if cur else "") + ref, now(), vid))
            audit(request, c, "vhk", vid, "update", "Журнал входного контроля: к записи «" + row["name"][:60] + "» привязан документ качества «" + ref[:80] + "»", {"Документ изготовителя": [cur, ref]}, section_id=sec["id"])
        for vid in have - want:
            c.execute("DELETE FROM vhk_quality WHERE doc_id=? AND vhk_id=?", (p.id, vid))
            row = c.execute("SELECT doc_ref FROM input_control WHERE id=?", (vid,)).fetchone()
            if row and ref in (row["doc_ref"] or ""):
                parts = [x.strip() for x in (row["doc_ref"] or "").split(";") if x.strip() and x.strip() != ref]
                c.execute("UPDATE input_control SET doc_ref=?, updated_at=? WHERE id=?", ("; ".join(parts), now(), vid))
        return {"linked": len(want)}


class VdRow(BaseModel):
    name: str = Field(min_length=1, max_length=500)
    qty: str = Field(default="", max_length=120)
    delivered_on: str = Field(min_length=10, max_length=10)
    supplier: str = Field(default="", max_length=300)
    doc_ref: str = Field(default="", max_length=600)
    note: str = Field(default="", max_length=400)
    est: str = Field(default="", max_length=40)


class VdRows(BaseModel):
    id: str
    rows: list[VdRow] = Field(min_length=1, max_length=200)


@app.post("/api/vhk-docs/rows", status_code=201)
def vhk_doc_rows(request: Request, p: VdRows, section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        _doc_lock(c, sec["id"], "vhk")
        dr = _vd_row(c, sec, p.id)
        its = _expected_items(c, sec)["items"]
        keys = {i["key"] for i in its}
        for n, x in enumerate(p.rows, 1):
            if not x.est:
                raise HTTPException(422, f"Строка {n}: выберите позицию сметы или отметьте «Сверх сметы»")
            if x.est != "over" and x.est not in keys:
                raise HTTPException(422, f"Строка {n}: такой позиции нет в смете")
            try:
                date.fromisoformat(x.delivered_on)
            except ValueError as ex:
                raise HTTPException(422, f"Строка {n}: укажите дату доставки") from ex
        ids = []
        user = (getattr(request.state, "user", "") or "")[:80]
        for x in p.rows:
            d = {k: "" for k in VHK_FIELDS}
            d.update({"delivered_on": x.delivered_on, "name": x.name.strip(), "qty": x.qty.strip(), "supplier": x.supplier.strip(), "doc_ref": x.doc_ref.strip(),
                      "note": x.note.strip(), "doc_check": "Соответствует проектной документации и стандартам, повреждений нет", "instr_decision": "Не требуется", "instr_result": "—"})
            i = _vhk_insert(request, c, sec, d, "", " (из документа «" + dr["name"][:60] + "»)")
            _link_set(c, sec["id"], i, "" if x.est == "over" else x.est, user)
            c.execute("INSERT OR REPLACE INTO vhk_doc_rows (vhk_id,doc_id) VALUES (?,?)", (i, p.id))
            ids.append(i)
        return {"ids": ids}


@app.delete("/api/vhk-docs")
def vhk_doc_del(id: str, section: Optional[str] = None) -> dict[str, str]:
    with db() as c:
        sec = _section(c, section)
        _vd_row(c, sec, id)
        if c.execute("SELECT 1 FROM vhk_doc_rows WHERE doc_id=?", (id,)).fetchone():
            raise HTTPException(409, "По документу уже есть записи в журнале — сначала удалите их")
        c.execute("DELETE FROM vhk_docs WHERE id=?", (id,))
    (FILES_DIR / ("vd-" + id)).unlink(missing_ok=True)
    return {"message": "Удалено"}


def _vhk_header(c: sqlite3.Connection, sec: sqlite3.Row) -> dict[str, str]:
    p = c.execute("SELECT * FROM projects WHERE id=?", (sec["project_id"],)).fetchone()
    ppl = _act_people(c, sec["project_id"])
    our = p["our_role"] or ""
    org = (ppl.get(our, {}) if our else {}).get("org_name") or ppl.get("contractor", {}).get("org_name") or ppl.get("subcontractor", {}).get("org_name") or ""
    return {"object": p["object_name"], "address": p["address"] or "", "org": org}


def _vhk_rows(c: sqlite3.Connection, section_id: str) -> list[dict[str, Any]]:
    rows = c.execute("SELECT * FROM input_control WHERE section_id=? ORDER BY delivered_on, created_at", (section_id,)).fetchall()
    ph: dict[str, list[str]] = {}
    for r in c.execute("SELECT id, operation_id FROM photos WHERE operation_id LIKE 'vhk:%' ORDER BY uploaded_at"):
        ph.setdefault(r["operation_id"][4:], []).append(r["id"])
    ac: dict[str, list[dict[str, str]]] = {}
    for r in c.execute("SELECT ab.vhk_id, d.id, d.number, d.status FROM act_batches ab JOIN documents d ON d.id=ab.doc_id ORDER BY d.seq, d.created_at"):
        ac.setdefault(r["vhk_id"], []).append({"id": r["id"], "number": r["number"], "status": r["status"]})
    return [{**dict(r), "n": i + 1, "photos": ph.get(r["id"], []), "acts": ac.get(r["id"], [])} for i, r in enumerate(rows)]


@app.get("/api/vhk")
def vhk_list(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        items = _vhk_rows(c, sec["id"])
        hints: dict[str, list[str]] = {"name": [], "supplier": [], "doc_ref": []}
        for r in c.execute("SELECT name,supplier,doc_ref FROM input_control ORDER BY created_at DESC LIMIT 300"):
            for k in hints:
                v = (r[k] or "").strip()
                if v and v not in hints[k] and len(hints[k]) < 80:
                    hints[k].append(v)
        for r in c.execute("SELECT name FROM dict_orgs ORDER BY name"):
            if r["name"] not in hints["supplier"]:
                hints["supplier"].append(r["name"])
        its = _expected_items(c, sec)["items"]
        byk = {i["key"]: i for i in its}
        lk = {r["vhk_id"]: r["item_key"] for r in c.execute("SELECT vhk_id,item_key FROM vhk_link WHERE section_id=?", (sec["id"],))}
        dm: dict[str, list[dict[str, str]]] = {}
        for r in c.execute("SELECT r.vhk_id, d.id, d.name FROM vhk_doc_rows r JOIN vhk_docs d ON d.id=r.doc_id WHERE d.section_id=?", (sec["id"],)):
            dm.setdefault(r["vhk_id"], []).append({"id": r["id"], "name": r["name"]})
        qm: dict[str, list[dict[str, str]]] = {}
        for r in c.execute("SELECT q.vhk_id, d.id, d.name, d.meta_json FROM vhk_quality q JOIN vhk_docs d ON d.id=q.doc_id WHERE d.section_id=? ORDER BY d.uploaded_at", (sec["id"],)):
            mt = json.loads(r["meta_json"] or "{}")
            qm.setdefault(r["vhk_id"], []).append({"id": r["id"], "name": r["name"], "ref": _q_ref(mt, r["name"]), "valid_to": mt.get("valid_to", "")})
        for x in items:
            if x["id"] in lk:
                k = lk[x["id"]]
                st = "over" if k == "" else ("matched" if k in byk else "none")
            else:
                k = _auto_match(x["name"], its)
                st = "auto" if k in byk else "none"
            x["est"] = {"state": st if its or st == "over" else "", "name": byk[k]["name"] if k in byk else "", "key": k if k in byk else ""}
            x["docs"] = dm.get(x["id"], [])
            x["qdocs"] = qm.get(x["id"], [])
        hints["est_items"] = [{"key": i["key"], "name": i["name"], "units": i["units"], "group": i["group"]} for i in its]  # type: ignore[assignment]
        hints["est_required"] = bool(its)  # type: ignore[assignment]
        noact = [x["n"] for x in items if not x["acts"]]
        nodoc = [x["n"] for x in items if not (x["doc_ref"] or "").strip()]
        nophoto = [x["n"] for x in items if not x["photos"] and not x.get("qdocs")]
        acts_nob = [r["number"] for r in c.execute("SELECT d.number FROM documents d WHERE d.section_id=? AND d.document_type='АОСР' AND NOT EXISTS (SELECT 1 FROM act_batches ab WHERE ab.doc_id=d.id) ORDER BY d.seq, d.created_at", (sec["id"],))]
        return {"items": items, "header": _vhk_header(c, sec), "hints": hints, "section": sec["code"],
                "trace": {"no_act": noact, "no_doc": nodoc, "no_photo": nophoto, "acts_without_batches": acts_nob}}


def _vhk_supplier(c: sqlite3.Connection, name: str) -> None:
    """Поставщик, которого нет в справочнике организаций, добавляется туда; затем записи ЖВК связываются по идентификатору."""
    nm = " ".join(name.split())
    if nm and not c.execute("SELECT 1 FROM dict_orgs WHERE lower(name)=lower(?)", (nm,)).fetchone():
        c.execute("INSERT INTO dict_orgs (id,name,created_at) VALUES (?,?,?)", (str(uuid.uuid4()), nm, now()))
    _relink(c)


def _vhk_clean(p: VhkIn) -> dict[str, str]:
    try:
        date.fromisoformat(p.delivered_on)
    except ValueError as ex:
        raise HTTPException(422, "Укажите дату доставки") from ex
    return {k: str(getattr(p, k)).strip() for k in VHK_FIELDS}


def _est_decide(c: sqlite3.Connection, sec: sqlite3.Row, name: str, est: Optional[str], strict_empty: bool = True) -> Optional[str]:
    """Сопоставление со сметой при заведении: ключ позиции, '' (= сверх сметы) или None (ничего не записывать, подберётся автоматически)."""
    if est is None:
        return None
    its = _expected_items(c, sec)["items"]
    if est == "over":
        return ""
    if est == "":
        if not strict_empty or not its or _auto_match(name, its):
            return None
        raise HTTPException(422, "Укажите позицию сметы или отметьте «Сверх сметы» — материал без сопоставления в журнал не принимается")
    if est not in {i["key"] for i in its}:
        raise HTTPException(422, "Такой позиции нет в смете — выберите из списка или отметьте «Сверх сметы»")
    return est


def _link_set(c: sqlite3.Connection, sid: str, vid: str, key: str, user: str) -> None:
    c.execute("INSERT INTO vhk_link (vhk_id,section_id,item_key,linked_by,linked_at) VALUES (?,?,?,?,?) ON CONFLICT(vhk_id) DO UPDATE SET item_key=excluded.item_key, linked_by=excluded.linked_by, linked_at=excluded.linked_at",
              (vid, sid, key, user, now()))


def _vhk_insert(request: Request, c: sqlite3.Connection, sec: sqlite3.Row, d: dict[str, str], rid: str = "", note_src: str = "") -> str:
    i = str(uuid.uuid4())
    c.execute(f"INSERT INTO input_control (id,section_id,{','.join(VHK_FIELDS)},created_by,created_at,updated_at,client_request_id) VALUES (?,?,{','.join('?' * len(VHK_FIELDS))},?,?,?,?)",
              (i, sec["id"], *[d[k] for k in VHK_FIELDS], (getattr(request.state, "user", "") or "")[:80], now(), now(), rid))
    _vhk_supplier(c, d["supplier"])
    audit(request, c, "vhk", i, "create", "Журнал входного контроля: принят материал «" + d["name"][:80] + "»" + note_src, {"Наименование": ["", d["name"]], "Количество": ["", d["qty"]], "Поставщик": ["", d["supplier"]]}, section_id=sec["id"])
    return i


@app.post("/api/vhk", status_code=201)
def vhk_add(request: Request, p: VhkIn, section: Optional[str] = None) -> dict[str, Any]:
    d = _vhk_clean(p)
    with db() as c:
        sec = _section(c, section)
        _doc_lock(c, sec["id"], "vhk")
        if p.rid:
            old = c.execute("SELECT id FROM input_control WHERE client_request_id=?", (p.rid,)).fetchone()
            if old:
                return {"id": old["id"], "duplicate": True}
        dec = _est_decide(c, sec, d["name"], p.est)
        i = _vhk_insert(request, c, sec, d, p.rid)
        if dec is not None:
            _link_set(c, sec["id"], i, dec, (getattr(request.state, "user", "") or "")[:80])
    return {"id": i}


@app.put("/api/vhk/{rid}")
def vhk_put(request: Request, rid: str, p: VhkIn) -> dict[str, str]:
    d = _vhk_clean(p)
    with db() as c:
        old = c.execute("SELECT * FROM input_control WHERE id=?", (rid,)).fetchone()
        if not old:
            raise HTTPException(404, "Запись не найдена")
        _doc_lock(c, old["section_id"], "vhk")
        if p.base and p.base != old["updated_at"]:
            raise HTTPException(409, "Запись уже изменена другим пользователем (" + (old["updated_at"] or "")[:16].replace("T", " ") + "). Закройте окно, обновите страницу и повторите правку")
        c.execute(f"UPDATE input_control SET {','.join(k + '=?' for k in VHK_FIELDS)}, updated_at=? WHERE id=?", (*[d[k] for k in VHK_FIELDS], now(), rid))
        if d["supplier"].lower() != (old["supplier"] or "").lower():
            c.execute("UPDATE input_control SET supplier_id='' WHERE id=?", (rid,))
        _vhk_supplier(c, d["supplier"])
        if p.est:
            _link_set(c, old["section_id"], rid, _est_decide(c, _section(c, old["section_id"]), d["name"], p.est) or "", (getattr(request.state, "user", "") or "")[:80])
        df = _diff(dict(old), d, VHK_LABELS)
        if df:
            audit(request, c, "vhk", rid, "update", "Журнал входного контроля: изменена запись «" + old["name"][:80] + "»", df, section_id=old["section_id"])
    return {"message": "Сохранено"}


@app.delete("/api/vhk/{rid}")
def vhk_del(request: Request, rid: str) -> dict[str, str]:
    with db() as c:
        pids = [r["id"] for r in c.execute("SELECT id FROM photos WHERE operation_id=?", ("vhk:" + rid,))]
        old = c.execute("SELECT * FROM input_control WHERE id=?", (rid,)).fetchone()
        if not old:
            raise HTTPException(404, "Запись не найдена")
        _doc_lock(c, old["section_id"], "vhk")
        used = [r["number"] for r in c.execute("SELECT d.number FROM act_batches ab JOIN documents d ON d.id=ab.doc_id WHERE ab.vhk_id=?", (rid,))]
        if used:
            raise HTTPException(409, "Запись использована в актах АОСР № " + ", ".join(used) + " — сначала уберите её из актов")
        c.execute("DELETE FROM input_control WHERE id=?", (rid,))
        audit(request, c, "vhk", rid, "delete", "Журнал входного контроля: удалена запись «" + old["name"][:80] + "»", {k: [str(old[k] or ""), ""] for k in ("name", "qty", "supplier", "doc_ref")}, section_id=old["section_id"])
        c.execute("DELETE FROM photos WHERE operation_id=?", ("vhk:" + rid,))
    for pid in pids:
        try:
            (PHOTOS_DIR / pid).unlink()
        except OSError:
            pass
    return {"message": "Удалено"}


def build_vhk_docx(head: dict[str, str], items: list[dict[str, Any]]) -> bytes:
    import io
    from docx import Document
    from docx.enum.section import WD_ORIENT
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn
    from docx.shared import Mm, Pt
    doc = Document()
    st = doc.styles["Normal"]
    st.font.name = "Times New Roman"
    st.font.size = Pt(11)
    st.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    sec = doc.sections[0]
    sec.orientation = WD_ORIENT.LANDSCAPE
    sec.page_width, sec.page_height = Mm(297), Mm(210)
    sec.left_margin, sec.right_margin, sec.top_margin, sec.bottom_margin = Mm(20), Mm(10), Mm(15), Mm(15)

    def para(text="", size=11, bold=False, align=None, before=0, after=4):
        p = doc.add_paragraph()
        p.paragraph_format.space_before, p.paragraph_format.space_after = Pt(before), Pt(after)
        if align:
            p.alignment = align
        r = p.add_run(text)
        r.font.size, r.bold = Pt(size), bold
        return p
    C = WD_ALIGN_PARAGRAPH.CENTER
    para("Рекомендуемая форма (Приложение Г к СП 543.1325800.2024)", 9, align=WD_ALIGN_PARAGRAPH.RIGHT)
    para("", after=40)
    para("ЖУРНАЛ", 20, True, C, after=6)
    para("входного контроля и контроля качества получаемых деталей, материалов, изделий, конструкций и оборудования", 14, True, C, after=40)
    for lab, val in (("Наименование объекта", head["object"]), ("Адрес объекта", head["address"]), ("Наименование строительной организации", head["org"])):
        para(f"{lab}: {val or '________________________________________'}", 12, after=8)
    first = min((i["delivered_on"] for i in items), default="")
    fd = (lambda d: f"{d[8:10]}.{d[5:7]}.{d[:4]}" if d else "«___» __________ 20__ г.")
    para(f"Начат {fd(first)}", 12, before=16, after=4)
    para("Окончен «___» __________ 20__ г.", 12, after=20)
    doc.add_page_break()
    heads = ["№ п/п", "Дата доставки", "Наименование деталей, материалов, изделий, конструкций, оборудования", "Количество", "Поставщик",
             "Наименование и номер документа изготовителя", "Результат проверки сопроводительных документов изготовителя и визуального осмотра на соответствие требованиям утвержденной проектной документации и соответствующим документам по стандартизации",
             "Решение о необходимости проведения инструментального контроля", "Результат инструментального контроля",
             "Подпись лица, осуществляющего контроль со стороны лица, осуществляющего строительство, и застройщика (технического заказчика)"]
    widths = [10, 20, 45, 20, 32, 38, 48, 28, 30, 36]
    t = doc.add_table(rows=2, cols=10)
    t.style = "Table Grid"
    t.autofit = False

    def cell(c, text, size=9, bold=False, center=False):
        c.text = ""
        p = c.paragraphs[0]
        p.paragraph_format.space_after = Pt(0)
        if center:
            p.alignment = C
        r = p.add_run(str(text))
        r.font.size, r.bold = Pt(size), bold
    for i, h in enumerate(heads):
        cell(t.rows[0].cells[i], h, 8, True, True)
        cell(t.rows[1].cells[i], str(i + 1), 8, False, True)
    for r in t.rows[:1]:
        trPr = r._tr.get_or_add_trPr()
        th = OxmlElement("w:tblHeader")
        th.set(qn("w:val"), "true")
        trPr.append(th)
    for it in items:
        cs = t.add_row().cells
        d = it["delivered_on"]
        sign = "\n".join(x for x in (it["controller"], it["customer_rep"]) if x)
        vals = [it["n"], f"{d[8:10]}.{d[5:7]}.{d[:4]}", it["name"], it["qty"], it["supplier"], it["doc_ref"], it["doc_check"], it["instr_decision"] or "Не требуется", it["instr_result"] or "—", sign]
        for i, v in enumerate(vals):
            cell(cs[i], v, 9, False, i in (0, 1, 3))
    for i, w in enumerate(widths):
        t.columns[i].width = Mm(w)
    for row in t.rows:
        for i, w in enumerate(widths):
            row.cells[i].width = Mm(w)
    para("", after=10)
    para("В журнале пронумеровано и прошнуровано __________ страниц", 11, before=10, after=6)
    para("«____» ______________________ 20___ г.", 11, after=14)
    para("_________________________________________________________________________", 11, after=0)
    para("(должность, фамилия, инициалы и подпись руководителя организации, выдавшего журнал)", 8, align=C, after=6)
    para("М.П.", 11)
    buf = io.BytesIO()
    doc.save(buf)
    return buf.getvalue()


@app.get("/api/vhk/docx")
def vhk_docx(section: Optional[str] = None) -> Response:
    with db() as c:
        sec = _section(c, section)
        head, items = _vhk_header(c, sec), _vhk_rows(c, sec["id"])
    blob = build_vhk_docx(head, items)
    from urllib.parse import quote
    return Response(blob, media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                    headers={"Content-Disposition": "attachment; filename*=UTF-8''" + quote("Журнал_входного_контроля_" + re.sub(r"[^\w.-]+", "_", sec["code"]) + ".docx")})


# ---------------------------------------------------------------- АОСР (акты освидетельствования скрытых работ)
HIDDEN_KW = re.compile(r"траншe|траншеи|основани|подготов|укладк|присып|засыпк|армирован|бетонир|гидроизол|герметиз|заделк|прокладк|монтаж|устройств|разработк|колодц|гнб|антикорр|обмазк|футляр|песчан", re.I)
NOT_HIDDEN_CODES = {"survey", "test", "accept"}


def is_hidden_work(raw: Any, code: str, title: str, element_name: str) -> bool:
    """Скрытая работа: решение пользователя (если есть), иначе по типу операции и ключевым словам."""
    if raw is not None:
        return bool(raw)
    if code in NOT_HIDDEN_CODES or re.search(r"съ[её]мк|испытан|проверк|принят|приёмк|акт", title, re.I):
        return False
    if code in ("trench", "bed", "lay", "sand", "backfill", "install"):
        return True
    return bool(HIDDEN_KW.search(title) or HIDDEN_KW.search(element_name or ""))


class HiddenIn(BaseModel):
    hidden: Optional[bool] = None


@app.put("/api/operations/{operation_id}/hidden")
def operation_hidden(operation_id: str, payload: HiddenIn) -> dict[str, str]:
    with db() as c:
        if not c.execute("SELECT 1 FROM operations WHERE id=?", (operation_id,)).fetchone():
            raise HTTPException(404, "Операция не найдена")
        c.execute("UPDATE operations SET hidden=? WHERE id=?", (None if payload.hidden is None else int(payload.hidden), operation_id))
    return {"message": "Сохранено"}


class OpEditIn(BaseModel):
    title: Optional[str] = None
    done: Optional[bool] = None
    performed_on: Optional[date] = None
    actor: str = ""
    reason: str = ""
    out_of_order: bool = False


@app.put("/api/operations/{operation_id}/edit")
def operation_edit(operation_id: str, payload: OpEditIn, request: Request) -> dict[str, Any]:
    """Правка строки «Выполнение работ»: операция, статус, дата. Всё фиксируется в журнале правок."""
    user = (getattr(request.state, "user", "") or "")[:80]
    reason = payload.reason.strip()
    with db() as c:
        op = c.execute("""SELECT o.id,o.title,el.code ecode,el.name ename,el.section_id FROM operations o JOIN elements el ON el.id=o.element_id WHERE o.id=?""", (operation_id,)).fetchone()
        if not op:
            raise HTTPException(404, "Операция не найдена")
        last = c.execute("SELECT * FROM events WHERE operation_id=? ORDER BY created_at DESC LIMIT 1", (operation_id,)).fetchone()
        is_done = bool(last and last["event_type"] == "complete")
        cur_date = last["performed_on"] if is_done else ""
        signed = [dict(r) for r in c.execute("""SELECT d.number FROM act_ops ao JOIN documents d ON d.id=ao.doc_id WHERE ao.operation_id=? AND d.status IN ('Подписан','В архиве')""", (operation_id,))]
        locked_msg = "Операция входит в подписанный акт №" + ", ".join(str(x["number"]) for x in signed) + ". Сначала верните акт в черновик."
        diffs: dict[str, list[str]] = {}
        log: list[tuple[str, str, str, str]] = []
        title = (payload.title if payload.title is not None else op["title"]).strip()
        if not title or len(title) > 300:
            raise HTTPException(400, "Название операции: от 1 до 300 символов")
        want_done = is_done if payload.done is None else payload.done
        new_date = payload.performed_on.isoformat() if payload.performed_on else ""
        if new_date and new_date > date.today().isoformat():
            raise HTTPException(400, "Дата выполнения не может быть в будущем")
        status_change = want_done != is_done
        date_change = bool(is_done and want_done and new_date and new_date != cur_date)
        if (status_change or date_change) and len(reason) < 5:
            raise HTTPException(400, "Укажите причину правки (не короче 5 символов)")
        if (status_change or date_change) and signed:
            raise HTTPException(409, locked_msg)
        event_id = last["id"] if last else ""
        if status_change:
            etype = "complete" if want_done else "undo"
            actor = payload.actor.strip() or user
            if not actor:
                raise HTTPException(400, "Укажите, кто выполнил")
            ops = c.execute("""SELECT o.id,o.title,(SELECT e.event_type FROM events e WHERE e.operation_id=o.id ORDER BY e.created_at DESC LIMIT 1) last
                FROM operations o WHERE o.element_id=(SELECT element_id FROM operations WHERE id=?) ORDER BY o.sort_order""", (operation_id,)).fetchall()
            idx = next(i for i, o in enumerate(ops) if o["id"] == operation_id)
            viol = ""
            if etype == "complete":
                miss = [o for o in ops[:idx] if o["last"] != "complete"]
                if miss:
                    viol = f"Нарушена последовательность: сначала нужно отметить «{miss[0]['title']}»"
            else:
                later = [o for o in ops[idx + 1:] if o["last"] == "complete"]
                if later:
                    viol = f"Нарушена последовательность: сначала снимите отметку «{later[-1]['title']}»"
            if viol and not payload.out_of_order:
                raise HTTPException(409, viol)
            event_id = str(uuid.uuid4())
            c.execute("INSERT INTO events VALUES (?,?,?,?,?,?,?,?)", (event_id, operation_id, etype, (new_date or date.today().isoformat()), actor,
                      ("[ВНЕ ОЧЕРЕДИ] " if viol else "") + "[Правка] " + reason, now(), str(uuid.uuid4())))
            diffs["Статус"] = ["Выполнено" if is_done else "Не отмечено", "Выполнено" if want_done else "Не отмечено"]
            log.append(("status", diffs["Статус"][0], diffs["Статус"][1], event_id))
            if want_done:
                diffs["Дата выполнения"] = ["", new_date or date.today().isoformat()]
                diffs["Исполнитель"] = ["", actor]
        elif date_change:
            c.execute("UPDATE events SET performed_on=? WHERE id=?", (new_date, event_id))
            diffs["Дата выполнения"] = [cur_date, new_date]
            log.append(("date", cur_date, new_date, event_id))
        if title != op["title"]:
            c.execute("UPDATE operations SET title=? WHERE id=?", (title, operation_id))
            diffs["Операция"] = [op["title"], title]
            log.append(("title", op["title"], title, ""))
        if not diffs:
            return {"message": "Изменений нет", "changed": False}
        for f, o, n, ev in log:
            c.execute("INSERT INTO op_edit_log (id,operation_id,event_id,field,old_value,new_value,reason,by_user,at) VALUES (?,?,?,?,?,?,?,?,?)",
                      (str(uuid.uuid4()), operation_id, ev, f, o, n, reason, user, now()))
        parts = [f"{k}: «{v[0] or '—'}» → «{v[1] or '—'}»" for k, v in diffs.items()]
        summary = f"Выполнение работ, {op['ecode']} · «{op['title']}»: " + "; ".join(parts) + (f". Причина: {reason}" if reason else "")
        audit(request, c, "operation", operation_id, "Правка строки работ", summary, diffs, section_id=op["section_id"])
    return {"message": "Сохранено", "changed": True}


MONTHS = ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"]
STD_HINTS = ["СП 45.13330.2017 «Земляные сооружения, основания и фундаменты»", "СП 129.13330.2019 «Наружные сети и сооружения водоснабжения и канализации»",
             "СП 399.1325800.2018 «Системы водоснабжения и канализации наружные из пластмассовых труб. Правила проектирования и монтажа»",
             "СП 70.13330.2012 «Несущие и ограждающие конструкции»", "СП 28.13330.2017 «Защита строительных конструкций от коррозии»"]


def _suffix(code: str) -> str:
    m = re.search(r"-([А-ЯЁA-Z]{2,6})\s*$", code.strip())
    return m.group(1) if m else re.sub(r"\W+", "", code)[:8] or "АОСР"


def _org_line(p: Optional[dict[str, Any]]) -> str:
    if not p or not p.get("org_name"):
        return ""
    parts = [p["org_name"]]
    if p.get("ogrn"):
        parts.append("ОГРН " + p["ogrn"])
    if p.get("inn"):
        parts.append("ИНН " + p["inn"])
    return ", ".join(parts)


def _org_addr(p: Optional[dict[str, Any]]) -> str:
    if not p:
        return ""
    return ", ".join(x for x in (p.get("address"), ("тел. " + p["phone"]) if p.get("phone") else "") if x)


def _rep_line(p: Optional[dict[str, Any]], with_nrs: bool = True) -> str:
    if not p or not p.get("rep_name"):
        return ""
    pos = (p.get("rep_position") or "").strip()
    org = (p.get("org_name") or "").strip()
    head = pos if (org and org in pos) or not org else f"{pos} {org}".strip()
    bits = [f"{head} {p['rep_name']}".strip()]
    if with_nrs and p.get("rep_nrs_id"):
        bits.append(p["rep_nrs_id"])
    if p.get("rep_order"):
        bits.append(p["rep_order"])
    return ", ".join(bits)


def _fmt_date_ru(iso: str) -> tuple[str, str, str]:
    try:
        d = date.fromisoformat(iso)
        return f"{d.day:02d}", MONTHS[d.month - 1], f"{d.year}"
    except Exception:  # noqa: BLE001
        return "__", "__________", "____"


def _act_people(c: sqlite3.Connection, project_id: str) -> dict[str, dict[str, Any]]:
    return {r["role"]: dict(r) for r in c.execute("SELECT * FROM participants WHERE project_id=?", (project_id,))}


def act_issues(c: sqlite3.Connection, project_id: str, d: dict[str, Any]) -> list[str]:
    out = []
    ppl = _act_people(c, project_id)
    for key, label, core in ROLES:
        if core and not (ppl.get(key, {}).get("org_name") and (ppl.get(key, {}).get("rep_name") or key not in SIGNERS)):
            out.append("участник: " + label)
    for k, t in (("drawing", "проектная документация"), ("materials", "материалы (или «Не применялись»)"), ("docs", "предъявленные документы"),
                 ("standards", "нормативные документы"), ("next_work", "последующие работы")):
        if not str(d.get(k, "")).strip():
            out.append(t)
    if not d.get("start") or not d.get("end"):
        out.append("даты работ")
    return out


def _executor(ppl: dict[str, dict[str, Any]]) -> tuple[str, Optional[dict[str, Any]]]:
    sub = ppl.get("subcontractor")
    if sub and sub.get("org_name"):
        return "subcontractor", sub
    return "contractor", ppl.get("contractor")


def build_aosr_docx(act: dict[str, Any], obj: dict[str, Any], ppl: dict[str, dict[str, Any]]) -> bytes:
    import io
    from docx import Document
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn
    from docx.shared import Mm, Pt
    d = act["data"]
    doc = Document()
    sec = doc.sections[0]
    sec.page_width, sec.page_height = Mm(210), Mm(297)
    sec.left_margin, sec.right_margin, sec.top_margin, sec.bottom_margin = Mm(20), Mm(10), Mm(10), Mm(10)
    st = doc.styles["Normal"]
    st.font.name = "Times New Roman"
    st.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    st.font.size = Pt(10)
    st.paragraph_format.space_after = Pt(0)
    st.paragraph_format.space_before = Pt(0)

    def para(text: str = "", size: float = 10, bold: bool = False, align: Any = None, italic: bool = False, line: bool = False, after: float = 0, before: float = 0):
        p = doc.add_paragraph()
        r = p.add_run(text)
        r.font.size = Pt(size); r.bold = bold; r.italic = italic
        if align is not None:
            p.alignment = align
        p.paragraph_format.space_after = Pt(after); p.paragraph_format.space_before = Pt(before)
        if line:
            ppr = p._p.get_or_add_pPr()
            b = OxmlElement("w:pBdr")
            bt = OxmlElement("w:bottom")
            for k, v in (("w:val", "single"), ("w:sz", "4"), ("w:space", "1"), ("w:color", "000000")):
                bt.set(qn(k), v)
            b.append(bt); ppr.append(b)
        return p

    CAP = 7.0

    def val(text: str, caption: str = "", blank_lines: int = 1):
        t = (text or "").strip()
        if not t:
            t = " "
        for i, ln in enumerate(t.split("\n")):
            para(ln, 10, line=True, before=2 if i == 0 else 0)
        if caption:
            para(caption, CAP, italic=False, align=WD_ALIGN_PARAGRAPH.CENTER, after=3)

    def label(text: str, bold: bool = False, before: float = 3):
        para(text, 10, bold=bold, before=before)

    para("Приложение N 3 к составу исполнительной документации при строительстве, реконструкции, капитальном ремонте объектов капитального строительства, "
         "утвержденному приказом Министерства строительства и жилищно-коммунального хозяйства Российской Федерации от 16 мая 2023г. N 344/пр", 7.5,
         align=WD_ALIGN_PARAGRAPH.RIGHT, after=4)
    label("Объект капитального строительства", before=0)
    val(obj.get("object_name", "") + ((", " + obj["cipher"]) if obj.get("cipher") else "") + ((", " + obj["address"]) if obj.get("address") and obj["address"] not in obj.get("object_name", "") else ""),
        "(наименование объекта капитального строительства в соответствии с проектной документацией, почтовый или строительный адрес объекта капитального строительства)")
    dev, tz = ppl.get("developer"), ppl.get("tech_customer")
    label("Застройщик, технический заказчик, лицо, ответственное за эксплуатацию здания, сооружения, или региональный оператор")
    val(_org_line(dev), "(фамилия, имя, отчество (последнее - при наличии), адрес места жительства, ОГРНИП, ИНН индивидуального предпринимателя,")
    val(_org_addr(dev) + ("\nв лице " + _org_line(tz) if tz and tz.get("org_name") else ""), "полное и (или) сокращенное наименование, ОГРН, ИНН, место нахождения юридического лица, телефон/факс;")
    val((dev or {}).get("sro", ""), "полное и (или) сокращенное наименование, ОГРН, ИНН саморегулируемой организации, членом которой является указанное юридическое лицо или индивидуальный предприниматель (за исключением случаем, когда членство в саморегулируемых организациях в области архитектурно-строительного проектирования не требуется)")
    con = ppl.get("contractor")
    label("Лицо, осуществляющее строительство, реконструкцию, капитальный ремонт")
    val(_org_line(con), "(фамилия, имя, отчество (последнее при наличии), адрес места жительства, ОГРНИП, ИНН индивидуального предпринимателя, полное и (или) сокращенное наименование, ОГРН, ИНН,")
    val(_org_addr(con), "адрес юридического лица в пределах его места нахождения, телефон или факс,")
    val((con or {}).get("sro", ""), "полное и (или) сокращенное наименование, ОГРН, ИНН саморегулируемой организации, членом которой является указанное юридическое лицо или индивидуальный предприниматель (за исключением случаем, когда членство в саморегулируемых организациях в области архитектурно-строительного проектирования не требуется)")
    des = ppl.get("designer")
    label("Лицо, осуществляющее подготовку проектной документации")
    val(_org_line(des), "(фамилия, имя, отчество (последнее при наличии), адрес места жительства, ОГРНИП, ИНН индивидуального предпринимателя, полное и (или) сокращенное наименование, ОГРН, ИНН,")
    val(_org_addr(des), "адрес юридического лица в пределах его места нахождения, телефон или факс,")
    val((des or {}).get("sro", ""), "полное и (или) сокращенное наименование, ОГРН, ИНН саморегулируемой организации, членом которой является указанное юридическое лицо или индивидуальный предприниматель (за исключением случаем, когда членство в саморегулируемых организациях в области архитектурно-строительного проектирования не требуется)")
    para("АКТ", 12, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, before=10)
    para("освидетельствования скрытых работ", 12, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER)
    dd, mm, yy = _fmt_date_ru(act.get("act_date", ""))
    para(f"№ {act['number']}                                                                                         «{dd}» {mm} {yy} г.", 10, before=6)
    para("(дата составления акта)", CAP, align=WD_ALIGN_PARAGRAPH.RIGHT, after=3)
    dc = ppl.get("dev_control")
    label("Представитель застройщика, технического заказчика, лица, ответственного за эксплуатацию здания, сооружения, или регионального оператора по вопросам строительного контроля")
    val(_rep_line(dc), "(должность (при наличии), фамилия, инициалы, идентификационный номер в национальном реестре специалистов в области строительства (за исключением случаев, когда членство в саморегулируемых организациях в области строительства, реконструкции, капитального ремонта объектов капитального строительства не требуется), реквизиты распорядительного документа, подтверждающего полномочия)")
    val((_org_line(dc) + (("\n" + _org_addr(dc)) if _org_addr(dc) else "")) if dc else "", "с указанием полного и (или) сокращенного наименования, ОГРН, ИНН, адреса юридического лица в пределах его места нахождения, фамилии, имени отчества (последнее – при наличии), адреса места жительства, ОГРНИП, ИНН индивидуального предпринимателя)")
    label("Представитель лица, осуществляющего строительство, реконструкцию, капитальный ремонт")
    val(_rep_line(con, False), "(должность (при наличии), фамилия, инициалы, реквизиты распорядительного документа, подтверждающего полномочия)")
    cc = ppl.get("contractor_control")
    label("Представитель лица, осуществляющего строительство, реконструкцию, капитальный ремонт, по вопросам строительного контроля")
    val(_rep_line(cc), "(должность (при наличии), фамилия, инициалы, идентификационный номер в национальном реестре специалистов в области строительства (за исключением случаев, когда членство в саморегулируемых организациях в области строительства, реконструкции, капитального ремонта объектов капитального строительства не требуется), реквизиты распорядительного документа, подтверждающего полномочия)")
