def _act_row(c: sqlite3.Connection, r: sqlite3.Row, with_issues: bool = True) -> dict[str, Any]:
    data = json.loads(r["data_json"] or "{}")
    d = {"id": r["id"], "number": r["number"], "status": r["status"], "act_date": r["act_date"], "created_at": r["created_at"], "section_id": r["section_id"], "seq": r["seq"],
         "updated_at": r["updated_at"] or r["created_at"], "signed_at": r["signed_at"], "signed_by": r["signed_by"],
         "data": data, "operations": c.execute("SELECT COUNT(*) FROM act_ops WHERE doc_id=?", (r["id"],)).fetchone()[0],
         "batches": [x[0] for x in c.execute("SELECT vhk_id FROM act_batches WHERE doc_id=?", (r["id"],))]}
    if with_issues:
        pid = c.execute("SELECT project_id FROM sections WHERE id=?", (r["section_id"],)).fetchone()["project_id"]
        d["issues"] = act_issues(c, pid, data)
    return d


@app.get("/api/acts")
def acts_list(section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sec = _section(c, section)
        rows = c.execute("SELECT * FROM documents WHERE section_id=? AND document_type='АОСР' ORDER BY seq, created_at", (sec["id"],)).fetchall()
        hints = {"standards": list(STD_HINTS), "materials": [], "drawing": [], "docs": []}
        for r in c.execute("SELECT data_json FROM documents WHERE document_type='АОСР' ORDER BY created_at DESC LIMIT 60"):
            dj = json.loads(r["data_json"] or "{}")
            for k in ("standards", "materials", "drawing", "docs"):
                v = (dj.get(k) or "").strip()
                if v and v not in hints[k] and len(v) < 400:
                    hints[k].append(v)
        for r in c.execute("SELECT name,qty,doc_ref FROM input_control WHERE section_id=? ORDER BY delivered_on DESC LIMIT 60", (sec["id"],)):
            line = r["name"] + (f" — {r['qty']}" if r["qty"] else "") + (f" ({r['doc_ref']})" if r["doc_ref"] else "")
            if line not in hints["materials"]:
                hints["materials"].insert(0, line)
        rown: dict[str, list[int]] = {}
        for it in ozhr_build(c, sec)["items"]:
            for a_ in it["acts"]:
                rown.setdefault(a_["id"], []).append(it["n"])
        acts_out = []
        for r in rows:
            ar = _act_row(c, r)
            ar["ozhr_rows"] = sorted(rown.get(r["id"], []))
            acts_out.append(ar)
        return {"acts": acts_out, "hints": hints, "section": sec["code"]}


@app.get("/api/acts/proposals")
def acts_proposals(section: Optional[str] = None) -> dict[str, Any]:
    """Выполненные скрытые работы, по которым акта ещё нет, сгруппированные по виду работ и участку."""
    with db() as c:
        sec = _section(c, section)
        rows = c.execute("""
          SELECT el.id eid, el.code ecode, el.name ename, el.block, el.planned_note, o.id oid, o.code ocode, o.title otitle, o.sort_order, o.hidden,
            (SELECT e.event_type FROM events e WHERE e.operation_id=o.id ORDER BY e.created_at DESC LIMIT 1) last,
            (SELECT e.performed_on FROM events e WHERE e.operation_id=o.id ORDER BY e.created_at DESC LIMIT 1) day,
            (SELECT COUNT(*) FROM act_ops a WHERE a.operation_id=o.id) used
          FROM elements el JOIN operations o ON o.element_id=el.id WHERE el.enabled=1 AND el.section_id=? ORDER BY el.block, el.created_at, o.sort_order""", (sec["id"],)).fetchall()
        by_el: dict[str, list[sqlite3.Row]] = {}
        for r in rows:
            by_el.setdefault(r["eid"], []).append(r)
        groups: dict[tuple[str, str], dict[str, Any]] = {}
        for ops in by_el.values():
            for i, r in enumerate(ops):
                if r["last"] != "complete" or r["used"] or not is_hidden_work(r["hidden"], r["ocode"], r["otitle"], r["ename"]):
                    continue
                title = r["otitle"] if r["ocode"] != "done" else r["ename"]
                key = (title, r["block"] or "")
                g = groups.setdefault(key, {"title": title, "block": r["block"] or "", "codes": [], "operation_ids": [], "start": r["day"], "end": r["day"], "length": 0.0, "next": []})
                g["codes"].append(r["ecode"]); g["operation_ids"].append(r["oid"])
                g["start"] = min(g["start"], r["day"]); g["end"] = max(g["end"], r["day"])
                m = re.search(r"L\s*=\s*(\d+(?:[.,]\d+)?)\s*м", r["planned_note"] or "")
                if m:
                    g["length"] += float(m.group(1).replace(",", "."))
                nxt = ops[i + 1]["otitle"] if i + 1 < len(ops) else ""
                if nxt and nxt not in g["next"]:
                    g["next"].append(nxt)
        out = []
        for g in groups.values():
            codes = g["codes"]
            shown = ", ".join(codes[:8]) + (f" и ещё {len(codes) - 8}" if len(codes) > 8 else "")
            work = f"{g['title']}" + (f" — {g['block']}" if g["block"] else "") + f": {shown}" + (f", общей протяжённостью {g['length']:g} м".replace(".", ",") if g["length"] else "")
            out.append({"work_name": work, "title": g["title"], "block": g["block"], "count": len(codes), "operation_ids": g["operation_ids"], "start": g["start"], "end": g["end"],
                        "next_work": "; ".join(g["next"]), "codes": codes, "length": g["length"]})
        out.sort(key=lambda x: (x["end"], x["title"]))
        return {"proposals": out, "section": sec["code"]}


class ActProposal(BaseModel):
    work_name: str = Field(min_length=1, max_length=1500)
    operation_ids: list[str] = []
    start: str = ""
    end: str = ""
    next_work: str = ""


@app.post("/api/acts", status_code=201)
def acts_create(items: list[ActProposal], section: Optional[str] = None) -> dict[str, Any]:
    made = []
    with db() as c:
        sec = _section(c, section)
        suffix = _suffix(sec["code"])
        pe_others, pe_sign = persons_for_act(c, sec["id"])
        seq = c.execute("SELECT COALESCE(MAX(seq),0) FROM documents WHERE section_id=? AND document_type='АОСР'", (sec["id"],)).fetchone()[0]
        for it in items:
            seq += 1
            yy = (it.end or date.today().isoformat())[2:4]
            did = str(uuid.uuid4())
            data = {"work_name": it.work_name, "drawing": f"{sec['code']} «{sec['title']}»", "materials": "", "docs": "Исполнительная схема. " + it.work_name.split(":")[0],
                    "start": it.start, "end": it.end, "standards": "", "next_work": it.next_work, "extra": "", "copies": "5-х", "others": pe_others, "others_sign": pe_sign, "attachments": ""}
            c.execute("INSERT INTO documents (id,document_type,number,status,created_at,section_id,data_json,act_date,seq) VALUES (?,?,?,?,?,?,?,?,?)",
                      (did, "АОСР", f"{seq}/{yy}-{suffix}", "Черновик", now(), sec["id"], json.dumps(data, ensure_ascii=False), it.end or "", seq))
            for oid in it.operation_ids:
                c.execute("INSERT OR IGNORE INTO act_ops (doc_id, operation_id) VALUES (?,?)", (did, oid))
            made.append(did)
    return {"created": len(made), "message": f"Создано актов: {len(made)} (черновики)"}


class ActUpdate(BaseModel):
    number: Optional[str] = Field(default=None, max_length=60)
    status: Optional[Literal["Черновик", "Готов к подписанию", "Подписан", "В архиве"]] = None
    act_date: Optional[str] = None
    data: Optional[dict[str, str]] = None
    base: Optional[str] = None
    reason: Optional[str] = None
    batches: Optional[list[str]] = None


@app.put("/api/acts/{act_id}")
def acts_update(request: Request, act_id: str, payload: ActUpdate) -> dict[str, str]:
    with db() as c:
        r = c.execute("SELECT * FROM documents WHERE id=? AND document_type='АОСР'", (act_id,)).fetchone()
        if not r:
            raise HTTPException(404, "Акт не найден")
        cur = r["status"]
        if payload.base and payload.base != (r["updated_at"] or r["created_at"]):
            raise HTTPException(409, "Акт уже изменён другим пользователем (" + (r["updated_at"] or "")[:16].replace("T", " ") + "). Закройте окно, обновите страницу и повторите правку")
        data = json.loads(r["data_json"] or "{}")
        before = {"number": r["number"], "act_date": r["act_date"], "status": cur, **data}
        new_status = payload.status or cur
        edits = bool(payload.data) or payload.number is not None or payload.act_date is not None
        reason = (payload.reason or "").strip()
        if new_status == "В архиве" and cur not in SIGNED:
            raise HTTPException(409, "В архив можно отправить только подписанный акт")
        if cur == "Подписан" and new_status == "В архиве":
            c.execute("UPDATE documents SET status='В архиве', updated_at=? WHERE id=?", (now(), act_id))
            audit(request, c, "act", act_id, "update", "Акт АОСР №" + r["number"] + ": статус «Подписан» → «В архиве»", {"Статус": ["Подписан", "В архиве"]}, section_id=r["section_id"])
            return {"message": "Акт отправлен в архив"}
        if cur == "В архиве" and new_status not in ("В архиве", "Подписан"):
            raise HTTPException(409, "Из архива акт возвращается в статус «Подписан»; дальше — по порядку")
        if cur in SIGNED:
            if new_status == cur:
                if edits and any(str(v or "") != str(before.get(k, "") or "") for k, v in {**(payload.data or {}), **({"number": payload.number} if payload.number is not None else {}), **({"act_date": payload.act_date} if payload.act_date is not None else {})}.items()):
                    raise HTTPException(409, "Акт подписан — правка закрыта. Чтобы изменить, верните его в «Черновик» с указанием причины")
                return {"message": "Без изменений"}
            if len(reason) < 5:
                raise HTTPException(409, "Чтобы вернуть подписанный акт в работу, укажите причину (не короче 5 символов)")
        old_b = {x[0] for x in c.execute("SELECT vhk_id FROM act_batches WHERE doc_id=?", (act_id,))}
        new_b = old_b
        if payload.batches is not None:
            ok = {x[0] for x in c.execute("SELECT id FROM input_control WHERE section_id=?", (r["section_id"],))}
            new_b = {b for b in payload.batches if b in ok}
            if cur in SIGNED and new_status == cur and new_b != old_b:
                raise HTTPException(409, "Акт подписан — состав материалов закрыт. Верните акт в «Черновик» с указанием причины")
        if payload.data:
            allowed = {"work_name", "drawing", "materials", "docs", "start", "end", "standards", "next_work", "extra", "copies", "others", "others_sign", "attachments"}
            data.update({k: v for k, v in payload.data.items() if k in allowed})
        number = (payload.number.strip() if payload.number is not None else r["number"]) or r["number"]
        act_date = payload.act_date if payload.act_date is not None else r["act_date"]
        signed_at, signed_by = r["signed_at"], r["signed_by"]
        if new_status == "Подписан" and cur not in SIGNED:
            pid = c.execute("SELECT project_id FROM sections WHERE id=?", (r["section_id"],)).fetchone()["project_id"]
            issues = act_issues(c, pid, data)
            if issues:
                raise HTTPException(409, "Подписать нельзя, пока не заполнено: " + "; ".join(issues[:8]) + (" и ещё " + str(len(issues) - 8) if len(issues) > 8 else ""))
            signed_at, signed_by = now(), (getattr(request.state, "user", "") or "")[:80]
        if cur in SIGNED and new_status not in SIGNED:
            signed_at = signed_by = ""
        c.execute("UPDATE documents SET number=?, status=?, act_date=?, data_json=?, updated_at=?, signed_at=?, signed_by=? WHERE id=?",
                  (number, new_status, act_date, json.dumps(data, ensure_ascii=False), now(), signed_at, signed_by, act_id))
        if new_b != old_b:
            c.execute("DELETE FROM act_batches WHERE doc_id=?", (act_id,))
            for b in new_b:
                c.execute("INSERT INTO act_batches (doc_id,vhk_id) VALUES (?,?)", (act_id, b))
        after = {"number": number, "act_date": act_date, "status": new_status, **data}
        df = _diff(before, after, ACT_LABELS)
        if new_b != old_b:
            nm = {x["id"]: x["name"] for x in c.execute("SELECT id,name FROM input_control WHERE section_id=?", (r["section_id"],))}
            df["Материалы из журнала входного контроля"] = ["; ".join(sorted(nm.get(b, "?") for b in old_b)), "; ".join(sorted(nm.get(b, "?") for b in new_b))]
        if reason:
            df["Причина"] = ["", reason]
        if df:
            act = "Акт АОСР №" + number
            summ = act + (": статус «" + cur + "» → «" + new_status + "»" if new_status != cur else ": изменены данные")
            audit(request, c, "act", act_id, "update", summ, df, section_id=r["section_id"])
    return {"message": "Сохранено"}


@app.delete("/api/acts/{act_id}")
def acts_delete(request: Request, act_id: str) -> dict[str, str]:
    with db() as c:
        r = c.execute("SELECT status,number,section_id FROM documents WHERE id=? AND document_type='АОСР'", (act_id,)).fetchone()
        if not r:
            raise HTTPException(404, "Акт не найден")
        if r["status"] in SIGNED:
            raise HTTPException(409, "Подписанный или архивный акт удалить нельзя")
        audit(request, c, "act", act_id, "delete", "Удалён акт АОСР №" + r["number"] + " (статус «" + r["status"] + "»)", None, section_id=r["section_id"])
        c.execute("DELETE FROM act_ops WHERE doc_id=?", (act_id,))
        c.execute("DELETE FROM act_batches WHERE doc_id=?", (act_id,))
        c.execute("DELETE FROM documents WHERE id=?", (act_id,))
    return {"message": "Акт удалён, работы снова доступны для включения в акт"}


@app.get("/api/acts/{act_id}/docx")
def acts_docx(act_id: str) -> Response:
    with db() as c:
        r = c.execute("SELECT d.*, s.project_id, s.code scode FROM documents d JOIN sections s ON s.id=d.section_id WHERE d.id=? AND d.document_type='АОСР'", (act_id,)).fetchone()
        if not r:
            raise HTTPException(404, "Акт не найден")
        p = c.execute("SELECT * FROM projects WHERE id=?", (r["project_id"],)).fetchone()
        ppl = _act_people(c, r["project_id"])
        act = {"number": r["number"], "act_date": r["act_date"], "data": json.loads(r["data_json"] or "{}")}
        obj = {"object_name": p["object_name"], "address": p["address"], "cipher": r["scode"]}
    try:
        blob = build_aosr_docx(act, obj, ppl)
    except ImportError as ex:
        raise HTTPException(500, "На сервере не установлена библиотека python-docx — выполните обновление ещё раз") from ex
    from urllib.parse import quote
    fn = "АОСР_" + re.sub(r"[^\w.-]+", "_", r["number"]) + ".docx"
    return Response(blob, media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                    headers={"Content-Disposition": "attachment; filename*=UTF-8''" + quote(fn)})



@app.post("/api/revisions", status_code=201)
def add_revision(payload: RevisionIn, section: Optional[str] = None) -> dict[str, str]:
    rid = str(uuid.uuid4())
    with db() as c:
        sid = _section(c, section)["id"]
        c.execute("INSERT INTO revisions (id,revision,change_summary,created_by,created_at,section_id) VALUES (?,?,?,?,?,?)", (rid, payload.revision.strip(), payload.change_summary.strip(), payload.created_by.strip(), now(), sid))
    return {"id": rid, "message": "Редакция проекта добавлена в историю"}


@app.post("/api/schema-versions", status_code=201)
def create_schema_version(reason: str = "Сформирована новая рабочая версия", section: Optional[str] = None) -> dict[str, Any]:
    with db() as c:
        sid = _section(c, section)["id"]
        version = c.execute("SELECT COALESCE(MAX(version),0)+1 FROM schema_versions WHERE section_id=?", (sid,)).fetchone()[0]
        state = json.dumps(_elements(c, sid), ensure_ascii=False)
        c.execute("INSERT INTO schema_versions (id,section_id,version,reason,state_json,created_by,created_at) VALUES (?,?,?,?,?,?,?)", (str(uuid.uuid4()), sid, version, reason[:500], state, "ПТО", now()))
    return {"version": version, "message": "Снимок состояния сохранён"}


@app.get("/api/documents")
def documents(section: Optional[str] = None) -> list[dict[str, Any]]:
    with db() as c:
        sid = _section(c, section)["id"]
        return [dict(r) for r in c.execute("SELECT * FROM documents WHERE section_id=? ORDER BY created_at DESC", (sid,))]


# ---------- Загрузка готовых перечней работ (seeds/*.json) ----------
SEEDS_DIR = Path(os.getenv("APP_SEEDS_DIR", "/seeds"))


def _load_seed(name: str) -> dict[str, Any]:
    if not name or "/" in name or "\\" in name or ".." in name:
        raise HTTPException(400, "Недопустимое имя набора")
    path = SEEDS_DIR / f"{name}.json"
    if not path.is_file():
        raise HTTPException(404, "Набор не найден")
    return json.loads(path.read_text(encoding="utf-8"))


class ImportIn(BaseModel):
    seed: str


@app.get("/api/seeds")
def list_seeds(project: str = "") -> list[dict[str, Any]]:
    """Готовые наборы. С параметром project — только те, что относятся к объекту этого проекта (чужие наборы не показываем)."""
    out = []
    names: set[str] = set()
    if project:
        with db() as c:
            p = c.execute("SELECT object_name, short_name FROM projects WHERE id=?", (project,)).fetchone()
        if p:
            names = {(p["object_name"] or "").strip().lower(), (p["short_name"] or "").strip().lower()} - {""}
    if SEEDS_DIR.is_dir():
        for f in sorted(SEEDS_DIR.glob("*.json")):
            try:
                d = json.loads(f.read_text(encoding="utf-8"))
                if project:
                    o = d.get("object") or {}
                    if not ({str(o.get("object_name") or "").strip().lower(), str(o.get("short_name") or "").strip().lower()} - {""}) & names:
                        continue
                out.append({"seed": f.stem, "title": d.get("title", f.stem), "description": d.get("description", ""), "elements": len(d.get("elements", []))})
            except Exception:
                continue
    return out


@app.post("/api/import")
def import_seed(payload: ImportIn) -> dict[str, Any]:
    seed = _load_seed(payload.seed)
    elems = seed.get("elements", [])
    obj, sec = seed.get("object"), seed.get("section")
    if not elems or not obj or not sec:
        raise HTTPException(400, "В наборе должны быть object, section и elements")
    backup = DB_PATH.with_name(f"{DB_PATH.stem}.backup-{datetime.now().strftime('%Y%m%d-%H%M%S')}{DB_PATH.suffix}")
    src, dst = sqlite3.connect(DB_PATH), sqlite3.connect(backup)
    with dst:
        src.backup(dst)
    src.close(); dst.close()
    added = skipped = ops_added = 0
    created_project = False
    with db() as c:
        sn = (obj.get("short_name") or "").strip()
        p = c.execute("SELECT id,short_name FROM projects WHERE object_name=?", (obj["object_name"].strip(),)).fetchone()
        if not p and sn:
            p = c.execute("SELECT id,short_name FROM projects WHERE short_name=?", (sn,)).fetchone()
        if p:
            pid = p["id"]
            if sn and not p["short_name"]:
                c.execute("UPDATE projects SET short_name=? WHERE id=?", (sn, pid))
        else:
            pid = str(uuid.uuid4()); created_project = True
            c.execute("INSERT INTO projects (id,object_name,address,created_at,short_name) VALUES (?,?,?,?,?)", (pid, obj["object_name"].strip(), obj.get("address", "").strip(), now(), sn))
            if seed.get("participants"):
                _save_participants(c, pid, [ParticipantIn(**x) for x in seed["participants"]])
        s = c.execute("SELECT id FROM sections WHERE project_id=? AND code=?", (pid, sec["code"].strip())).fetchone()
        sid = s["id"] if s else _create_section(c, pid, sec["code"], sec["title"], sec.get("system", ""))
        for e in elems:
            if c.execute("SELECT 1 FROM elements WHERE section_id=? AND code=?", (sid, e["code"])).fetchone():
                skipped += 1
                continue
            eid = str(uuid.uuid4())
            c.execute("INSERT INTO elements (id,section_id,code,name,kind,block,planned_note,enabled,created_at) VALUES (?,?,?,?,?,?,?,1,?)", (eid, sid, e["code"], e["name"], e["kind"], e["block"], e.get("planned_note", ""), now()))
            for order, (op_code, title) in enumerate(e["operations"], 1):
                c.execute("INSERT INTO operations (id,element_id,code,title,sort_order) VALUES (?,?,?,?,?)", (str(uuid.uuid4()), eid, op_code, title, order))
                ops_added += 1
            added += 1
        rv = seed.get("revision")
        if rv and added:
            c.execute("INSERT INTO revisions (id,revision,change_summary,created_by,created_at,section_id) VALUES (?,?,?,?,?,?)", (str(uuid.uuid4()), rv["revision"], rv["change_summary"], "ПТО", now(), sid))
    return {"added": added, "skipped_existing": skipped, "operations": ops_added, "project_id": pid, "section_id": sid,
            "project_created": created_project, "backup": backup.name,
            "message": f"Загружено элементов: {added}, операций: {ops_added}"}


