def guess_kind(name: str) -> str:
    n = name.lower()
    if "график" in n:
        return "schedule"
    if re.search(r"организаци\w*\s+строительств", n) or re.search(r"(?<![а-яёa-z])пос(?![а-яёa-z])", n):
        return "pos"
    if "аоср" in n or "aosr" in n:
        return "aosr"
    if n.endswith(".dxf"):
        return "dxf_survey" if any(w in n for w in ("съём", "съем", "survey", "исполн", "фактическ")) else "dxf_project"
    if n.endswith(".xml") or "смет" in n:
        return "estimate"
    if n.endswith(".pdf"):
        return "pdf"
    if n.endswith((".docx", ".doc")):
        return "doc"
    if n.endswith((".xlsx", ".xls")):
        return "table"
    return "other"


def _norm_code(x: str) -> str:
    return re.sub(r"\s", "", x).replace("–", "-")


_POINT_RE = re.compile(r"^(?:КНС\s*)?К\s?\d+(?:\.\d+)?\s?[-–]\s?[A-Za-zА-Яа-я]{0,3}\.?\s?\d+(?:\.\d+)?\*?$")


def _dxf_texts_xy(path: Path) -> list[tuple[float, float, str]]:
    """Подписи DXF с координатами (потоково, без ezdxf) — для разбора таблиц продольных профилей."""
    with open(path, "rb") as fb:
        hd = fb.read(300000).decode("latin-1")
    m = re.search(r"\$ACADVER\s+1\s+(AC\d+)", hd)
    ver = m.group(1) if m else ""
    enc = "cp1251" if (ver and ver < "AC1021" and "ANSI_1251" in hd) else "utf-8"
    out: list[tuple[float, float, str]] = []
    cur = None
    g: dict[str, Any] = {}

    def flush() -> None:
        if cur in ("TEXT", "MTEXT") and "1" in g and "10" in g and "20" in g:
            out.append((g["10"], g["20"], re.sub(r"\{\\[^;]*;|[{}]", "", _U_ESC.sub(lambda mm: chr(int(mm.group(1), 16)), g["1"])).strip()))

    with open(path, "r", encoding=enc, errors="replace") as f:
        it = iter(f)
        for cl in it:
            vl = next(it, None)
            if vl is None:
                break
            c = cl.strip()
            v = vl.rstrip("\r\n")
            if c == "0":
                flush()
                cur = v.strip()
                g = {}
            elif cur in ("TEXT", "MTEXT"):
                if c in ("1", "3"):
                    g["1"] = g.get("1", "") + v
                elif c in ("10", "20") and c not in g:
                    try:
                        g[c] = float(v)
                    except ValueError:
                        pass
    flush()
    return out


def extract_pipes(texts: list[tuple[float, float, str]]) -> list[dict[str, Any]]:
    """Участки труб из таблиц профилей: строки «Номер колодца, точки», «Расстояние», «Длина, м», «Обозначение трубы»."""
    heads = [t for t in texts if t[2].startswith("Номер колодца")]
    if not heads:
        return []
    num = re.compile(r"^\d+(?:[.,]\d+)?$")
    res: dict[tuple[str, str], dict[str, Any]] = {}
    for hx, hy, _ in heads:
        right = [h[0] for h in heads if abs(h[1] - hy) < 3 and h[0] > hx + 50]
        x1 = min(right) if right else hx + 1200
        inb = [t for t in texts if hx < t[0] < x1 and hy - 70 < t[1] < hy + 60]
        pts = sorted([t for t in inb if abs(t[1] - hy) < 3.5 and _POINT_RE.match(t[2])], key=lambda t: t[0])
        dist = sorted([t for t in inb if hy + 4 < t[1] < hy + 12 and num.match(t[2])], key=lambda t: t[0])
        ln = sorted([t for t in inb if hy + 12 < t[1] < hy + 20 and num.match(t[2])], key=lambda t: t[0])
        lab = [t for t in inb if hy + 30 < t[1] < hy + 50 and re.search(r"DN/OD-?\s*(\d+)|%%[Cc]\s*(\d+)|[ØÆ⌀]\s*(\d+)", t[2])]
        if len(pts) < 2 or len(dist) != len(pts) - 1:
            continue
        for i, d in enumerate(dist):
            L = float(d[2].replace(",", "."))
            fr, to = pts[i][2].replace("КНС", "").strip().rstrip("*"), pts[i + 1][2].replace("КНС", "").strip().rstrip("*")
            dn = ""
            if lab:
                mx = (pts[i][0] + pts[i + 1][0]) / 2
                best = min(lab, key=lambda t: abs(t[0] - mx))
                mm = re.search(r"DN/OD-?\s*(\d+)|%%[Cc]\s*(\d+)|[ØÆ⌀]\s*(\d+)", best[2])
                dn = next((x for x in mm.groups() if x), "") if mm else ""
            res.setdefault((fr, to), {"from": fr, "to": to, "len": round(L, 2), "dn": dn})
    return list(res.values())


def _pdf_pages_words(path: Path) -> list[list[tuple[float, float, float, str]]]:
    """Слова PDF с координатами (pdftotext -bbox): по страницам [(x1, y1, x2, text)]. Нужен текстовый слой."""
    import html as _html
    r = subprocess.run(["pdftotext", "-bbox", str(path), "-"], capture_output=True, timeout=240)
    txt = r.stdout.decode("utf-8", "replace")
    pages: list[list[tuple[float, float, float, str]]] = []
    for part in txt.split("<page ")[1:]:
        ws = [(float(a), float(b), float(c), _html.unescape(w).strip())
              for a, b, c, w in re.findall(r'xMin="([\d.]+)" yMin="([\d.]+)" xMax="([\d.]+)" yMax="[\d.]+">([^<]*)<', part)]
        pages.append([w for w in ws if w[3]])
    return pages


_PT_STANDALONE = re.compile(r"^(?:т\.\s?\S+|УП\s?\d+|\d+|[А-Яа-я]{1,3}\d+)$")


_UNIT_RE = re.compile(r"^(шт|компл|м|м2|м3|кг|т|пог\.?\s*м|комплект)\.?$", re.I)
_SPEC_NOISE = re.compile(r"Согласовано|Взам\.|Подп\.|Инв\.|Лист|Формат|Изм\.|Разраб|Н\.контр|Отв\. представитель|В производство|РОМЕКС|Примечани|Спецификация|изделий и материалов|^\d\s+\d\s+\d|Позиция|Единица|изготовитель|обозначение", re.I)


def extract_spec_pdf(path: Path) -> list[dict[str, Any]]:
    """Спецификация оборудования, изделий и материалов из PDF проекта (pdftotext -layout): [{section, pos, name, mark, unit, qty, note}]."""
    r = subprocess.run(["pdftotext", "-layout", str(path), "-"], capture_output=True, timeout=240)
    pages = r.stdout.decode("utf-8", "replace").split("\f")
    out: list[dict[str, Any]] = []
    section = ""
    for pg in pages:
        if not ("Единица" in pg and ("Коли-" in pg or "чество" in pg) and "Наименование" in pg):
            continue
        for raw in pg.splitlines():
            line = raw.strip()
            if not line or _SPEC_NOISE.search(line):
                continue
            cols = [x.strip() for x in re.split(r"\s{2,}", line) if x.strip()]
            ui = next((i for i, x in enumerate(cols) if _UNIT_RE.match(x) and i + 1 < len(cols) and re.match(r"^\d+(?:[.,]\d+)?\\*?$", cols[i + 1])), -1)
            if ui < 0:
                if len(cols) == 1 and 3 < len(cols[0]) < 60 and not re.search(r"\d{2}\\.\d{2}\\.\d{4}", cols[0]) and re.match(r"(Колодц|Сеть|Сети|Система|Узел|Прочая|Насосная|Трубопровод|Камер|Пожарн|Водопровод|Канализац)", cols[0]):
                    section = cols[0]
                continue
            pos = ""
            head = cols[:ui]
            if head and re.match(r"^\d{1,3}$", head[0]):
                pos = head.pop(0)
            if not head:
                continue
            name = head[0]
            mark = " ".join(head[1:3]) if len(head) > 1 else ""
            note = " ".join(cols[ui + 2:])
            out.append({"section": section, "pos": pos, "name": name, "mark": mark, "unit": cols[ui].rstrip("."), "qty": float(cols[ui + 1].rstrip("*").replace(",", ".")), "note": note})
    return out


