def _obj_class(name: str) -> Optional[tuple[str, str, str, str, bool]]:
    """Класс объекта по наименованию (из спецификации проекта или позиции сметы): (подпись, вид, префикс, семейство, поштучно)."""
    nm = (name or "").lower()
    if not nm or _OBJ_SKIP.search(nm):
        return None
    for rx, label, kind, ab, fam, one in _OBJ_CLASSES:
        if re.search(rx, nm):
            return label, kind, ab, fam, one
    return None


def _dn_set(name: str) -> set[str]:
    nm = (name or "").replace("∅", "d").replace("Ø", "d").replace("ф", "d").replace("Ф", "d")
    out: set[str] = set()
    for m in re.finditer(r"\bdn\s*/\s*od\s*(\d{2,4})(?:\s*/\s*\d{2,4})?", nm, re.I):   # «DN/OD 800/669»: наружный диаметр — первое число
        out.add(m.group(1))
    nm = re.sub(r"\bdn\s*/\s*od\s*\d{2,4}(?:\s*/\s*\d{2,4})?", " ", nm, flags=re.I)
    for m in re.finditer(r"\b(?:dн|dу|дн|ду)\s*(\d{2,4})", nm, re.I):                 # «Dн 500», «Ду 150»
        out.add(m.group(1))
    for m in re.finditer(r"(?:\bdn|\bd|диаметром:?)\s*(\d{2,3})(?:\s*[-х×x/]\s*(\d{2,3})(?![.,]\d))?", nm, re.I):
        out.update(x for x in m.groups() if x)
    for m in re.finditer(r"(\d{2,3})\s*мм", nm):
        out.add(m.group(1))
    for m in re.finditer(r"(?<![\d.,])(\d{2,3})\s*[хx×]\s*\d{1,2}[.,]\d", nm):   # типоразмер трубы 160х9,5
        out.add(m.group(1))
    return out


def _dn_range(name: str) -> Optional[tuple[int, int]]:
    """Диаметр из позиции сметы как интервал (нижняя граница не включена, верхняя включена): «до 50 мм», «свыше 160 до 225», «160 мм», «SDR17-160х9,5»."""
    nm = (name or "").lower()
    m = re.search(r"свыше\s*(\d+)\s*до\s*(\d+)", nm)
    if m:
        return int(m.group(1)), int(m.group(2))
    m = re.search(r"до\s*(\d+)\s*мм", nm)
    if m:
        return 0, int(m.group(1))
    m = re.search(r"диаметром:?\s*(\d{2,3})\s*мм", nm)
    if m and not re.search(r"\d{2,3}\s*[хx×]\s*\d{1,2}[.,]\d", nm):    # условный проход: 150 мм ≈ труба d160
        v = int(m.group(1))
        return v - 1, v + 10
    ds = _dn_set(name)
    if ds:
        v = int(sorted(ds, key=int)[0])
        return v - 1, v
    return None


def _el_qty(note: str) -> float:
    m = re.match(r"\s*(\d+(?:[.,]\d+)?)\s*(?:шт|компл)", note or "")
    return float(m.group(1).replace(",", ".")) if m else 1.0


def extract_node_titles_pdf(path: Path) -> list[str]:
    """Названия узлов с чертежей: подписи вида «Узел учета В1 основной (1:25)»."""
    try:
        txt = subprocess.run(["pdftotext", "-layout", str(path), "-"], capture_output=True, text=True, timeout=120).stdout
    except Exception:  # noqa: BLE001
        return []
    out: list[str] = []
    for m in re.finditer(r"(Узел[а-я]*\s+[^()\n]{2,70}?)\s*\(\s*1\s*:\s*\d+\s*\)", txt):
        t = re.sub(r"\s+", " ", m.group(1)).strip()
        if t not in out:
            out.append(t)
    return out


def spec_objects(items: list[dict[str, Any]], fname: str, have: set[str], titles: Optional[list[str]] = None) -> list[dict[str, Any]]:
    """Объекты проекта из спецификации: арматура поштучно, остальное строкой с количеством. Трубы и сыпучие материалы — не объекты."""
    out: list[dict[str, Any]] = []
    cnt: dict[str, int] = {}
    fm = re.search(r"Н([ВК]\d+)", fname or "")
    nodes: dict[str, list[str]] = {}
    for it in items:
        cl = _obj_class(it["name"])
        if not cl or not str(it.get("unit", "")).lower().startswith(("шт", "компл")):
            continue
        label, kind, ab, fam, one = cl
        sec = it.get("section") or "Спецификация"
        nm = re.search(r"\b([ВК]\d+(?:\.\d+)?)\b", sec)
        net = nm.group(1) if nm else (fm.group(1) if fm else "")
        pre = f"{net}-" if net else ""
        qty = it["qty"]
        dn = sorted(_dn_set(it["name"]), key=int)
        dns = f" DN{dn[0]}" if dn else ""
        if one and qty == int(qty) and 1 <= qty <= 80:
            for _ in range(int(qty)):
                cnt[ab] = cnt.get(ab, 0) + 1
                code = f"{pre}{ab}-{cnt[ab]}"
                if _norm_code(code) in have:
                    continue
                out.append({"code": code, "name": f"{label}{dns} № {cnt[ab]}", "kind": kind, "block": sec,
                            "planned_note": f"1 шт · {it['name'][:110]}", "source": "project", "ops": OBJ_OPS[kind], "file": fname})
        else:
            cnt[ab] = cnt.get(ab, 0) + 1
            code = f"{pre}{ab}-{cnt[ab]}"
            if _norm_code(code) in have:
                continue
            out.append({"code": code, "name": it["name"][:160], "kind": kind, "block": sec,
                        "planned_note": f"{qty:g} {it['unit']}" + (f" · {it['mark']}" if it.get("mark") else ""), "source": "project", "ops": OBJ_OPS[kind], "file": fname})
    for it in items:        # Узел: раздел спецификации «Узел …» объединяет свои арматуру, фитинги и оборудование
        sec = it.get("section") or ""
        if re.match(r"\s*узел", sec, re.I) and _obj_class(it["name"]) and str(it.get("unit", "")).lower().startswith(("шт", "компл")):
            nodes.setdefault(sec, []).append(f"{_obj_class(it['name'])[0]}×{it['qty']:g}")
    def _nk(t: str) -> str:
        return re.sub(r"[^а-яa-z0-9]", "", t.lower())
    for t in titles or []:      # узлы, показанные на чертежах, но не выделенные разделом спецификации
        if not any(_nk(t) in _nk(sec) or _nk(sec) in _nk(t) for sec in nodes):
            nodes[t] = []
    for k, (sec, parts) in enumerate(nodes.items(), 1):
        nm = re.search(r"\b([ВК]\d+(?:\.\d+)?)\b", sec)
        net = nm.group(1) if nm else (fm.group(1) if fm else "")
        code = f"{net}-У{k}" if net else f"У{k}"
        if _norm_code(code) in have:
            continue
        agg: dict[str, float] = {}
        for p in parts:
            lb, q = p.rsplit("×", 1)
            agg[lb] = agg.get(lb, 0) + float(q)
        out.insert(0, {"code": code, "name": sec[:160], "kind": "Узел", "block": sec, "planned_note": ("Состав: " + "; ".join(f"{a}×{v:g}" for a, v in agg.items())) if agg else "по чертежу проекта (состав не указан в спецификации)",
                       "source": "project", "ops": OBJ_OPS["Узел"], "file": fname})
    return out


_WT_MARK = re.compile(r"^(?:\d?ПП\d+(?:-\d)?|КС\d+\.\d|ПН\d+|КО\d+)$")


def _norm_mark(m: str) -> str:
    m = (m or "").strip().upper().replace(" ", "")
    mm = re.match(r"^\d?(ПП\d+)(?:-\d)?$", m)
    return mm.group(1) if mm else m


def extract_wells_table_pdf(pages: list[list[tuple[float, float, float, str]]]) -> list[dict[str, Any]]:
    """«Таблица водопроводных колодцев»: по каждому колодцу — состав (марки плит, колец, люков), объём бетона на опоры, глубина."""
    out: list[dict[str, Any]] = []
    for pg in pages:
        title = next((w for w in pg if w[3] == "Таблица" and any(x[3].startswith("колодцев") and abs(x[1] - w[1]) < 4 for x in pg)), None)
        if not title:
            continue
        line = " ".join(x[3] for x in sorted([x for x in pg if abs(x[1] - title[1]) < 4], key=lambda x: x[0]))
        nm = re.search(r"сети\s+(\S+)", line)
        net = nm.group(1) if nm else ""
        cols = [(w[0] + w[2]) / 2 for w in pg]  # noqa: F841
        marks = [((w[0] + w[2]) / 2, _norm_mark(w[3])) for w in pg if _WT_MARK.match(w[3]) and 150 < w[1] < 215]
        hatches = sorted([(w[0] + w[2]) / 2 for w in pg if w[3] == "Люк" and 150 < w[1] < 215])
        if hatches:
            marks += [(hatches[i], "Люк ГОСТ" if i == 0 else "Люк ТМ") for i in range(min(2, len(hatches)))]
            marks = [m for m in marks if m[1] != "Люк"]
        if not marks:
            continue
        ys = sorted({round(w[1]) for w in pg if re.fullmatch(r"\d{1,3}", w[3]) and w[0] < 100 and 232 < w[1] < 400})
        items = sorted([w for w in pg if re.fullmatch(r"\d{1,3}", w[3]) and w[0] < 100 and 232 < w[1] < 400], key=lambda w: w[1])
        for k, w in enumerate(items):
            y0, y1 = w[1] - 8, (items[k + 1][1] - 8 if k + 1 < len(items) else w[1] + 40)
            band = [x for x in pg if y0 <= x[1] < y1]
            comp: dict[str, int] = {}
            for x in band:
                if re.fullmatch(r"\d", x[3]):
                    xc = (x[0] + x[2]) / 2
                    best = min(marks, key=lambda m: abs(m[0] - xc))
                    if abs(best[0] - xc) < 9:
                        comp[best[1]] = comp.get(best[1], 0) + int(x[3])
            conc = [x for x in band if re.fullmatch(r"0,\d\d", x[3]) and 420 < x[0] < 450]
            hh = [x for x in band if re.fullmatch(r"\d{3,4}", x[3]) and 360 < x[0] < 375]
            out.append({"n": w[3], "net": net, "comp": comp, "conc": float(conc[0][3].replace(",", ".")) if conc else 0.0, "depth": int(hh[0][3]) if hh else 0})
    return out


def extract_pipes_pdf(pages: list[list[tuple[float, float, float, str]]]) -> list[dict[str, Any]]:
    """Участки труб из PDF-профилей: строка «Расстояние» (длины) + строка «Номер колодца, точки» (имена точек).
    Каждая длина привязывается к паре соседних точек по положению на листе; если на листе несколько профилей рядом, пары без длины — разрыв."""
    res: dict[tuple[str, str, str], dict[str, Any]] = {}
    num = re.compile(r"^\d+(?:[.,]\d+)?$")
    stand = re.compile(r"^(?:т\.\s?\S+|УП\s?\d+|\d+|[А-Яа-я]{1,3}\d+|Ввод\s+\S+)$")
    for pg in pages:
        for rx, ry, rx2, _ in [w for w in pg if w[3].startswith("Расстояние")]:
            heads = [w for w in pg if w[3] == "Номер" and w[1] > ry and w[1] - ry < 45 and abs(w[0] - rx) < 80]
            if not heads:
                continue
            hy = min(heads, key=lambda w: w[1] - ry)[1]
            dist = sorted([w for w in pg if ry - 2 <= w[1] <= ry + 3 and w[0] > rx2 + 20 and num.match(w[3])], key=lambda w: w[0])
            if not dist:
                continue
            title = next((w for w in sorted(pg, key=lambda w: w[1]) if w[3] == "Профиль" and abs(w[1] - hy) < 40 and w[0] > dist[-1][0] + 150), None)
            xend = (title[0] - 5) if title else dist[-1][0] + 300
            names = sorted([w for w in pg if hy - 4 <= w[1] <= hy + 30 and rx2 + 20 < w[0] < xend and w[3] not in ("Номер", "колодца,", "точки", "угла", "поворота")], key=lambda w: w[0])
            clusters: list[list[tuple[float, float, float, str]]] = []
            for w in names:
                if clusters and w[0] - max(x[2] for x in clusters[-1]) <= 14:
                    clusters[-1].append(w)
                else:
                    clusters.append([w])

            def lines(cl: list[tuple[float, float, float, str]]) -> list[str]:
                out: list[list[tuple[float, float, float, str]]] = []
                for w in sorted(cl, key=lambda w: (round(w[1] / 6), w[0])):
                    if out and abs(out[-1][0][1] - w[1]) < 5:
                        out[-1].append(w)
                    else:
                        out.append([w])
                return [" ".join(x[3] for x in sorted(l, key=lambda x: x[0])) for l in out]

            pts: list[tuple[float, str]] = []
            for cl in clusters:
                ls = lines(cl)
                xc = (min(x[0] for x in cl) + max(x[2] for x in cl)) / 2
                if len(ls) > 1 and all(stand.match(x) for x in ls):
                    pts.extend((xc, x) for x in ls)       # точки друг над другом (отстоят на 1 м и т. п.)
                elif len(ls) == 1 and any(re.fullmatch(r"УП\d+", x[3]) for x in cl) and len(cl) > 1:
                    groups: list[list[tuple[float, float, float, str]]] = []         # «Ввод В1-1 УП7 УП6» — несколько точек в одной строке
                    for x in sorted(cl, key=lambda x: x[0]):
                        if re.fullmatch(r"УП\d+", x[3]) or not groups or re.fullmatch(r"УП\d+", groups[-1][-1][3]):
                            groups.append([x])
                        else:
                            groups[-1].append(x)
                    pts.extend(((min(x[0] for x in g) + max(x[2] for x in g)) / 2, " ".join(x[3] for x in g)) for g in groups)
                else:
                    pts.append((xc, " ".join(ls)))
            if len(pts) < 2:
                continue
            net = ""
            if title:
                tt = " ".join(x[3] for x in sorted([x for x in pg if abs(x[1] - title[1]) < 6 and x[0] >= title[0]], key=lambda x: x[0]))
                m = re.search(r"сети\s+(\S+?)\.?(?:\s|$)", tt)
                net = m.group(1) if m else ""
            labs = [w for w in pg if w[3].startswith("ПЭ") and ry - 140 < w[1] < ry - 40]
            cs = [(d[0] + d[2]) / 2 for d in dist]
            npair = len(pts) - 1
            if len(dist) > npair:
                continue
            # монотонное соответствие «длина → пара точек» с минимальной суммой отклонений от середины пары (динамическое программирование)
            INF = 1e18
            cost = lambda i, k: abs(cs[i] - (pts[k][0] + pts[k + 1][0]) / 2) + (0 if pts[k][0] - 45 <= cs[i] <= pts[k + 1][0] + 45 else 1000)
            dp = [[INF] * npair for _ in dist]
            bk = [[-1] * npair for _ in dist]
            for k in range(npair):
                dp[0][k] = cost(0, k)
            for i2 in range(1, len(dist)):
                best, bkk = INF, -1
                for k in range(npair):
                    if k > 0 and dp[i2 - 1][k - 1] < best:
                        best, bkk = dp[i2 - 1][k - 1], k - 1
                    dp[i2][k] = best + cost(i2, k) if bkk >= 0 else INF
                    bk[i2][k] = bkk
            kend = min(range(npair), key=lambda k: dp[-1][k])
            if dp[-1][kend] >= 1000:
                continue
            assign = [0] * len(dist)
            k = kend
            for i2 in range(len(dist) - 1, -1, -1):
                assign[i2] = k
                k = bk[i2][k]
            for d, k in zip(dist, assign):
                c = (d[0] + d[2]) / 2
                L = float(d[3].replace(",", "."))
                spec, dn = "", ""
                if labs:
                    def lab_c(w: tuple[float, float, float, str]) -> float:
                        ln = [x for x in pg if abs(x[1] - w[1]) < 3 and w[0] - 45 <= x[0] < w[0] + 170]
                        return (min(x[0] for x in ln) + max(x[2] for x in ln)) / 2
                    b = min(labs, key=lambda w: abs(lab_c(w) - c))
                    lt = " ".join(w[3] for w in sorted([w for w in pg if -3 <= w[1] - b[1] < 16 and b[0] - 5 <= w[0] < b[0] + 170], key=lambda w: (round(w[1] / 6), w[0])))
                    mm, ms = re.search(r"ПЭ\s*(\d+)", lt), re.search(r"SDR\s*(\d+)", lt)
                    md = re.search(r"(\d{2,3})\s*[хx]\s*(\d+(?:[.,]\d+)?)", lt)
                    spec = ("ПЭ" + (mm.group(1) if mm else "")) + (f" SDR{ms.group(1)}" if ms else "") + (f" {md.group(1)}х{md.group(2)}" if md else "")
                    dn = md.group(1) if md else ""
                fr, to = pts[k][1], pts[k + 1][1]
                res.setdefault((net, fr, to), {"from": fr, "to": to, "len": round(L, 2), "dn": dn, "net": net, "spec": spec})
    return list(res.values())


def analyze_dxf(path: Path) -> dict[str, Any]:
    """Сводка по DXF: слои, типы объектов, подписи, найденные шифры колодцев. Падать нельзя — анализ необязателен."""
    try:
        import ezdxf
        from ezdxf import recover
        try:
            doc = ezdxf.readfile(str(path))
        except Exception:
            doc, _aud = recover.readfile(str(path))
        msp = doc.modelspace()
        layers: dict[str, int] = {}
        types: dict[str, int] = {}
        texts: list[str] = []
        blocks: dict[str, int] = {}
        xs: list[float] = []
        ys: list[float] = []
        for e in msp:
            t = e.dxftype()
            layers[e.dxf.layer] = layers.get(e.dxf.layer, 0) + 1
            types[t] = types.get(t, 0) + 1
            try:
                if t == "TEXT":
                    texts.append(e.dxf.text)
                elif t == "MTEXT":
                    texts.append(e.plain_text())
                elif t == "INSERT":
                    blocks[e.dxf.name] = blocks.get(e.dxf.name, 0) + 1
                    for a in e.attribs:
                        texts.append(a.dxf.text)
                if t in ("LINE", "LWPOLYLINE", "POLYLINE", "CIRCLE", "INSERT", "TEXT", "MTEXT"):
                    pt = e.dxf.start if t == "LINE" else (e.dxf.insert if t in ("INSERT", "TEXT", "MTEXT") else (e.dxf.center if t == "CIRCLE" else None))
                    if pt is not None:
                        xs.append(float(pt[0])); ys.append(float(pt[1]))
            except Exception:
                pass
        codes = sorted({_norm_code(m.group(0)) for tx in texts for m in CODE_RE.finditer(tx or "")})
        top = lambda d, n: [{"name": k, "count": v} for k, v in sorted(d.items(), key=lambda kv: -kv[1])[:n]]
        return {"ok": True, "dxf_version": doc.dxfversion, "entities": sum(types.values()),
                "layers_total": len(layers), "layers": top(layers, 40), "types": top(types, 12), "blocks": top(blocks, 15),
                "texts": len(texts), "codes": codes[:300],
                "extent": [round(min(xs), 2), round(min(ys), 2), round(max(xs), 2), round(max(ys), 2)] if xs else None}
    except Exception as ex:  # noqa: BLE001
        return {"ok": False, "error": f"{type(ex).__name__}: {ex}"[:300]}


def _num(x: str) -> float:
    try:
        return float(str(x).replace(" ", "").replace("\xa0", "").replace(",", "."))
    except ValueError:
        return 0.0


def analyze_estimate(path: Path) -> dict[str, Any]:
    """Разбор сметы ГрандСмета (XML): главы, позиции, единицы и объёмы."""
    try:
        import xml.etree.ElementTree as ET
        root = ET.parse(str(path)).getroot()
        props = root.find("Properties")
        title = ""
        obj = ""
        if props is not None:
            obj = props.get("Constr", "")
            title = props.get("Caption", "") or props.get("Name", "")
        positions: list[dict[str, Any]] = []
        chapters: list[dict[str, Any]] = []

        def pos_row(ch: Any, chapter: str) -> dict[str, Any]:
            q = ch.find("Quantity")
            qty = _num(q.get("Result", "")) if q is not None else _num(ch.get("Quantity", ""))
            return {"n": ch.get("Number", ""), "code": ch.get("Code", ""), "name": ch.get("Caption", ""),
                    "units": ch.get("Units", ""), "qty": qty, "chapter": chapter}

        used: set[int] = set()
        for chp in root.iter("Chapter"):
            rows = [pos_row(x, chp.get("Caption", "")) for x in chp.iter("Position") if id(x) not in used]
            used.update(id(x) for x in chp.iter("Position"))
            positions.extend(rows)
            chapters.append({"caption": chp.get("Caption", ""), "positions": len(rows)})
        for x in root.iter("Position"):
            if id(x) not in used:
                positions.append(pos_row(x, ""))
        if not positions:
            return {"ok": False, "type": "estimate", "error": "позиции не найдены — это точно смета ГрандСмета в XML?"}
        return {"ok": True, "type": "estimate", "object": obj[:300], "title": title[:200], "positions_total": len(positions),
                "chapters": chapters, "positions": positions[:2500]}
    except Exception as ex:  # noqa: BLE001
        return {"ok": False, "type": "estimate", "error": f"{type(ex).__name__}: {ex}"[:300]}


_RES_KIND = {"Tzr": "Труд рабочих", "Tzm": "Труд машинистов", "Mch": "Машины и механизмы", "Mat": "Материалы"}


def estimate_table(path: Path) -> dict[str, Any]:
    """Смета ГрандСмета (XML) -> таблица для просмотра: главы, подразделы, позиции с обоснованием и ресурсами."""
    import xml.etree.ElementTree as ET
    root = ET.parse(str(path)).getroot()
    props = root.find("Properties")
    head = {"object": "", "title": ""}
    if props is not None:
        head["object"] = props.get("Constr", "")
        head["title"] = props.get("Description", "") or props.get("Caption", "") or props.get("Name", "")

    def pos(el: Any) -> dict[str, Any]:
        q = el.find("Quantity")
        qty = _num(q.get("Result", "")) if q is not None and q.get("Result") else _num(el.get("Quantity", ""))
        formula = ""
        if q is not None and q.get("Fx"):
            formula = q.get("Fx", "").lstrip("=")
        elif el.get("Quantity") and not re.fullmatch(r"[\d\s.,]+", el.get("Quantity", "")):
            formula = el.get("Quantity", "")
        res: list[dict[str, Any]] = []
        rs = el.find("Resources")
        if rs is not None:
            for r in rs:
                if r.tag not in _RES_KIND:
                    continue
                norm = _num(r.get("Quantity", ""))
                res.append({"kind": _RES_KIND[r.tag], "tag": r.tag, "opt": r.get("Options", ""), "code": r.get("Code", ""), "name": r.get("Caption", ""), "units": r.get("Units", ""),
                            "norm": norm, "total": round(norm * qty, 4) if qty else 0.0})
        works = []
        wl = el.find("WorksList")
        if wl is not None:
            works = [w.get("Caption", "") for w in wl.iter("Work") if w.get("Caption")]
        return {"t": "p", "n": el.get("Number", ""), "code": el.get("Code", ""), "name": el.get("Caption", ""), "units": el.get("Units", ""),
                "kunit": _num(q.get("KUnit", "")) if q is not None and q.get("KUnit") else 0.0, "qty": qty, "flags": el.get("ItemFlags", ""), "formula": formula[:200], "note": el.get("DBComment", ""), "works": works[:30], "res": res}

    chapters: list[dict[str, Any]] = []

    def walk(chp: Any, rows: list[dict[str, Any]]) -> None:
        for ch in chp:
            if ch.tag == "Header":
                rows.append({"t": "h", "name": ch.get("Caption", "")})
            elif ch.tag == "Position":
                rows.append(pos(ch))
            elif ch.tag == "Chapter":
                rows.append({"t": "h", "name": ch.get("Caption", "")})
                walk(ch, rows)

    top = [c for c in root.iter("Chapter")]
    nested = {id(x) for c in top for x in c.iter("Chapter") if x is not c}
    for chp in top:
        if id(chp) in nested:
            continue
        rows: list[dict[str, Any]] = []
        walk(chp, rows)
        chapters.append({"caption": chp.get("Caption", ""), "rows": rows})
    seen = {id(x) for c in top for x in c.iter("Position")}
    loose = [pos(x) for x in root.iter("Position") if id(x) not in seen]
    if loose:
        chapters.append({"caption": "Без главы", "rows": loose})
    total = sum(1 for c in chapters for r in c["rows"] if r["t"] == "p")
    if not total:
        raise ValueError("позиции не найдены — это точно смета ГрандСмета в XML?")
    return {**head, "chapters": chapters, "positions": total}


BIG_DXF = 5 * 1024 * 1024
INBOX_HOST = os.getenv("APP_INBOX_HOST", "/opt/id-its/mvp/inbox")
_U_ESC = re.compile(r"\\U\+([0-9A-Fa-f]{4})")
_ANALYSIS_SLOT = threading.Semaphore(1)  # тяжёлые разборы идут по одному, чтобы не съесть память сервера


def _top(d: dict[str, int], n: int) -> list[dict[str, Any]]:
    return [{"name": k, "count": v} for k, v in sorted(d.items(), key=lambda kv: -kv[1])[:n]]


def analyze_dxf_light(path: Path) -> dict[str, Any]:
    """Потоковый разбор больших DXF (почти без памяти): слои, типы объектов, подписи, шифры колодцев."""
    try:
        with open(path, "rb") as fb:
            hd = fb.read(300000).decode("latin-1")
        m = re.search(r"\$ACADVER\s+1\s+(AC\d+)", hd)
        ver = m.group(1) if m else ""
        enc = "cp1251" if (ver and ver < "AC1021" and "ANSI_1251" in hd) else "utf-8"
        layers: dict[str, int] = {}
        types: dict[str, int] = {}
        texts: list[str] = []
        cur = None
        in_ent = sec_next = False
        with open(path, "r", encoding=enc, errors="replace") as f:
            it = iter(f)
            for code_line in it:
                val_line = next(it, None)
                if val_line is None:
                    break
                c = code_line.strip()
                v = val_line.rstrip("\r\n")
                if c == "0":
                    vs = v.strip()
                    if vs == "SECTION":
                        sec_next = True; cur = None
                    elif vs == "ENDSEC":
                        in_ent = False; cur = None
                    elif in_ent:
                        cur = vs; types[vs] = types.get(vs, 0) + 1
                elif c == "2" and sec_next:
                    sec_next = False; in_ent = v.strip() == "ENTITIES"
                elif in_ent and cur:
                    if c == "8":
                        k = v.strip(); layers[k] = layers.get(k, 0) + 1
                    elif c in ("1", "3") and cur in ("TEXT", "MTEXT", "ATTRIB"):
                        texts.append(_U_ESC.sub(lambda mm: chr(int(mm.group(1), 16)), v))
        codes = sorted({_norm_code(mm.group(0)) for tx in texts for mm in CODE_RE.finditer(tx)})
        return {"ok": True, "light": True, "dxf_version": ver, "entities": sum(types.values()), "layers_total": len(layers),
                "layers": _top(layers, 40), "types": _top(types, 12), "blocks": [], "texts": len(texts), "codes": codes[:300], "extent": None}
    except Exception as ex:  # noqa: BLE001
        return {"ok": False, "error": f"{type(ex).__name__}: {ex}"[:300]}


def analyze_any(path: Path, name: str) -> dict[str, Any]:
    n = name.lower()
    if n.endswith(".dxf"):
        return analyze_dxf_light(path) if path.stat().st_size > BIG_DXF else analyze_dxf(path)
    if n.endswith(".xml"):
        return analyze_estimate(path)
    if n.endswith(".pdf"):
        return analyze_pdf_project(path)
    return {}


def analyze_pdf_project(path: Path) -> dict[str, Any]:
    """Разбор PDF проекта целиком: участки, таблица колодцев, спецификация, узлы. Каждая часть независима — сбой одной не рушит остальные."""
    out: dict[str, Any] = {}
    words = None
    for key, fn in (("pipes", lambda: extract_pipes_pdf(words)), ("wells_table", lambda: extract_wells_table_pdf(words)),
                    ("spec", lambda: extract_spec_pdf(path)), ("nodes", lambda: extract_node_titles_pdf(path))):
        try:
            if words is None and key in ("pipes", "wells_table"):
                words = _pdf_pages_words(path)
            out[key] = fn()
        except Exception:  # noqa: BLE001
            out[key] = []
    return out


def _analysis_job(fid: str, name: str) -> None:
    with _ANALYSIS_SLOT:
        res: dict[str, Any] = {}
        for attempt in range(1, 4):                       # сбой разбора — молча пробуем ещё раз (файл мог быть недописан, память занята)
            try:
                res = analyze_any(FILES_DIR / fid, name)
                if name.lower().endswith(".dxf") and res.get("ok", True):
                    try:
                        build_geom(fid)
                    except Exception:  # noqa: BLE001
                        pass
            except Exception as ex:  # noqa: BLE001
                res = {"ok": False, "error": f"{type(ex).__name__}: {ex}"[:300]}
            if res.get("ok", True):
                break
            time.sleep(1.5 * attempt)
        res["tries"] = attempt
        for _ in range(6):
            try:
                conn = sqlite3.connect(DB_PATH, timeout=30)
                n = conn.execute("UPDATE source_files SET analysis_json=?, status='ready' WHERE id=?", (json.dumps(res, ensure_ascii=False), fid)).rowcount
                row = conn.execute("SELECT project_id, kind FROM source_files WHERE id=?", (fid,)).fetchone()
                conn.commit(); conn.close()
                if n:
                    if row and row[1] == "dxf_project" and name.lower().endswith(".dxf"):
                        auto_first_draft(row[0])
                    return
            except Exception:  # noqa: BLE001
                pass
            time.sleep(0.5)


def _start_analysis(fid: str, name: str) -> None:
    threading.Thread(target=_analysis_job, args=(fid, name), daemon=True).start()


def _store_path(c: sqlite3.Connection, project_id: str, section_id: Optional[str], kind: str, name: str, tmp: Path, size: int, sha: str, who: str) -> dict[str, Any]:
    if not c.execute("SELECT 1 FROM projects WHERE id=?", (project_id,)).fetchone():
        tmp.unlink(missing_ok=True)
        raise HTTPException(404, "Проект не найден")
    if kind not in FILE_KINDS:
        kind = guess_kind(name)
    dup = c.execute("SELECT id,name FROM source_files WHERE project_id=? AND sha256=?", (project_id, sha)).fetchone()
    if dup:
        tmp.unlink(missing_ok=True)
        return {"id": dup["id"], "name": dup["name"], "duplicate": True, "status": "ready"}
    fid = str(uuid.uuid4())
    tmp.replace(FILES_DIR / fid)
    needs = name.lower().endswith((".dxf", ".xml"))
    c.execute("INSERT INTO source_files (id,project_id,section_id,kind,name,size,sha256,uploaded_by,uploaded_at,analysis_json,status) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
              (fid, project_id, section_id or None, kind, name[:200], size, sha, who[:80], now(), "{}", "analyzing" if needs else "ready"))
    return {"id": fid, "name": name, "duplicate": False, "status": "analyzing" if needs else "ready", "_start": needs}


def _file_row(c: sqlite3.Connection, r: sqlite3.Row) -> dict[str, Any]:
    a = json.loads(r["analysis_json"] or "{}")
    matched: list[str] = []
    if a.get("codes"):
        names = [x["name"] + " " + x["code"] for x in c.execute(
            "SELECT el.code,el.name FROM elements el JOIN sections s ON s.id=el.section_id WHERE s.project_id=? AND el.enabled=1", (r["project_id"],))]
        blob = _norm_code(" ".join(names))
        matched = [k for k in a["codes"] if k in blob]
    return {"id": r["id"], "kind": r["kind"], "kind_label": FILE_KINDS.get(r["kind"], r["kind"]), "name": r["name"], "size": r["size"],
            "uploaded_by": r["uploaded_by"], "uploaded_at": r["uploaded_at"], "section_id": r["section_id"], "status": r["status"],
            "analysis": a, "matched_codes": len(matched)}


def _reanalyze(c: sqlite3.Connection, fid: str, name: str) -> None:
    c.execute("UPDATE source_files SET analysis_json='{}', status='analyzing' WHERE id=?", (fid,))
    _start_analysis(fid, name)


def _heal_failed_files(c: sqlite3.Connection, project: str) -> None:
    """Файлы со старой пометкой «не удалось прочитать» (без счётчика попыток) перечитываем сами — один раз."""
    for r in c.execute("SELECT id,name,kind,analysis_json,status FROM source_files WHERE project_id=? AND status='ready' AND kind<>'scheme'", (project,)).fetchall():
        try:
            a = json.loads(r["analysis_json"] or "{}")
        except ValueError:
            a = {"ok": False}
        if not (FILES_DIR / r["id"]).exists():
            continue
        low = str(r["name"]).lower()
        if "tries" not in a and (a.get("ok") is False or (a and low.endswith(".pdf") and "ok" in a)) and low.endswith((".dxf", ".xml", ".pdf")):
            _reanalyze(c, r["id"], r["name"])


class FileMove(BaseModel):
    section_id: str = ""


@app.put("/api/files/{file_id}/move")
def file_move(file_id: str, payload: FileMove) -> dict[str, str]:
    with db() as c:
        r = c.execute("SELECT project_id,kind FROM source_files WHERE id=?", (file_id,)).fetchone()
        if not r:
            raise HTTPException(404, "Файл не найден")
        if r["kind"] in OBJECT_KINDS:
            raise HTTPException(400, "Этот файл относится к объекту целиком, в раздел его переносить не нужно")
        sid = payload.section_id.strip()
        if sid and not c.execute("SELECT 1 FROM sections WHERE id=? AND project_id=?", (sid, r["project_id"])).fetchone():
            raise HTTPException(404, "Раздел не найден в этом проекте")
        c.execute("UPDATE source_files SET section_id=? WHERE id=?", (sid or None, file_id))
    return {"message": "Файл перенесён"}


@app.post("/api/files/{file_id}/reanalyze")
def file_reanalyze(file_id: str) -> dict[str, str]:
    with db() as c:
        r = c.execute("SELECT name FROM source_files WHERE id=?", (file_id,)).fetchone()
        if not r:
            raise HTTPException(404, "Файл не найден")
        if not (FILES_DIR / file_id).exists():
            raise HTTPException(404, "Файла нет на сервере — загрузите его заново")
        _reanalyze(c, file_id, r["name"])
    return {"message": "Перечитываем файл"}


@app.get("/api/files")
def files_list(project: str, level: str = "", section: str = "") -> dict[str, Any]:
    with db() as c:
        p = c.execute("SELECT * FROM projects WHERE id=?", (project,)).fetchone()
        if not p:
            raise HTTPException(404, "Проект не найден")
        _heal_failed_files(c, project)
        rows = [_file_row(c, r) for r in c.execute("SELECT * FROM source_files WHERE project_id=? AND kind<>'scheme' ORDER BY uploaded_at DESC", (project,))]
        if level == "object":      # объект: ПОС, график, образец АОСР и прочее без раздела
            rows = [r for r in rows if r["kind"] in OBJECT_KINDS or (r["kind"] not in SECTION_KINDS and not r["section_id"])]
        elif level == "section":   # раздел: проект DXF/PDF и смета XML этого раздела (файлы без раздела — общие, видны во всех)
            rows = [r for r in rows if r["kind"] not in OBJECT_KINDS and (not r["section_id"] or r["section_id"] == section)]
        return {"files": rows, "source_link": p["source_link"], "source_link_at": p["source_link_at"], "kinds": FILE_KINDS}


def _section_code_of(cipher: str) -> str:
    """«РК-ДП-39-26-НВ1» → «НВ1»: последняя часть шифра — обозначение раздела."""
    m = re.search(r"-([А-ЯЁA-Z]{1,3}\d+(?:\.\d+)?)\s*$", (cipher or "").strip())
    return m.group(1) if m else ""


def _cipher_title(lines: list[str], cipher: str) -> str:
    """Наименование раздела с титула/штампа: строка перед шифром («Наружные сети хозяйственно-питьевого водоснабжения»)."""
    for i, l in enumerate(lines):
        if cipher and cipher in l.replace(" ", "") .replace("\u00a0", "") or (cipher and l.strip().startswith(cipher)):
            for j in range(i - 1, max(-1, i - 4), -1):
                t = re.sub(r"\s+", " ", lines[j]).strip()
                if len(t) >= 8 and not re.fullmatch(r"[\d\W]+", t) and not re.search(r"Изм|Подп|Дата|Лист", t):
                    return t[:160]
    return ""


def _net_of(name: str) -> str:
    m = re.search(r"(?<![А-Яа-яA-Za-z0-9])([ВКТвкт]\d+(?:\.\d+)?)(?![\d])", name or "")
    return m.group(1).upper() if m else ""


def _norm_sec(v: str) -> str:
    return re.sub(r"[^А-ЯA-Z0-9.]", "", (v or "").upper())


def _auto_probe(name: str, kind: str, path: Path) -> dict[str, str]:
    """Что за файл (без БД, тяжёлое чтение): код раздела и наименование для проекта, сеть — для сметы."""
    out = {"code": "", "title": "", "net": ""}
    try:
        if kind in ("pdf", "dxf_project"):
            cipher = ""
            m = CIPHER_RE.search(name or "")
            if m and _section_code_of(m.group(0)):
                cipher = m.group(0)
            lines: list[str] = []
            if name.lower().endswith(".pdf"):
                lines = pdf_lines(path)
                if not cipher:
                    cipher = extract_project_meta(lines).get("cipher", "")
            out["code"] = _section_code_of(cipher)
            out["title"] = _cipher_title(lines, cipher) if lines else ""
        elif kind == "estimate":
            out["net"] = _net_of(name)
    except Exception:  # noqa: BLE001
        pass
    return out


def _auto_section(c: sqlite3.Connection, project_id: str, probe: dict[str, str], fallback: Optional[str]) -> tuple[Optional[str], dict[str, Any]]:
    """Раздел для загружаемого файла: по шифру проектной документации (РК-ДП-39-26-НВ1 → раздел НВ1, создаётся при отсутствии);
    смета — по сети в названии файла («В1 открыт Крым.xml» → раздел с сетью В1)."""
    secs = c.execute("SELECT id,code,title,system FROM sections WHERE project_id=?", (project_id,)).fetchall()
    info: dict[str, Any] = {"section_code": "", "created": False}

    def nets(r: sqlite3.Row) -> list[str]:
        return [_norm_sec(x) for x in re.split(r"[,;\s]+", r["system"] or "") if x]

    if probe.get("net"):
        net = probe["net"]
        for r in secs:
            if net in nets(r) or _norm_sec(r["code"]).endswith(net):
                info["section_code"] = r["code"]
                return r["id"], info
        return fallback, info
    code = probe.get("code", "")
    if not code:
        return fallback, info
    nc = _norm_sec(code)
    for r in secs:
        if _norm_sec(r["code"]).endswith(nc) or (nc.startswith("Н") and nc[1:] in nets(r)):
            info["section_code"] = r["code"]
            return r["id"], info
    system = nc[1:] if nc.startswith("Н") and len(nc) > 2 else nc
    sid = _create_section(c, project_id, code, probe.get("title") or f"Раздел {code}", system)
    info.update({"section_code": code, "created": True})
    return sid, info


def _uploader(c: sqlite3.Connection, request: Request, fallback: str = "") -> str:
    """Кто загрузил: ФИО вошедшего пользователя (по логину из команды или справочника), иначе логин. Имя из браузера не доверяем."""
    login = (getattr(request.state, "user", "") or "").strip()
    if not login:
        return fallback[:80]
    for tbl in ("team", "dict_users"):
        try:
            r = c.execute(f"SELECT name FROM {tbl} WHERE lower(login)=lower(?) AND name<>'' LIMIT 1", (login,)).fetchone()
        except sqlite3.Error:
            r = None
        if r:
            return r["name"][:80]
    return login[:80]


@app.post("/api/files", status_code=201)
async def file_upload(request: Request, project: str, name: str, kind: str = "", section: str = "", who: str = "", auto: int = 0) -> dict[str, Any]:
    FILES_DIR.mkdir(parents=True, exist_ok=True)
    tmp = FILES_DIR / f"tmp-{uuid.uuid4().hex}"
    h = hashlib.sha256()
    size = 0
    try:
        with open(tmp, "wb") as f:
            async for chunk in request.stream():
                size += len(chunk)
                if size > MAX_FILE:
                    raise HTTPException(413, "Файл больше 95 МБ — разделите или сожмите (zip)")
                h.update(chunk)
                f.write(chunk)
        if size == 0:
            raise HTTPException(400, "Пустой файл")
        nm = os.path.basename(name)
        info: dict[str, Any] = {}
        k = kind or guess_kind(nm)
        obj_level = k in OBJECT_KINDS
        probe = await run_in_threadpool(_auto_probe, nm, k, tmp) if (auto and not obj_level) else {}
        with db() as c:
            sec = None if obj_level else (section or None)
            if auto and not obj_level:
                sec, info = _auto_section(c, project, probe, sec)
            res = _store_path(c, project, sec, k, nm, tmp, size, h.hexdigest(), _uploader(c, request, who))
            if auto:
                res.update({"section_id": sec or "", **info})
        if res.pop("_start", False):
            _start_analysis(res["id"], nm)
        return res
    finally:
        tmp.unlink(missing_ok=True)


# ---------------------------------------------------------------- просмотр: облегчённая геометрия DXF
_ACI = {1: "#ff3b3b", 2: "#ffe14a", 3: "#3bd96b", 4: "#3be3e3", 5: "#4a7bff", 6: "#ff4aff", 7: "#ffffff", 8: "#8a8a8a", 9: "#c0c0c0"}


def _aci(n: int) -> str:
    if n in _ACI:
        return _ACI[n]
    import colorsys
    h = ((n * 37) % 360) / 360.0
    r, g, b = colorsys.hsv_to_rgb(h, 0.65, 0.95)
    return "#%02x%02x%02x" % (int(r * 255), int(g * 255), int(b * 255))


_MTEXT_FMT = re.compile(r"\\[A-Za-z][^;\\]*;|[{}]")


def _clean_mtext(t: str) -> str:
    t = t.replace("\\P", " ").replace("\\~", " ")
    t = _MTEXT_FMT.sub("", t)
    return _U_ESC.sub(lambda mm: chr(int(mm.group(1), 16)), t).strip()


def dxf_geometry(path: Path) -> dict[str, Any]:
    """Потоковое чтение DXF (ENTITIES): линии, полилинии, окружности, дуги, подписи. Блоки и штриховки не рисуются."""
    with open(path, "rb") as fb:
        hd = fb.read(300000).decode("latin-1")
    m = re.search(r"\$ACADVER\s+1\s+(AC\d+)", hd)
    ver = m.group(1) if m else ""
    enc = "cp1251" if (ver and ver < "AC1021" and "ANSI_1251" in hd) else "utf-8"
    layer_col: dict[str, int] = {}
    layers: dict[str, dict[str, Any]] = {}
    xs: list[float] = []
    ys: list[float] = []
    r2 = lambda v: round(v, 2)

    def lay(n: str) -> dict[str, Any]:
        d = layers.get(n)
        if d is None:
            d = layers[n] = {"name": n, "L": [], "P": [], "C": [], "A": [], "T": []}
        return d

    def mark(x: float, y: float) -> None:
        if len(xs) < 400000:
            xs.append(x); ys.append(y)

    sec = ""
    sec_next = False
    cur: Optional[str] = None
    g: dict[str, Any] = {}
    poly: Optional[dict[str, Any]] = None
    in_layer_tab = False
    lname = ""

    def fin() -> None:
        nonlocal poly
        t = cur
        if t is None:
            return
        v = g.get
        ly = v("8", "0")
        if t == "LINE" and all(k in g for k in ("10", "20", "11", "21")):
            lay(ly)["L"] += [r2(v("10")), r2(v("20")), r2(v("11")), r2(v("21"))]
            mark(v("10"), v("20")); mark(v("11"), v("21"))
        elif t == "LWPOLYLINE":
            px, py = g.get("px", []), g.get("py", [])
            n = min(len(px), len(py))
            if n >= 2:
                pts = []
                for i in range(n):
                    pts += [r2(px[i]), r2(py[i])]
                if int(v("70", 0)) & 1:
                    pts += pts[:2]
                lay(ly)["P"].append(pts); mark(px[0], py[0]); mark(px[n - 1], py[n - 1])
        elif t == "SPLINE":
            px, py = g.get("px", []), g.get("py", [])
            n = min(len(px), len(py))
            if n >= 2:
                lay(ly)["P"].append([r2(c) for i in range(n) for c in (px[i], py[i])]); mark(px[0], py[0])
        elif t == "POLYLINE":
            poly = {"ly": ly, "px": [], "py": [], "closed": int(v("70", 0)) & 1}
        elif t == "VERTEX" and poly is not None and "10" in g and "20" in g:
            poly["px"].append(g["10"]); poly["py"].append(g["20"])
        elif t == "SEQEND" and poly is not None:
            n = len(poly["px"])
            if n >= 2:
                pts = [r2(c) for i in range(n) for c in (poly["px"][i], poly["py"][i])]
                if poly["closed"]:
                    pts += pts[:2]
                lay(poly["ly"])["P"].append(pts); mark(poly["px"][0], poly["py"][0])
            poly = None
        elif t == "CIRCLE" and "10" in g and "20" in g and "40" in g:
            lay(ly)["C"] += [r2(v("10")), r2(v("20")), r2(v("40"))]; mark(v("10"), v("20"))
        elif t == "ARC" and "10" in g and "20" in g and "40" in g:
            lay(ly)["A"] += [r2(v("10")), r2(v("20")), r2(v("40")), r2(v("50", 0.0)), r2(v("51", 360.0))]; mark(v("10"), v("20"))
        elif t in ("TEXT", "MTEXT") and "10" in g and "20" in g:
            txt = "".join(g.get("t3", [])) + str(v("1", ""))
            txt = _clean_mtext(txt) if t == "MTEXT" else _U_ESC.sub(lambda mm: chr(int(mm.group(1), 16)), txt).strip()
            if txt:
                lay(ly)["T"].append([r2(v("10")), r2(v("20")), r2(v("40", 2.5) or 2.5), r2(v("50", 0.0)) if t == "TEXT" else 0, txt[:400]])
                mark(v("10"), v("20"))

    NUM = {"10", "20", "11", "21", "40", "50", "51", "70", "62"}
    with open(path, "r", encoding=enc, errors="replace") as f:
        it = iter(f)
        for code_line in it:
            val_line = next(it, None)
            if val_line is None:
                break
            c = code_line.strip()
            v = val_line.rstrip("\r\n")
            if c == "0":
                vs = v.strip()
                if sec == "ENTITIES":
                    fin()
                if in_layer_tab and lname:
                    pass
                if vs == "SECTION":
                    sec_next = True; sec = ""; cur = None; g = {}
                elif vs == "ENDSEC":
                    if sec == "ENTITIES":
                        pass
                    sec = ""; cur = None; g = {}; in_layer_tab = False
                elif sec == "ENTITIES":
                    cur = vs; g = {}
                elif sec == "TABLES":
                    if vs == "LAYER":
                        in_layer_tab = True; lname = ""
                    else:
                        in_layer_tab = False
                continue
            if c == "2" and sec_next:
                sec_next = False; sec = v.strip(); continue
            if sec == "TABLES" and in_layer_tab:
                if c == "2":
                    lname = v.strip()
                elif c == "62" and lname:
                    try:
                        layer_col[lname] = int(float(v))
                    except ValueError:
                        pass
                continue
            if sec != "ENTITIES" or cur is None:
                continue
            if c == "8":
                g["8"] = v.strip()
            elif c in ("10", "20") and cur in ("LWPOLYLINE", "SPLINE"):
                g.setdefault("px" if c == "10" else "py", []).append(_num(v))
            elif c in NUM:
                try:
                    g[c] = float(v)
                except ValueError:
                    pass
            elif c == "1" and cur in ("TEXT", "MTEXT"):
                g["1"] = v
            elif c == "3" and cur == "MTEXT":
                g.setdefault("t3", []).append(v)
    out_layers = []
    for n, d in layers.items():
        col = layer_col.get(n, 7)
        d["c"] = _aci(abs(col))
        d["off"] = col < 0
        d["n"] = len(d["L"]) // 4 + len(d["P"]) + len(d["C"]) // 3 + len(d["A"]) // 5 + len(d["T"])
        if d["n"]:
            out_layers.append(d)
    out_layers.sort(key=lambda d: -d["n"])
    ext = None
    if xs:
        sx, sy = sorted(xs), sorted(ys)
        lo, hi = int(len(sx) * 0.005), max(int(len(sx) * 0.995) - 1, 0)
        ext = [sx[lo], sy[lo], sx[hi], sy[hi]]
    return {"layers": out_layers, "ext": ext}


GEOM_LOCK = threading.Lock()


def geom_path(fid: str) -> Path:
    return FILES_DIR / f"{fid}.geom.gz"


def build_geom(fid: str) -> Path:
    gp = geom_path(fid)
    with GEOM_LOCK:
        if not gp.exists():
            import gzip
            data = json.dumps(dxf_geometry(FILES_DIR / fid), ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            tmp = gp.with_suffix(".tmp")
            tmp.write_bytes(gzip.compress(data, 6))
            tmp.replace(gp)
    return gp


def docx_html(path: Path) -> str:
    import zipfile
    import html as H
    import xml.etree.ElementTree as ET
    W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
    with zipfile.ZipFile(path) as z:
        root = ET.fromstring(z.read("word/document.xml"))
    def ptext(p: Any) -> str:
        out = []
        for e in p.iter():
            if e.tag == W + "t":
                out.append(e.text or "")
            elif e.tag in (W + "tab",):
                out.append("    ")
            elif e.tag in (W + "br", W + "cr"):
                out.append("\n")
        return "".join(out)
    body = root.find(W + "body")
    parts: list[str] = []
    size = 0
    for el in (body if body is not None else []):
        if el.tag == W + "p":
            t = ptext(el)
            h = f"<p>{H.escape(t).replace(chr(10), '<br>')}</p>" if t.strip() else ""
        elif el.tag == W + "tbl":
            rows = []
            for tr in el.iter(W + "tr"):
                cells = ["<td>" + "<br>".join(H.escape(ptext(p)) for p in tc.findall(W + "p") if ptext(p).strip()) + "</td>" for tc in tr.findall(W + "tc")]
                rows.append("<tr>" + "".join(cells) + "</tr>")
            h = "<table>" + "".join(rows) + "</table>"
        else:
            h = ""
        size += len(h)
        parts.append(h)
        if size > 600000:
            parts.append("<p><i>… документ обрезан для просмотра, скачайте файл целиком</i></p>")
            break
    return "".join(parts)


