def photo_get(photo_id: str) -> FileResponse:
    with db() as c:
        r = c.execute("SELECT ct,name FROM photos WHERE id=?", (photo_id,)).fetchone()
    path = PHOTOS_DIR / photo_id
    if not r or not path.exists():
        raise HTTPException(404, "Фото не найдено")
    return FileResponse(path, media_type=r["ct"], headers={"Cache-Control": "private, max-age=86400"})


@app.delete("/api/photos/{photo_id}")
def photo_delete(photo_id: str) -> dict[str, str]:
    with db() as c:
        if not c.execute("SELECT 1 FROM photos WHERE id=?", (photo_id,)).fetchone():
            raise HTTPException(404, "Фото не найдено")
        c.execute("DELETE FROM photos WHERE id=?", (photo_id,))
    try:
        (PHOTOS_DIR / photo_id).unlink()
    except OSError:
        pass
    return {"message": "Фото удалено"}


# ---------------- Мобильное рабочее место прораба (PWA) ----------------
def _icon_png(n: int) -> bytes:
    """Иконка приложения: белая «галочка» на бирюзовом фоне (без внешних библиотек)."""
    segs = [((0.26, 0.52), (0.43, 0.69)), ((0.43, 0.69), (0.75, 0.33))]
    half = 0.052
    bg = (8, 127, 128)
    raw = bytearray()
    for y in range(n):
        raw.append(0)
        fy = (y + 0.5) / n
        for x in range(n):
            fx = (x + 0.5) / n
            on = False
            for (ax, ay), (bx, by) in segs:
                dx, dy = bx - ax, by - ay
                t = max(0.0, min(1.0, ((fx - ax) * dx + (fy - ay) * dy) / (dx * dx + dy * dy)))
                if (fx - (ax + t * dx)) ** 2 + (fy - (ay + t * dy)) ** 2 <= half * half:
                    on = True
                    break
            raw += bytes((255, 255, 255) if on else bg)

    def chunk(tag: bytes, data: bytes) -> bytes:
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", n, n, 8, 2, 0, 0, 0)) + chunk(b"IDAT", zlib.compress(bytes(raw), 9)) + chunk(b"IEND", b"")


_ICONS: dict[int, bytes] = {}


@app.get("/m-icon-{size}.png")
def m_icon(size: int) -> Response:
    if size not in (192, 512):
        raise HTTPException(404, "Нет такой иконки")
    if size not in _ICONS:
        _ICONS[size] = _icon_png(size)
    return Response(_ICONS[size], media_type="image/png", headers={"Cache-Control": "public, max-age=604800"})


@app.get("/manifest.webmanifest")
def manifest() -> JSONResponse:
    return JSONResponse({"name": "ИД ИТС · Прораб", "short_name": "Прораб", "start_url": "/m", "scope": "/", "display": "standalone",
                         "orientation": "portrait", "background_color": "#112b36", "theme_color": "#087f80", "lang": "ru",
                         "icons": [{"src": "/m-icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any maskable"},
                                   {"src": "/m-icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable"}]},
                        media_type="application/manifest+json")


SW_JS = """const C='idits-m-v2';
self.addEventListener('install',e=>{e.waitUntil(caches.open(C).then(c=>c.addAll(['/manifest.webmanifest','/m-icon-192.png'])).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==C).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin)return;
if(e.request.mode==='navigate'&&u.pathname==='/m'){e.respondWith(fetch(e.request).then(r=>{if(r.ok&&!r.redirected){const cp=r.clone();caches.open(C).then(c=>c.put('/m',cp))}return r}).catch(()=>caches.match('/m')))}});
"""


@app.get("/sw.js")
def service_worker() -> Response:
    return Response(SW_JS, media_type="application/javascript", headers={"Service-Worker-Allowed": "/", "Cache-Control": "no-cache"})


